window.__qzParts=window.__qzParts||{};window.__qzParts.tin=[{"p":"Bộ phận nào của máy tính dùng để hiển thị hình ảnh và chữ?","o":["Màn hình","Bàn phím","Chuột máy tính","Thân máy"],"a":"Màn hình","h":"Bộ phận trông giống chiếc ti vi.","e":"Màn hình hiển thị hình ảnh, chữ và video để em nhìn thấy.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Bộ phận nào của máy tính chứa các mạch điện và được ví như bộ não xử lí thông tin?","o":["Thân máy","Màn hình","Chuột máy tính","Loa"],"a":"Thân máy","h":"Đây là chiếc hộp lớn nhất trong các bộ phận rời của máy tính để bàn.","e":"Thân máy chứa bộ xử lí trung tâm, được ví như bộ não của máy tính.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Để nhập chữ và số vào máy tính, em dùng bộ phận nào?","o":["Bàn phím","Màn hình","Chuột máy tính","Thân máy"],"a":"Bàn phím","h":"Bộ phận có rất nhiều phím chữ và phím số.","e":"Bàn phím có các phím chữ, phím số để em gõ vào máy tính.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Thao tác nháy đúp chuột là làm gì?","o":["Nhấn nút trái chuột hai lần liên tiếp thật nhanh","Nhấn giữ chuột thật lâu","Kéo chuột đi thật xa","Nhấn nút phải chuột một lần"],"a":"Nhấn nút trái chuột hai lần liên tiếp thật nhanh","h":"Thao tác này gồm hai lần nhấn chuột rất gần nhau.","e":"Nháy đúp là nhấn nút trái chuột hai lần liên tiếp thật nhanh, thường dùng để mở phần mềm.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi ngồi học với máy tính, tư thế nào là đúng?","o":["Ngồi thẳng lưng, mắt cách màn hình vừa phải","Ghé sát mặt vào màn hình","Ngồi cong lưng, cúi sát bàn phím","Nằm dài ra ghế nhìn màn hình"],"a":"Ngồi thẳng lưng, mắt cách màn hình vừa phải","h":"Tư thế đúng giúp em bảo vệ mắt và cột sống.","e":"Ngồi thẳng lưng và giữ khoảng cách vừa phải với màn hình giúp em bảo vệ mắt và cột sống.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Phím nào sau đây thuộc hàng phím cơ sở trên bàn phím?","o":["Phím A","Phím Q","Phím Z","Phím P"],"a":"Phím A","h":"Hàng phím cơ sở là hàng phím ở giữa, nơi em đặt tay khi bắt đầu gõ.","e":"Hàng phím cơ sở gồm các phím A, S, D, F, G, H, J, K, L.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Việc nào sau đây giúp em an toàn khi dùng máy tính?","o":["Không chạm tay ướt vào dây điện và ổ cắm","Vừa ăn uống vừa gõ bàn phím","Để cốc nước ngay cạnh bàn phím","Tự ý tháo nắp thân máy ra xem"],"a":"Không chạm tay ướt vào dây điện và ổ cắm","h":"Hãy nghĩ đến nguy cơ từ điện và nước.","e":"Tay ướt chạm vào điện rất nguy hiểm, em cần giữ tay khô và tránh xa ổ cắm điện.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Thông tin nào sau đây em không nên chia sẻ cho người lạ?","o":["Mật khẩu và địa chỉ nhà của em","Tên bài hát em thích","Màu sắc em yêu thích","Môn học em thích nhất"],"a":"Mật khẩu và địa chỉ nhà của em","h":"Đó là những thông tin riêng tư chỉ em và gia đình biết.","e":"Mật khẩu, địa chỉ nhà, số điện thoại là thông tin cá nhân cần giữ kín.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Để di chuyển một biểu tượng trên màn hình đến vị trí khác, em dùng thao tác nào với chuột?","o":["Kéo thả","Nháy đúp","Nháy chuột phải","Lăn nút cuộn"],"a":"Kéo thả","h":"Em nhấn giữ chuột, đưa biểu tượng đi rồi buông ra.","e":"Kéo thả là nhấn giữ nút trái chuột, di chuyển chuột đến vị trí mới rồi thả ra.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Em sắp xếp sách vở và đồ dùng gọn gàng, theo đúng chỗ để làm gì?","o":["Để dễ tìm khi cần dùng","Chỉ để trông cho đẹp mắt","Để được bạn bè khen","Để cất được nhiều đồ hơn"],"a":"Để dễ tìm khi cần dùng","h":"Giống như khi em tìm một quyển sách trong cặp đã sắp xếp ngăn nắp.","e":"Sắp xếp đồ vật theo trật tự giúp em tìm nhanh khi cần dùng.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Để chơi trò chơi ghép hình trên máy tính, em cần mở gì?","o":["Một phần mềm trò chơi","Thân máy","Ổ cắm điện","Bàn học"],"a":"Một phần mềm trò chơi","h":"Trò chơi trên máy tính chạy nhờ một chương trình được cài sẵn.","e":"Trò chơi ghép hình là một phần mềm, em nháy đúp vào biểu tượng của nó để mở và chơi.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Khi em di chuyển chuột trên mặt bàn, con trỏ chuột trên màn hình sẽ thế nào?","o":["Di chuyển theo","Đứng yên một chỗ","Biến mất","Quay tròn liên tục"],"a":"Di chuyển theo","h":"Con trỏ chuột luôn nghe theo chuyển động của chuột.","e":"Con trỏ chuột di chuyển theo đúng hướng em di chuyển chuột trên mặt bàn.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Hai phím có gờ nhỏ trên hàng phím cơ sở, giúp em đặt tay đúng mà không cần nhìn, là phím nào?","o":["Phím F và phím J","Phím A và phím L","Phím G và phím H","Phím D và phím K"],"a":"Phím F và phím J","h":"Đó là hai phím dành cho hai ngón tay trỏ.","e":"Phím F và phím J có gờ nhỏ để em định vị hai ngón tay trỏ khi gõ phím.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Em muốn mở một phần mềm từ màn hình nền (Desktop). Thao tác đúng là gì?","o":["Nháy đúp chuột vào biểu tượng của phần mềm","Nháy chuột một lần vào biểu tượng","Kéo biểu tượng của phần mềm đi chỗ khác","Nhấn nút phải chuột vào biểu tượng"],"a":"Nháy đúp chuột vào biểu tượng của phần mềm","h":"Hãy nhớ thao tác mở phần mềm đã học ở bài chuột máy tính.","e":"Trên màn hình nền, em nháy đúp chuột vào biểu tượng để mở phần mềm.","t":"tin-lop3","g":3,"l":"kho"},{"p":"Sắp xếp các tệp và thư mục trong máy tính gọn gàng, theo từng nhóm có lợi ích gì?","o":["Giúp em tìm lại tệp nhanh và dễ dàng","Làm máy tính nặng hơn","Làm màn hình sáng hơn","Giúp chuột chạy nhanh hơn"],"a":"Giúp em tìm lại tệp nhanh và dễ dàng","h":"Lợi ích này giống với việc sắp xếp đồ dùng trong phòng của em.","e":"Giống như sắp xếp đồ dùng, sắp xếp tệp ngăn nắp giúp em tìm lại nhanh khi cần.","t":"tin-lop3","g":3,"l":"kho"},{"p":"Phần cứng của máy tính là gì?","o":["Các bộ phận em có thể nhìn thấy và chạm vào được","Các chương trình chạy trong máy tính","Các trò chơi trên máy tính","Các trang web trên Internet"],"a":"Các bộ phận em có thể nhìn thấy và chạm vào được","h":"Hãy nghĩ đến màn hình, bàn phím và chuột.","e":"Phần cứng gồm các bộ phận vật lí như màn hình, bàn phím, chuột và thân máy.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Phần mềm của máy tính là gì?","o":["Các chương trình giúp máy tính làm việc theo yêu cầu của em","Chiếc hộp chứa các bộ phận máy tính","Sợi dây nối các bộ phận với nhau","Chiếc ghế em ngồi khi học"],"a":"Các chương trình giúp máy tính làm việc theo yêu cầu của em","h":"Phần mềm khác phần cứng ở chỗ em không chạm vào được.","e":"Phần mềm là các chương trình bên trong máy tính, em không sờ hay chạm vào được.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Vật nào sau đây là phần cứng của máy tính?","o":["Bàn phím","Phần mềm vẽ Paint","Phần mềm soạn thảo văn bản","Trò chơi trên máy tính"],"a":"Bàn phím","h":"Chỉ có một lựa chọn là vật thật em cầm được.","e":"Bàn phím là bộ phận vật lí nên thuộc phần cứng, các lựa chọn còn lại là phần mềm.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Internet là gì?","o":["Mạng máy tính khổng lồ kết nối các máy tính trên khắp thế giới","Một loại máy tính mới","Một trò chơi trực tuyến","Một phần mềm vẽ tranh"],"a":"Mạng máy tính khổng lồ kết nối các máy tính trên khắp thế giới","h":"Nhờ có Internet, em xem được thông tin từ rất xa.","e":"Internet kết nối hàng tỉ máy tính trên thế giới để các máy chia sẻ thông tin với nhau.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Thư mục trong máy tính dùng để làm gì?","o":["Chứa và sắp xếp các tệp cho gọn gàng","Để vẽ tranh","Để nghe nhạc","Để gõ văn bản"],"a":"Chứa và sắp xếp các tệp cho gọn gàng","h":"Thư mục giống như một ngăn tủ đựng đồ.","e":"Thư mục giúp em chứa và phân loại các tệp cho gọn gàng, dễ tìm.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Muốn gõ được tiếng Việt có dấu trên máy tính, em cần bật gì?","o":["Phần mềm hỗ trợ gõ tiếng Việt","Phần mềm vẽ tranh","Phần mềm trình chiếu","Phần mềm nghe nhạc"],"a":"Phần mềm hỗ trợ gõ tiếng Việt","h":"Bàn phím không tự tạo được dấu tiếng Việt nếu thiếu phần mềm này.","e":"Em cần bật phần mềm hỗ trợ gõ tiếng Việt thì mới gõ được chữ có dấu.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Sau khi soạn thảo văn bản xong, em cần làm gì để lần sau mở lại được?","o":["Lưu văn bản vào máy tính","Tắt máy ngay lập tức","Xoá hết văn bản vừa gõ","In văn bản ra giấy"],"a":"Lưu văn bản vào máy tính","h":"Việc này giúp bài làm của em không bị mất.","e":"Lưu văn bản giúp em giữ lại bài làm để xem và chỉnh sửa sau này.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Việc nào sau đây thể hiện em tôn trọng bản quyền?","o":["Không sao chép bài làm hay phần mềm của người khác khi chưa được phép","Sao chép tranh của bạn rồi nhận là của mình","Tải phần mềm lậu về dùng","Chép bài của bạn khi làm bài tập"],"a":"Không sao chép bài làm hay phần mềm của người khác khi chưa được phép","h":"Tôn trọng bản quyền nghĩa là tôn trọng công sức của người tạo ra sản phẩm.","e":"Tôn trọng bản quyền là không dùng sản phẩm của người khác khi chưa được cho phép.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Em muốn giới thiệu về trường mình trước lớp bằng các trang chiếu có chữ và hình ảnh. Phần mềm trình chiếu giúp em làm gì?","o":["Tạo các trang chiếu có chữ, hình ảnh để trình bày trước lớp","Chỉ dùng để nghe nhạc","Chỉ dùng để luyện gõ phím","Dùng để lưu trữ mọi tệp"],"a":"Tạo các trang chiếu có chữ, hình ảnh để trình bày trước lớp","h":"Hãy nhớ các buổi thuyết trình em từng xem trên lớp.","e":"Phần mềm trình chiếu giúp em tạo các trang chiếu sinh động để trình bày trước lớp.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Khi đặt tên cho tệp, em nên đặt tên như thế nào?","o":["Tên gợi nhớ nội dung của tệp","Tên thật dài và khó hiểu","Tên không có nghĩa","Tên giống hệt nhau cho mọi tệp"],"a":"Tên gợi nhớ nội dung của tệp","h":"Tên tệp tốt giúp em nhận ra ngay tệp chứa gì.","e":"Đặt tên tệp gợi nhớ nội dung giúp em tìm lại tệp nhanh chóng.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Muốn chèn một bức ảnh vào trang chiếu, em làm thế nào?","o":["Dùng lệnh chèn ảnh trong phần mềm trình chiếu rồi chọn ảnh","Vẽ lại bức ảnh bằng tay","In ảnh ra rồi dán lên màn hình","Không thể chèn ảnh vào trang chiếu"],"a":"Dùng lệnh chèn ảnh trong phần mềm trình chiếu rồi chọn ảnh","h":"Phần mềm trình chiếu có sẵn lệnh dành riêng cho việc đưa ảnh vào.","e":"Phần mềm trình chiếu có lệnh chèn ảnh, em chọn ảnh từ trong máy tính để đưa vào trang chiếu.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Khi tìm thông tin trên Internet để làm bài tập, em nên làm gì?","o":["Gõ từ khoá ngắn gọn liên quan đến điều cần tìm","Gõ cả một đoạn văn thật dài vào ô tìm kiếm","Chỉ xem bất kì trang nào hiện ra đầu tiên","Sao chép mọi thứ tìm thấy vào bài làm"],"a":"Gõ từ khoá ngắn gọn liên quan đến điều cần tìm","h":"Từ khoá là những từ quan trọng nhất của điều em cần tìm.","e":"Dùng từ khoá ngắn gọn giúp máy tìm kiếm đưa ra kết quả đúng ý em hơn.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Ví dụ nào sau đây là phần mềm?","o":["Phần mềm soạn thảo văn bản","Màn hình","Thân máy","Sợi dây cáp nối"],"a":"Phần mềm soạn thảo văn bản","h":"Phần mềm là chương trình, không phải vật em cầm được.","e":"Phần mềm soạn thảo là chương trình trong máy tính, các lựa chọn còn lại đều là phần cứng.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Em có nhiều tệp ảnh chụp chuyến đi chơi của lớp. Cách sắp xếp nào hợp lí nhất?","o":["Tạo một thư mục riêng cho chuyến đi và đưa các ảnh vào đó","Để tất cả ảnh lẫn với mọi tệp khác","Đặt tất cả các ảnh cùng một tên","Xoá bớt ảnh cho đỡ rối"],"a":"Tạo một thư mục riêng cho chuyến đi và đưa các ảnh vào đó","h":"Hãy gom những tệp liên quan đến nhau vào cùng một chỗ.","e":"Gom các tệp liên quan vào một thư mục giúp em quản lí và tìm kiếm dễ dàng.","t":"tin-lop4","g":4,"l":"kho"},{"p":"Bạn em bảo em chép lại một phần mềm học tập có bản quyền (phải mua mới được dùng) để mang về cài. Em nên làm gì?","o":["Không sao chép trái phép, chỉ dùng khi được phép hoặc nhờ người lớn mua bản quyền","Cứ chép về dùng thoải mái","Chép rồi chia sẻ cho cả lớp dùng","Đổi tên phần mềm rồi mới dùng"],"a":"Không sao chép trái phép, chỉ dùng khi được phép hoặc nhờ người lớn mua bản quyền","h":"Hãy nhớ bài học về tôn trọng bản quyền.","e":"Sao chép phần mềm có bản quyền khi chưa được phép là vi phạm bản quyền.","t":"tin-lop4","g":4,"l":"kho"},{"p":"Thư điện tử (email) dùng để làm gì?","o":["Gửi và nhận thư qua Internet","Để vẽ tranh trên máy tính","Để chơi trò chơi","Để nghe nhạc"],"a":"Gửi và nhận thư qua Internet","h":"Email giống như thư tay nhưng được gửi qua mạng.","e":"Email giúp em gửi và nhận thư, kèm tệp đính kèm, qua mạng Internet rất nhanh.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Địa chỉ email luôn có kí tự đặc biệt nào?","o":["Kí tự @","Kí tự #","Kí tự %","Kí tự &"],"a":"Kí tự @","h":"Kí tự này đứng giữa tên người dùng và tên nhà cung cấp dịch vụ thư.","e":"Địa chỉ email gồm tên người dùng, kí tự @ và tên nhà cung cấp dịch vụ.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Khối lệnh vòng lặp trong Scratch giúp em làm gì?","o":["Lặp lại một việc nhiều lần mà không cần xếp lại nhiều khối lệnh giống nhau","Làm nhân vật biến mất","Đổi màu sân khấu","Tắt máy tính"],"a":"Lặp lại một việc nhiều lần mà không cần xếp lại nhiều khối lệnh giống nhau","h":"Nhờ vòng lặp, chương trình của em ngắn gọn hơn.","e":"Vòng lặp giúp các lệnh bên trong được thực hiện lặp lại nhiều lần.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Để chương trình Scratch bắt đầu chạy khi em nháy chuột vào lá cờ xanh, em dùng nhóm khối lệnh nào?","o":["Khối lệnh sự kiện","Khối lệnh âm thanh","Khối lệnh hiển thị","Khối lệnh bút vẽ"],"a":"Khối lệnh sự kiện","h":"Nhóm khối lệnh này có khối lệnh bắt đầu bằng chữ Khi.","e":"Khối lệnh sự kiện Khi bấm vào lá cờ xanh giúp chương trình bắt đầu chạy.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Em nhận được thư điện tử từ người lạ mời nhận quà và yêu cầu gửi thông tin cá nhân. Em nên làm gì?","o":["Không trả lời, không làm theo và báo cho người lớn","Gửi ngay thông tin cá nhân của mình","Nhờ bạn bè gửi thông tin giúp","Trả lời thư để hỏi thêm về quà"],"a":"Không trả lời, không làm theo và báo cho người lớn","h":"Thư lạ hứa tặng quà thường là bẫy lừa đảo.","e":"Thư lạ có thể là lừa đảo; em không cung cấp thông tin cá nhân và hãy báo cho người lớn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Muốn bài trình chiếu sinh động hơn khi thuyết trình, em có thể thêm gì vào trang chiếu?","o":["Hiệu ứng cho chữ và hình ảnh","Xoá hết chữ trên trang chiếu","Chỉ để một trang trắng","Tắt loa của máy tính"],"a":"Hiệu ứng cho chữ và hình ảnh","h":"Điều này giúp chữ và hình xuất hiện bắt mắt hơn.","e":"Hiệu ứng giúp chữ và hình ảnh xuất hiện sinh động, thu hút người xem.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong soạn thảo văn bản, bảng (table) giúp em làm gì?","o":["Trình bày thông tin theo hàng và cột cho rõ ràng","Để nghe nhạc","Để vẽ hình tròn","Để đổi màu chữ"],"a":"Trình bày thông tin theo hàng và cột cho rõ ràng","h":"Hãy nghĩ đến thời khoá biểu được kẻ thành ô.","e":"Bảng giúp em sắp xếp thông tin thành hàng và cột, dễ đọc và dễ so sánh.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Khi tìm kiếm thông tin trên Internet, cách nào giúp em tìm được kết quả đúng và nhanh hơn?","o":["Dùng từ khoá cụ thể, sát với điều cần tìm","Dùng từ khoá thật chung chung","Gõ sai chính tả thật nhiều","Chỉ gõ một chữ cái duy nhất"],"a":"Dùng từ khoá cụ thể, sát với điều cần tìm","h":"Từ khoá càng rõ ràng, máy tìm kiếm càng hiểu đúng ý em.","e":"Từ khoá cụ thể giúp máy tìm kiếm lọc ra đúng thông tin em cần.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Em muốn gửi kèm một bức ảnh vào thư điện tử cho bạn. Em cần dùng chức năng nào?","o":["Đính kèm tệp","Xoá thư","Chuyển tiếp thư","In thư ra giấy"],"a":"Đính kèm tệp","h":"Chức năng này thường có biểu tượng chiếc kẹp giấy.","e":"Chức năng đính kèm tệp cho phép em gửi ảnh và tài liệu cùng với thư.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Vì sao em nên đối chiếu thông tin tìm được trên Internet từ nhiều nguồn khác nhau?","o":["Vì không phải thông tin nào trên mạng cũng đúng","Vì xem nhiều trang cho vui","Vì máy tính bắt buộc như vậy","Vì để mất nhiều thời gian hơn"],"a":"Vì không phải thông tin nào trên mạng cũng đúng","h":"Trên mạng có cả thông tin đúng và thông tin sai.","e":"Đối chiếu nhiều nguồn giúp em chọn được thông tin đáng tin cậy.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Việc nào sau đây giúp em an toàn khi sử dụng mạng Internet?","o":["Không chia sẻ mật khẩu và thông tin cá nhân cho người lạ","Kết bạn rồi hẹn gặp mặt người lạ quen qua mạng","Tải mọi phần mềm lạ về máy","Gửi ảnh cá nhân cho người không quen biết"],"a":"Không chia sẻ mật khẩu và thông tin cá nhân cho người lạ","h":"Hãy giữ kín những thông tin riêng tư của mình.","e":"Giữ kín mật khẩu và thông tin cá nhân giúp em an toàn trên môi trường mạng.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Em lập trình Scratch cho nhân vật vẽ hình vuông: lặp lại 4 lần hai việc di chuyển 100 bước và quay 90 độ. Cách xếp lệnh nào gọn và đúng nhất?","o":["Dùng khối lệnh lặp lại 4 lần chứa hai lệnh di chuyển và quay","Xếp 8 khối lệnh rời nhau giống hệt nhau","Dùng một khối lệnh chờ","Dùng khối lệnh phát âm thanh"],"a":"Dùng khối lệnh lặp lại 4 lần chứa hai lệnh di chuyển và quay","h":"Việc lặp đi lặp lại nhiều lần nên giao cho vòng lặp.","e":"Dùng vòng lặp 4 lần giúp chương trình ngắn gọn mà vẫn vẽ đúng hình vuông.","t":"tin-lop5","g":5,"l":"kho"},{"p":"Phần mềm có bản quyền và phần mềm miễn phí khác nhau ở điểm nào?","o":["Phần mềm có bản quyền chỉ được dùng và sao chép khi được tác giả cho phép, còn phần mềm miễn phí được dùng miễn phí theo điều kiện của tác giả","Phần mềm miễn phí luôn tốt hơn phần mềm có bản quyền","Phần mềm có bản quyền thì không cần cài đặt","Cả hai loại đều được sao chép thoải mái"],"a":"Phần mềm có bản quyền chỉ được dùng và sao chép khi được tác giả cho phép, còn phần mềm miễn phí được dùng miễn phí theo điều kiện của tác giả","h":"Điểm khác nhau nằm ở quyền sử dụng và sao chép phần mềm.","e":"Dù miễn phí hay có bản quyền, em đều phải tôn trọng điều kiện sử dụng của tác giả phần mềm.","t":"tin-lop5","g":5,"l":"kho"},{"p":"Thông tin là gì?","o":["Dữ liệu chưa được xử lí","Những hiểu biết của con người về một sự vật, sự kiện","Một thiết bị lưu trữ dữ liệu","Một chương trình máy tính"],"a":"Những hiểu biết của con người về một sự vật, sự kiện","h":"Thông tin gắn với sự hiểu biết của con người.","e":"Thông tin là những hiểu biết của con người về sự vật, sự kiện, thu nhận qua nghe, nhìn, đọc,...","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Đơn vị nhỏ nhất để biểu diễn thông tin trong máy tính là gì?","o":["Byte","Bit","KB","MB"],"a":"Bit","h":"Đơn vị này chỉ nhận một trong hai giá trị 0 hoặc 1.","e":"Bit là đơn vị nhỏ nhất biểu diễn thông tin trong máy tính, chỉ gồm kí hiệu 0 hoặc 1.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Một byte bằng bao nhiêu bit?","o":["2 bit","4 bit","8 bit","16 bit"],"a":"8 bit","h":"Hãy nhớ: 1 byte = 8 bit.","e":"Một byte gồm 8 bit và thường dùng để biểu diễn một kí tự.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Vật nào sau đây là thiết bị lưu trữ dữ liệu?","o":["Màn hình","Bàn phím","Thẻ nhớ USB","Loa"],"a":"Thẻ nhớ USB","h":"Thiết bị lưu trữ giúp giữ lại dữ liệu để dùng sau.","e":"Thẻ nhớ USB là thiết bị lưu trữ; màn hình là thiết bị ra, bàn phím là thiết bị vào, loa là thiết bị ra.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Mạng máy tính là gì?","o":["Một máy tính có cấu hình mạnh","Tập hợp các máy tính được kết nối với nhau để trao đổi thông tin và chia sẻ tài nguyên","Một chương trình diệt virus","Một loại cáp kết nối"],"a":"Tập hợp các máy tính được kết nối với nhau để trao đổi thông tin và chia sẻ tài nguyên","h":"Mạng gồm nhiều máy tính liên kết với nhau.","e":"Mạng máy tính là tập hợp các máy tính được kết nối để trao đổi thông tin và chia sẻ tài nguyên như máy in, dữ liệu.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Mạng LAN là loại mạng nào?","o":["Mạng diện rộng, kết nối các quốc gia","Mạng cục bộ, kết nối các máy tính trong phạm vi hẹp như một trường học hay cơ quan","Mạng không dây toàn cầu","Mạng của một nhà cung cấp dịch vụ Internet"],"a":"Mạng cục bộ, kết nối các máy tính trong phạm vi hẹp như một trường học hay cơ quan","h":"LAN viết tắt của Local Area Network.","e":"LAN là mạng cục bộ, phạm vi kết nối hẹp như trong một phòng, một tòa nhà hay một trường học.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong phần mềm soạn thảo văn bản, để in đậm đoạn chữ đã chọn, ta nhấn tổ hợp phím nào?","o":["Ctrl + I","Ctrl + U","Ctrl + B","Ctrl + S"],"a":"Ctrl + B","h":"B là viết tắt của Bold (đậm).","e":"Ctrl + B dùng để in đậm; Ctrl + I in nghiêng, Ctrl + U gạch chân, Ctrl + S lưu văn bản.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Thuật toán là gì?","o":["Một phần mềm soạn thảo văn bản","Dãy các bước rõ ràng, được sắp xếp theo trình tự để giải quyết một vấn đề","Một thiết bị của máy tính","Một trò chơi trên máy tính"],"a":"Dãy các bước rõ ràng, được sắp xếp theo trình tự để giải quyết một vấn đề","h":"Thuật toán giống như một bản hướng dẫn gồm từng bước.","e":"Thuật toán là dãy hữu hạn các bước rõ ràng, thực hiện theo trình tự để giải quyết một vấn đề.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Một KB (kilobyte) bằng bao nhiêu byte?","o":["100 byte","1000 byte","1024 byte","2048 byte"],"a":"1024 byte","h":"Các đơn vị dung lượng tăng theo bội số 1024.","e":"Theo quy ước trong tin học, 1 KB = 1024 byte, 1 MB = 1024 KB.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Để chèn một bảng (table) vào văn bản, ta sử dụng lệnh trong thẻ (tab) nào?","o":["Home","Insert","Design","View"],"a":"Insert","h":"Insert nghĩa là 'chèn'.","e":"Lệnh Table nằm trong thẻ Insert, dùng để chèn bảng, hình ảnh, hình vẽ vào văn bản.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Trong sơ đồ khối mô tả thuật toán, hình thoi được dùng để biểu diễn bước nào?","o":["Bước bắt đầu, kết thúc","Bước nhập hoặc xuất dữ liệu","Bước kiểm tra điều kiện","Bước thực hiện phép tính"],"a":"Bước kiểm tra điều kiện","h":"Hình thoi là nơi thuật toán phải 'quyết định' đi đường nào.","e":"Trong sơ đồ khối, hình thoi biểu diễn bước kiểm tra điều kiện để rẽ nhánh; hình ô van là bắt đầu/kết thúc, hình bình hành là nhập/xuất.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Điểm khác nhau cơ bản giữa mạng WAN và mạng LAN là gì?","o":["WAN dùng cáp, LAN không dùng cáp","WAN có phạm vi kết nối rộng hơn LAN, có thể giữa các thành phố, quốc gia","LAN nhanh hơn mọi mạng WAN trong mọi trường hợp","WAN chỉ gồm đúng hai máy tính"],"a":"WAN có phạm vi kết nối rộng hơn LAN, có thể giữa các thành phố, quốc gia","h":"So sánh về phạm vi địa lí của hai loại mạng.","e":"LAN là mạng cục bộ phạm vi hẹp; WAN là mạng diện rộng, kết nối các mạng LAN ở khoảng cách xa nhau.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Một tệp ảnh có dung lượng 2 MB. Dung lượng đó bằng bao nhiêu KB?","o":["2000 KB","1024 KB","2048 KB","4096 KB"],"a":"2048 KB","h":"1 MB = 1024 KB, nhân lên với 2.","e":"1 MB = 1024 KB nên 2 MB = 2 × 1024 = 2048 KB.","t":"tin-lop6","g":6,"l":"kho"},{"p":"Một thư mục chứa ba tệp có dung lượng lần lượt là 512 KB, 1 MB và 256 KB. Tổng dung lượng của thư mục là bao nhiêu KB?","o":["768 KB","1536 KB","1792 KB","2048 KB"],"a":"1792 KB","h":"Đổi 1 MB ra KB rồi cộng cả ba số lại.","e":"1 MB = 1024 KB, vậy tổng là 512 + 1024 + 256 = 1792 KB.","t":"tin-lop6","g":6,"l":"kho"},{"p":"Thiết bị nào sau đây là thiết bị VÀO của máy tính?","o":["Màn hình","Bàn phím","Máy in","Loa"],"a":"Bàn phím","h":"Thiết bị vào giúp đưa thông tin vào máy tính.","e":"Bàn phím là thiết bị vào; màn hình, máy in và loa là các thiết bị ra.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Chức năng chính của hệ điều hành là gì?","o":["Soạn thảo văn bản","Quản lí và điều khiển mọi hoạt động của máy tính","Lướt web và xem phim","Diệt mọi loại virus"],"a":"Quản lí và điều khiển mọi hoạt động của máy tính","h":"Hệ điều hành là phần mềm nền tảng chạy đầu tiên khi mở máy.","e":"Hệ điều hành quản lí phần cứng, tổ chức lưu trữ dữ liệu và điều phối các chương trình khác hoạt động.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Windows là tên của phần mềm nào?","o":["Trình duyệt web","Hệ điều hành","Phần mềm bảng tính","Phần mềm diệt virus"],"a":"Hệ điều hành","h":"Đây là phần mềm của hãng Microsoft, rất phổ biến trên máy tính cá nhân.","e":"Windows là hệ điều hành thông dụng do Microsoft phát triển.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Địa chỉ ô A5 trong bảng tính có nghĩa là gì?","o":["Ô ở hàng A, cột 5","Ô ở cột A, hàng 5","Ô ở cột 5, hàng A","Ô thứ 5 của trang tính đầu tiên"],"a":"Ô ở cột A, hàng 5","h":"Địa chỉ ô viết theo dạng: chữ cái cột trước, số hàng sau.","e":"Địa chỉ ô gồm tên cột viết trước và số hàng viết sau, nên A5 là ô thuộc cột A, hàng 5.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong phần mềm bảng tính, một công thức luôn bắt đầu bằng kí tự nào?","o":["Dấu +","Dấu =","Dấu #","Dấu @"],"a":"Dấu =","h":"Đây là quy ước bắt buộc để phần mềm hiểu đó là công thức.","e":"Mọi công thức trong bảng tính đều bắt đầu bằng dấu =, sau đó là các toán hạng và phép toán.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Hàm SUM trong phần mềm bảng tính dùng để làm gì?","o":["Tính giá trị trung bình","Tính tổng các số","Tìm số lớn nhất","Đếm số ô có dữ liệu"],"a":"Tính tổng các số","h":"SUM trong tiếng Anh có nghĩa là 'tổng'.","e":"Hàm SUM dùng để tính tổng các giá trị số trong một vùng ô.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Hàm AVERAGE trong phần mềm bảng tính dùng để làm gì?","o":["Tính tổng các số","Tính giá trị trung bình cộng của các số","Tìm số nhỏ nhất","Sắp xếp dữ liệu"],"a":"Tính giá trị trung bình cộng của các số","h":"AVERAGE trong tiếng Anh có nghĩa là 'trung bình'.","e":"Hàm AVERAGE tính trung bình cộng của các giá trị trong vùng ô được chọn.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Hành vi nào sau đây thể hiện ứng xử văn minh trên mạng xã hội?","o":["Chia sẻ ngay mọi tin tức giật gân chưa kiểm chứng","Dùng lời lẽ xúc phạm người khác khi tranh luận","Kiểm chứng thông tin trước khi chia sẻ và tôn trọng người khác","Đăng ảnh của bạn bè mà không cần hỏi ý kiến"],"a":"Kiểm chứng thông tin trước khi chia sẻ và tôn trọng người khác","h":"Hãy nghĩ về trách nhiệm của mình với mỗi bài đăng.","e":"Ứng xử văn minh trên mạng gồm: kiểm chứng thông tin, tôn trọng người khác và không phát tán tin giả.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Trong thuật toán, bước 'Nếu điểm kiểm tra từ 5 trở lên thì xếp loại Đạt, ngược lại xếp loại Chưa đạt' thuộc cấu trúc nào?","o":["Cấu trúc tuần tự","Cấu trúc rẽ nhánh","Cấu trúc lặp","Cấu trúc lưu trữ"],"a":"Cấu trúc rẽ nhánh","h":"Thuật toán phải chọn một trong hai hướng tùy theo điều kiện.","e":"Khi việc thực hiện bước tiếp theo phụ thuộc vào một điều kiện đúng hay sai, đó là cấu trúc rẽ nhánh.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Thiết bị nào sau đây vừa là thiết bị vào, vừa là thiết bị ra?","o":["Chuột máy tính","Màn hình cảm ứng","Máy in","Bàn phím"],"a":"Màn hình cảm ứng","h":"Thiết bị này vừa hiển thị thông tin, vừa nhận lệnh chạm của người dùng.","e":"Màn hình cảm ứng vừa hiển thị thông tin (thiết bị ra) vừa nhận thao tác chạm để đưa lệnh vào (thiết bị vào).","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Trong bảng tính, giá trị của công thức =MAX(3, 7, 5) + MIN(3, 7, 5) là bao nhiêu?","o":["8","10","12","15"],"a":"10","h":"Tìm số lớn nhất và số nhỏ nhất trong ba số rồi cộng lại.","e":"MAX(3, 7, 5) = 7 và MIN(3, 7, 5) = 3, nên kết quả là 7 + 3 = 10.","t":"tin-lop7","g":7,"l":"kho"},{"p":"Hàm IF trong phần mềm bảng tính dùng để làm gì?","o":["Tính tổng một vùng dữ liệu","Kiểm tra một điều kiện và trả về giá trị tương ứng với điều kiện đúng hoặc sai","Vẽ biểu đồ cho dữ liệu","Định dạng màu cho ô tính"],"a":"Kiểm tra một điều kiện và trả về giá trị tương ứng với điều kiện đúng hoặc sai","h":"IF trong tiếng Anh có nghĩa là 'nếu'.","e":"Hàm IF kiểm tra điều kiện: nếu điều kiện đúng thì trả về một giá trị, nếu sai thì trả về giá trị khác.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Biểu đồ cột thường được dùng với mục đích chính nào?","o":["Thể hiện tỉ lệ phần trăm của một tổng thể","So sánh dữ liệu giữa các đối tượng","Thể hiện sự thay đổi theo thời gian liên tục","Trang trí cho trang tính"],"a":"So sánh dữ liệu giữa các đối tượng","h":"Chiều cao của các cột giúp ta nhìn ra ngay đối tượng nào hơn kém nhau.","e":"Biểu đồ cột dùng để so sánh số liệu giữa các đối tượng; biểu đồ quạt tròn dùng để thể hiện tỉ lệ phần trăm.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Hành vi nào sau đây vi phạm bản quyền trong môi trường số?","o":["Mua phần mềm có bản quyền để sử dụng","Sao chép phần mềm có bản quyền rồi chia sẻ trái phép cho nhiều người","Trích dẫn một đoạn ngắn và ghi rõ nguồn","Sử dụng phần mềm miễn phí theo đúng giấy phép"],"a":"Sao chép phần mềm có bản quyền rồi chia sẻ trái phép cho nhiều người","h":"Hãy tôn trọng công sức và quyền của tác giả sản phẩm số.","e":"Sao chép, phát tán sản phẩm số có bản quyền khi chưa được phép là hành vi vi phạm bản quyền.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Chức năng sắp xếp (Sort) dữ liệu trong bảng tính có tác dụng gì?","o":["Xoá bớt các hàng không cần thiết","Sắp xếp các hàng theo thứ tự tăng dần hoặc giảm dần của một cột dữ liệu","Đổi màu nền của bảng dữ liệu","Tạo biểu đồ từ dữ liệu"],"a":"Sắp xếp các hàng theo thứ tự tăng dần hoặc giảm dần của một cột dữ liệu","h":"Ví dụ: xếp danh sách học sinh theo điểm từ cao xuống thấp.","e":"Sắp xếp dữ liệu là bố trí lại các hàng theo thứ tự tăng dần hoặc giảm dần dựa trên giá trị của một cột.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Chức năng lọc (Filter) dữ liệu trong bảng tính dùng để làm gì?","o":["Tính tổng toàn bộ dữ liệu","Chỉ hiển thị các hàng thoả mãn điều kiện đặt ra, tạm ẩn các hàng còn lại","Sao chép dữ liệu sang trang tính khác","In dữ liệu ra giấy"],"a":"Chỉ hiển thị các hàng thoả mãn điều kiện đặt ra, tạm ẩn các hàng còn lại","h":"Ví dụ: chỉ xem những học sinh có điểm Toán từ 8 trở lên.","e":"Lọc dữ liệu giúp chỉ hiển thị các hàng thoả mãn điều kiện, các hàng không thoả mãn sẽ tạm thời bị ẩn đi.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Hành vi nào sau đây thể hiện đạo đức tốt khi tham gia môi trường số?","o":["Đăng ảnh của người khác khi chưa được đồng ý","Tôn trọng quyền riêng tư của người khác và không phát tán thông tin cá nhân của họ","Dùng tài khoản giả để nói xấu bạn bè","Tải lậu phim và phần mềm để tiết kiệm tiền"],"a":"Tôn trọng quyền riêng tư của người khác và không phát tán thông tin cá nhân của họ","h":"Hãy đối xử với người khác trên mạng như ngoài đời thực.","e":"Tôn trọng quyền riêng tư, không tự ý đăng tải thông tin hay hình ảnh của người khác là biểu hiện của đạo đức số.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Ô B2 chứa công thức =IF(A2>=5, \"Đạt\", \"Chưa đạt\"). Nếu ô A2 có giá trị 7 thì ô B2 hiển thị kết quả gì?","o":["Chưa đạt","Đạt","7","Báo lỗi công thức"],"a":"Đạt","h":"Kiểm tra xem điều kiện A2>=5 đúng hay sai khi A2 bằng 7.","e":"Vì 7 >= 5 là điều kiện đúng nên hàm IF trả về giá trị 'Đạt'.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trong Scratch, khối lệnh 'lặp lại 10 lần' (repeat 10) thuộc cấu trúc điều khiển nào?","o":["Cấu trúc tuần tự","Cấu trúc rẽ nhánh","Cấu trúc lặp","Cấu trúc gán"],"a":"Cấu trúc lặp","h":"Khối lệnh này thực hiện một nhóm lệnh nhiều lần.","e":"Khối 'lặp lại' cho phép thực hiện lặp đi lặp lại một nhóm lệnh, thuộc cấu trúc lặp.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trực quan hoá dữ liệu là gì?","o":["Nhập dữ liệu vào máy tính bằng bàn phím","Biểu diễn dữ liệu dưới dạng hình ảnh, biểu đồ để dễ quan sát, so sánh và hiểu","Xoá những dữ liệu không cần thiết","Sao lưu dữ liệu lên đám mây"],"a":"Biểu diễn dữ liệu dưới dạng hình ảnh, biểu đồ để dễ quan sát, so sánh và hiểu","h":"Một biểu đồ thường dễ hiểu hơn một bảng số dài.","e":"Trực quan hoá dữ liệu là dùng hình ảnh, biểu đồ để biểu diễn dữ liệu, giúp con người nắm bắt thông tin nhanh và rõ hơn.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Khi sử dụng một bức ảnh tìm được trên Internet cho bài đăng của mình, việc làm nào là đúng?","o":["Cứ dùng thoải mái vì ảnh đã công khai trên mạng","Ghi rõ nguồn và tôn trọng bản quyền của tác giả","Xoá tên tác giả đi để tránh rắc rối","Bán lại bức ảnh đó cho người khác"],"a":"Ghi rõ nguồn và tôn trọng bản quyền của tác giả","h":"Ảnh trên mạng vẫn thuộc về tác giả của nó.","e":"Khi dùng tác phẩm của người khác cần tôn trọng bản quyền, ghi nguồn rõ ràng hoặc xin phép khi cần thiết.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trong lập trình, biểu thức là gì?","o":["Một câu lệnh in kết quả ra màn hình","Tổ hợp các giá trị, biến và phép toán tạo ra một giá trị","Một loại nhân vật trong Scratch","Tên của một chương trình máy tính"],"a":"Tổ hợp các giá trị, biến và phép toán tạo ra một giá trị","h":"Ví dụ: (a + b) × 2 là một biểu thức.","e":"Biểu thức là sự kết hợp của các toán hạng (giá trị, biến) bằng các phép toán và cho ra một giá trị.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Để đếm số học sinh có điểm từ 8 trở lên trong vùng điểm D2:D31 của bảng tính, ta nên dùng hàm nào?","o":["SUM","COUNTIF","AVERAGE","MAX"],"a":"COUNTIF","h":"Cần một hàm vừa đếm, vừa xét điều kiện 'từ 8 trở lên'.","e":"Hàm COUNTIF đếm số ô thoả mãn một điều kiện cho trước, ví dụ COUNTIF(D2:D31,\">=8\").","t":"tin-lop9","g":9,"l":"kho"},{"p":"Trong Scratch, để nhân vật di chuyển liên tục cho đến khi chạm vào cạnh sân khấu mới dừng, ta nên dùng cấu trúc nào?","o":["Một lệnh di chuyển duy nhất","Vòng lặp cho đến khi điều kiện đúng (repeat until)","Câu lệnh rẽ nhánh một lần","Lệnh chờ (wait)"],"a":"Vòng lặp cho đến khi điều kiện đúng (repeat until)","h":"Việc di chuyển phải được kiểm tra điều kiện sau mỗi bước đi.","e":"Cấu trúc 'lặp cho đến khi' (repeat until) giúp lặp lại hành động và dừng lại khi điều kiện chạm cạnh được thoả mãn.","t":"tin-lop8","g":8,"l":"kho"},{"p":"Trong ngôn ngữ lập trình Python, lệnh print() dùng để làm gì?","o":["Nhập dữ liệu từ bàn phím","Hiển thị thông tin ra màn hình","Lưu chương trình vào tệp","Dừng chương trình ngay lập tức"],"a":"Hiển thị thông tin ra màn hình","h":"print trong tiếng Anh có nghĩa là 'in ra'.","e":"Lệnh print() dùng để đưa thông tin, kết quả ra màn hình.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong Python, lệnh input() dùng để làm gì?","o":["In kết quả ra màn hình","Nhận dữ liệu do người dùng nhập vào từ bàn phím","Tạo một biến mới có giá trị bằng 0","Vẽ hình trên màn hình"],"a":"Nhận dữ liệu do người dùng nhập vào từ bàn phím","h":"input trong tiếng Anh có nghĩa là 'đầu vào'.","e":"Lệnh input() tạm dừng để người dùng nhập dữ liệu từ bàn phím và đưa vào chương trình.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong lập trình, biến được dùng để làm gì?","o":["Lưu trữ giá trị để chương trình sử dụng và thay đổi khi cần","Trang trí giao diện chương trình","Kết nối chương trình với Internet","Bảo vệ chương trình khỏi virus"],"a":"Lưu trữ giá trị để chương trình sử dụng và thay đổi khi cần","h":"Biến giống một chiếc hộp có nhãn, chứa một giá trị.","e":"Biến là vùng nhớ được đặt tên, dùng để lưu giá trị phục vụ quá trình xử lí của chương trình.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Mật khẩu mạnh nên có đặc điểm nào sau đây?","o":["Chỉ gồm ngày tháng năm sinh của mình","Dài, gồm chữ hoa, chữ thường, chữ số và kí tự đặc biệt","Giống với tên tài khoản đăng nhập","Càng ngắn càng dễ nhớ"],"a":"Dài, gồm chữ hoa, chữ thường, chữ số và kí tự đặc biệt","h":"Trộn nhiều loại kí tự khiến mật khẩu khó bị đoán hơn.","e":"Mật khẩu mạnh cần đủ dài, kết hợp chữ hoa, chữ thường, số và kí tự đặc biệt, tránh dùng thông tin cá nhân.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Cơ sở dữ liệu là gì?","o":["Một phần mềm soạn thảo văn bản","Tập hợp dữ liệu được tổ chức, lưu trữ có hệ thống để tiện quản lí và khai thác","Một thiết bị phần cứng của máy tính","Một loại mạng máy tính"],"a":"Tập hợp dữ liệu được tổ chức, lưu trữ có hệ thống để tiện quản lí và khai thác","h":"Ví dụ: dữ liệu học sinh của một trường được tổ chức thành các bảng.","e":"Cơ sở dữ liệu là tập hợp dữ liệu có liên quan, được tổ chức và lưu trữ một cách hệ thống phục vụ quản lí, tra cứu.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong một bảng dữ liệu (ví dụ bảng danh sách học sinh), mỗi hàng của bảng thường biểu diễn điều gì?","o":["Một trường dữ liệu","Một bản ghi về một đối tượng cụ thể","Toàn bộ cơ sở dữ liệu","Một cột dữ liệu"],"a":"Một bản ghi về một đối tượng cụ thể","h":"Mỗi hàng ứng với thông tin của đúng một học sinh.","e":"Trong bảng dữ liệu, mỗi hàng là một bản ghi (record) chứa thông tin về một đối tượng, mỗi cột là một trường dữ liệu.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Phần mềm mô phỏng được sử dụng chủ yếu để làm gì?","o":["Soạn thảo văn bản nhanh hơn","Mô hình hoá một hiện tượng hay quá trình để quan sát và thử nghiệm một cách an toàn","Diệt virus cho máy tính","Nén dữ liệu để tiết kiệm bộ nhớ"],"a":"Mô hình hoá một hiện tượng hay quá trình để quan sát và thử nghiệm một cách an toàn","h":"Ví dụ: mô phỏng lái máy bay giúp phi công tập luyện mà không gặp nguy hiểm thật.","e":"Phần mềm mô phỏng tái hiện hiện tượng, quá trình trên máy tính, giúp học tập và thử nghiệm an toàn, tiết kiệm.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Công việc nào sau đây thuộc lĩnh vực nghề nghiệp tin học?","o":["Lập trình viên phát triển phần mềm","Thợ sửa chữa ô tô","Đầu bếp nhà hàng","Kiến trúc sư xây dựng"],"a":"Lập trình viên phát triển phần mềm","h":"Hãy chọn nghề trực tiếp làm việc với phần mềm và máy tính.","e":"Lập trình viên là nghề tiêu biểu trong lĩnh vực tin học, cùng với các nghề như quản trị mạng, phân tích dữ liệu,...","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong Python, giá trị \"Xin chào\" thuộc kiểu dữ liệu nào?","o":["Số nguyên","Số thực","Chuỗi kí tự","Danh sách"],"a":"Chuỗi kí tự","h":"Giá trị này được đặt trong dấu ngoặc kép.","e":"Giá trị văn bản đặt trong dấu ngoặc đơn hoặc ngoặc kép thuộc kiểu chuỗi kí tự (str).","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong Python, phép toán 7 // 2 cho kết quả bằng bao nhiêu?","o":["3.5","3","2","1"],"a":"3","h":"Dấu // là phép chia lấy phần nguyên.","e":"Phép toán // chia lấy phần nguyên, 7 chia 2 được 3 dư 1 nên kết quả là 3.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Dấu hiệu nào sau đây cho thấy một tin nhắn 'trúng thưởng' rất có thể là lừa đảo?","o":["Tin nhắn gửi từ số điện thoại của người thân","Yêu cầu bạn gửi mã OTP hoặc nộp một khoản tiền để được nhận quà","Tin nhắn chỉ thông báo mà không yêu cầu gì thêm","Tên đơn vị gửi tin được viết đúng chính tả"],"a":"Yêu cầu bạn gửi mã OTP hoặc nộp một khoản tiền để được nhận quà","h":"Không một giải thưởng thật nào bắt bạn nộp tiền hay lộ mã OTP.","e":"Kẻ lừa đảo thường yêu cầu nộp 'phí nhận thưởng' hoặc cung cấp mã OTP, mật khẩu — đây là dấu hiệu lừa đảo điển hình.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Trong bảng dữ liệu học sinh, các cột 'Họ và tên', 'Ngày sinh', 'Lớp' được gọi là gì?","o":["Các bản ghi","Các trường dữ liệu","Các bảng phụ","Các khoá chính"],"a":"Các trường dữ liệu","h":"Mỗi cột mô tả một thuộc tính của đối tượng.","e":"Mỗi cột trong bảng dữ liệu là một trường (field) mô tả một thuộc tính, ví dụ họ tên, ngày sinh, lớp.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Vòng lặp for trong lập trình thường được sử dụng hiệu quả nhất trong trường hợp nào?","o":["Khi không thể biết chương trình sẽ chạy bao lâu","Khi biết trước số lần cần lặp lại công việc","Khi chỉ cần kiểm tra một điều kiện duy nhất","Khi muốn chương trình dừng ngay lập tức"],"a":"Khi biết trước số lần cần lặp lại công việc","h":"Ví dụ: in bảng cửu chương 5 đúng 10 dòng.","e":"Vòng lặp for phù hợp khi số lần lặp đã biết trước; vòng lặp while phù hợp khi lặp theo điều kiện.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Cho đoạn chương trình Python: x = 5; x = x + 3; print(x). Chương trình in ra kết quả nào?","o":["5","3","8","x + 3"],"a":"8","h":"Hãy theo dõi giá trị của biến x qua từng lệnh.","e":"Ban đầu x = 5, lệnh x = x + 3 gán lại x = 5 + 3 = 8, nên print(x) in ra 8.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Ngoài việc đặt mật khẩu mạnh, biện pháp nào sau đây giúp bảo vệ tài khoản trực tuyến tốt nhất?","o":["Đăng nhập tài khoản trên càng nhiều máy càng tốt","Bật xác thực hai yếu tố cho tài khoản","Chia sẻ mật khẩu với bạn thân để nhờ giữ hộ","Tắt mọi thông báo đăng nhập lạ"],"a":"Bật xác thực hai yếu tố cho tài khoản","h":"Thêm một lớp bảo vệ ngoài mật khẩu, ví dụ mã gửi về điện thoại.","e":"Xác thực hai yếu tố thêm một lớp kiểm chứng ngoài mật khẩu, giúp tài khoản an toàn hơn nhiều kể cả khi lộ mật khẩu.","t":"tin-lop9","g":9,"l":"kho"},{"p":"Trí tuệ nhân tạo (AI) là lĩnh vực khoa học máy tính nhằm giúp máy tính thực hiện được những công việc nào?","o":["Những công việc vốn cần đến trí thông minh của con người","Chỉ những công việc tính toán đơn giản","Việc in ấn tài liệu","Việc lưu trữ tệp tin"],"a":"Những công việc vốn cần đến trí thông minh của con người","h":"Nghĩ tới các việc như nhận diện giọng nói, hình ảnh, trò chuyện.","e":"AI hướng tới giúp máy thực hiện các công việc cần trí thông minh như con người: học, suy luận, nhận dạng.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Ví dụ nào sau đây là ứng dụng của Internet vạn vật (IoT) trong đời sống?","o":["Đèn trong nhà được bật, tắt từ xa qua điện thoại","Máy tính để bàn dùng để soạn văn bản","Máy in phun mực in tài liệu","Ổ cứng di động để chép dữ liệu"],"a":"Đèn trong nhà được bật, tắt từ xa qua điện thoại","h":"IoT là các đồ vật kết nối Internet và điều khiển được từ xa.","e":"Đèn thông minh kết nối Internet, nhận lệnh từ điện thoại là một ứng dụng điển hình của IoT.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Dữ liệu lớn (Big Data) thường được nhắc đến với những đặc điểm nào?","o":["Khối lượng rất lớn, tốc độ tạo ra nhanh và dạng dữ liệu đa dạng","Chỉ gồm các con số trong một bảng tính","Luôn được lưu trên một máy tính duy nhất","Không cần qua xử lí vẫn dùng được ngay"],"a":"Khối lượng rất lớn, tốc độ tạo ra nhanh và dạng dữ liệu đa dạng","h":"Nhớ ba chữ V thường được nhắc tới: khối lượng, tốc độ, đa dạng.","e":"Dữ liệu lớn có khối lượng khổng lồ, sinh ra nhanh và đa dạng về dạng (văn bản, hình ảnh, video...).","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Mạng cục bộ (LAN) là mạng máy tính có phạm vi kết nối như thế nào?","o":["Trong một khu vực nhỏ như phòng học, văn phòng, cơ quan","Trên phạm vi toàn quốc","Trên phạm vi toàn thế giới","Giữa các châu lục với nhau"],"a":"Trong một khu vực nhỏ như phòng học, văn phòng, cơ quan","h":"Chữ L trong LAN là Local — cục bộ, phạm vi hẹp.","e":"LAN kết nối các máy tính trong phạm vi hẹp như một phòng, một toà nhà hay một cơ quan.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Địa chỉ IP trong mạng máy tính dùng để làm gì?","o":["Định danh một thiết bị khi tham gia vào mạng","Tăng tốc độ xử lí của máy tính","Lưu trữ dữ liệu cho người dùng","Dịch nội dung trang web sang tiếng Việt"],"a":"Định danh một thiết bị khi tham gia vào mạng","h":"Giống như số nhà để thư được gửi đến đúng nơi.","e":"Mỗi thiết bị tham gia mạng có một địa chỉ IP để các thiết bị khác nhận diện và gửi dữ liệu tới.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Hệ điều hành là phần mềm có vai trò gì?","o":["Quản lí, điều khiển phần cứng và làm nền cho các phần mềm khác hoạt động","Dùng để chơi trò chơi điện tử","Dùng để soạn thảo văn bản","Dùng để lướt web và xem video"],"a":"Quản lí, điều khiển phần cứng và làm nền cho các phần mềm khác hoạt động","h":"Windows, Android, iOS đều là các hệ điều hành quen thuộc.","e":"Hệ điều hành quản lí phần cứng, điều phối tài nguyên và tạo môi trường cho các phần mềm ứng dụng chạy.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong ngôn ngữ lập trình Python, để hiển thị kết quả ra màn hình ta dùng lệnh nào?","o":["print()","write()","show()","display()"],"a":"print()","h":"Lệnh này trong tiếng Anh có nghĩa là 'in ra'.","e":"Python dùng hàm print() để đưa dữ liệu ra màn hình.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Hành vi nào sau đây vi phạm bản quyền phần mềm?","o":["Sao chép, chia sẻ phần mềm có bản quyền khi chưa được chủ sở hữu cho phép","Mua phần mềm bản quyền để sử dụng","Dùng phần mềm mã nguồn mở theo đúng giấy phép của nó","Tự viết một phần mềm của riêng mình"],"a":"Sao chép, chia sẻ phần mềm có bản quyền khi chưa được chủ sở hữu cho phép","h":"Bản quyền là quyền của tác giả/chủ sở hữu đối với sản phẩm của họ.","e":"Sao chép và phát tán phần mềm có bản quyền trái phép là hành vi xâm phạm bản quyền.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Hệ thống tên miền DNS có nhiệm vụ chính là gì?","o":["Chuyển đổi tên miền thành địa chỉ IP tương ứng","Bảo vệ máy tính khỏi virus","Nén dữ liệu để truyền nhanh hơn","Tăng dung lượng cho ổ cứng"],"a":"Chuyển đổi tên miền thành địa chỉ IP tương ứng","h":"Nhờ DNS ta chỉ cần nhớ tên như google.com thay vì dãy số IP.","e":"DNS phân giải tên miền (dễ nhớ với con người) thành địa chỉ IP để máy tính kết nối đúng máy chủ.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Giao thức trong mạng máy tính được hiểu là gì?","o":["Tập hợp các quy tắc mà các thiết bị tuân theo để trao đổi dữ liệu với nhau","Một loại cáp dùng để nối mạng","Tên gọi của một hãng sản xuất máy tính","Một phần mềm soạn thảo văn bản"],"a":"Tập hợp các quy tắc mà các thiết bị tuân theo để trao đổi dữ liệu với nhau","h":"Giống như hai người muốn nói chuyện thì phải chung một 'luật' giao tiếp.","e":"Giao thức là tập hợp quy tắc, quy ước về định dạng và cách truyền dữ liệu giữa các thiết bị trong mạng.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về Internet vạn vật (IoT)?","o":["Các đồ vật được gắn cảm biến, kết nối Internet để thu thập và trao đổi dữ liệu","IoT chỉ áp dụng cho máy tính để bàn","IoT hoạt động mà không cần kết nối mạng","IoT là tên một trò chơi trực tuyến nhiều người chơi"],"a":"Các đồ vật được gắn cảm biến, kết nối Internet để thu thập và trao đổi dữ liệu","h":"Hãy nghĩ tới đồng hồ thông minh, camera, nhà thông minh.","e":"IoT kết nối các đồ vật có cảm biến qua Internet để chúng thu thập, trao đổi dữ liệu và phục vụ con người.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong Python, câu lệnh rẽ nhánh (điều kiện) bắt đầu bằng từ khoá nào?","o":["if","when","check","case"],"a":"if","h":"Từ khoá này trong tiếng Anh có nghĩa là 'nếu'.","e":"Python dùng từ khoá if để bắt đầu câu lệnh điều kiện, kèm theo else/elif khi cần.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Cho đoạn chương trình Python: s = 0; for i in range(1, 5): s = s + i; print(s). Kết quả in ra là bao nhiêu?","o":["10","6","15","4"],"a":"10","h":"Vòng lặp cho i chạy qua các số 1, 2, 3, 4 và cộng dồn vào s.","e":"s = 1 + 2 + 3 + 4 = 10 (range(1, 5) cho các giá trị 1 đến 4).","t":"tin-lop10","g":10,"l":"kho"},{"p":"Khi một trang web sử dụng giao thức HTTPS thay vì HTTP, điểm khác biệt chính là gì?","o":["Dữ liệu truyền đi được mã hoá nên an toàn hơn","Trang web luôn tải nhanh hơn trong mọi trường hợp","Người dùng không cần mật khẩu khi đăng nhập","Trang web được truy cập hoàn toàn miễn phí"],"a":"Dữ liệu truyền đi được mã hoá nên an toàn hơn","h":"Chữ S trong HTTPS là Secure — an toàn.","e":"HTTPS bổ sung khả năng mã hoá đường truyền, giúp dữ liệu trao đổi giữa người dùng và máy chủ an toàn hơn HTTP.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Cơ sở dữ liệu (CSDL) là gì?","o":["Tập hợp dữ liệu có liên quan với nhau, được tổ chức và lưu trữ để phục vụ khai thác, quản lí","Một phần mềm dùng để soạn thảo văn bản","Một thiết bị dùng để lưu trữ dữ liệu","Một ngôn ngữ lập trình phổ biến"],"a":"Tập hợp dữ liệu có liên quan với nhau, được tổ chức và lưu trữ để phục vụ khai thác, quản lí","h":"Ví dụ: dữ liệu học sinh của một trường được tổ chức thành các bảng liên quan.","e":"CSDL là tập hợp dữ liệu có liên quan, được tổ chức theo cấu trúc nhất định để lưu trữ và khai thác hiệu quả.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong một bảng dữ liệu của CSDL, mỗi hàng (dòng) của bảng được gọi là gì?","o":["Bản ghi","Trường","Khoá chính","Tệp dữ liệu"],"a":"Bản ghi","h":"Mỗi hàng chứa thông tin về một đối tượng cụ thể, ví dụ một học sinh.","e":"Mỗi hàng trong bảng là một bản ghi, lưu thông tin đầy đủ về một đối tượng.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Khoá chính của một bảng dữ liệu có vai trò gì?","o":["Giúp phân biệt các bản ghi với nhau, mỗi bản ghi có giá trị khoá chính riêng","Giúp sắp xếp các bản ghi theo thứ tự bảng chữ cái","Giúp tô màu cho bảng dữ liệu đẹp hơn","Giúp xoá bỏ các dữ liệu không cần thiết"],"a":"Giúp phân biệt các bản ghi với nhau, mỗi bản ghi có giá trị khoá chính riêng","h":"Ví dụ: mã học sinh — mỗi học sinh có một mã duy nhất.","e":"Khoá chính gồm một hoặc một số trường mà giá trị của chúng xác định duy nhất mỗi bản ghi trong bảng.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Microsoft Access là phần mềm thuộc loại nào?","o":["Hệ quản trị cơ sở dữ liệu","Trình duyệt web","Phần mềm chỉnh sửa ảnh","Hệ điều hành"],"a":"Hệ quản trị cơ sở dữ liệu","h":"Đây là phần mềm của Microsoft dùng để tạo và quản lí các bảng dữ liệu.","e":"Access là hệ quản trị CSDL phổ biến, cho phép tạo bảng, truy vấn, biểu mẫu và báo cáo.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong Python, một danh sách (list) được viết trong cặp dấu nào?","o":["Dấu ngoặc vuông [ ]","Dấu ngoặc tròn ( )","Dấu ngoặc nhọn { }","Dấu nháy kép \" \""],"a":"Dấu ngoặc vuông [ ]","h":"Ví dụ: diem = [8, 9, 10].","e":"Danh sách trong Python được khai báo bằng cặp dấu ngoặc vuông, các phần tử cách nhau bởi dấu phẩy.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Để định nghĩa một hàm trong Python, ta dùng từ khoá nào?","o":["def","func","function","proc"],"a":"def","h":"Từ khoá này viết tắt của 'define' — định nghĩa.","e":"Python dùng từ khoá def để khai báo hàm, theo sau là tên hàm và các tham số.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Việc đặt mật khẩu mạnh và thường xuyên cập nhật phần mềm đem lại lợi ích gì?","o":["Giúp tăng tính an toàn, bảo mật cho dữ liệu và tài khoản","Giúp máy tính chạy nhanh gấp đôi","Giúp màn hình hiển thị sáng hơn","Giúp tăng dung lượng ổ cứng miễn phí"],"a":"Giúp tăng tính an toàn, bảo mật cho dữ liệu và tài khoản","h":"Mật khẩu dễ đoán và phần mềm lỗi thời là cửa ngõ cho kẻ xấu.","e":"Mật khẩu mạnh khó bị dò đoán; cập nhật phần mềm giúp vá các lỗ hổng bảo mật đã biết.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Công việc nào sau đây thuộc lĩnh vực tin học?","o":["Lập trình viên phát triển phần mềm","Kĩ sư xây dựng cầu đường","Bác sĩ khám chữa bệnh","Đầu bếp nhà hàng"],"a":"Lập trình viên phát triển phần mềm","h":"Hãy chọn công việc gắn trực tiếp với máy tính và phần mềm.","e":"Lập trình viên là nghề tiêu biểu trong lĩnh vực công nghệ thông tin/tin học.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong ngôn ngữ truy vấn SQL, câu lệnh SELECT dùng để làm gì?","o":["Truy xuất (lấy) dữ liệu từ các bảng trong CSDL","Xoá hẳn một bảng dữ liệu","Tạo tài khoản người dùng mới","Sao lưu toàn bộ CSDL ra ổ cứng"],"a":"Truy xuất (lấy) dữ liệu từ các bảng trong CSDL","h":"SELECT trong tiếng Anh có nghĩa là 'chọn/lấy ra'.","e":"SELECT là câu lệnh dùng để chọn và lấy ra những dữ liệu cần thiết từ một hay nhiều bảng.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong bảng dữ liệu, 'trường' (field) được hiểu là gì?","o":["Một cột của bảng, thể hiện một thuộc tính của đối tượng","Một hàng của bảng dữ liệu","Toàn bộ bảng dữ liệu","Một tệp tin chứa dữ liệu"],"a":"Một cột của bảng, thể hiện một thuộc tính của đối tượng","h":"Ví dụ bảng Học sinh có các cột: Họ tên, Ngày sinh, Lớp...","e":"Mỗi cột của bảng là một trường, lưu một thuộc tính chung của tất cả các đối tượng trong bảng.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong Python, biểu thức len(\"Tin hoc\") cho kết quả bằng bao nhiêu?","o":["7","6","8","5"],"a":"7","h":"Hãy đếm từng kí tự trong chuỗi, kể cả dấu cách.","e":"Chuỗi \"Tin hoc\" gồm 7 kí tự: T, i, n, dấu cách, h, o, c.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Thao tác 'lọc dữ liệu' trong CSDL có nghĩa là gì?","o":["Chọn ra những bản ghi thoả mãn một điều kiện nào đó","Xoá toàn bộ dữ liệu của bảng","In toàn bộ bảng ra giấy","Đổi tên cho bảng dữ liệu"],"a":"Chọn ra những bản ghi thoả mãn một điều kiện nào đó","h":"Ví dụ: chỉ hiện những học sinh có điểm trung bình từ 8 trở lên.","e":"Lọc dữ liệu là hiển thị/chọn ra các bản ghi đáp ứng điều kiện đặt ra, ví dụ điểm ≥ 8.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Hệ quản trị cơ sở dữ liệu (HQTCSDL) là phần mềm dùng để làm gì?","o":["Tạo lập, lưu trữ, cập nhật và khai thác CSDL","Soạn thảo văn bản và trình chiếu","Nghe nhạc và xem phim","Lướt web và gửi thư điện tử"],"a":"Tạo lập, lưu trữ, cập nhật và khai thác CSDL","h":"Access, MySQL, SQL Server là những ví dụ của loại phần mềm này.","e":"HQTCSDL là phần mềm giúp người dùng tạo lập CSDL, thêm/sửa/xoá dữ liệu và truy vấn khai thác thông tin.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Cho đoạn chương trình Python: a = [2, 4, 6]; a.append(8); print(len(a)). Kết quả in ra là bao nhiêu?","o":["4","3","5","8"],"a":"4","h":"append() thêm một phần tử vào cuối danh sách.","e":"Danh sách ban đầu có 3 phần tử, thêm số 8 thành 4 phần tử nên len(a) bằng 4.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Câu truy vấn: SELECT * FROM HOCSINH WHERE Diem >= 8 có tác dụng gì?","o":["Lấy mọi thông tin của những học sinh có điểm từ 8 trở lên","Xoá những học sinh có điểm dưới 8","Sắp xếp học sinh theo thứ tự điểm giảm dần","Thêm một học sinh mới vào bảng"],"a":"Lấy mọi thông tin của những học sinh có điểm từ 8 trở lên","h":"Chú ý mệnh đề WHERE — đó là điều kiện chọn bản ghi.","e":"SELECT * lấy tất cả các trường; WHERE Diem >= 8 chỉ giữ lại các bản ghi có điểm từ 8 trở lên.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Học máy (Machine Learning) là cách tiếp cận trong đó máy tính làm gì?","o":["Tự học từ dữ liệu để thực hiện nhiệm vụ tốt dần lên mà không cần lập trình chi tiết từng bước","Được con người viết sẵn mọi tình huống có thể xảy ra","Chỉ biết lưu trữ dữ liệu mà không xử lí","Hoạt động hoàn toàn không cần dữ liệu"],"a":"Tự học từ dữ liệu để thực hiện nhiệm vụ tốt dần lên mà không cần lập trình chi tiết từng bước","h":"Ví dụ: cho máy xem nhiều ảnh mèo, máy dần tự nhận ra mèo.","e":"Học máy cho phép máy tính rút ra quy luật từ dữ liệu mẫu để dự đoán, phân loại các dữ liệu mới.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Mã độc (phần mềm độc hại) có thể lây nhiễm vào máy tính qua con đường nào?","o":["Tệp đính kèm lạ, phần mềm không rõ nguồn gốc, USB đã nhiễm độc","Việc gõ bàn phím thường xuyên","Việc tắt máy đúng quy trình","Việc dùng chuột và màn hình chính hãng"],"a":"Tệp đính kèm lạ, phần mềm không rõ nguồn gốc, USB đã nhiễm độc","h":"Hãy cảnh giác với những tệp không rõ nguồn gốc được gửi tới.","e":"Mã độc thường ẩn trong tệp đính kèm lạ, phần mềm bẻ khoá/không rõ nguồn và thiết bị lưu trữ nhiễm độc.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Ứng dụng nào sau đây có sử dụng trí tuệ nhân tạo?","o":["Trợ lí ảo trên điện thoại nhận diện giọng nói để trả lời câu hỏi","Chiếc bút bi thông thường dùng để viết","Đồng hồ cơ đeo tay lên dây cót","Chiếc xe đạp không có thiết bị điện tử"],"a":"Trợ lí ảo trên điện thoại nhận diện giọng nói để trả lời câu hỏi","h":"Ứng dụng AI thường 'nghe, hiểu' hoặc 'nhìn, nhận biết' được.","e":"Trợ lí ảo dùng AI để nhận dạng tiếng nói và hiểu ngôn ngữ tự nhiên của người dùng.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong bệnh viện, cơ sở dữ liệu được ứng dụng chủ yếu để làm gì?","o":["Lưu trữ và tra cứu hồ sơ bệnh án của bệnh nhân","Trang trí phòng khám cho đẹp hơn","Thay thế hoàn toàn bác sĩ trong khám bệnh","In hoá đơn bán thuốc lá lẻ"],"a":"Lưu trữ và tra cứu hồ sơ bệnh án của bệnh nhân","h":"Nhờ CSDL, bác sĩ xem lại được tiền sử bệnh của bệnh nhân rất nhanh.","e":"CSDL giúp bệnh viện quản lí hồ sơ bệnh án, lịch khám, kết quả xét nghiệm một cách khoa học và tra cứu nhanh.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Khi sử dụng mạng xã hội, hành vi nào thể hiện văn hoá số đúng đắn?","o":["Kiểm chứng thông tin trước khi chia sẻ cho người khác","Chia sẻ ngay mọi tin giật gân chưa rõ đúng sai","Bình luận xúc phạm người không cùng quan điểm","Đăng công khai thông tin cá nhân của người khác"],"a":"Kiểm chứng thông tin trước khi chia sẻ cho người khác","h":"Tin giả lan nhanh phần lớn do người dùng chia sẻ vội vàng.","e":"Người dùng văn minh cần kiểm chứng nguồn tin, tránh lan truyền tin giả gây hại cho cộng đồng.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Phát biểu nào sau đây đúng về hạn chế của trí tuệ nhân tạo hiện nay?","o":["AI chưa thể thay thế hoàn toàn con người trong các công việc cần cảm xúc, kinh nghiệm sống và sáng tạo sâu sắc","AI luôn cho kết quả đúng tuyệt đối trong mọi trường hợp","AI hoạt động không cần bất kì dữ liệu nào","AI hiểu được mọi ngôn ngữ và văn hoá như con người"],"a":"AI chưa thể thay thế hoàn toàn con người trong các công việc cần cảm xúc, kinh nghiệm sống và sáng tạo sâu sắc","h":"AI rất mạnh ở xử lí dữ liệu nhưng còn yếu ở cảm xúc và kinh nghiệm sống.","e":"AI hiện nay mạnh trong các nhiệm vụ có dữ liệu rõ ràng, nhưng còn hạn chế về cảm xúc, kinh nghiệm và phán đoán như con người.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Xác thực hai yếu tố (mật khẩu kèm mã xác nhận gửi về điện thoại) giúp ích gì cho tài khoản trực tuyến?","o":["Tăng độ an toàn, kẻ xấu biết mật khẩu vẫn khó đăng nhập được","Giúp đăng nhập nhanh hơn không cần thao tác gì thêm","Giúp tài khoản không bao giờ bị quên mật khẩu","Giúp tăng dung lượng lưu trữ của tài khoản"],"a":"Tăng độ an toàn, kẻ xấu biết mật khẩu vẫn khó đăng nhập được","h":"Đây là thêm một 'lớp khoá' nữa ngoài mật khẩu.","e":"Xác thực hai yếu tố buộc người đăng nhập có thêm mã xác nhận, nên tài khoản an toàn hơn hẳn.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Người làm việc trong lĩnh vực tin học cần có phẩm chất nào sau đây?","o":["Tư duy logic, cẩn thận và luôn ham học hỏi công nghệ mới","Chỉ cần thuộc lòng một ngôn ngữ lập trình là đủ","Không cần làm việc nhóm hay giao tiếp với ai","Ngại thay đổi, chỉ dùng những gì đã quen"],"a":"Tư duy logic, cẩn thận và luôn ham học hỏi công nghệ mới","h":"Công nghệ thay đổi rất nhanh nên người làm tin học phải liên tục cập nhật.","e":"Tư duy logic, tính cẩn thận và tinh thần tự học là những phẩm chất quan trọng của nghề tin học.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Điểm khác biệt cơ bản giữa học máy và lập trình truyền thống là gì?","o":["Học máy để máy tự rút ra quy luật từ dữ liệu, còn lập trình truyền thống do con người viết sẵn mọi quy tắc","Học máy không dùng đến máy tính","Lập trình truyền thống luôn cho kết quả nhanh hơn học máy","Học máy chỉ dùng cho trò chơi điện tử"],"a":"Học máy để máy tự rút ra quy luật từ dữ liệu, còn lập trình truyền thống do con người viết sẵn mọi quy tắc","h":"Một bên 'dạy bằng ví dụ', một bên 'viết luật chi tiết'.","e":"Trong lập trình truyền thống, con người định sẵn quy tắc; trong học máy, mô hình tự học quy luật từ dữ liệu mẫu.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"'Phần mềm độc hại' (malware) là tên gọi chung cho các chương trình như thế nào?","o":["Được tạo ra với mục đích xấu như đánh cắp dữ liệu, phá hoại hoặc chiếm quyền điều khiển hệ thống","Được cài sẵn theo máy để hỗ trợ người dùng","Dùng để tăng tốc độ mạng cho máy tính","Dùng để sao lưu dữ liệu an toàn"],"a":"Được tạo ra với mục đích xấu như đánh cắp dữ liệu, phá hoại hoặc chiếm quyền điều khiển hệ thống","h":"Virus, sâu máy tính, mã độc tống tiền đều thuộc nhóm này.","e":"Malware là các chương trình có hại như virus, worm, trojan, ransomware... gây tổn hại cho hệ thống và người dùng.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Biện pháp nào sau đây giúp phòng tránh mã độc hiệu quả?","o":["Cài phần mềm diệt virus, cập nhật hệ điều hành và không mở tệp, đường liên kết lạ","Tắt mọi phần mềm bảo vệ để máy chạy nhẹ hơn","Mở thử mọi tệp đính kèm để kiểm tra nội dung","Dùng chung một mật khẩu đơn giản cho mọi tài khoản"],"a":"Cài phần mềm diệt virus, cập nhật hệ điều hành và không mở tệp, đường liên kết lạ","h":"Phòng bệnh hơn chữa bệnh — hãy nghĩ tới các thói quen an toàn hằng ngày.","e":"Kết hợp phần mềm diệt virus, cập nhật bản vá và thận trọng với tệp/link lạ là cách phòng tránh mã độc hiệu quả.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Khi sử dụng kết quả do AI tạo ra (bài viết, hình ảnh), trách nhiệm của người dùng là gì?","o":["Kiểm tra lại độ tin cậy của kết quả và chịu trách nhiệm về nội dung mình sử dụng, chia sẻ","Cứ dùng và chia sẻ ngay vì AI luôn đúng","Không cần quan tâm vì lỗi là do AI chịu trách nhiệm","Chỉ cần ghi nguồn 'do AI làm' là đủ mọi trách nhiệm"],"a":"Kiểm tra lại độ tin cậy của kết quả và chịu trách nhiệm về nội dung mình sử dụng, chia sẻ","h":"AI có thể tạo ra thông tin sai trông rất thuyết phục.","e":"Kết quả AI có thể sai hoặc bịa đặt; người dùng phải kiểm chứng và chịu trách nhiệm về nội dung mình dùng.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Việc ứng dụng cơ sở dữ liệu trong ngân hàng đem lại lợi ích gì nổi bật?","o":["Quản lí thông tin khách hàng, tài khoản và giao dịch chính xác, tra cứu nhanh chóng","Giúp ngân hàng không cần nhân viên nữa","Giúp khách hàng không cần nhớ số tài khoản khi giao dịch ở nhà","Tự động tăng số tiền trong tài khoản khách hàng"],"a":"Quản lí thông tin khách hàng, tài khoản và giao dịch chính xác, tra cứu nhanh chóng","h":"Mỗi ngày ngân hàng xử lí hàng triệu giao dịch — không thể quản lí bằng giấy tờ.","e":"CSDL giúp ngân hàng lưu trữ và xử lí lượng lớn dữ liệu khách hàng, giao dịch một cách chính xác, an toàn và tức thời.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Một mô hình AI được huấn luyện gần như chỉ bằng ảnh mèo. Khi đưa ảnh chó vào, nó phân loại rất kém. Hiện tượng này cho thấy điều gì?","o":["Chất lượng của mô hình học máy phụ thuộc nhiều vào dữ liệu dùng để huấn luyện","Máy tính bị hỏng phần cứng","AI có thể tự hiểu mọi loài vật mà không cần học","Dữ liệu huấn luyện không ảnh hưởng gì tới kết quả của AI"],"a":"Chất lượng của mô hình học máy phụ thuộc nhiều vào dữ liệu dùng để huấn luyện","h":"Máy chỉ 'biết' những gì đã được học từ dữ liệu.","e":"Mô hình học máy chỉ làm tốt với dữ liệu tương tự dữ liệu huấn luyện; dữ liệu thiếu đa dạng khiến kết quả kém.","t":"tin-lop12","g":12,"l":"kho"},{"p":"Bạn nhận được thư điện tử lạ giả danh ngân hàng, yêu cầu bấm vào đường liên kết để 'xác minh tài khoản kẻo bị khoá'. Cách xử lí đúng nhất là gì?","o":["Không bấm vào liên kết; tự truy cập trang web chính thức của ngân hàng hoặc gọi tổng đài để kiểm tra","Bấm ngay vào liên kết và nhập mật khẩu cho kịp thời hạn","Chuyển tiếp thư cho bạn bè để mọi người cùng xác minh","Trả lời thư và hỏi lại người gửi có phải ngân hàng thật không"],"a":"Không bấm vào liên kết; tự truy cập trang web chính thức của ngân hàng hoặc gọi tổng đài để kiểm tra","h":"Đây là chiêu lừa đảo 'phishing' rất phổ biến nhằm đánh cắp tài khoản.","e":"Thư giả mạo ngân hàng là hình thức lừa đảo phổ biến; cần liên hệ ngân hàng qua kênh chính thức thay vì làm theo liên kết trong thư.","t":"tin-lop12","g":12,"l":"kho"},{"p":"Em nghe dự báo thời tiết trên tivi nói chiều nay trời sẽ mưa. Để không bị ướt khi đi học về, em nên làm gì?","o":["Mang theo áo mưa hoặc ô","Mặc thêm áo ấm thật dày","Mang theo quạt cầm tay","Đội mũ lưỡi trai"],"a":"Mang theo áo mưa hoặc ô","h":"Thông tin nghe được sẽ giúp em quyết định mang theo thứ gì cho phù hợp.","e":"Thông tin từ dự báo thời tiết giúp em quyết định mang áo mưa hoặc ô để không bị ướt.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em biết được tin 'ngày mai lớp mình được nghỉ học' là nhờ đâu?","o":["Nghe thầy cô thông báo","Tự đoán trong đầu","Nhìn lên bầu trời","Ngủ mơ thấy"],"a":"Nghe thầy cô thông báo","h":"Ai là người thông báo tin tức của lớp cho em?","e":"Em nhận được thông tin về việc nghỉ học khi nghe thầy cô thông báo.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Mỗi ngày em nghe thầy cô giảng bài, nhìn tranh ảnh và đọc sách. Những điều em thu nhận được như vậy gọi là gì?","o":["Thông tin","Đồ dùng học tập","Trò chơi","Bài tập về nhà"],"a":"Thông tin","h":"Nhờ nghe, nhìn và đọc, em biết thêm nhiều điều mới.","e":"Những gì em thu nhận được qua nghe, nhìn, đọc giúp em hiểu biết về xung quanh được gọi là thông tin.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Người lái xe nhìn thấy đèn giao thông chuyển sang màu đỏ thì dừng xe lại. Thông tin giúp người lái xe quyết định dừng xe là gì?","o":["Màu đỏ của đèn giao thông","Tiếng còi xe phía sau","Màu sơn của chiếc xe","Số người trên vỉa hè"],"a":"Màu đỏ của đèn giao thông","h":"Người lái xe nhìn thấy điều gì trên cột đèn giao thông?","e":"Đèn đỏ là thông tin báo hiệu phải dừng xe, giúp người lái xe ra quyết định đúng.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Khi em gõ phím chữ A trên bàn phím, điều gì xảy ra?","o":["Chữ A hiện trên màn hình","Máy tính tự tắt","Chuột tự di chuyển","Loa phát ra nhạc"],"a":"Chữ A hiện trên màn hình","h":"Em hãy nhớ lại mỗi lần gõ phím khi soạn thảo.","e":"Em gõ phím là đưa thông tin vào, máy tính xử lí và cho kết quả là chữ hiện trên màn hình.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em nháy chuột và gõ phím để ra lệnh cho máy tính làm việc. Đó là bước nào trong cách máy tính làm việc?","o":["Đưa thông tin vào máy tính","Máy tính cho ra kết quả","Máy tính đang nghỉ","Tắt máy tính"],"a":"Đưa thông tin vào máy tính","h":"Chuột và bàn phím giúp em gửi lệnh vào trong máy.","e":"Nháy chuột và gõ phím là cách em đưa thông tin, ra lệnh cho máy tính.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Máy tính được coi là đang xử lí thông tin khi nào?","o":["Khi máy tính thực hiện lệnh, tính toán theo yêu cầu của em","Khi máy tính đã tắt hẳn","Khi màn hình bị tối đen","Khi em rời khỏi phòng máy"],"a":"Khi máy tính thực hiện lệnh, tính toán theo yêu cầu của em","h":"Việc xử lí diễn ra sau khi máy nhận được lệnh của em.","e":"Sau khi nhận thông tin vào, máy tính xử lí bằng cách thực hiện lệnh và tính toán để cho ra kết quả.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Em chọn bài hát yêu thích trên máy tính, loa phát ra tiếng nhạc. Tiếng nhạc từ loa là gì?","o":["Kết quả sau khi máy tính xử lí thông tin","Thông tin em đưa vào","Lệnh em gõ từ bàn phím","Một phần mềm vẽ tranh"],"a":"Kết quả sau khi máy tính xử lí thông tin","h":"Việc chọn bài hát là đưa vào, vậy tiếng nhạc phát ra thuộc bước cuối nào?","e":"Em chọn bài hát là đưa thông tin vào, máy tính xử lí và loa phát ra tiếng nhạc chính là kết quả.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Máy tính xử lí thông tin theo đúng thứ tự nào?","o":["Nhận thông tin → Xử lí → Cho ra kết quả","Cho ra kết quả → Nhận thông tin → Xử lí","Xử lí → Cho ra kết quả → Nhận thông tin","Nhận thông tin → Cho ra kết quả → Xử lí"],"a":"Nhận thông tin → Xử lí → Cho ra kết quả","h":"Máy phải nhận được lệnh trước, rồi mới làm việc và cho kết quả.","e":"Máy tính luôn làm việc theo ba bước: nhận thông tin vào, xử lí, rồi cho ra kết quả.","t":"tin-lop3","g":3,"l":"kho"},{"p":"Thiết bị số nào sau đây có thể xử lí thông tin như một chiếc máy tính nhỏ?","o":["Điện thoại thông minh","Chiếc quạt điện","Đèn bàn học","Cái gương soi"],"a":"Điện thoại thông minh","h":"Thiết bị nào có màn hình, chạy được phần mềm và nối mạng được?","e":"Điện thoại thông minh là thiết bị số có khả năng xử lí thông tin, chạy phần mềm giống như máy tính.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Đồng hồ thông minh khác đồng hồ thường ở điểm nào?","o":["Có thể xử lí thông tin, kết nối với điện thoại và hiện nhiều thông tin hơn","Chỉ khác ở màu của dây đeo","Có kim đồng hồ to hơn","Không cần đeo vào tay"],"a":"Có thể xử lí thông tin, kết nối với điện thoại và hiện nhiều thông tin hơn","h":"Chữ 'thông minh' cho thấy chiếc đồng hồ làm được thêm việc gì?","e":"Đồng hồ thông minh có thể xử lí thông tin như đếm bước chân, hiện thông báo và kết nối với điện thoại.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Máy tính bảng và điện thoại thông minh giống nhau ở điểm nào?","o":["Đều có màn hình cảm ứng và xử lí được thông tin","Đều chỉ dùng để gọi điện","Đều không cần sạc pin","Đều to bằng chiếc tivi"],"a":"Đều có màn hình cảm ứng và xử lí được thông tin","h":"Em thao tác trên hai thiết bị này bằng cách chạm tay vào đâu?","e":"Cả máy tính bảng và điện thoại thông minh đều có màn hình cảm ứng và khả năng xử lí thông tin.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Tivi thông minh (Smart TV) làm được việc gì mà tivi thường khó làm được?","o":["Kết nối Internet để xem phim, video trực tuyến","Tự nấu cơm cho em","Phát ra mùi thơm","Tự di chuyển ra sân"],"a":"Kết nối Internet để xem phim, video trực tuyến","h":"Nhờ kết nối mạng, tivi thông minh xem thêm được những gì?","e":"Tivi thông minh kết nối được Internet nên xem được phim và video trực tuyến theo yêu cầu.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Để chọn và mở các đối tượng trên màn hình, em thường dùng nút chuột nào?","o":["Nút chuột trái","Nút chuột phải","Con lăn chuột","Cả thân chuột"],"a":"Nút chuột trái","h":"Hầu hết thao tác nháy chuột đều dùng nút ở phía bên trái.","e":"Nút chuột trái là nút được dùng phổ biến nhất để chọn và mở đối tượng.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Con lăn (bánh xe cuộn) trên chuột dùng để làm gì?","o":["Cuộn trang lên hoặc xuống","Tắt máy tính","Tăng âm lượng loa","Đổi màu con trỏ chuột"],"a":"Cuộn trang lên hoặc xuống","h":"Khi đọc một trang dài, em lăn bánh xe này để xem tiếp nội dung.","e":"Con lăn chuột giúp em cuộn nội dung trang lên hoặc xuống một cách nhanh chóng.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Phím dài nhất trên bàn phím (phím Space) dùng để làm gì?","o":["Tạo dấu cách giữa các từ","Xoá chữ vừa gõ","Xuống dòng mới","Tắt màn hình"],"a":"Tạo dấu cách giữa các từ","h":"Giữa hai từ trong một câu luôn có một khoảng trống.","e":"Phím Space dùng để tạo khoảng cách (dấu cách) giữa các từ khi gõ văn bản.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em vừa gõ nhầm một chữ ở ngay trước con trỏ soạn thảo. Nhấn phím nào để xoá chữ đó?","o":["Phím Backspace","Phím Enter","Phím Shift","Phím Space"],"a":"Phím Backspace","h":"Có một phím chuyên dùng để xoá chữ ở phía bên trái con trỏ.","e":"Phím Backspace xoá kí tự ở phía bên trái con trỏ soạn thảo.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Khi gõ một bài thơ, muốn chuyển xuống dòng mới em nhấn phím nào?","o":["Phím Enter","Phím Backspace","Phím Shift","Con lăn chuột"],"a":"Phím Enter","h":"Đây là phím quen thuộc dùng để xuống dòng và thực hiện lệnh.","e":"Phím Enter dùng để xuống dòng khi soạn thảo và để thực hiện một lệnh.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Em giữ phím Shift rồi gõ phím chữ a. Kết quả trên màn hình sẽ là gì?","o":["Chữ A in hoa","Chữ a thường","Số 1","Một dấu cách"],"a":"Chữ A in hoa","h":"Phím Shift giúp đổi chữ thường thành dạng chữ nào?","e":"Giữ phím Shift trong khi gõ phím chữ sẽ cho ra chữ in hoa tương ứng.","t":"tin-lop3","g":3,"l":"kho"},{"p":"Trong phần mềm Paint, muốn tô kín một hình bằng một màu, em dùng công cụ nào?","o":["Công cụ đổ màu (thùng sơn)","Công cụ tẩy","Công cụ bút chì","Công cụ viết chữ"],"a":"Công cụ đổ màu (thùng sơn)","h":"Công cụ này có hình chiếc thùng đang nghiêng đổ sơn.","e":"Công cụ đổ màu (Fill with color) giúp tô kín một vùng hình bằng màu đã chọn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Vẽ xong bức tranh trong Paint, muốn giữ lại để lần sau xem tiếp, em phải làm gì?","o":["Lưu bức tranh vào máy tính","Tắt luôn máy tính","Đóng phần mềm mà không lưu","In thật nhiều bản ra giấy"],"a":"Lưu bức tranh vào máy tính","h":"Nếu không làm việc này, bức tranh sẽ bị mất khi em đóng phần mềm.","e":"Em cần lưu (Save) bức tranh vào máy tính thì lần sau mới mở ra xem và sửa tiếp được.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Muốn vẽ một hình tròn trong Paint, em chọn công cụ hình nào?","o":["Công cụ hình bầu dục (Oval)","Công cụ đường thẳng","Công cụ hình chữ nhật","Công cụ ngôi sao"],"a":"Công cụ hình bầu dục (Oval)","h":"Hình tròn là một dạng đặc biệt của hình bầu dục.","e":"Trong Paint, công cụ hình bầu dục (Oval) dùng để vẽ hình tròn và hình bầu dục.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Em vẽ sai một nét trong Paint và muốn xoá riêng nét đó. Em dùng công cụ nào?","o":["Công cụ tẩy (Eraser)","Công cụ đổ màu","Công cụ kính lúp","Công cụ bút vẽ"],"a":"Công cụ tẩy (Eraser)","h":"Công cụ này giống như cục tẩy em vẫn dùng trên giấy.","e":"Công cụ tẩy (Eraser) giúp xoá những nét vẽ sai trong bức tranh.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Muốn vẽ một đường thẳng thật thẳng trong Paint, cách nào sau đây là đúng?","o":["Chọn công cụ đường thẳng rồi kéo chuột","Vẽ tự do bằng bút chì thật nhanh","Dùng công cụ đổ màu","Nhấn phím Enter nhiều lần"],"a":"Chọn công cụ đường thẳng rồi kéo chuột","h":"Paint có sẵn một công cụ chuyên dùng để kẻ thẳng.","e":"Công cụ đường thẳng (Line) giúp em kẻ được đường thẳng đẹp, chỉ cần chọn công cụ rồi kéo chuột.","t":"tin-lop5","g":5,"l":"kho"},{"p":"Khi ngồi học với máy tính, mắt em nên cách màn hình khoảng bao nhiêu là hợp lí?","o":["Khoảng 50 đến 70 cm","Khoảng 10 cm","Càng sát màn hình càng tốt","Khoảng 3 mét"],"a":"Khoảng 50 đến 70 cm","h":"Khoảng cách này áng chừng bằng độ dài một cánh tay của em.","e":"Giữ mắt cách màn hình khoảng 50–70 cm giúp mắt đỡ mỏi và bảo vệ thị lực.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Dùng máy tính liên tục khoảng 20 – 30 phút, em nên làm gì để bảo vệ mắt?","o":["Nghỉ giải lao, đứng dậy vận động và nhìn ra xa","Tiếp tục dùng thêm cho xong việc","Nhìn chằm chằm vào màn hình lâu hơn","Tắt hết đèn phòng cho tối"],"a":"Nghỉ giải lao, đứng dậy vận động và nhìn ra xa","h":"Đôi mắt cũng cần được nghỉ ngơi như cơ thể em vậy.","e":"Sau 20–30 phút dùng máy tính, em nên nghỉ giải lao, nhìn ra xa và vận động nhẹ để mắt được thư giãn.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Tay em đang ướt, em có nên tự cắm phích điện của máy tính vào ổ điện không?","o":["Không, vì nước dẫn điện rất nguy hiểm","Có, miễn là cắm thật nhanh","Có, nếu em đứng trên ghế gỗ","Có, nếu chỉ cắm bằng một tay"],"a":"Không, vì nước dẫn điện rất nguy hiểm","h":"Nước kết hợp với điện sẽ gây ra điều gì nguy hiểm?","e":"Tay ướt chạm vào ổ điện có thể bị điện giật, rất nguy hiểm; em phải lau khô tay và nhờ người lớn giúp.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Phòng học máy tính nên có ánh sáng như thế nào để tốt cho mắt?","o":["Đủ sáng, không quá tối và không để ánh nắng chói thẳng vào màn hình","Tối om để nhìn màn hình cho rõ","Chỉ cần bật mỗi màn hình máy tính","Ánh sáng càng chói càng tốt"],"a":"Đủ sáng, không quá tối và không để ánh nắng chói thẳng vào màn hình","h":"Ánh sáng thế nào thì em nhìn vừa rõ mà không bị chói, mỏi mắt?","e":"Ánh sáng đủ, đều và không chói vào màn hình giúp em nhìn rõ và bảo vệ mắt.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Em phát hiện dây điện của máy tính bị hở, tróc vỏ, nhìn thấy lõi đồng bên trong. Việc làm đúng là gì?","o":["Không chạm vào dây điện, báo ngay cho thầy cô hoặc người lớn","Cầm sợi dây lên xem cho rõ","Tự lấy băng dính quấn lại rồi dùng tiếp","Giật mạnh sợi dây để rút phích điện ra"],"a":"Không chạm vào dây điện, báo ngay cho thầy cô hoặc người lớn","h":"Dây điện bị hở rất nguy hiểm, em tuyệt đối không được tự ý chạm vào.","e":"Dây điện bị hở có thể gây điện giật; em không chạm vào và phải báo ngay cho người lớn xử lí.","t":"tin-lop3","g":3,"l":"kho"},{"p":"Màn hình máy tính quá sáng khiến em bị chói và mỏi mắt. Em nên làm gì?","o":["Nhờ thầy cô hoặc người lớn chỉnh lại độ sáng màn hình cho vừa","Dí mắt sát vào màn hình hơn","Nhắm mắt lại rồi gõ tiếp","Lấy tay che hết màn hình"],"a":"Nhờ thầy cô hoặc người lớn chỉnh lại độ sáng màn hình cho vừa","h":"Độ sáng của màn hình hoàn toàn có thể chỉnh lại cho phù hợp với mắt.","e":"Em nên nhờ người lớn chỉnh độ sáng màn hình vừa phải để bảo vệ mắt khi học.","t":"tin-lop3","g":3,"l":"kho"},{"p":"Thiết bị nào giúp em nghe âm thanh từ máy tính mà không làm phiền người xung quanh?","o":["Tai nghe","Loa ngoài","Máy in","Webcam"],"a":"Tai nghe","h":"Thiết bị này em đeo lên tai khi nghe.","e":"Tai nghe phát âm thanh chỉ cho riêng em nghe nên không làm phiền người khác.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Máy in là thiết bị dùng để làm gì?","o":["In văn bản và hình ảnh từ máy tính ra giấy","Thu hình ảnh của em vào máy tính","Lưu trữ dữ liệu để mang đi","Phát âm thanh to hơn"],"a":"In văn bản và hình ảnh từ máy tính ra giấy","h":"Sau khi dùng thiết bị này, em cầm được tờ giấy có chữ và hình.","e":"Máy in chuyển văn bản, hình ảnh trong máy tính thành bản in trên giấy.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"USB (thiết bị nhớ USB) thường được dùng để làm gì?","o":["Lưu trữ và mang dữ liệu từ máy tính này sang máy tính khác","Làm mát cho máy tính","Kết nối chuột với máy tính","Chiếu hình lên tường"],"a":"Lưu trữ và mang dữ liệu từ máy tính này sang máy tính khác","h":"Em cắm thiết bị nhỏ này vào máy tính để chép tệp mang đi.","e":"USB là thiết bị lưu trữ nhỏ gọn, giúp lưu và chuyển dữ liệu giữa các máy tính.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Khi học trực tuyến, webcam giúp em làm việc gì?","o":["Thu hình ảnh của em để thầy cô và bạn bè nhìn thấy","In bài tập ra giấy","Gõ chữ nhanh hơn","Nghe nhạc hay hơn"],"a":"Thu hình ảnh của em để thầy cô và bạn bè nhìn thấy","h":"Thầy cô nhìn thấy hình ảnh của em qua thiết bị nào?","e":"Webcam thu hình ảnh của em và gửi đi, giúp thầy cô và bạn bè nhìn thấy em khi học trực tuyến.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Chuột không dây khác chuột có dây ở điểm nào?","o":["Kết nối với máy tính bằng sóng, không cần dây nối","Không bao giờ cần pin hay sạc","Chỉ dùng được trên mặt kính","To hơn gấp đôi chuột có dây"],"a":"Kết nối với máy tính bằng sóng, không cần dây nối","h":"Tên gọi 'không dây' nói lên cách con chuột này kết nối với máy tính.","e":"Chuột không dây kết nối với máy tính qua sóng (thông qua đầu thu USB) nên không bị vướng dây nối.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Nhờ có mạng máy tính của trường, các máy tính trong phòng Tin học có thể cùng dùng chung thiết bị nào sau đây?","o":["Máy in","Bàn ghế","Bảng viết","Quạt trần"],"a":"Máy in","h":"Thiết bị nào chỉ cần một cái là đủ cho cả phòng máy cùng dùng?","e":"Nhờ mạng máy tính, nhiều máy trong phòng có thể cùng gửi lệnh in tới một máy in chung.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Khi em đổi tên một tệp trong máy tính, nội dung bên trong tệp sẽ thế nào?","o":["Vẫn giữ nguyên, chỉ có tên tệp thay đổi","Bị xoá hết","Tự động nhân đôi thành hai tệp","Chuyển thành một tệp hoàn toàn khác"],"a":"Vẫn giữ nguyên, chỉ có tên tệp thay đổi","h":"Đổi tên chỉ thay đổi cách gọi tệp, không đụng tới phần bên trong.","e":"Đổi tên tệp chỉ thay đổi tên gọi; nội dung của tệp vẫn được giữ nguyên.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Máy tính của em chưa được kết nối mạng. Em KHÔNG thể làm được việc nào sau đây?","o":["Truy cập Internet để tìm thông tin","Soạn thảo một bài văn","Vẽ tranh bằng phần mềm Paint","Chơi trò chơi đã cài sẵn trong máy"],"a":"Truy cập Internet để tìm thông tin","h":"Việc nào bắt buộc phải có kết nối mạng mới làm được?","e":"Truy cập Internet để tìm thông tin cần máy tính có kết nối mạng; các việc còn lại làm được ngay trên máy.","t":"tin-lop4","g":4,"l":"kho"},{"p":"Muốn gõ toàn chữ IN HOA trong một đoạn dài mà không phải giữ phím liên tục, em bật phím nào?","o":["Phím Caps Lock","Phím Enter","Phím Backspace","Phím Space"],"a":"Phím Caps Lock","h":"Khi bật phím này, trên bàn phím thường có một đèn nhỏ sáng lên.","e":"Bật Caps Lock giúp em gõ liên tục toàn chữ in hoa mà không cần giữ phím Shift.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Để tiêu đề của bài văn nằm chính giữa trang giấy, em chọn lệnh căn lề nào?","o":["Căn giữa","Căn trái","Căn phải","Không cần căn gì cả"],"a":"Căn giữa","h":"Tiêu đề thường đứng ở vị trí nào trên trang cho cân đối?","e":"Lệnh căn giữa giúp dòng tiêu đề nằm chính giữa trang, trông cân đối và đẹp mắt.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Muốn chèn một bức tranh vào bài văn đang soạn thảo, em dùng lệnh nào?","o":["Lệnh chèn hình ảnh (Insert Picture)","Lệnh lưu văn bản","Lệnh căn giữa","Lệnh in văn bản"],"a":"Lệnh chèn hình ảnh (Insert Picture)","h":"Trong phần mềm soạn thảo có một lệnh chuyên để đưa hình vào văn bản.","e":"Em dùng lệnh chèn hình ảnh trong phần mềm soạn thảo rồi chọn bức tranh cần chèn vào vị trí mong muốn.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Em đã bôi đen (chọn) một đoạn văn bản bị thừa. Nhấn phím nào để xoá đoạn văn đó?","o":["Phím Delete","Phím Enter","Phím Caps Lock","Phím Shift"],"a":"Phím Delete","h":"Có một phím mang tên Delete chuyên dùng để xoá phần đã chọn.","e":"Sau khi chọn đoạn văn, nhấn phím Delete (hoặc Backspace) sẽ xoá đoạn văn đó.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Em vừa xoá nhầm một đoạn văn quan trọng. Tổ hợp phím nào giúp em khôi phục lại thao tác vừa làm (hoàn tác)?","o":["Ctrl + Z","Ctrl + C","Ctrl + V","Ctrl + A"],"a":"Ctrl + Z","h":"Tổ hợp phím hoàn tác quen thuộc là Ctrl kết hợp với phím Z.","e":"Tổ hợp phím Ctrl + Z là lệnh hoàn tác, giúp khôi phục lại thao tác vừa làm sai.","t":"tin-lop5","g":5,"l":"kho"},{"p":"Muốn chép một đoạn văn sang vị trí khác mà đoạn văn gốc vẫn giữ nguyên, em làm thế nào?","o":["Chọn đoạn văn, dùng lệnh Sao chép (Copy) rồi Dán (Paste) vào vị trí mới","Cắt đoạn văn rồi dán sang chỗ mới","Gõ lại toàn bộ đoạn văn bằng tay","Xoá đoạn văn rồi cố nhớ lại"],"a":"Chọn đoạn văn, dùng lệnh Sao chép (Copy) rồi Dán (Paste) vào vị trí mới","h":"Lệnh nào tạo thêm một bản giống hệt mà không làm mất bản gốc?","e":"Lệnh Sao chép (Copy) tạo một bản sao của đoạn văn, sau đó Dán (Paste) vào vị trí mới, đoạn gốc vẫn còn nguyên.","t":"tin-lop5","g":5,"l":"kho"},{"p":"Muốn có thêm một trang chiếu mới trong bài trình chiếu, em dùng lệnh nào?","o":["Lệnh thêm trang chiếu mới (New Slide)","Lệnh xoá trang chiếu","Lệnh lưu bài trình chiếu","Lệnh thoát phần mềm"],"a":"Lệnh thêm trang chiếu mới (New Slide)","h":"Tên lệnh này trong tiếng Anh có nghĩa là 'trang chiếu mới'.","e":"Lệnh New Slide giúp em thêm một trang chiếu mới vào bài trình chiếu.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Để bài trình chiếu đẹp và đồng nhất, em có thể chọn sẵn những gì trong phần mềm?","o":["Các mẫu nền (mẫu thiết kế) có sẵn","Các bài hát có sẵn","Các trò chơi có sẵn","Các hình ảnh lạ trên mạng"],"a":"Các mẫu nền (mẫu thiết kế) có sẵn","h":"Phần mềm đã chuẩn bị sẵn các bộ nền trang trí cho em chọn.","e":"Phần mềm trình chiếu có sẵn nhiều mẫu nền (theme) giúp bài trình chiếu đẹp và thống nhất.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Một trang chiếu trong bài bị thừa, em muốn xoá bỏ. Cách làm đúng là gì?","o":["Chọn trang chiếu đó rồi dùng lệnh xoá trang (Delete Slide)","Đóng phần mềm lại ngay","Xoá hết chữ trong trang đó","Tắt máy tính rồi mở lại"],"a":"Chọn trang chiếu đó rồi dùng lệnh xoá trang (Delete Slide)","h":"Em thao tác trên khung danh sách các trang ở bên trái màn hình.","e":"Em chọn trang chiếu cần bỏ trong danh sách trang rồi dùng lệnh xoá trang để loại bỏ nó khỏi bài.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Khi làm trang chiếu để cả lớp cùng xem, chữ trên trang nên như thế nào?","o":["Chữ to, ít chữ, rõ ràng dễ đọc","Chữ thật nhỏ để chứa được nhiều nội dung","Chữ kín cả trang, không chừa khoảng trống","Chữ màu nhạt trên nền cũng nhạt"],"a":"Chữ to, ít chữ, rõ ràng dễ đọc","h":"Bạn ngồi ở cuối lớp cũng cần đọc được chữ trên màn chiếu.","e":"Trang chiếu nên có chữ to, ngắn gọn và rõ ràng để mọi người dễ đọc và nắm ý chính.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Muốn bắt đầu trình chiếu toàn màn hình từ trang đầu tiên, em nhấn phím nào?","o":["Phím F5","Phím Enter","Phím Space","Phím Esc"],"a":"Phím F5","h":"Đây là một phím chức năng nằm ở hàng trên cùng của bàn phím.","e":"Nhấn phím F5 để bắt đầu trình chiếu toàn màn hình từ trang chiếu đầu tiên.","t":"tin-lop4","g":4,"l":"kho"},{"p":"Trình duyệt web là phần mềm dùng để làm gì?","o":["Mở và xem các trang web trên Internet","Vẽ tranh trên máy tính","Nghe nhạc trong máy tính","Dọn dẹp rác cho máy tính"],"a":"Mở và xem các trang web trên Internet","h":"Cốc Cốc và Google Chrome là ví dụ của loại phần mềm này.","e":"Trình duyệt web là phần mềm giúp em truy cập và xem các trang web trên Internet.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Một trang web là gì?","o":["Một trang thông tin trên Internet, có địa chỉ riêng để truy cập","Một tờ giấy trong vở của em","Một phần mềm vẽ tranh","Tên của chiếc máy tính"],"a":"Một trang thông tin trên Internet, có địa chỉ riêng để truy cập","h":"Em mở trang này bằng trình duyệt để đọc thông tin.","e":"Trang web là trang thông tin trên Internet, mỗi trang có một địa chỉ riêng để em truy cập bằng trình duyệt.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Địa chỉ của một trang web có tác dụng gì?","o":["Giúp trình duyệt tìm và mở đúng trang web em cần","Làm cho máy tính chạy nhanh hơn","Trang trí cho trang web đẹp hơn","Thay thế cho mật khẩu đăng nhập"],"a":"Giúp trình duyệt tìm và mở đúng trang web em cần","h":"Giống như địa chỉ nhà giúp em tìm đến đúng ngôi nhà cần tìm.","e":"Địa chỉ trang web cho trình duyệt biết cần tìm và mở trang nào trên Internet.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Trên trang web, siêu liên kết (đường liên kết) là gì?","o":["Chữ hoặc hình ảnh mà khi nháy chuột vào sẽ đưa em tới nội dung khác","Một loại dây cáp mạng","Tên người viết ra trang web","Mật khẩu của trang web"],"a":"Chữ hoặc hình ảnh mà khi nháy chuột vào sẽ đưa em tới nội dung khác","h":"Đó thường là dòng chữ có màu khác, bấm vào là chuyển sang nội dung khác.","e":"Siêu liên kết là chữ hoặc hình trên trang web; nháy vào đó, trình duyệt sẽ chuyển em tới một trang hay nội dung khác.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Muốn đến một trang web bằng địa chỉ của nó, em gõ địa chỉ vào đâu trong trình duyệt?","o":["Ô địa chỉ (thanh địa chỉ) ở phía trên cửa sổ trình duyệt","Bất kì chỗ nào ở giữa trang web","Trong phần mềm soạn thảo văn bản","Trên màn hình nền của máy tính"],"a":"Ô địa chỉ (thanh địa chỉ) ở phía trên cửa sổ trình duyệt","h":"Đó là ô dài nằm ở trên cùng của cửa sổ trình duyệt.","e":"Em gõ địa chỉ trang web vào ô địa chỉ của trình duyệt rồi nhấn Enter để mở trang.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Em thấy một bộ phim hay nhưng trang web lạ bắt tải phim về từ nguồn không rõ ràng. Việc làm đúng là gì?","o":["Không tải về, chỉ xem ở nơi được phép và hỏi ý kiến người lớn","Tải ngay về cho nhanh","Nhờ bạn tải hộ vào máy của mình","Tắt phần mềm bảo vệ máy rồi tải"],"a":"Không tải về, chỉ xem ở nơi được phép và hỏi ý kiến người lớn","h":"Tải phim từ nguồn lạ vừa vi phạm bản quyền vừa dễ dính phần mềm độc hại.","e":"Em không nên tải phim từ nguồn lạ; hãy xem ở nơi được phép và hỏi ý kiến người lớn để bảo đảm an toàn và tôn trọng bản quyền.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Một quảng cáo lạ bật lên báo em 'trúng thưởng điện thoại, hãy bấm vào ngay'. Em nên làm gì?","o":["Không bấm vào, đóng quảng cáo lại","Bấm vào ngay kẻo mất quà","Nhập số điện thoại để nhận thưởng","Gọi bạn đến bấm thử thay mình"],"a":"Không bấm vào, đóng quảng cáo lại","h":"Quà tặng bất ngờ trong quảng cáo lạ thường là bẫy lừa đảo.","e":"Quảng cáo trúng thưởng bất ngờ thường là lừa đảo; em không bấm vào mà đóng quảng cáo lại, nếu lo lắng hãy kể cho người lớn nghe.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Em muốn tải một phần mềm học tập mới về máy tính. Việc làm đúng là gì?","o":["Xin phép và nhờ người lớn tải cùng từ trang web chính thức của phần mềm","Tự tải từ bất kì trang nào hiện ra đầu tiên","Tải từ trang lạ có rất nhiều quảng cáo","Mượn chiếc USB lạ chép phần mềm vào máy"],"a":"Xin phép và nhờ người lớn tải cùng từ trang web chính thức của phần mềm","h":"Nguồn tải chính thức và có người lớn cùng kiểm tra sẽ an toàn nhất.","e":"Em cần xin phép người lớn và tải phần mềm từ trang chính thức để tránh phần mềm độc hại.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Bạn em rủ tải nhạc và phim lậu (không được phép phát hành miễn phí) để xem cho 'đỡ tốn tiền'. Việc làm đó là gì?","o":["Vi phạm bản quyền, không nên làm","Việc làm thông minh, nên làm theo","Chỉ sai khi bị người khác phát hiện","Không sao vì rất nhiều người cũng làm thế"],"a":"Vi phạm bản quyền, không nên làm","h":"Phim và nhạc là sản phẩm có bản quyền của người sáng tạo ra chúng.","e":"Tải và dùng phim, nhạc lậu là vi phạm bản quyền của tác giả nên em không nên làm.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Một trang web lạ yêu cầu em nhập họ tên, địa chỉ nhà và số điện thoại của bố mẹ để nhận quà miễn phí. Em nên làm gì?","o":["Không nhập thông tin, đóng trang web và kể lại cho người lớn nghe","Nhập đầy đủ thông tin để nhận quà","Chỉ nhập tên giả còn địa chỉ thì nhập thật","Nhờ bạn nhập thông tin của bạn ấy thay mình"],"a":"Không nhập thông tin, đóng trang web và kể lại cho người lớn nghe","h":"Thông tin cá nhân và gia đình phải được giữ kín trước người lạ trên mạng.","e":"Em tuyệt đối không cung cấp thông tin cá nhân, gia đình cho trang web lạ; hãy đóng trang và báo cho người lớn.","t":"tin-lop4","g":4,"l":"kho"},{"p":"Trong Scratch, biến được dùng để làm gì?","o":["Lưu trữ một giá trị có thể thay đổi trong khi chương trình chạy","Vẽ hình cho nhân vật","Phát ra âm thanh cho chương trình","Đổi màu cho sân khấu"],"a":"Lưu trữ một giá trị có thể thay đổi trong khi chương trình chạy","h":"Nghĩ tới biến Điểm trong trò chơi.","e":"Biến là nơi lưu một giá trị, ví dụ điểm số, và giá trị đó có thể thay đổi khi chương trình chạy.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Muốn nhân vật trong Scratch nói 'Xin chào!' trong 2 giây, em dùng khối lệnh nào?","o":["Khối 'nói ... trong ... giây' ở nhóm Hiển thị","Khối 'di chuyển 10 bước'","Khối 'đổi trang phục'","Khối 'chờ 1 giây'"],"a":"Khối 'nói ... trong ... giây' ở nhóm Hiển thị","h":"Nhóm lệnh làm nhân vật hiện lời nói trong bong bóng.","e":"Khối nói trong nhóm Hiển thị giúp nhân vật hiện bong bóng lời nói trong một khoảng thời gian.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Muốn nhân vật mèo phát ra tiếng 'meo' khi em bấm vào nhân vật, em dùng nhóm khối lệnh nào?","o":["Nhóm Âm thanh","Nhóm Bút vẽ","Nhóm Cảm biến","Nhóm Số học"],"a":"Nhóm Âm thanh","h":"Nhóm lệnh liên quan tới tiếng động.","e":"Các khối phát âm thanh trong Scratch nằm ở nhóm Âm thanh.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Trong Scratch, sau khi dùng khối bút 'đặt bút xuống', điều gì xảy ra khi nhân vật di chuyển?","o":["Nhân vật vẽ thành một đường theo đường di chuyển","Nhân vật biến mất khỏi sân khấu","Nhân vật nói thành tiếng","Sân khấu đổi màu nền"],"a":"Nhân vật vẽ thành một đường theo đường di chuyển","h":"Giống như em đặt đầu bút xuống giấy rồi kéo đi.","e":"Đặt bút xuống giúp nhân vật để lại nét vẽ trên sân khấu khi di chuyển, giống bút vẽ trên giấy.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Muốn nhân vật nhảy lên mỗi khi em nhấn phím cách trên bàn phím, chương trình Scratch nên bắt đầu bằng sự kiện nào?","o":["Khi phím cách được nhấn","Khi lá cờ xanh được bấm","Khi nhân vật được bấm vào","Khi sân khấu được bấm vào"],"a":"Khi phím cách được nhấn","h":"Sự kiện gắn với phím trên bàn phím.","e":"Scratch có sự kiện 'khi phím ... được nhấn', dùng để điều khiển nhân vật bằng bàn phím.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Nhân vật đang đi sang phải và chạm vào cạnh sân khấu. Khối lệnh nào giúp nhân vật tự quay lại và đi tiếp thay vì bị kẹt ở cạnh?","o":["Khối 'nếu chạm cạnh, bật lại'","Khối 'xoá tất cả hình vẽ'","Khối 'dừng tất cả'","Khối 'ẩn nhân vật'"],"a":"Khối 'nếu chạm cạnh, bật lại'","h":"Khối này nằm trong nhóm Di chuyển.","e":"Khối 'nếu chạm cạnh, bật lại' trong nhóm Di chuyển giúp nhân vật đổi hướng khi chạm mép sân khấu.","t":"tin-lop5","g":5,"l":"kho"},{"p":"Biến Điểm đang có giá trị 5. Sau khi thực hiện khối 'thay đổi Điểm thêm 1', biến Điểm có giá trị bao nhiêu?","o":["6","5","1","10"],"a":"6","h":"Cộng thêm 1 vào giá trị đang có.","e":"Khối thay đổi biến thêm 1 sẽ tăng giá trị của biến Điểm từ 5 lên 6.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Nhận được email của cô giáo, muốn viết thư trả lời ngay cho cô, em bấm vào nút nào?","o":["Trả lời (Reply)","Chuyển tiếp (Forward)","Xoá thư","In thư"],"a":"Trả lời (Reply)","h":"Nút có nghĩa là hồi âm lại thư vừa nhận.","e":"Nút Trả lời (Reply) mở khung soạn thư gửi lại cho chính người vừa gửi thư cho em.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi viết email, dòng 'Chủ đề' có tác dụng gì?","o":["Cho người nhận biết ngay thư nói về việc gì","Trang trí cho email đẹp hơn","Đính kèm tệp vào thư","Gửi thư đi nhanh hơn"],"a":"Cho người nhận biết ngay thư nói về việc gì","h":"Giống như tiêu đề của một bài văn.","e":"Chủ đề tóm tắt nội dung thư, giúp người nhận biết thư nói về việc gì trước khi mở đọc.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Thư rác (spam) trong email là gì?","o":["Thư quảng cáo hoặc thư lạ được gửi hàng loạt mà em không mong muốn","Thư của thầy cô gửi cho em","Thư em đã đọc xong","Thư nháp chưa gửi đi"],"a":"Thư quảng cáo hoặc thư lạ được gửi hàng loạt mà em không mong muốn","h":"Đó là những thư em không hề yêu cầu được gửi tới.","e":"Thư rác là thư quảng cáo, thư lạ gửi hàng loạt tới nhiều người mà người nhận không mong muốn.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Khi nhận được một thư rác lạ có đường liên kết mời bấm vào để nhận quà, em nên làm gì?","o":["Xoá thư hoặc đánh dấu là thư rác, không bấm vào liên kết","Bấm ngay vào liên kết để nhận quà","Chuyển tiếp cho nhiều bạn bè","Trả lời thư hỏi thêm thông tin"],"a":"Xoá thư hoặc đánh dấu là thư rác, không bấm vào liên kết","h":"Quà miễn phí từ người lạ thường là bẫy lừa đảo.","e":"Thư rác có liên kết lạ có thể chứa lừa đảo hoặc mã độc, em nên xoá thư và không bấm vào liên kết.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Thư của cô giáo được gửi cho cả lớp. Muốn trả lời sao cho tất cả các bạn cùng nhận được thư trả lời của em, em dùng nút nào?","o":["Trả lời tất cả (Reply All)","Trả lời (Reply)","Chuyển tiếp (Forward)","Xoá thư"],"a":"Trả lời tất cả (Reply All)","h":"Có một nút trả lời dành cho mọi người cùng nhận thư.","e":"Nút Trả lời tất cả (Reply All) gửi thư trả lời tới tất cả những người có trong danh sách nhận thư, không chỉ người gửi.","t":"tin-lop6","g":6,"l":"kho"},{"p":"Trong phần mềm soạn thảo, nút chữ B dùng để làm gì?","o":["Làm cho chữ được chọn đậm hơn","Làm cho chữ nghiêng đi","Gạch chân dưới chữ","Đổi màu chữ thành đỏ"],"a":"Làm cho chữ được chọn đậm hơn","h":"B là chữ cái đầu của từ 'Bold' nghĩa là đậm.","e":"Nút B (Bold) dùng để in đậm phần chữ đang được chọn trong văn bản.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Muốn gạch chân dưới một từ quan trọng trong bài soạn thảo, em dùng nút nào?","o":["Nút U","Nút B","Nút I","Nút căn giữa"],"a":"Nút U","h":"U là chữ cái đầu của từ 'Underline'.","e":"Nút U (Underline) dùng để gạch chân dưới chữ được chọn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Muốn các chữ trong tiêu đề to hơn phần nội dung, em cần thay đổi điều gì?","o":["Cỡ chữ của tiêu đề","Màu giấy của trang","Khoảng cách giữa các trang","Tên của tệp văn bản"],"a":"Cỡ chữ của tiêu đề","h":"Đó là con số chỉ độ lớn của chữ, ví dụ 14, 16, 20.","e":"Cỡ chữ quyết định độ to nhỏ của chữ; tăng cỡ chữ sẽ làm tiêu đề to hơn nội dung.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Sau khi chèn một bức hình vào văn bản, muốn đưa hình sang vị trí khác trong trang, em làm thế nào?","o":["Bấm chọn hình rồi kéo thả tới vị trí mới","Xoá văn bản rồi gõ lại từ đầu","Đổi tên tệp văn bản","Tắt máy rồi bật lại"],"a":"Bấm chọn hình rồi kéo thả tới vị trí mới","h":"Dùng chuột kéo vật tới nơi em muốn đặt.","e":"Hình đã chèn vào văn bản có thể được chọn và kéo thả bằng chuột tới vị trí khác trong trang.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Em muốn tiêu đề bài thơ vừa to, vừa đậm và nằm giữa trang. Cách làm nào hợp lí nhất?","o":["Chọn tiêu đề, tăng cỡ chữ, bấm nút in đậm rồi bấm căn giữa","Gõ lại tiêu đề bằng toàn chữ hoa","Chèn một bức hình chụp tiêu đề vào văn bản","Đổi màu giấy của trang thành màu khác"],"a":"Chọn tiêu đề, tăng cỡ chữ, bấm nút in đậm rồi bấm căn giữa","h":"Kết hợp cả ba thao tác định dạng đã học.","e":"Muốn tiêu đề to, đậm và ở giữa trang, em chọn tiêu đề rồi tăng cỡ chữ, in đậm và căn giữa.","t":"tin-lop5","g":5,"l":"kho"},{"p":"Muốn tìm đường đi ngắn nhất từ nhà em tới trường bằng Internet, em nên dùng loại công cụ nào?","o":["Bản đồ số trên Internet","Phần mềm nghe nhạc","Trò chơi điện tử","Máy tính bỏ túi"],"a":"Bản đồ số trên Internet","h":"Công cụ cho xem đường phố và chỉ đường đi.","e":"Bản đồ số trực tuyến giúp em tìm vị trí và đường đi giữa hai nơi một cách nhanh chóng.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Học trực tuyến là hình thức học như thế nào?","o":["Học qua Internet bằng các bài giảng, lớp học trên mạng","Học bằng cách đọc sách giấy ở nhà","Học cùng bạn ở sân trường","Học qua truyền hình cáp tại nhà hàng xóm"],"a":"Học qua Internet bằng các bài giảng, lớp học trên mạng","h":"Chữ 'trực tuyến' gắn với mạng Internet.","e":"Học trực tuyến là học qua Internet, qua video bài giảng hoặc lớp học trực tuyến với thầy cô.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Khi tìm kiếm trên Internet, việc đặt cụm từ khoá trong dấu ngoặc kép giúp ích gì?","o":["Máy tìm kiếm ưu tiên các kết quả chứa đúng cụm từ đó","Kết quả tìm kiếm hiện ra nhanh gấp đôi","Không còn quảng cáo trong kết quả","Tự động dịch kết quả sang tiếng Việt"],"a":"Máy tìm kiếm ưu tiên các kết quả chứa đúng cụm từ đó","h":"Ngoặc kép giúp tìm đúng nguyên văn cụm từ.","e":"Đặt từ khoá trong dấu ngoặc kép giúp máy tìm kiếm trả về kết quả chứa đúng cụm từ em cần.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Đang xem video bài giảng trực tuyến mà chưa hiểu một đoạn, em nên làm gì?","o":["Tạm dừng hoặc tua lại đoạn đó để xem lại","Tắt video và bỏ qua luôn","Xem tiếp cho hết dù không hiểu","Chờ bạn bên cạnh giảng lại"],"a":"Tạm dừng hoặc tua lại đoạn đó để xem lại","h":"Video trực tuyến có thể xem lại nhiều lần.","e":"Video bài giảng có thể tạm dừng và tua lại, giúp em xem lại đoạn chưa hiểu cho tới khi hiểu bài.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Em cần tìm đúng nguyên văn câu thơ 'Quê hương là chùm khế ngọt' trên Internet. Cách gõ tìm kiếm nào hiệu quả nhất?","o":["Gõ cả câu thơ trong dấu ngoặc kép","Chỉ gõ một từ 'quê'","Gõ tên của em vào ô tìm kiếm","Gõ câu thơ không dấu và thêm nhiều từ lạ"],"a":"Gõ cả câu thơ trong dấu ngoặc kép","h":"Dùng dấu ngoặc kép cho cả câu cần tìm nguyên văn.","e":"Đặt cả câu trong dấu ngoặc kép giúp máy tìm kiếm tìm đúng nguyên văn câu thơ.","t":"tin-lop5","g":5,"l":"kho"},{"p":"Vì sao em không nên dùng cùng một mật khẩu cho mọi tài khoản trên mạng?","o":["Nếu mật khẩu bị lộ ở một nơi, kẻ xấu có thể đăng nhập tất cả tài khoản còn lại","Vì máy tính không cho phép đặt trùng mật khẩu","Vì mật khẩu dùng chung sẽ tự hết hạn","Vì các tài khoản sẽ bị khoá vĩnh viễn"],"a":"Nếu mật khẩu bị lộ ở một nơi, kẻ xấu có thể đăng nhập tất cả tài khoản còn lại","h":"Nghĩ tới trường hợp một tài khoản bị lộ mật khẩu.","e":"Dùng chung một mật khẩu rất nguy hiểm: lộ ở một tài khoản là kẻ xấu có thể vào mọi tài khoản khác.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Một người lạ trên mạng nhắn tin rủ em gửi ảnh cá nhân và hứa tặng quà trong trò chơi. Em nên làm gì?","o":["Không gửi ảnh, chặn người đó và kể với bố mẹ hoặc thầy cô","Gửi ảnh để nhận quà","Hỏi xin thêm quà rồi mới gửi","Nhắn cho bạn bè cùng gửi ảnh"],"a":"Không gửi ảnh, chặn người đó và kể với bố mẹ hoặc thầy cô","h":"Không tin lời hứa quà tặng của người lạ trên mạng.","e":"Người lạ xin ảnh cá nhân có thể có ý đồ xấu; em không gửi, chặn liên lạc và báo cho người lớn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Khi chơi trò chơi trực tuyến, em muốn mua một vật phẩm bằng tiền thật. Việc em cần làm trước tiên là gì?","o":["Xin phép và được bố mẹ đồng ý","Mua ngay kẻo hết hàng","Mượn tài khoản của bạn để mua","Giấu bố mẹ và tự mua"],"a":"Xin phép và được bố mẹ đồng ý","h":"Mọi khoản chi tiền thật đều cần người lớn đồng ý.","e":"Mua vật phẩm bằng tiền thật trong trò chơi phải xin phép và được bố mẹ đồng ý trước.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Bạn thân xin mật khẩu tài khoản học trực tuyến của em để vào xem bài. Em nên làm gì?","o":["Không chia sẻ mật khẩu, khuyên bạn dùng tài khoản của chính bạn","Cho bạn mật khẩu vì là bạn thân","Đổi mật khẩu đơn giản hơn rồi cho bạn","Cho bạn mật khẩu nhưng dặn giữ bí mật"],"a":"Không chia sẻ mật khẩu, khuyên bạn dùng tài khoản của chính bạn","h":"Mật khẩu là của riêng mỗi người, kể cả với bạn thân.","e":"Mật khẩu tài khoản là thông tin riêng, không chia sẻ cho bất kì ai; bạn nên dùng tài khoản của chính mình.","t":"tin-lop5","g":5,"l":"kho"},{"p":"Thông tin nào sau đây em KHÔNG nên công khai cho mọi người trên mạng?","o":["Địa chỉ nhà và số điện thoại của em","Tên cuốn truyện em yêu thích","Màu sắc em thích nhất","Tên môn học em thích"],"a":"Địa chỉ nhà và số điện thoại của em","h":"Đó là thông tin riêng tư của gia đình em.","e":"Địa chỉ nhà và số điện thoại là thông tin cá nhân cần giữ kín, không công khai trên mạng.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Số nhị phân được viết bằng những chữ số nào?","o":["Chỉ hai chữ số 0 và 1","Các chữ số từ 0 đến 9","Các chữ cái A và B","Các chữ số từ 1 đến 9"],"a":"Chỉ hai chữ số 0 và 1","h":"Chữ 'nhị' nghĩa là hai.","e":"Hệ nhị phân chỉ dùng hai chữ số 0 và 1 để biểu diễn mọi thông tin.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Mỗi bit trong máy tính chỉ nhận một trong hai giá trị nào?","o":["0 hoặc 1","1 hoặc 2","Chữ Đ hoặc chữ S","Âm hoặc dương"],"a":"0 hoặc 1","h":"Bit là đơn vị thông tin nhỏ nhất.","e":"Một bit chỉ có hai trạng thái, được kí hiệu bằng 0 hoặc 1.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Vì sao máy tính dùng hệ nhị phân để biểu diễn và xử lí thông tin?","o":["Vì các bộ phận điện tử của máy tính dễ thể hiện hai trạng thái như có điện và không có điện","Vì hệ nhị phân có nhiều chữ số hơn hệ thập phân","Vì con người chỉ đếm được tới số 2","Vì hệ nhị phân luôn viết nhanh hơn mọi hệ đếm khác"],"a":"Vì các bộ phận điện tử của máy tính dễ thể hiện hai trạng thái như có điện và không có điện","h":"Liên quan tới cách mạch điện trong máy tính hoạt động.","e":"Mạch điện trong máy tính có hai trạng thái rõ ràng (đóng/mở, có điện/không có điện) nên hệ nhị phân rất phù hợp.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Khi em gõ chữ 'A' trên bàn phím, trong máy tính chữ đó được biểu diễn dưới dạng nào?","o":["Một dãy các bit 0 và 1","Một hình vẽ của chữ A","Một âm thanh đọc chữ A","Một tờ giấy in chữ A"],"a":"Một dãy các bit 0 và 1","h":"Mọi thông tin trong máy tính đều được đưa về cùng một dạng.","e":"Mọi kí tự khi đưa vào máy tính đều được mã hoá thành dãy bit gồm các số 0 và 1.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Trong hệ nhị phân, số 11 tương đương với số nào trong hệ thập phân?","o":["3","2","11","10"],"a":"3","h":"11 trong hệ nhị phân bằng 1×2 + 1.","e":"Số nhị phân 11 có giá trị 1×2 + 1 = 3 trong hệ thập phân.","t":"tin-lop6","g":6,"l":"kho"},{"p":"Văn bản, hình ảnh và âm thanh khi được lưu trong máy tính có điểm chung nào?","o":["Đều được chuyển thành dãy bit để lưu trữ và xử lí","Đều được in ra giấy ngay lập tức","Đều có dung lượng bằng nhau","Đều không cần điện để hoạt động"],"a":"Đều được chuyển thành dãy bit để lưu trữ và xử lí","h":"Máy tính chỉ xử lí được một dạng thông tin duy nhất.","e":"Mọi dạng thông tin đưa vào máy tính đều được biểu diễn bằng dãy bit để lưu trữ và xử lí.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Muốn có một tài khoản thư điện tử (email) để gửi và nhận thư, em cần làm gì?","o":["Đăng kí tài khoản với một nhà cung cấp dịch vụ thư điện tử","Mua một chiếc máy tính mới","Xin số điện thoại của bạn bè","Cài thêm một trò chơi vào máy"],"a":"Đăng kí tài khoản với một nhà cung cấp dịch vụ thư điện tử","h":"Giống như đăng kí một hộp thư của riêng em trên mạng.","e":"Để dùng email, em cần đăng kí một tài khoản với nhà cung cấp dịch vụ thư điện tử.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Bạn gửi email cho em. Khi em đăng nhập vào hộp thư của mình, thư của bạn sẽ nằm ở đâu?","o":["Trong hộp thư đến (Inbox)","Trong thư mục rác","Trong thư nháp","Trong các tệp đã xoá"],"a":"Trong hộp thư đến (Inbox)","h":"Đó là nơi chứa các thư người khác gửi tới.","e":"Thư người khác gửi tới sẽ xuất hiện trong hộp thư đến (Inbox) của em.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Đâu là một mặt trái của Internet mà em cần cảnh giác?","o":["Có thông tin sai lệch, độc hại và những kẻ lừa đảo trên mạng","Internet làm máy tính trở nên nặng hơn","Internet chỉ dùng được vào ban ngày","Internet khiến em không thể học tập được nữa"],"a":"Có thông tin sai lệch, độc hại và những kẻ lừa đảo trên mạng","h":"Bên cạnh nhiều lợi ích, Internet cũng có những nguy cơ.","e":"Internet có thể chứa thông tin sai lệch, nội dung độc hại và lừa đảo, nên em cần cẩn thận khi sử dụng.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Em nhận được email lạ tự xưng là ngân hàng và yêu cầu em cung cấp mật khẩu tài khoản. Em nên làm gì?","o":["Không cung cấp mật khẩu, xoá thư và báo cho người lớn","Cung cấp ngay để không bị khoá tài khoản","Chuyển tiếp thư cho bạn bè cùng làm theo","Trả lời thư để hỏi lại cho rõ"],"a":"Không cung cấp mật khẩu, xoá thư và báo cho người lớn","h":"Ngân hàng không bao giờ xin mật khẩu của khách hàng qua email.","e":"Đây là chiêu lừa đảo nhằm đánh cắp tài khoản; em tuyệt đối không cung cấp mật khẩu và nên báo cho người lớn.","t":"tin-lop5","g":5,"l":"kho"},{"p":"Mạng xã hội là gì?","o":["Dịch vụ trên Internet giúp mọi người kết nối, chia sẻ thông tin và trò chuyện với nhau","Một loại trò chơi điện tử trên máy tính","Một thiết bị lưu trữ dữ liệu","Một phần mềm soạn thảo văn bản"],"a":"Dịch vụ trên Internet giúp mọi người kết nối, chia sẻ thông tin và trò chuyện với nhau","h":"Đó là nơi mọi người kết bạn và chia sẻ bài viết, hình ảnh.","e":"Mạng xã hội là dịch vụ trực tuyến giúp mọi người kết nối, chia sẻ thông tin và trò chuyện.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Danh sách đánh số tự động trong văn bản có lợi ích gì?","o":["Các mục được đánh số thứ tự và tự thay đổi khi em thêm hoặc bớt mục","Làm cho chữ trong danh sách to hơn","Tự động đổi màu cho cả danh sách","Giúp văn bản được in ra nhanh hơn"],"a":"Các mục được đánh số thứ tự và tự thay đổi khi em thêm hoặc bớt mục","h":"Em không phải tự gõ số cho từng mục.","e":"Danh sách đánh số tự động giúp các mục luôn đúng thứ tự khi em thêm, bớt hoặc sắp xếp lại mục.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Công cụ Tìm kiếm và Thay thế (Find and Replace) trong soạn thảo dùng để làm gì?","o":["Tìm một từ trong văn bản và thay nó bằng từ khác ở tất cả các vị trí","Tìm tệp văn bản trong máy tính","Thay đổi màu nền của trang giấy","Thay thế hình ảnh bằng văn bản"],"a":"Tìm một từ trong văn bản và thay nó bằng từ khác ở tất cả các vị trí","h":"Rất tiện khi một từ bị gõ sai ở nhiều chỗ trong bài.","e":"Find and Replace giúp tìm một từ và thay thế nó bằng từ khác trong toàn bộ văn bản một cách nhanh chóng.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Trước khi in một văn bản, em nên làm gì để chắc chắn trang in được trình bày đúng ý?","o":["Xem trước khi in (Print Preview)","Tắt màn hình máy tính","Đổi tên tệp văn bản","Gửi văn bản cho bạn bè"],"a":"Xem trước khi in (Print Preview)","h":"Chế độ này cho em nhìn thấy trang giấy trước khi in thật.","e":"Xem trước khi in giúp em kiểm tra bố cục, lề và lỗi trình bày trước khi in ra giấy.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong soạn thảo văn bản, 'lề trang' là gì?","o":["Khoảng trống giữa phần nội dung văn bản và các mép của trang giấy","Đường kẻ ở giữa hai cột văn bản","Tên của người soạn văn bản","Số trang in ở cuối tờ giấy"],"a":"Khoảng trống giữa phần nội dung văn bản và các mép của trang giấy","h":"Đó là phần giấy trắng bao quanh nội dung.","e":"Lề trang là khoảng cách từ nội dung văn bản tới các mép trên, dưới, trái, phải của trang giấy.","t":"tin-lop6","g":6,"l":"kho"},{"p":"Muốn liệt kê các đồ dùng học tập cần mang theo bằng dấu chấm đầu dòng, em dùng loại danh sách nào?","o":["Danh sách gạch đầu dòng (không đánh số)","Danh sách đánh số thứ tự","Bảng biểu","Biểu đồ cột"],"a":"Danh sách gạch đầu dòng (không đánh số)","h":"Các mục này không cần thứ tự trước sau.","e":"Khi các mục không cần xếp thứ tự, em dùng danh sách gạch đầu dòng với dấu chấm hoặc kí hiệu ở đầu mỗi mục.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Trong phần mềm trình chiếu PowerPoint, 'bố cục' (layout) của một trang chiếu là gì?","o":["Cách sắp xếp vị trí của tiêu đề, nội dung và hình ảnh trên trang chiếu","Màu nền của trang chiếu","Hiệu ứng chuyển động của chữ","Số lượng trang chiếu trong bài"],"a":"Cách sắp xếp vị trí của tiêu đề, nội dung và hình ảnh trên trang chiếu","h":"Nó quyết định mỗi thành phần nằm ở đâu trên trang.","e":"Bố cục (layout) quy định cách bố trí tiêu đề, nội dung, hình ảnh trên một trang chiếu.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Hiệu ứng chuyển trang trong bài trình chiếu là gì?","o":["Cách một trang chiếu mới xuất hiện thay cho trang chiếu trước khi trình chiếu","Âm thanh phát ra khi bấm chuột","Màu chữ của tiêu đề trang chiếu","Tên của tệp trình chiếu"],"a":"Cách một trang chiếu mới xuất hiện thay cho trang chiếu trước khi trình chiếu","h":"Hiệu ứng này xảy ra ở khoảnh khắc đổi từ trang này sang trang khác.","e":"Hiệu ứng chuyển trang là hiệu ứng xuất hiện khi chuyển từ trang chiếu này sang trang chiếu tiếp theo.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Trình tự nào sau đây là hợp lí khi tạo một bài trình chiếu đơn giản?","o":["Mở phần mềm, tạo các trang chiếu và nhập nội dung, chèn hình, rồi lưu và trình chiếu thử","Trình chiếu thử trước rồi mới tạo trang chiếu","In bài trình chiếu rồi mới nhập nội dung","Chèn hình vào máy trước khi mở phần mềm"],"a":"Mở phần mềm, tạo các trang chiếu và nhập nội dung, chèn hình, rồi lưu và trình chiếu thử","h":"Làm xong bài mới trình chiếu thử để kiểm tra.","e":"Quy trình hợp lí: mở phần mềm, tạo trang và nhập nội dung, chèn hình minh hoạ, lưu tệp rồi trình chiếu thử.","t":"tin-lop4","g":4,"l":"kho"},{"p":"Một trang chiếu thường gồm những thành phần chính nào?","o":["Tiêu đề và phần nội dung (văn bản, hình ảnh)","Chỉ có hình ảnh động","Chỉ có âm thanh","Chỉ có đúng một dòng chữ"],"a":"Tiêu đề và phần nội dung (văn bản, hình ảnh)","h":"Nhìn vào bất kì trang chiếu mẫu nào em cũng thấy hai phần này.","e":"Trang chiếu thường có tiêu đề ở phía trên và phần nội dung gồm văn bản, hình ảnh ở phía dưới.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong sơ đồ khối của thuật toán, hình chữ nhật thể hiện điều gì?","o":["Một bước xử lí (thao tác cần thực hiện)","Điểm bắt đầu của thuật toán","Điểm kết thúc của thuật toán","Một câu hỏi kiểm tra điều kiện"],"a":"Một bước xử lí (thao tác cần thực hiện)","h":"Hình này khác với hình thoi dùng cho bước kiểm tra điều kiện.","e":"Trong sơ đồ khối, hình chữ nhật biểu diễn một bước xử lí, tức một thao tác cần thực hiện.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong sơ đồ khối, hình ô-van (hình bầu dục) thể hiện điều gì?","o":["Bắt đầu hoặc kết thúc của thuật toán","Một bước tính toán","Một bước kiểm tra điều kiện","Thứ tự thực hiện các bước"],"a":"Bắt đầu hoặc kết thúc của thuật toán","h":"Hình này luôn nằm ở đầu và ở cuối sơ đồ.","e":"Hình ô-van trong sơ đồ khối dùng để đánh dấu điểm bắt đầu hoặc điểm kết thúc của thuật toán.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong sơ đồ khối, các mũi tên có vai trò gì?","o":["Chỉ trình tự thực hiện các bước của thuật toán","Trang trí cho sơ đồ đẹp hơn","Đánh số thứ tự cho các hình","Thể hiện kết quả cuối cùng"],"a":"Chỉ trình tự thực hiện các bước của thuật toán","h":"Mũi tên nối bước trước với bước sau.","e":"Mũi tên trong sơ đồ khối cho biết thứ tự thực hiện: bước nào làm trước, bước nào làm sau.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Cấu trúc tuần tự trong thuật toán là gì?","o":["Các bước được thực hiện lần lượt theo thứ tự, bước trước xong mới tới bước sau","Tất cả các bước được thực hiện cùng một lúc","Các bước được lặp lại nhiều lần không dừng","Chỉ thực hiện bước cuối cùng rồi dừng"],"a":"Các bước được thực hiện lần lượt theo thứ tự, bước trước xong mới tới bước sau","h":"Giống như làm lần lượt từng bước trong một công thức nấu ăn.","e":"Cấu trúc tuần tự là cấu trúc mà các bước của thuật toán được thực hiện lần lượt theo đúng thứ tự đã liệt kê.","t":"tin-lop6","g":6,"l":"kho"},{"p":"Khi dùng một đoạn tài liệu lấy từ Internet cho bài tập của mình, em cần làm gì cho đúng?","o":["Ghi rõ nguồn của tài liệu đó","Không cần ghi gì cả","Đổi tên tác giả thành tên của em","Xoá hết mọi dấu vết của nguồn tài liệu"],"a":"Ghi rõ nguồn của tài liệu đó","h":"Đó là cách tôn trọng công sức của tác giả.","e":"Khi sử dụng tài liệu của người khác, em phải ghi rõ nguồn để tôn trọng tác giả và bản quyền.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây KHÔNG nên làm khi sử dụng mạng Internet?","o":["Công khai địa chỉ nhà và số điện thoại của mình cho mọi người","Hỏi bố mẹ khi gặp điều lạ trên mạng","Dùng Internet để tra cứu bài học","Kết bạn với bạn cùng lớp trên mạng"],"a":"Công khai địa chỉ nhà và số điện thoại của mình cho mọi người","h":"Thông tin cá nhân cần được giữ kín.","e":"Địa chỉ nhà và số điện thoại là thông tin cá nhân, không nên công khai trên mạng để tránh nguy hiểm.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Một bạn sao chép nguyên văn bài viết trên Internet rồi nộp cho thầy cô như bài làm của mình. Việc làm này sai ở điểm nào?","o":["Không trung thực và vi phạm bản quyền vì không ghi nguồn, đó không phải bài do mình làm","Sai vì bài viết trên Internet luôn ngắn hơn bài tự làm","Sai vì máy tính không cho phép sao chép văn bản","Không sai, vì tài liệu trên Internet là của chung mọi người"],"a":"Không trung thực và vi phạm bản quyền vì không ghi nguồn, đó không phải bài do mình làm","h":"Vấn đề nằm ở sự trung thực và tôn trọng tác giả.","e":"Sao chép nguyên văn mà không ghi nguồn là thiếu trung thực và vi phạm bản quyền của tác giả.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Máy in thuộc loại thiết bị nào của máy tính?","o":["Thiết bị vào","Thiết bị ra","Thiết bị lưu trữ","Bộ xử lí trung tâm"],"a":"Thiết bị ra","h":"Nghĩ xem máy in đưa thông tin ra ngoài hay nhận thông tin vào.","e":"Máy in đưa kết quả xử lí từ máy tính ra giấy nên là thiết bị ra.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Khi trình chiếu bài học cho cả lớp, máy chiếu có vai trò gì?","o":["Lưu trữ bài học trong máy tính","Xử lí dữ liệu của bài học","Hiển thị hình ảnh từ máy tính lên màn hình lớn","Kết nối máy tính với Internet"],"a":"Hiển thị hình ảnh từ máy tính lên màn hình lớn","h":"Cả lớp cùng nhìn thấy bài học ở đâu?","e":"Máy chiếu là thiết bị ra, giúp hiển thị hình ảnh từ máy tính lên màn chiếu lớn cho nhiều người cùng xem.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong các dung lượng lưu trữ sau, dung lượng nào lớn nhất?","o":["256 GB","512 GB","128 GB","1 TB"],"a":"1 TB","h":"Nhớ mối quan hệ giữa GB và TB.","e":"1 TB bằng 1024 GB nên lớn hơn 512 GB, 256 GB và 128 GB.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Cổng HDMI trên máy tính thường được dùng để làm gì?","o":["Kết nối máy tính với màn hình hoặc máy chiếu để truyền hình ảnh","Sạc pin cho điện thoại","Kết nối máy tính với mạng có dây","Cắm tai nghe nghe nhạc"],"a":"Kết nối máy tính với màn hình hoặc máy chiếu để truyền hình ảnh","h":"Em thường thấy dây HDMI cắm giữa máy tính và thiết bị nào khi trình chiếu?","e":"Cổng HDMI dùng để truyền tín hiệu hình ảnh (và âm thanh) từ máy tính sang màn hình, ti vi hoặc máy chiếu.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Điểm khác nhau cơ bản giữa ổ cứng gắn trong máy tính và USB là gì?","o":["Ổ cứng không lưu được dữ liệu, USB thì có","Ổ cứng thường có dung lượng lớn và gắn cố định trong máy, USB nhỏ gọn, dễ mang theo","USB có dung lượng lớn hơn mọi ổ cứng","Ổ cứng chỉ lưu được ảnh, USB lưu được mọi loại tệp"],"a":"Ổ cứng thường có dung lượng lớn và gắn cố định trong máy, USB nhỏ gọn, dễ mang theo","h":"So sánh về kích thước, dung lượng và tính di động.","e":"Ổ cứng gắn trong thường có dung lượng lớn và cố định trong máy; USB nhỏ gọn nên tiện mang theo để chép dữ liệu.","t":"tin-lop7","g":7,"l":"kho"},{"p":"Android và iOS là gì?","o":["Phần mềm chơi trò chơi trên điện thoại","Hệ điều hành dành cho điện thoại thông minh","Ứng dụng chụp ảnh","Trình duyệt web trên điện thoại"],"a":"Hệ điều hành dành cho điện thoại thông minh","h":"Điện thoại cần phần mềm nào để hoạt động và chạy các ứng dụng?","e":"Android và iOS là hai hệ điều hành phổ biến trên điện thoại thông minh.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Phần mềm soạn thảo văn bản thuộc loại phần mềm nào?","o":["Hệ điều hành","Phần mềm ứng dụng","Phần mềm hệ thống","Chương trình diệt virus"],"a":"Phần mềm ứng dụng","h":"Phần mềm này phục vụ một công việc cụ thể là soạn thảo.","e":"Phần mềm soạn thảo văn bản phục vụ nhu cầu công việc cụ thể nên thuộc nhóm phần mềm ứng dụng.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Máy tính báo hết dung lượng trống nên không cài thêm được phần mềm mới. Nguyên nhân thường là gì?","o":["Màn hình quá nhỏ","Ổ đĩa lưu trữ đã đầy","Bàn phím bị hỏng","Chuột hết pin"],"a":"Ổ đĩa lưu trữ đã đầy","h":"Phần mềm mới cài vào đâu trong máy tính?","e":"Phần mềm được cài đặt và lưu trên ổ đĩa; khi ổ đĩa đầy sẽ không còn chỗ để cài thêm.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Muốn loại bỏ hẳn một phần mềm không còn sử dụng khỏi máy tính, em nên làm gì?","o":["Chỉ xoá biểu tượng của phần mềm trên màn hình nền","Gỡ cài đặt (uninstall) phần mềm đó đúng cách","Đổi tên thư mục chứa phần mềm","Tắt máy tính rồi mở lại"],"a":"Gỡ cài đặt (uninstall) phần mềm đó đúng cách","h":"Xoá biểu tượng có xoá được phần mềm thật không?","e":"Phải gỡ cài đặt đúng cách thì phần mềm mới bị loại bỏ hoàn toàn; xoá biểu tượng chỉ xoá lối tắt.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Khi cài đặt một phần mềm mới tải từ Internet, việc làm nào quan trọng nhất để tránh mã độc?","o":["Cài thật nhanh trước khi máy tự tắt","Chỉ tải phần mềm từ trang web chính thức, đáng tin cậy và quét virus trước khi cài","Tắt phần mềm diệt virus để cài cho nhanh","Cài mọi phần mềm được quảng cáo trên trang web lạ"],"a":"Chỉ tải phần mềm từ trang web chính thức, đáng tin cậy và quét virus trước khi cài","h":"Phần mềm từ nguồn không rõ ràng có thể chứa gì?","e":"Tải phần mềm từ nguồn chính thức và quét virus trước khi cài giúp tránh cài phải mã độc.","t":"tin-lop7","g":7,"l":"kho"},{"p":"Hàm COUNT trong bảng tính dùng để làm gì?","o":["Tính tổng các số trong một vùng","Đếm số ô có chứa dữ liệu số trong một vùng","Tìm số lớn nhất trong một vùng","Đếm tất cả các ô kể cả ô trống"],"a":"Đếm số ô có chứa dữ liệu số trong một vùng","h":"COUNT liên quan tới việc đếm, không phải tính tổng.","e":"Hàm COUNT đếm số lượng ô có chứa dữ liệu số trong vùng được chọn.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Muốn chèn thêm một hàng mới vào bảng tính, em dùng lệnh nào?","o":["Lệnh Insert để chèn hàng","Lệnh Delete để xoá hàng","Lệnh Save để lưu bảng","Lệnh Print để in bảng"],"a":"Lệnh Insert để chèn hàng","h":"Insert trong tiếng Anh nghĩa là chèn vào.","e":"Dùng lệnh Insert (chèn) để thêm hàng hoặc cột mới vào bảng tính.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi nhập 15/03/2026 vào một ô tính, phần mềm thường hiểu đây là dữ liệu kiểu gì?","o":["Dữ liệu số thập phân","Dữ liệu ngày tháng","Dữ liệu công thức","Dữ liệu hình ảnh"],"a":"Dữ liệu ngày tháng","h":"Dạng ngày/tháng/năm quen thuộc.","e":"Chuỗi nhập theo dạng ngày/tháng/năm được phần mềm bảng tính nhận biết là dữ liệu ngày tháng.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Theo mặc định trong bảng tính, dữ liệu số và dữ liệu chữ thường được căn lề thế nào?","o":["Số căn trái, chữ căn phải","Số căn phải, chữ căn trái","Cả số và chữ đều căn giữa","Cả số và chữ đều căn phải"],"a":"Số căn phải, chữ căn trái","h":"Quan sát vị trí của số và chữ trong ô khi mới nhập.","e":"Mặc định, bảng tính căn dữ liệu số về bên phải và dữ liệu chữ về bên trái của ô.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Ô C1 có công thức =A1+B1. Khi sao chép công thức này xuống ô C2, công thức ở C2 sẽ là gì?","o":["=A1+B1","=A2+B2","=A1+B2","=C1+C2"],"a":"=A2+B2","h":"Địa chỉ tương đối tự thay đổi theo vị trí mới.","e":"Địa chỉ tương đối trong công thức tự điều chỉnh theo hàng mới, nên =A1+B1 ở C1 thành =A2+B2 ở C2.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Một vùng bảng tính gồm các giá trị: 5, 8, Toán, 10. Hàm COUNT áp dụng trên vùng này cho kết quả nào?","o":["4","3","23","0"],"a":"3","h":"COUNT chỉ đếm các ô chứa số.","e":"COUNT chỉ đếm ô có dữ liệu số; vùng có ba số là 5, 8, 10 nên kết quả là 3.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Khi gõ 007 vào một ô tính, phần mềm hiển thị 7. Vì sao?","o":["Phần mềm bị lỗi hiển thị","Vì phần mềm hiểu đó là số nên tự bỏ số 0 ở đầu","Vì ô tính quá hẹp","Vì phông chữ không hiển thị được số 0"],"a":"Vì phần mềm hiểu đó là số nên tự bỏ số 0 ở đầu","h":"Muốn giữ số 0 ở đầu, người ta thường định dạng ô thành kiểu chữ (Text).","e":"Dữ liệu dạng số không giữ số 0 ở đầu; muốn nhập 007 nguyên vẹn phải định dạng ô là Text hoặc thêm dấu nháy trước.","t":"tin-lop7","g":7,"l":"kho"},{"p":"Virus máy tính là gì?","o":["Một loại phần cứng của máy tính","Chương trình độc hại có khả năng lây lan và gây hại cho máy tính, dữ liệu","Phần mềm giúp máy tính chạy nhanh hơn","Tên một trò chơi trên máy tính"],"a":"Chương trình độc hại có khả năng lây lan và gây hại cho máy tính, dữ liệu","h":"Virus máy tính gây hại giống như virus sinh học lây bệnh.","e":"Virus máy tính là chương trình độc hại, tự lây lan sang tệp và máy khác, phá hoại dữ liệu hoặc làm máy hoạt động bất thường.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Phần mềm diệt virus có tác dụng gì?","o":["Tăng tốc độ mạng Internet","Phát hiện, ngăn chặn và loại bỏ virus, mã độc","Tự động làm bài tập cho học sinh","Thay thế cho hệ điều hành"],"a":"Phát hiện, ngăn chặn và loại bỏ virus, mã độc","h":"Tên của phần mềm đã nói rõ tác dụng.","e":"Phần mềm diệt virus quét, phát hiện và xử lí các chương trình độc hại để bảo vệ máy tính.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây giúp phòng tránh virus máy tính hiệu quả?","o":["Mở mọi tệp đính kèm nhận được cho vui","Không mở tệp lạ từ nguồn không rõ ràng, luôn bật phần mềm diệt virus","Tắt phần mềm diệt virus khi chép dữ liệu từ USB","Tải phần mềm từ bất kì trang web nào có quảng cáo hấp dẫn"],"a":"Không mở tệp lạ từ nguồn không rõ ràng, luôn bật phần mềm diệt virus","h":"Virus thường lây qua tệp lạ và USB không an toàn.","e":"Không mở tệp lạ, quét USB trước khi dùng và duy trì phần mềm diệt virus là các cách phòng virus hiệu quả.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Sao lưu (backup) dữ liệu là gì?","o":["Xoá bớt dữ liệu cũ cho nhẹ máy","Tạo bản sao của dữ liệu để phòng khi dữ liệu gốc bị mất hoặc hỏng","Đổi tên dữ liệu thành tên khác","Nén dữ liệu thành một tệp nhỏ hơn"],"a":"Tạo bản sao của dữ liệu để phòng khi dữ liệu gốc bị mất hoặc hỏng","h":"Backup nghĩa là có một bản dự phòng.","e":"Sao lưu là tạo thêm bản sao dữ liệu, lưu ở nơi khác để dùng khi bản gốc gặp sự cố.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Vì sao cần sao lưu dữ liệu thường xuyên?","o":["Để máy tính chạy nhanh hơn","Để khôi phục được dữ liệu khi máy hỏng, bị virus hoặc xoá nhầm","Để chia sẻ dữ liệu cho bạn bè dễ hơn","Để ổ cứng trông gọn gàng hơn"],"a":"Để khôi phục được dữ liệu khi máy hỏng, bị virus hoặc xoá nhầm","h":"Bản sao dự phòng phát huy tác dụng khi nào?","e":"Sao lưu thường xuyên giúp em lấy lại dữ liệu quan trọng khi xảy ra sự cố như hỏng máy, nhiễm virus hay xoá nhầm.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Phần mềm diệt virus KHÔNG làm được việc nào sau đây?","o":["Quét và phát hiện mã độc trong máy","Ngăn chặn tệp độc hại chạy trên máy","Khôi phục dữ liệu đã bị xoá mất mà chưa từng sao lưu","Cập nhật dữ liệu nhận diện virus mới"],"a":"Khôi phục dữ liệu đã bị xoá mất mà chưa từng sao lưu","h":"Việc khôi phục dữ liệu đã mất phụ thuộc vào bản sao lưu.","e":"Phần mềm diệt virus chỉ phòng và xử lí mã độc; dữ liệu đã mất chỉ khôi phục được nếu đã sao lưu từ trước.","t":"tin-lop7","g":7,"l":"kho"},{"p":"Khi sử dụng mạng xã hội, em chỉ nên kết bạn với ai?","o":["Bất kì ai gửi lời mời kết bạn","Những người em quen biết ngoài đời thực","Những tài khoản có nhiều người theo dõi","Những người ở nước ngoài cho vui"],"a":"Những người em quen biết ngoài đời thực","h":"Người lạ trên mạng có thể không phải người tốt.","e":"Chỉ kết bạn với người quen biết giúp em tránh bị lừa đảo và tiếp cận bởi người xấu.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Cài đặt quyền riêng tư trên mạng xã hội giúp em làm gì?","o":["Tăng số người theo dõi nhanh hơn","Kiểm soát ai có thể xem thông tin và bài đăng của em","Đăng bài được dài hơn","Xem được bài đăng của mọi người khác"],"a":"Kiểm soát ai có thể xem thông tin và bài đăng của em","h":"Riêng tư nghĩa là giới hạn người xem.","e":"Quyền riêng tư cho phép em giới hạn phạm vi người xem, ví dụ chỉ bạn bè mới xem được bài đăng và thông tin cá nhân.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây KHÔNG nên làm trên mạng xã hội?","o":["Chia sẻ vị trí trực tiếp cho mọi người biết em đang ở đâu","Đặt ảnh đại diện là hình hoạt hình","Chỉ cho bạn bè xem bài đăng","Đọc tin tức từ các trang chính thống"],"a":"Chia sẻ vị trí trực tiếp cho mọi người biết em đang ở đâu","h":"Thông tin về vị trí có thể bị kẻ xấu lợi dụng.","e":"Chia sẻ vị trí trực tiếp khiến người lạ biết em đang ở đâu, gây nguy hiểm cho bản thân.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Một người lạ trên mạng xã hội nhắn tin hỏi địa chỉ nhà và tên trường của em. Em nên làm gì?","o":["Trả lời đầy đủ vì họ hỏi lịch sự","Không cung cấp thông tin cá nhân, có thể chặn hoặc báo cáo tài khoản đó","Hỏi lại địa chỉ của họ trước","Gửi ảnh chụp thẻ học sinh cho họ xem"],"a":"Không cung cấp thông tin cá nhân, có thể chặn hoặc báo cáo tài khoản đó","h":"Thông tin cá nhân không được chia sẻ cho người lạ.","e":"Tuyệt đối không cho người lạ thông tin cá nhân; nên chặn, báo cáo và nói với người lớn khi cần.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Trước khi đăng ảnh có mặt bạn của em lên mạng xã hội, em nên làm gì?","o":["Đăng ngay vì ảnh chụp rất đẹp","Xin phép bạn trước khi đăng","Gắn thẻ càng nhiều người càng tốt","Chỉnh sửa ảnh tuỳ ý rồi đăng"],"a":"Xin phép bạn trước khi đăng","h":"Ảnh của người khác cũng cần được tôn trọng.","e":"Xin phép trước khi đăng ảnh người khác là ứng xử văn minh và tôn trọng quyền riêng tư của bạn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Một tài khoản mạng xã hội để chế độ công khai, thường xuyên đăng vị trí đang ở và ảnh chụp thẻ học sinh. Nguy cơ lớn nhất là gì?","o":["Bị ít người theo dõi hơn","Người xấu thu thập được thông tin cá nhân để lừa đảo hoặc gây hại","Bài đăng hiển thị chậm hơn","Bị mạng xã hội thu phí đăng bài"],"a":"Người xấu thu thập được thông tin cá nhân để lừa đảo hoặc gây hại","h":"Công khai quá nhiều thông tin giúp kẻ xấu biết những gì về em?","e":"Đăng công khai vị trí và giấy tờ cá nhân giúp kẻ xấu nắm thông tin để lừa đảo, giả mạo hoặc tìm đến gây hại.","t":"tin-lop7","g":7,"l":"kho"},{"p":"Tin giả (fake news) là gì?","o":["Tin tức được đăng trên báo chính thống","Thông tin sai sự thật nhưng được lan truyền như tin thật","Tin tức cũ đã qua lâu ngày","Tin tức chỉ có ít người đọc"],"a":"Thông tin sai sự thật nhưng được lan truyền như tin thật","h":"Fake trong tiếng Anh nghĩa là giả.","e":"Tin giả là thông tin bịa đặt hoặc sai lệch, được phát tán khiến nhiều người tưởng là thật.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi thấy một tin gây sốc lan truyền trên mạng, việc đầu tiên em nên làm là gì?","o":["Chia sẻ ngay cho bạn bè cùng biết","Kiểm chứng nguồn tin trước khi tin và chia sẻ","Bình luận thật nhiều để tin nổi hơn","Lưu lại để sau này kiểm chứng"],"a":"Kiểm chứng nguồn tin trước khi tin và chia sẻ","h":"Đừng vội tin, hãy kiểm tra trước.","e":"Kiểm chứng nguồn tin giúp em tránh tin và lan truyền thông tin sai sự thật.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Dấu hiệu nào sau đây cho thấy một tin tức trên mạng có thể là tin giả?","o":["Tin được nhiều báo uy tín cùng đăng","Tiêu đề giật gân, nguồn không rõ ràng và không thấy ở các báo uy tín","Tin có ghi rõ tác giả và ngày đăng","Tin được cơ quan nhà nước thông báo"],"a":"Tiêu đề giật gân, nguồn không rõ ràng và không thấy ở các báo uy tín","h":"Tin giả thường cố thu hút bằng cảm xúc mạnh.","e":"Tin giả thường có tiêu đề giật gân, thiếu nguồn tin cậy và không được các cơ quan báo chí uy tín đăng tải.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Để kiểm chứng một thông tin trên mạng có đúng hay không, em nên làm gì?","o":["Chỉ đọc bình luận của người khác dưới bài viết","Đối chiếu thông tin ở nhiều nguồn tin uy tín khác nhau","Tin ngay nếu bài viết có nhiều lượt thích","Hỏi ý kiến một người bạn bất kì"],"a":"Đối chiếu thông tin ở nhiều nguồn tin uy tín khác nhau","h":"Một nguồn duy nhất có thể sai; nhiều nguồn uy tín cùng khẳng định sẽ đáng tin hơn.","e":"Đối chiếu ở nhiều nguồn uy tín là cách kiểm chứng thông tin hiệu quả trước khi tin và chia sẻ.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Bạn em chia sẻ một bài viết quảng cáo thuốc chữa bệnh chưa rõ nguồn gốc và rủ em chia sẻ tiếp. Em nên khuyên bạn điều gì?","o":["Chia sẻ ngay vì biết đâu giúp được người bệnh","Không chia sẻ tin chưa kiểm chứng, nên tra cứu ở nguồn y tế chính thống vì tin sai về sức khoẻ rất nguy hiểm","Chỉ chia sẻ cho người thân trong gia đình","Chia sẻ kèm dòng chữ 'nghe nói thế' là được"],"a":"Không chia sẻ tin chưa kiểm chứng, nên tra cứu ở nguồn y tế chính thống vì tin sai về sức khoẻ rất nguy hiểm","h":"Tin giả về sức khoẻ có thể làm người bệnh bỏ qua cách chữa đúng.","e":"Không lan truyền tin chưa kiểm chứng; thông tin sức khoẻ phải tra cứu từ cơ quan y tế và báo chí chính thống.","t":"tin-lop8","g":8,"l":"kho"},{"p":"Địa chỉ tuyệt đối trong bảng tính có đặc điểm gì?","o":["Không có tên cột và số hàng","Có dấu $ trước tên cột và số hàng, ví dụ $A$1","Luôn nằm ở ô đầu tiên của bảng","Tự thay đổi khi sao chép công thức"],"a":"Có dấu $ trước tên cột và số hàng, ví dụ $A$1","h":"Dấu $ là dấu hiệu nhận biết.","e":"Địa chỉ tuyệt đối được viết với dấu $ trước cột và hàng, ví dụ $A$1.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Tác dụng của địa chỉ tuyệt đối khi sao chép công thức là gì?","o":["Giúp công thức tính nhanh hơn","Địa chỉ ô đó không thay đổi dù sao chép công thức tới vị trí nào","Tự động xoá các ô không cần thiết","Đổi màu cho ô chứa công thức"],"a":"Địa chỉ ô đó không thay đổi dù sao chép công thức tới vị trí nào","h":"Tuyệt đối nghĩa là cố định, không đổi.","e":"Địa chỉ tuyệt đối giữ nguyên khi sao chép công thức, thường dùng cho các giá trị cố định như tỉ lệ, đơn giá.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Biểu đồ tròn thường được dùng để thể hiện điều gì?","o":["Sự thay đổi của dữ liệu theo thời gian","Tỉ lệ phần trăm của các phần trong một tổng thể","So sánh chiều cao của các cột dữ liệu","Mối quan hệ giữa hai đại lượng"],"a":"Tỉ lệ phần trăm của các phần trong một tổng thể","h":"Cả hình tròn là 100%.","e":"Biểu đồ tròn chia tổng thể thành các phần theo tỉ lệ phần trăm, thích hợp để xem cơ cấu.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Biểu đồ đường thường được dùng để thể hiện điều gì?","o":["Sự thay đổi, xu hướng của dữ liệu theo thời gian","Tỉ lệ phần trăm trong một tổng thể","Danh sách học sinh của lớp","Kết quả của một phép tính"],"a":"Sự thay đổi, xu hướng của dữ liệu theo thời gian","h":"Đường nối các điểm cho thấy dữ liệu lên xuống thế nào.","e":"Biểu đồ đường thích hợp để theo dõi xu hướng biến đổi của dữ liệu qua các mốc thời gian.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Hàm SUMIF trong bảng tính dùng để làm gì?","o":["Tính tổng tất cả các số trong bảng","Tính tổng các ô thoả mãn một điều kiện cho trước","Đếm số ô có dữ liệu","Tìm giá trị trung bình của một vùng"],"a":"Tính tổng các ô thoả mãn một điều kiện cho trước","h":"SUM là tổng, IF là điều kiện.","e":"SUMIF tính tổng có điều kiện, chỉ cộng những ô đáp ứng điều kiện đã cho.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Ô C1 có công thức =A1*$B$1. Khi sao chép công thức xuống ô C2, công thức ở C2 sẽ là gì?","o":["=A1*$B$1","=A2*$B$1","=A2*$B$2","=A1*$B$2"],"a":"=A2*$B$1","h":"Phần có dấu $ giữ nguyên, phần còn lại thay đổi theo hàng.","e":"A1 là địa chỉ tương đối nên thành A2; $B$1 là địa chỉ tuyệt đối nên giữ nguyên khi sao chép.","t":"tin-lop8","g":8,"l":"kho"},{"p":"Một ô chứa giá trị 0,25. Khi định dạng ô theo kiểu phần trăm (Percent), ô sẽ hiển thị thế nào?","o":["0,25%","25%","250%","2,5%"],"a":"25%","h":"Đổi số thập phân sang phần trăm bằng cách nhân với 100.","e":"0,25 bằng 25/100 nên khi định dạng phần trăm sẽ hiển thị là 25%.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Sắp xếp dữ liệu giảm dần trong bảng tính nghĩa là sắp xếp thế nào?","o":["Từ giá trị nhỏ nhất đến lớn nhất","Từ giá trị lớn nhất đến nhỏ nhất","Theo thứ tự nhập dữ liệu ban đầu","Theo màu sắc của ô dữ liệu"],"a":"Từ giá trị lớn nhất đến nhỏ nhất","h":"Giảm dần là đi xuống.","e":"Sắp xếp giảm dần xếp dữ liệu từ lớn đến bé, ví dụ điểm số từ cao xuống thấp.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Bảng điểm được sắp xếp theo cột tổng điểm giảm dần. Học sinh có tổng điểm cao nhất sẽ nằm ở đâu?","o":["Ở cuối danh sách","Ở đầu danh sách","Ở giữa danh sách","Bị ẩn khỏi danh sách"],"a":"Ở đầu danh sách","h":"Giảm dần bắt đầu từ giá trị lớn nhất.","e":"Sắp xếp giảm dần đưa giá trị lớn nhất lên đầu nên học sinh điểm cao nhất đứng đầu danh sách.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Từ bảng dữ liệu chung của cả lớp, em muốn vẽ biểu đồ chỉ thể hiện học sinh nữ. Việc nên làm trước khi vẽ biểu đồ là gì?","o":["Xoá hết dữ liệu của học sinh nam","Lọc dữ liệu để chỉ hiển thị học sinh nữ rồi vẽ biểu đồ trên dữ liệu đã lọc","Đổi màu chữ của học sinh nữ","Sao chép bảng sang một tệp hoàn toàn mới"],"a":"Lọc dữ liệu để chỉ hiển thị học sinh nữ rồi vẽ biểu đồ trên dữ liệu đã lọc","h":"Lọc giúp chọn đúng nhóm dữ liệu cần xem mà không xoá dữ liệu gốc.","e":"Lọc dữ liệu chọn ra nhóm cần thiết, sau đó biểu đồ sẽ thể hiện đúng nhóm dữ liệu đã lọc.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Khi lọc dữ liệu trong bảng tính, các hàng không thoả mãn điều kiện lọc sẽ thế nào?","o":["Bị xoá vĩnh viễn khỏi bảng","Bị ẩn đi tạm thời, dữ liệu vẫn còn nguyên","Bị chuyển sang một bảng tính khác","Bị đổi thành số 0"],"a":"Bị ẩn đi tạm thời, dữ liệu vẫn còn nguyên","h":"Bỏ lọc đi thì dữ liệu có hiện lại không?","e":"Lọc chỉ ẩn tạm thời các hàng không thoả điều kiện; khi bỏ lọc, toàn bộ dữ liệu hiện lại đầy đủ.","t":"tin-lop8","g":8,"l":"kho"},{"p":"Trong Scratch, khối lệnh 'hỏi ... và chờ' dùng để làm gì?","o":["Hiển thị lời thoại của nhân vật","Hỏi người chơi và nhận câu trả lời do người chơi nhập vào","Đặt câu hỏi cho giáo viên","Tạm dừng chương trình mãi mãi"],"a":"Hỏi người chơi và nhận câu trả lời do người chơi nhập vào","h":"Khối này thuộc nhóm Cảm biến, dùng trong trò chơi hỏi đáp.","e":"Khối 'hỏi và chờ' hiển thị câu hỏi và chờ người chơi gõ câu trả lời để chương trình xử lí tiếp.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong Scratch, câu trả lời do người chơi nhập vào sau khối 'hỏi và chờ' được lưu ở đâu?","o":["Trong khối 'trả lời'","Trong tên của nhân vật","Trong hình nền sân khấu","Trong khối âm thanh"],"a":"Trong khối 'trả lời'","h":"Có một khối riêng cùng nhóm Cảm biến giữ nội dung này.","e":"Nội dung người chơi nhập được lưu trong khối 'trả lời' để các lệnh sau có thể sử dụng.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Muốn trò chơi Scratch kết thúc khi nhân vật chạm vào chướng ngại vật, em dùng nhóm khối nào?","o":["Khối cảm biến kiểm tra 'chạm vào ...' kết hợp khối điều kiện","Khối âm thanh phát tiếng","Khối bút vẽ lên sân khấu","Khối thay đổi trang phục"],"a":"Khối cảm biến kiểm tra 'chạm vào ...' kết hợp khối điều kiện","h":"Cần phát hiện sự va chạm trước rồi mới xử lí.","e":"Khối cảm biến 'chạm vào' trong khối điều kiện giúp chương trình phát hiện va chạm và thực hiện hành động như dừng trò chơi.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Khối lệnh 'tạo bản sao của chính tôi' trong Scratch có tác dụng gì?","o":["Lưu chương trình thành một tệp mới","Tạo thêm một nhân vật giống hệt để hoạt động độc lập","Xoá nhân vật khỏi sân khấu","Đổi tên cho nhân vật"],"a":"Tạo thêm một nhân vật giống hệt để hoạt động độc lập","h":"Bản sao trong tiếng Anh là clone.","e":"Tạo bản sao giúp sinh ra nhiều nhân vật giống nhau, ví dụ nhiều quả táo rơi cùng lúc trong trò chơi hứng táo.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trò chơi hứng táo trong Scratch: mỗi lần quả táo chạm vào giỏ, điểm tăng thêm 1. Khối lệnh nào xử lí việc tăng điểm?","o":["Khối 'thay đổi Điểm thêm 1' đặt trong điều kiện khi táo chạm giỏ","Khối 'nói Xin chào trong 2 giây'","Khối 'phát âm thanh' đặt ở đầu chương trình","Khối 'đi tới vị trí ngẫu nhiên' đặt riêng lẻ"],"a":"Khối 'thay đổi Điểm thêm 1' đặt trong điều kiện khi táo chạm giỏ","h":"Điểm chỉ tăng đúng vào thời điểm táo chạm giỏ.","e":"Khi điều kiện chạm giỏ đúng, lệnh thay đổi biến Điểm thêm 1 được thực hiện, đúng với luật của trò chơi.","t":"tin-lop8","g":8,"l":"kho"},{"p":"Cắt ảnh (crop) là thao tác chỉnh sửa ảnh nào?","o":["Thay đổi màu sắc của toàn bộ ảnh","Cắt bỏ phần thừa xung quanh, giữ lại phần ảnh cần dùng","Ghép nhiều ảnh thành một ảnh","Làm mờ toàn bộ ảnh"],"a":"Cắt bỏ phần thừa xung quanh, giữ lại phần ảnh cần dùng","h":"Giống như dùng kéo cắt bỏ viền thừa của tờ giấy.","e":"Cắt ảnh loại bỏ phần không cần thiết ở các cạnh, giúp bức ảnh tập trung vào chủ thể chính.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Một bức ảnh chụp bị nghiêng. Em dùng thao tác nào để sửa?","o":["Cắt ảnh","Xoay ảnh","Đổi tên tệp ảnh","Nén ảnh"],"a":"Xoay ảnh","h":"Cần đưa ảnh về hướng thẳng đứng bình thường.","e":"Thao tác xoay ảnh giúp chỉnh lại hướng của ảnh bị nghiêng hoặc bị ngược.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Một bức ảnh chụp thiếu sáng, trông quá tối. Em nên chỉnh thông số nào?","o":["Tăng độ sáng của ảnh","Giảm kích thước tệp ảnh","Đổi định dạng của ảnh","Xoá phông nền của ảnh"],"a":"Tăng độ sáng của ảnh","h":"Ảnh tối cần thêm sáng.","e":"Tăng độ sáng (và có thể thêm tương phản) giúp bức ảnh tối trở nên rõ ràng, dễ nhìn hơn.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Âm thanh số là gì?","o":["Âm thanh phát ra từ loa của máy tính","Âm thanh được ghi lại và biểu diễn dưới dạng dữ liệu số để máy tính lưu trữ, xử lí và phát lại","Tên một phần mềm nghe nhạc","Âm thanh chỉ nghe được bằng tai nghe"],"a":"Âm thanh được ghi lại và biểu diễn dưới dạng dữ liệu số để máy tính lưu trữ, xử lí và phát lại","h":"Giống như ảnh số, âm thanh cũng được số hoá.","e":"Âm thanh số là âm thanh đã được chuyển thành dữ liệu số, có thể lưu trong tệp, chỉnh sửa và phát lại bằng thiết bị số.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Tin nhắn tự xưng là ngân hàng, yêu cầu em cung cấp mã OTP để 'tránh bị khoá tài khoản'. Đây là dấu hiệu của điều gì?","o":["Chương trình khuyến mãi của ngân hàng","Hành vi lừa đảo mạo danh để chiếm đoạt tài khoản","Thông báo bảo mật bình thường","Lỗi hệ thống của ngân hàng"],"a":"Hành vi lừa đảo mạo danh để chiếm đoạt tài khoản","h":"Ngân hàng không bao giờ hỏi mã OTP qua tin nhắn.","e":"Kẻ xấu mạo danh ngân hàng để dụ cung cấp mã OTP và chiếm tiền trong tài khoản; ngân hàng không bao giờ yêu cầu mã OTP như vậy.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Em nhận được tin nhắn lạ tự xưng là nhà trường, yêu cầu chuyển tiền học qua một đường liên kết. Em nên làm gì?","o":["Chuyển tiền ngay để không bị ghi nợ học phí","Không bấm liên kết và không chuyển tiền, kiểm chứng lại qua giáo viên hoặc số điện thoại chính thức của trường","Chia sẻ tin nhắn cho bạn bè để cùng chuyển","Cung cấp thông tin tài khoản để họ kiểm tra"],"a":"Không bấm liên kết và không chuyển tiền, kiểm chứng lại qua giáo viên hoặc số điện thoại chính thức của trường","h":"Mọi yêu cầu chuyển tiền qua liên kết lạ đều đáng ngờ.","e":"Cần kiểm chứng qua kênh chính thức trước khi làm theo bất kì yêu cầu chuyển tiền nào nhận qua tin nhắn lạ.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Khi dùng Wi-Fi công cộng miễn phí ở quán cà phê, việc làm nào sau đây tiềm ẩn rủi ro?","o":["Đọc tin tức trên báo điện tử","Đăng nhập tài khoản ngân hàng và giao dịch chuyển tiền","Xem dự báo thời tiết","Nghe nhạc trực tuyến"],"a":"Đăng nhập tài khoản ngân hàng và giao dịch chuyển tiền","h":"Wi-Fi công cộng không được bảo vệ, kẻ xấu có thể nghe lén dữ liệu.","e":"Wi-Fi công cộng kém an toàn, thông tin đăng nhập và giao dịch quan trọng có thể bị đánh cắp.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Em nhận được tin nhắn giống hệt thông báo của ngân hàng, kèm đường liên kết đăng nhập để 'xác minh tài khoản'. Cách xử lí đúng nhất là gì?","o":["Bấm ngay vào liên kết trong tin nhắn và đăng nhập","Không dùng liên kết trong tin nhắn; tự mở ứng dụng hoặc trang web chính thức của ngân hàng để kiểm tra","Chuyển tiếp tin nhắn cho bạn bè để hỏi ý kiến","Trả lời tin nhắn để hỏi lại ngân hàng"],"a":"Không dùng liên kết trong tin nhắn; tự mở ứng dụng hoặc trang web chính thức của ngân hàng để kiểm tra","h":"Liên kết trong tin nhắn có thể dẫn tới trang giả mạo giống hệt trang thật.","e":"Trang đăng nhập giả mạo qua liên kết lạ là bẫy lừa đảo quen thuộc; luôn tự truy cập kênh chính thức của ngân hàng.","t":"tin-lop8","g":8,"l":"kho"},{"p":"Trong Python, phép toán 10 % 3 cho kết quả bằng bao nhiêu?","o":["0","1","3","10"],"a":"1","h":"% là phép chia lấy phần dư.","e":"10 chia cho 3 được 3, dư 1 nên 10 % 3 = 1.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong Python, 2 ** 3 cho kết quả bằng bao nhiêu?","o":["6","8","9","5"],"a":"8","h":"** là phép luỹ thừa.","e":"2 ** 3 nghĩa là 2 × 2 × 2 = 8.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong Python, toán tử == được dùng để làm gì?","o":["Gán giá trị cho biến","So sánh hai giá trị có bằng nhau không","Cộng hai số với nhau","In kết quả ra màn hình"],"a":"So sánh hai giá trị có bằng nhau không","h":"Đừng nhầm với dấu = dùng để gán.","e":"== là phép so sánh bằng, cho kết quả True nếu hai giá trị bằng nhau.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Hàm len('Python') cho kết quả bằng bao nhiêu?","o":["5","6","7","12"],"a":"6","h":"Hãy đếm từng kí tự trong chuỗi.","e":"Chuỗi 'Python' có 6 kí tự: P, y, t, h, o, n.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong Python, biểu thức so sánh 5 != 5 cho kết quả là gì?","o":["True","False","5","Chương trình báo lỗi"],"a":"False","h":"!= nghĩa là 'khác nhau'.","e":"5 != 5 nghĩa là '5 khác 5'; điều này sai nên kết quả là False.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong Python, biểu thức 'Ha' + 'Noi' cho kết quả nào?","o":["HaNoi","Ha Noi","Ha+Noi","Chương trình báo lỗi"],"a":"HaNoi","h":"Dấu + với chuỗi có tác dụng nối chuỗi.","e":"Dấu + nối hai chuỗi lại liền nhau thành 'HaNoi'.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong Python, biểu thức 'ab' * 3 cho kết quả nào?","o":["ababab","ab3","ab ab ab","Chương trình báo lỗi"],"a":"ababab","h":"Một chuỗi có thể được lặp lại nhiều lần.","e":"'ab' * 3 lặp lại chuỗi 'ab' ba lần, được 'ababab'.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Bạn Bình đọc được một số dưới dạng chuỗi '15' và muốn chuyển thành số nguyên để tính toán. Bạn cần dùng hàm nào?","o":["str()","int()","print()","len()"],"a":"int()","h":"Tên hàm gợi nhớ đến từ 'integer' (số nguyên).","e":"Hàm int() chuyển một chuỗi số như '15' thành số nguyên 15.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong Python, biểu thức (5 > 3) and (2 < 1) cho kết quả là gì?","o":["True","False","Lỗi cú pháp","Không xác định được"],"a":"False","h":"Phép and chỉ đúng khi cả hai vế đều đúng.","e":"(5 > 3) là True nhưng (2 < 1) là False; phép and cần cả hai cùng đúng nên kết quả là False.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Trong Python, biểu thức (7 % 4) + (2 ** 3) cho kết quả bằng bao nhiêu?","o":["10","11","12","15"],"a":"11","h":"Tính từng phần trước: 7 % 4 bằng mấy, 2 ** 3 bằng mấy?","e":"7 % 4 = 3 và 2 ** 3 = 8, vậy 3 + 8 = 11.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Cấu trúc if / elif / else trong chương trình được dùng khi nào?","o":["Khi cần lặp lại một lệnh nhiều lần","Khi cần lựa chọn thực hiện lệnh tuỳ theo điều kiện","Khi cần khai báo một biến mới","Khi cần lưu dữ liệu vào tệp"],"a":"Khi cần lựa chọn thực hiện lệnh tuỳ theo điều kiện","h":"Đây còn gọi là cấu trúc rẽ nhánh.","e":"if/elif/else giúp chương trình rẽ nhánh: kiểm tra điều kiện để chọn khối lệnh phù hợp.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Vòng lặp while trong Python thường được dùng khi nào?","o":["Khi biết trước chính xác số lần lặp","Khi muốn lặp lại lệnh trong lúc điều kiện còn đúng","Khi muốn khai báo một danh sách","Khi muốn in kết quả ra màn hình"],"a":"Khi muốn lặp lại lệnh trong lúc điều kiện còn đúng","h":"while trong tiếng Anh nghĩa là 'trong khi'.","e":"Vòng while kiểm tra điều kiện trước mỗi vòng lặp; điều kiện còn đúng thì còn lặp.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho đoạn chương trình: x = 7; if x > 5: print('Lớn') else: print('Nhỏ'). Chương trình in ra gì?","o":["Lớn","Nhỏ","7","Không in gì cả"],"a":"Lớn","h":"Hãy so sánh 7 với 5 trước.","e":"7 > 5 là đúng nên chương trình thực hiện lệnh ở nhánh if và in ra 'Lớn'.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Cho đoạn chương trình: s = 0; i = 1; while i <= 3: s = s + i; i = i + 1; print(s). Kết quả in ra là bao nhiêu?","o":["3","5","6","9"],"a":"6","h":"Cộng lần lượt i = 1, 2, 3 vào s.","e":"Qua ba vòng lặp, s = 0 + 1 + 2 + 3 = 6.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Trong Python, giá trị 2024 thuộc kiểu dữ liệu nào?","o":["Số nguyên (int)","Số thực (float)","Chuỗi kí tự (str)","Danh sách (list)"],"a":"Số nguyên (int)","h":"Giá trị này không có phần thập phân.","e":"Số 2024 là số nguyên nên thuộc kiểu dữ liệu int trong Python.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho danh sách a = [10, 20, 30]. Phần tử đầu tiên của danh sách có chỉ số là bao nhiêu?","o":["1","0","10","-1"],"a":"0","h":"Trong Python, việc đánh chỉ số bắt đầu rất đặc biệt.","e":"Python đánh chỉ số bắt đầu từ 0, nên phần tử đầu tiên có chỉ số 0.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho danh sách a = [2, 4, 6, 8, 10]. Giá trị của biểu thức len(a) - a[0] bằng bao nhiêu?","o":["2","3","5","8"],"a":"3","h":"Tính len(a) và a[0] riêng trước rồi trừ.","e":"len(a) = 5 phần tử, a[0] = 2, vậy 5 - 2 = 3.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Cho danh sách a = [5, 10, 15]. Giá trị của a[0] + a[2] bằng bao nhiêu?","o":["15","20","25","30"],"a":"20","h":"a[0] là phần tử đầu tiên, a[2] là phần tử thứ ba.","e":"a[0] = 5 và a[2] = 15 nên tổng là 20.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Lỗi cú pháp (syntax error) trong chương trình là lỗi gì?","o":["Lỗi do máy tính bị hỏng phần cứng","Lỗi viết sai quy tắc của ngôn ngữ lập trình","Lỗi do mất kết nối mạng","Lỗi do người dùng nhập dữ liệu chậm"],"a":"Lỗi viết sai quy tắc của ngôn ngữ lập trình","h":"Ví dụ như thiếu dấu ngoặc hoặc viết sai từ khoá.","e":"Lỗi cú pháp xảy ra khi câu lệnh viết không đúng quy tắc của ngôn ngữ, khiến chương trình không chạy được.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Vì sao sau khi viết chương trình, người lập trình cần kiểm thử chương trình?","o":["Để chương trình có giao diện đẹp hơn","Để phát hiện và sửa các lỗi trước khi sử dụng thật","Để đổi tên cho chương trình","Để in chương trình ra giấy"],"a":"Để phát hiện và sửa các lỗi trước khi sử dụng thật","h":"Kiểm thử giống như kiểm tra lại bài làm trước khi nộp.","e":"Kiểm thử là chạy thử chương trình với nhiều dữ liệu khác nhau để tìm và sửa lỗi sớm.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Bạn An viết lệnh print('Xin chào' nhưng quên dấu đóng ngoặc ). Khi chạy, chương trình báo lỗi. Đây là loại lỗi nào?","o":["Lỗi cú pháp","Lỗi logic","Lỗi dữ liệu","Không phải là lỗi"],"a":"Lỗi cú pháp","h":"Thiếu dấu ngoặc là viết sai quy tắc viết lệnh.","e":"Thiếu dấu đóng ngoặc khiến câu lệnh không đúng cấu trúc, đó là lỗi cú pháp.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Một chương trình chạy được bình thường, không báo lỗi, nhưng cho kết quả tính toán sai so với yêu cầu. Đây là loại lỗi nào?","o":["Lỗi cú pháp","Lỗi logic (sai thuật toán)","Lỗi phần cứng","Lỗi hệ điều hành"],"a":"Lỗi logic (sai thuật toán)","h":"Chương trình 'chạy được' nhưng 'nghĩ sai'.","e":"Lỗi logic xảy ra khi thuật toán hoặc công thức chưa đúng, chương trình vẫn chạy nhưng cho kết quả sai.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trong một bảng dữ liệu, khoá chính có vai trò gì?","o":["Giúp sắp xếp dữ liệu theo bảng chữ cái","Giúp phân biệt từng bản ghi, không có hai bản ghi nào trùng giá trị khoá chính","Giúp xoá nhanh dữ liệu cũ","Giúp in bảng dữ liệu ra giấy"],"a":"Giúp phân biệt từng bản ghi, không có hai bản ghi nào trùng giá trị khoá chính","h":"Hãy liên tưởng tới mã học sinh riêng của mỗi bạn trong lớp.","e":"Khoá chính nhận diện duy nhất mỗi bản ghi, giống như mã học sinh không bạn nào trùng nhau.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Phần mềm nào sau đây là một hệ quản trị cơ sở dữ liệu?","o":["Microsoft Word","Microsoft Access","Paint","Windows Media Player"],"a":"Microsoft Access","h":"Hệ quản trị CSDL giúp tạo và quản lí các bảng dữ liệu.","e":"Microsoft Access là hệ quản trị cơ sở dữ liệu phổ biến được giới thiệu trong chương trình phổ thông.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Thư viện trường dùng cơ sở dữ liệu để quản lí mượn sách. Để biết một quyển sách đang được bạn nào mượn, thủ thư nên làm gì?","o":["Đếm lại toàn bộ sách trên kệ","Tra cứu trong bảng dữ liệu quản lí mượn — trả sách","Hỏi từng học sinh trong trường","In lại toàn bộ danh mục sách"],"a":"Tra cứu trong bảng dữ liệu quản lí mượn — trả sách","h":"Điểm mạnh nhất của CSDL là tìm kiếm nhanh.","e":"Chỉ cần tra cứu theo tên sách trong bảng mượn — trả là biết ngay bạn nào đang mượn.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Một siêu thị dùng cơ sở dữ liệu để quản lí bán hàng. Cơ sở dữ liệu hỗ trợ tốt nhất cho việc nào sau đây?","o":["Trang trí cửa hàng đẹp hơn","Tra cứu nhanh thông tin và giá của hàng hoá khi tính tiền","Tự động nấu ăn cho nhân viên","Phát nhạc trong siêu thị"],"a":"Tra cứu nhanh thông tin và giá của hàng hoá khi tính tiền","h":"Hãy nghĩ tới lúc nhân viên quét mã vạch ở quầy thu ngân.","e":"Khi quét mã hàng, CSDL cho ngay tên và giá sản phẩm, giúp tính tiền nhanh và chính xác.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Lập trình viên là người làm công việc nào?","o":["Sửa chữa phần cứng máy tính","Viết các chương trình và phần mềm máy tính","Bán máy tính tại cửa hàng","Dạy thể dục cho học sinh"],"a":"Viết các chương trình và phần mềm máy tính","h":"Tên nghề gắn liền với từ 'lập trình'.","e":"Lập trình viên dùng ngôn ngữ lập trình để tạo ra các phần mềm phục vụ nhu cầu khác nhau.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Thương mại điện tử là gì?","o":["Việc mua bán hàng hoá và dịch vụ qua mạng Internet","Việc học trực tuyến qua video","Việc gửi thư điện tử cho bạn bè","Việc chơi trò chơi trực tuyến"],"a":"Việc mua bán hàng hoá và dịch vụ qua mạng Internet","h":"Ví dụ: mua hàng trên các sàn như Shopee, Tiki.","e":"Thương mại điện tử cho phép chọn hàng, thanh toán và nhận hàng mà không cần đến trực tiếp cửa hàng.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Quản trị mạng là người đảm nhiệm công việc nào?","o":["Thiết kế bìa sách và tờ rơi","Quản lí, vận hành và đảm bảo hệ thống mạng máy tính hoạt động ổn định","Viết bài quảng cáo cho trang web","Thu ngân tại siêu thị"],"a":"Quản lí, vận hành và đảm bảo hệ thống mạng máy tính hoạt động ổn định","h":"Tên nghề gắn liền với 'mạng máy tính'.","e":"Quản trị mạng cài đặt, theo dõi và xử lí sự cố để mạng của cơ quan, trường học luôn thông suốt.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Dịch vụ công trực tuyến giúp người dân thuận tiện nhất ở điểm nào?","o":["Được mua hàng giảm giá mỗi ngày","Làm các thủ tục hành chính qua mạng mà không phải đến trực tiếp cơ quan","Xem phim miễn phí không giới hạn","Chơi trò chơi cùng bạn bè"],"a":"Làm các thủ tục hành chính qua mạng mà không phải đến trực tiếp cơ quan","h":"Ví dụ: đăng kí làm căn cước qua cổng dịch vụ công.","e":"Dịch vụ công trực tuyến giúp người dân nộp hồ sơ và nhận kết quả qua mạng, tiết kiệm thời gian đi lại.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Điện toán đám mây (cloud computing) là gì?","o":["Một loại máy tính để bàn thế hệ mới","Việc lưu trữ và xử lí dữ liệu trên các máy chủ qua Internet thay vì chỉ trên máy cá nhân","Một kiểu mạng không dây trong gia đình","Phần mềm giúp làm mát máy tính"],"a":"Việc lưu trữ và xử lí dữ liệu trên các máy chủ qua Internet thay vì chỉ trên máy cá nhân","h":"Dữ liệu 'nằm trên Internet' nên dùng ở đâu cũng được.","e":"Với điện toán đám mây, dữ liệu được lưu trên máy chủ của nhà cung cấp và truy cập được qua Internet.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Ví dụ nào sau đây là ứng dụng của điện toán đám mây?","o":["Lưu ảnh và tài liệu trên Google Drive để xem trên nhiều thiết bị","Lưu tệp vào USB mang theo người","Ghi tệp ra đĩa CD","In tài liệu ra giấy để cất"],"a":"Lưu ảnh và tài liệu trên Google Drive để xem trên nhiều thiết bị","h":"Dịch vụ nào trong các lựa chọn hoạt động qua Internet?","e":"Google Drive là dịch vụ lưu trữ đám mây: tệp nằm trên máy chủ trực tuyến, mở được ở mọi nơi có Internet.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Thiết bị thông minh (ví dụ: đồng hồ thông minh, tivi thông minh) khác thiết bị thông thường chủ yếu ở điểm nào?","o":["Màn hình lớn hơn thiết bị thường","Có khả năng kết nối, thu thập và xử lí dữ liệu để phục vụ người dùng tốt hơn","Giá bán cao hơn thiết bị thường","Chỉ dùng pin sạc, không dùng điện trực tiếp"],"a":"Có khả năng kết nối, thu thập và xử lí dữ liệu để phục vụ người dùng tốt hơn","h":"Chữ 'thông minh' đến từ khả năng xử lí dữ liệu.","e":"Thiết bị thông minh có cảm biến, kết nối mạng và tự xử lí dữ liệu, ví dụ đồng hồ thông minh đo nhịp tim rồi đồng bộ với điện thoại.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Các trang thương mại điện tử thường gợi ý đúng sản phẩm mà từng người dùng quan tâm. Khả năng này chủ yếu nhờ vào công nghệ nào?","o":["Phân tích dữ liệu lớn (Big Data)","Công nghệ in 3D","Thực tế tăng cường (AR)","Robot tự động trong kho hàng"],"a":"Phân tích dữ liệu lớn (Big Data)","h":"Hệ thống phải 'học' từ rất nhiều dữ liệu về hành vi mua sắm.","e":"Phân tích dữ liệu lớn từ lịch sử xem và mua hàng giúp hệ thống dự đoán sở thích của từng người dùng.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Điều hoà thông minh có thể tự tăng hoặc giảm công suất để giữ nhiệt độ phòng luôn ổn định. Bộ phận nào giúp nó 'cảm nhận' được nhiệt độ trong phòng?","o":["Màn hình cảm ứng","Cảm biến nhiệt độ","Loa thông minh","Camera an ninh"],"a":"Cảm biến nhiệt độ","h":"'Cảm nhận' là nhiệm vụ của các cảm biến.","e":"Cảm biến nhiệt độ đo nhiệt độ phòng và gửi dữ liệu về bộ xử lí để điều hoà tự điều chỉnh.","t":"tin-lop10","g":10,"l":"kho"},{"p":"WWW (World Wide Web) là gì?","o":["Tên của một trình duyệt web","Hệ thống các trang web và tài nguyên liên kết với nhau trên Internet","Một loại mạng máy tính trong nhà","Tên của một hệ điều hành"],"a":"Hệ thống các trang web và tài nguyên liên kết với nhau trên Internet","h":"WWW là viết tắt của World Wide Web.","e":"WWW là hệ thống thông tin gồm vô số trang web liên kết với nhau mà em truy cập qua trình duyệt.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong thư điện tử, 'tệp đính kèm' có nghĩa là gì?","o":["Thư bị đánh dấu là thư rác","Một tệp (ảnh, tài liệu...) được gửi kèm theo nội dung thư","Địa chỉ của người gửi thư","Mật khẩu của hộp thư"],"a":"Một tệp (ảnh, tài liệu...) được gửi kèm theo nội dung thư","h":"Hãy nhớ biểu tượng chiếc kẹp giấy trong hộp thư.","e":"Khi gửi email, ta có thể đính kèm thêm tệp như ảnh hoặc tài liệu để người nhận tải về xem.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Wi-Fi là công nghệ dùng để làm gì?","o":["Kết nối các thiết bị vào mạng mà không cần dây cáp","Sạc pin cho điện thoại nhanh hơn","Tăng dung lượng ổ cứng của máy tính","Gửi thư điện tử tự động"],"a":"Kết nối các thiết bị vào mạng mà không cần dây cáp","h":"Nhờ nó mà điện thoại vào mạng không cần cắm dây.","e":"Wi-Fi kết nối thiết bị với mạng bằng sóng vô tuyến trong phạm vi gần như nhà ở, trường học, quán cà phê.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Tên miền kết thúc bằng .edu.vn thường thuộc về tổ chức nào?","o":["Cơ quan nhà nước của Việt Nam","Cơ sở giáo dục (trường học) của Việt Nam","Doanh nghiệp thương mại nước ngoài","Tổ chức phi chính phủ quốc tế"],"a":"Cơ sở giáo dục (trường học) của Việt Nam","h":"'edu' là viết tắt của education (giáo dục).","e":".edu.vn là tên miền dành cho lĩnh vực giáo dục của Việt Nam, ví dụ trang web của các trường học.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Khi em gõ 'tuoitre.vn' vào thanh địa chỉ của trình duyệt, cụm 'tuoitre.vn' được gọi là gì?","o":["Tên miền của trang web","Mật khẩu của trang web","Tên của trình duyệt","Địa chỉ thư điện tử"],"a":"Tên miền của trang web","h":"Nó giống như 'địa chỉ nhà' của trang web.","e":"Tên miền là địa chỉ dễ nhớ của một trang web trên Internet, thay cho địa chỉ IP dạng số khó nhớ.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Hành vi nào sau đây bị cấm khi sử dụng mạng Internet?","o":["Chia sẻ ảnh chuyến du lịch của bản thân","Đưa thông tin sai sự thật, xuyên tạc gây ảnh hưởng xấu đến người khác","Học trực tuyến trên các trang học tập","Gửi thư điện tử cho bạn bè"],"a":"Đưa thông tin sai sự thật, xuyên tạc gây ảnh hưởng xấu đến người khác","h":"Hãy chọn hành vi gây hại cho người khác và xã hội.","e":"Pháp luật cấm lợi dụng mạng để đưa thông tin sai sự thật, xuyên tạc, xúc phạm danh dự của tổ chức và cá nhân.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây vi phạm bản quyền nội dung số?","o":["Đọc một bài viết trên báo điện tử","Chia sẻ đường liên kết tới bài viết cho bạn bè","Sao chép toàn bộ bài viết của người khác rồi đăng lại như của mình","Viết cảm nghĩ của mình về một cuốn sách"],"a":"Sao chép toàn bộ bài viết của người khác rồi đăng lại như của mình","h":"Vi phạm xảy ra khi 'nhận vơ' công sức của người khác.","e":"Tác phẩm của người khác được pháp luật bảo hộ; sao chép toàn bộ và nhận là của mình là vi phạm bản quyền.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Một bạn đăng lại một tin sai sự thật lên mạng xã hội khiến nhiều người hoang mang. Phát biểu nào sau đây là đúng?","o":["Chỉ người tạo ra tin giả mới phải chịu trách nhiệm","Người chia sẻ thông tin sai sự thật cũng có thể bị xử lí theo quy định của pháp luật","Chia sẻ lại tin của người khác thì hoàn toàn không sao","Mọi thông tin trên mạng đều đáng tin cậy"],"a":"Người chia sẻ thông tin sai sự thật cũng có thể bị xử lí theo quy định của pháp luật","h":"Trước khi chia sẻ bất cứ tin gì, mỗi người đều phải kiểm chứng.","e":"Pháp luật quy định cả người đưa tin và người lan truyền thông tin sai sự thật đều có thể bị xử phạt.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Hành vi nào sau đây xâm phạm quyền riêng tư của người khác?","o":["Đăng ảnh chụp của chính mình lên trang cá nhân","Tự ý đăng số điện thoại và ảnh cá nhân của bạn lên mạng khi chưa được đồng ý","Nhắn tin riêng hỏi thăm bạn","Xem các bài viết công khai trên mạng"],"a":"Tự ý đăng số điện thoại và ảnh cá nhân của bạn lên mạng khi chưa được đồng ý","h":"Thông tin cá nhân của ai thì người đó có quyền quyết định.","e":"Số điện thoại và hình ảnh cá nhân là thông tin riêng tư; tự ý công khai khi chưa được đồng ý là xâm phạm quyền riêng tư.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong Python, kiểu dữ liệu float dùng để biểu diễn loại số nào?","o":["Số nguyên như 1, 2, 3","Số thực có phần thập phân như 3.5","Chuỗi kí tự như 'Xin chào'","Giá trị đúng (True) hoặc sai (False)"],"a":"Số thực có phần thập phân như 3.5","h":"float nghĩa là số có phần thập phân.","e":"float là kiểu số thực, dùng cho các giá trị có phần thập phân như điểm trung bình 7.5.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong Python, dữ liệu mà lệnh input() nhận vào luôn thuộc kiểu dữ liệu nào?","o":["Số nguyên (int)","Số thực (float)","Chuỗi (str)","Danh sách (list)"],"a":"Chuỗi (str)","h":"Dù em gõ số, máy vẫn coi dữ liệu nhập vào là...","e":"input() luôn trả về một chuỗi; muốn tính toán số học cần chuyển đổi bằng int() hoặc float().","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong Python, biểu thức 'Lớp' + '10' cho kết quả nào?","o":["Lớp10","Lớp 10","10Lớp","Chương trình báo lỗi"],"a":"Lớp10","h":"Dấu + nối hai chuỗi liền nhau, không tự thêm dấu cách.","e":"Phép + nối chuỗi 'Lớp' và '10' liền nhau thành 'Lớp10'.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Từ khoá elif trong Python được dùng để làm gì?","o":["Kết thúc chương trình ngay lập tức","Kiểm tra thêm một điều kiện khác khi điều kiện trước đó không đúng","Lặp lại một khối lệnh nhiều lần","Khai báo một biến mới"],"a":"Kiểm tra thêm một điều kiện khác khi điều kiện trước đó không đúng","h":"elif là viết gọn của 'else if' (ngược lại nếu).","e":"elif cho phép xét thêm một trường hợp mới trong cấu trúc rẽ nhánh khi điều kiện của if không đúng.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Cho chuỗi s = 'Hello'. Kí tự s[0] là kí tự nào?","o":["H","e","o","Chuỗi không có chỉ số 0"],"a":"H","h":"Chỉ số kí tự trong chuỗi bắt đầu từ 0.","e":"Kí tự đầu tiên của chuỗi có chỉ số 0, với 'Hello' thì s[0] = 'H'.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong Python, 17 // 5 và 17 % 5 cho kết quả lần lượt là gì?","o":["3 và 2","2 và 3","3.4 và 0","4 và 1"],"a":"3 và 2","h":"17 chia cho 5 được mấy, dư mấy?","e":"17 = 5 × 3 + 2 nên phép chia lấy phần nguyên cho 3 và phép chia lấy phần dư cho 2.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Cho đoạn chương trình: n = 0; while n < 5: n = n + 2; print(n). Kết quả in ra là bao nhiêu?","o":["4","5","6","Lặp vô hạn không dừng"],"a":"6","h":"Lần lượt thay n = 0, 2, 4... và kiểm tra điều kiện n < 5.","e":"n tăng dần 0 → 2 → 4 → 6; khi n = 6, điều kiện n < 5 sai nên vòng lặp dừng và in ra 6.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Cho đoạn chương trình: s = 'Viet' + 'Nam'; print(len(s)). Kết quả in ra là bao nhiêu?","o":["6","7","8","Chương trình báo lỗi"],"a":"7","h":"Nối chuỗi trước, rồi đếm số kí tự của chuỗi thu được.","e":"s = 'VietNam' gồm 7 kí tự nên len(s) = 7.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Điểm ảnh (pixel) là gì?","o":["Một loại máy ảnh kĩ thuật số","Phần tử nhỏ nhất tạo nên một hình ảnh số","Một phần mềm chỉnh sửa ảnh","Đơn vị đo dung lượng của tệp ảnh"],"a":"Phần tử nhỏ nhất tạo nên một hình ảnh số","h":"Phóng to ảnh thật lớn, em sẽ thấy những ô vuông nhỏ.","e":"Mỗi bức ảnh số được ghép từ rất nhiều điểm ảnh; mỗi điểm ảnh mang một màu nhất định.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Hệ màu RGB được tạo thành từ ba màu cơ bản nào?","o":["Đỏ, vàng, xanh dương","Đỏ, xanh lá, xanh dương","Cam, tím, hồng","Đen, trắng, xám"],"a":"Đỏ, xanh lá, xanh dương","h":"RGB là viết tắt tiếng Anh của ba màu đó.","e":"RGB gồm Red (đỏ), Green (xanh lá) và Blue (xanh dương); phối trộn ba màu này tạo ra các màu hiển thị trên màn hình.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Độ phân giải của một bức ảnh cho biết điều gì?","o":["Dung lượng của tệp ảnh tính bằng MB","Số lượng điểm ảnh cấu tạo nên bức ảnh","Độ sáng tối của bức ảnh","Kích thước giấy khi in ảnh"],"a":"Số lượng điểm ảnh cấu tạo nên bức ảnh","h":"Độ phân giải thường được ghi ở dạng như 1920 × 1080.","e":"Độ phân giải cho biết số điểm ảnh theo chiều ngang và chiều dọc; càng nhiều điểm ảnh, ảnh càng chi tiết.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Một bức ảnh có độ phân giải 1920 × 1080 có nghĩa là gì?","o":["Ảnh có dung lượng 1920 MB","Ảnh gồm 1920 điểm ảnh theo chiều ngang và 1080 điểm ảnh theo chiều dọc","Ảnh được chụp vào năm 1920","Ảnh chỉ xem được trên màn hình 1080 inch"],"a":"Ảnh gồm 1920 điểm ảnh theo chiều ngang và 1080 điểm ảnh theo chiều dọc","h":"Hai con số ứng với hai chiều của bức ảnh.","e":"1920 × 1080 nghĩa là bề ngang của ảnh có 1920 điểm ảnh và bề dọc có 1080 điểm ảnh.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Muốn in một bức ảnh ở khổ lớn mà hình vẫn sắc nét, em nên chọn ảnh có đặc điểm nào?","o":["Độ phân giải cao, nhiều điểm ảnh","Dung lượng tệp càng nhỏ càng tốt","Ảnh có càng ít màu càng tốt","Ảnh chụp bằng điện thoại đời cũ"],"a":"Độ phân giải cao, nhiều điểm ảnh","h":"In càng lớn thì càng cần nhiều điểm ảnh.","e":"Ảnh độ phân giải cao chứa nhiều điểm ảnh nên khi in khổ lớn vẫn giữ được chi tiết, không bị mờ vỡ.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Khi phóng to quá mức một bức ảnh có độ phân giải thấp, hiện tượng nào thường xảy ra?","o":["Ảnh tự động trở nên sắc nét hơn","Ảnh bị vỡ hạt, thấy rõ các ô vuông điểm ảnh và mất chi tiết","Ảnh tự chuyển thành ảnh đen trắng","Màu sắc của ảnh trở nên tươi hơn"],"a":"Ảnh bị vỡ hạt, thấy rõ các ô vuông điểm ảnh và mất chi tiết","h":"Số điểm ảnh không đổi nhưng mỗi điểm ảnh bị kéo to ra.","e":"Ảnh ít điểm ảnh khi bị phóng to sẽ lộ từng ô điểm ảnh, hình ảnh bị vỡ hạt và mờ chi tiết.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Trong cơ sở dữ liệu quan hệ, khoá ngoại của một bảng dùng để làm gì?","o":["Liên kết bảng đó với một bảng khác thông qua khoá chính của bảng kia","Mã hoá toàn bộ dữ liệu trong bảng","Sắp xếp các bản ghi theo thứ tự bảng chữ cái","Tự động xoá các bản ghi bị trùng lặp"],"a":"Liên kết bảng đó với một bảng khác thông qua khoá chính của bảng kia","h":"Nhờ nó mà hai bảng biết được bản ghi nào thuộc về nhau.","e":"Khoá ngoại là trường trong một bảng chứa giá trị khoá chính của bảng khác, dùng để thiết lập mối liên kết giữa hai bảng.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong CSDL trường học, bảng HOCSINH có trường MaLop lưu mã của các lớp có trong bảng LOP. Trường MaLop trong bảng HOCSINH là:","o":["Khoá chính","Khoá ngoại","Trường ghi chú","Trường tính toán"],"a":"Khoá ngoại","h":"Nó trỏ sang khoá chính của một bảng khác.","e":"MaLop trong bảng HOCSINH chứa giá trị khoá chính của bảng LOP nên nó là khoá ngoại, giúp biết mỗi học sinh thuộc lớp nào.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Khi thiết kế CSDL trường học, vì sao người ta tách thông tin lớp học thành một bảng LOP riêng thay vì ghi đầy đủ tên lớp trong từng bản ghi học sinh?","o":["Để bảng học sinh trông ngắn hơn khi in ra","Để tránh trùng lặp dữ liệu; khi tên lớp thay đổi chỉ cần sửa ở một nơi duy nhất","Để học sinh không biết mình học lớp nào","Để bắt buộc phải dùng hai máy tính khác nhau"],"a":"Để tránh trùng lặp dữ liệu; khi tên lớp thay đổi chỉ cần sửa ở một nơi duy nhất","h":"Hãy nghĩ xem điều gì xảy ra khi một thông tin phải sửa ở hàng trăm chỗ.","e":"Tách bảng giúp mỗi thông tin chỉ lưu một lần, tránh trùng lặp và mâu thuẫn khi cập nhật.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong CSDL trường học, một lớp có nhiều học sinh, mỗi học sinh chỉ thuộc một lớp. Quan hệ giữa bảng LOP và bảng HOCSINH là quan hệ nào?","o":["Một – một","Một – nhiều","Nhiều – nhiều","Không có quan hệ"],"a":"Một – nhiều","h":"Một ở phía lớp, nhiều ở phía học sinh.","e":"Một bản ghi của bảng LOP liên kết với nhiều bản ghi của bảng HOCSINH nên đây là quan hệ một – nhiều.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Người quản trị xoá một lớp trong bảng LOP trong khi bảng HOCSINH vẫn còn nhiều học sinh mang mã lớp đó. Hệ quả đúng nhất là:","o":["Không có vấn đề gì vì hai bảng độc lập hoàn toàn","Dữ liệu trở nên không nhất quán vì các học sinh đó tham chiếu tới một lớp không còn tồn tại","Các học sinh đó tự động bị xoá theo","Bảng HOCSINH tự tạo lại lớp vừa xoá"],"a":"Dữ liệu trở nên không nhất quán vì các học sinh đó tham chiếu tới một lớp không còn tồn tại","h":"Khoá ngoại vẫn còn đó nhưng đầu mối liên kết đã mất.","e":"Đây là vi phạm toàn vẹn tham chiếu: khoá ngoại trỏ tới một bản ghi không còn tồn tại khiến dữ liệu mất nhất quán.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Trong bảng ĐIỂM, trường điểm trung bình môn nên dùng kiểu dữ liệu nào?","o":["Văn bản","Số","Ngày tháng","Hình ảnh"],"a":"Số","h":"Điểm cần được cộng và chia trung bình.","e":"Điểm là giá trị cần tính toán (cộng, tính trung bình, xếp loại) nên phải lưu bằng kiểu số.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Trường họ và tên học sinh trong bảng HOCSINH nên dùng kiểu dữ liệu nào?","o":["Số nguyên","Ngày tháng","Văn bản","Âm thanh"],"a":"Văn bản","h":"Họ tên được viết bằng các kí tự chữ.","e":"Họ và tên là dãy kí tự chữ nên dùng kiểu văn bản (text).","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Trường ngày sinh của học sinh nên dùng kiểu dữ liệu nào?","o":["Ngày tháng","Số thập phân","Văn bản dài","Hình ảnh"],"a":"Ngày tháng","h":"Kiểu này giúp tính được tuổi của học sinh.","e":"Kiểu ngày tháng giúp lưu đúng ngày sinh, tính được tuổi và sắp xếp theo thời gian.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Nếu lưu điểm số dưới dạng văn bản, khó khăn nào dễ gặp phải khi xử lí dữ liệu?","o":["Không thể in bảng điểm ra giấy","Không tính toán trực tiếp được và sắp xếp theo văn bản có thể cho thứ tự sai, ví dụ '10' đứng trước '9'","Điểm sẽ tự động bị nhân đôi","Máy tính không hiển thị được con số"],"a":"Không tính toán trực tiếp được và sắp xếp theo văn bản có thể cho thứ tự sai, ví dụ '10' đứng trước '9'","h":"Máy tính coi chúng là chuỗi kí tự chứ không phải con số.","e":"Dữ liệu kiểu văn bản không tham gia tính toán số học và được sắp xếp theo từng kí tự nên thứ tự có thể sai so với giá trị số.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong câu lệnh SQL, mệnh đề ORDER BY dùng để làm gì?","o":["Lọc ra các bản ghi thỏa điều kiện","Sắp xếp kết quả truy vấn theo một hoặc nhiều trường","Thêm bản ghi mới vào bảng","Đổi tên của bảng dữ liệu"],"a":"Sắp xếp kết quả truy vấn theo một hoặc nhiều trường","h":"Tên mệnh đề gợi ý tới việc thứ tự của kết quả.","e":"ORDER BY sắp xếp các dòng kết quả truy vấn, mặc định tăng dần hoặc giảm dần khi có DESC.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Câu truy vấn có đoạn ... ORDER BY Diem DESC sẽ cho kết quả thế nào?","o":["Học sinh có điểm thấp nhất xếp trước","Học sinh có điểm cao nhất xếp trước","Chỉ lấy học sinh có tên là DESC","Xoá các học sinh điểm thấp"],"a":"Học sinh có điểm cao nhất xếp trước","h":"DESC nghĩa là giảm dần.","e":"DESC sắp xếp giảm dần nên điểm cao nhất đứng đầu danh sách kết quả.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Điều kiện WHERE Diem >= 5 AND GioiTinh = 'Nữ' sẽ chọn những học sinh nào?","o":["Mọi học sinh có điểm từ 5 trở lên, không phân biệt giới tính","Mọi học sinh nữ, không phân biệt điểm","Học sinh nữ có điểm từ 5 trở lên (thỏa đồng thời cả hai điều kiện)","Học sinh thỏa ít nhất một trong hai điều kiện"],"a":"Học sinh nữ có điểm từ 5 trở lên (thỏa đồng thời cả hai điều kiện)","h":"Chú ý vai trò của từ AND giữa hai điều kiện.","e":"Toán tử AND yêu cầu cả hai điều kiện cùng đúng thì bản ghi mới được chọn.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Điều kiện WHERE Lop = '11A1' OR Lop = '11A2' sẽ chọn những học sinh nào?","o":["Chỉ học sinh học đồng thời cả hai lớp","Học sinh thuộc lớp 11A1 hoặc lớp 11A2","Học sinh không thuộc hai lớp trên","Toàn bộ học sinh trong trường"],"a":"Học sinh thuộc lớp 11A1 hoặc lớp 11A2","h":"Chú ý vai trò của từ OR giữa hai điều kiện.","e":"Toán tử OR chỉ cần một trong hai điều kiện đúng là bản ghi được chọn.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Cho truy vấn: SELECT HoTen FROM HOCSINH WHERE GioiTinh = 'Nữ' AND Diem >= 9 ORDER BY Diem DESC. Kết quả của truy vấn là:","o":["Họ tên mọi học sinh nữ, xếp theo bảng chữ cái","Họ tên các học sinh nữ có điểm từ 9 trở lên, điểm cao nhất xếp trước","Họ tên các học sinh nam có điểm từ 9 trở lên","Điểm trung bình của học sinh nữ toàn trường"],"a":"Họ tên các học sinh nữ có điểm từ 9 trở lên, điểm cao nhất xếp trước","h":"Đọc lần lượt từng phần: chọn trường nào, điều kiện lọc ra sao, sắp xếp thế nào.","e":"Mệnh đề WHERE lọc học sinh nữ có điểm từ 9 trở lên, ORDER BY Diem DESC sắp xếp điểm giảm dần.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Muốn in danh sách gồm họ tên học sinh kèm theo tên lớp của từng em, trong khi họ tên nằm ở bảng HOCSINH còn tên lớp nằm ở bảng LOP, truy vấn cần làm gì?","o":["Chỉ truy vấn bảng HOCSINH là đủ","Kết hợp dữ liệu của hai bảng dựa trên trường liên kết MaLop","Sao chép tên lớp sang mọi bảng khác","Xoá bảng LOP rồi gõ tay tên lớp vào danh sách"],"a":"Kết hợp dữ liệu của hai bảng dựa trên trường liên kết MaLop","h":"Hai bảng được nối với nhau nhờ trường chung nào?","e":"Truy vấn phải kết nối hai bảng theo khoá ngoại MaLop để lấy đồng thời thông tin từ cả hai bảng.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Để đưa thêm một học sinh mới vào bảng HOCSINH, ta cần thực hiện thao tác nào?","o":["Thêm một trường mới","Thêm một bản ghi mới","Thêm một bảng mới","Đổi khoá chính của bảng"],"a":"Thêm một bản ghi mới","h":"Mỗi học sinh chiếm một hàng trong bảng.","e":"Mỗi học sinh là một bản ghi (một hàng) trong bảng nên thêm học sinh tức là thêm bản ghi mới.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong phần mềm quản trị CSDL, biểu mẫu (form) thường được dùng để làm gì?","o":["Nhập và hiển thị dữ liệu theo từng bản ghi một cách thuận tiện","Nén dữ liệu để tiết kiệm bộ nhớ","Vẽ biểu đồ thống kê","Sao lưu dữ liệu ra ổ cứng ngoài"],"a":"Nhập và hiển thị dữ liệu theo từng bản ghi một cách thuận tiện","h":"Biểu mẫu giống như một tờ phiếu điền thông tin.","e":"Biểu mẫu trình bày mỗi bản ghi trong một khung nhập liệu rõ ràng, giúp nhập và xem dữ liệu dễ hơn làm việc trực tiếp với bảng.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Một học sinh chuyển từ lớp 11A1 sang 11A2, người quản trị cần sửa giá trị MaLop trong bản ghi của học sinh đó. Đây là thao tác nào?","o":["Thêm bản ghi","Xoá bản ghi","Cập nhật (sửa) bản ghi","Tạo bảng mới"],"a":"Cập nhật (sửa) bản ghi","h":"Bản ghi vẫn còn đó, chỉ một giá trị trong đó thay đổi.","e":"Thay đổi giá trị đã có trong một bản ghi được gọi là cập nhật dữ liệu.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Một học sinh đã chuyển trường và không còn học tại trường nữa. Để danh sách lớp được đúng, thao tác phù hợp với bản ghi của học sinh đó là:","o":["Giữ nguyên và thêm một bản ghi giống hệt","Xoá bản ghi của học sinh đó khỏi bảng (theo quy định lưu trữ của trường)","Đổi họ tên học sinh thành khoảng trắng","Thêm một trường mới dành riêng cho học sinh đó"],"a":"Xoá bản ghi của học sinh đó khỏi bảng (theo quy định lưu trữ của trường)","h":"CSDL phải phản ánh đúng tình hình thực tế hiện tại.","e":"Bản ghi không còn đúng với thực tế cần được xoá hoặc xử lí theo quy định để CSDL phản ánh đúng hiện trạng.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong Python, lệnh return trong một hàm dùng để làm gì?","o":["In giá trị ra màn hình","Trả một giá trị từ hàm về cho nơi gọi hàm","Khai báo một biến toàn cục","Dừng toàn bộ chương trình ngay lập tức"],"a":"Trả một giá trị từ hàm về cho nơi gọi hàm","h":"Nhờ nó mà ta có thể viết y = f(3) và dùng tiếp giá trị y.","e":"return kết thúc hàm và gửi giá trị kết quả về cho dòng lệnh đã gọi hàm.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho định nghĩa hàm: def tinh_tong(a, b): return a + b. Hai tên a và b được gọi là gì?","o":["Biến toàn cục","Tham số của hàm","Từ khoá của Python","Kết quả của hàm"],"a":"Tham số của hàm","h":"Chúng nhận giá trị truyền vào mỗi khi hàm được gọi.","e":"a và b là các tham số của hàm, nhận giá trị truyền vào khi hàm được gọi.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho s = 'abc'. Biểu thức s.upper() cho kết quả nào?","o":["'abc'","'ABC'","'Abc'","'aBc'"],"a":"'ABC'","h":"upper() tác động lên mọi kí tự chữ trong chuỗi.","e":"Phương thức upper() chuyển toàn bộ kí tự trong chuỗi thành chữ in hoa.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho s = 'Tin Hoc'. Biểu thức s.lower() cho kết quả nào?","o":["'TIN HOC'","'Tin Hoc'","'tin hoc'","'tIN hOC'"],"a":"'tin hoc'","h":"lower() là phương thức ngược lại với upper().","e":"Phương thức lower() chuyển toàn bộ kí tự trong chuỗi thành chữ thường.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Cho danh sách a = [10, 20, 30, 40]. Giá trị của a[1] là bao nhiêu?","o":["10","20","30","40"],"a":"20","h":"Chỉ số trong Python bắt đầu từ 0.","e":"Phần tử đầu tiên có chỉ số 0 nên a[1] là phần tử thứ hai, tức 20.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Cho đoạn chương trình: a = [1, 2, 3]; tong = 0; for x in a: tong = tong + x; print(tong). Kết quả in ra là:","o":["3","5","6","123"],"a":"6","h":"Vòng lặp cộng lần lượt từng phần tử của danh sách.","e":"Vòng for duyệt từng phần tử 1, 2, 3 và cộng dồn vào biến tong nên kết quả in ra là 6.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Một biến được tạo ra ở bên trong một hàm trong Python (biến cục bộ) có đặc điểm nào?","o":["Dùng được ở mọi nơi trong chương trình","Chỉ có tác dụng bên trong hàm đó; ra khỏi hàm thì không còn dùng được","Tự động được lưu xuống đĩa cứng","Luôn có giá trị bằng 0"],"a":"Chỉ có tác dụng bên trong hàm đó; ra khỏi hàm thì không còn dùng được","h":"Hãy nghĩ tới phạm vi hoạt động của biến.","e":"Biến cục bộ chỉ tồn tại trong phạm vi hàm nơi nó được tạo ra.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Trong hệ thống quản lí điểm của trường, học sinh chỉ được xem điểm của mình mà không thể sửa điểm. Điều này là nhờ cơ chế nào?","o":["Sao lưu dữ liệu","Phân quyền người dùng","Nén dữ liệu","Tự động sắp xếp"],"a":"Phân quyền người dùng","h":"Mỗi đối tượng sử dụng chỉ được làm những việc nhất định.","e":"Hệ thống cấp quyền khác nhau cho từng đối tượng: học sinh chỉ có quyền xem, giáo viên mới có quyền nhập và sửa điểm.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Người chuyên phụ trách cài đặt, quản lí, bảo trì và bảo mật cơ sở dữ liệu của một cơ quan được gọi là:","o":["Quản trị viên cơ sở dữ liệu","Nhân viên nhập liệu","Thiết kế đồ hoạ","Kế toán trưởng"],"a":"Quản trị viên cơ sở dữ liệu","h":"Tên gọi tắt tiếng Anh của nghề này là DBA.","e":"Quản trị viên CSDL (DBA) chịu trách nhiệm vận hành, phân quyền, sao lưu và bảo mật cơ sở dữ liệu.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Việc sao lưu cơ sở dữ liệu định kì mang lại lợi ích gì quan trọng nhất?","o":["Làm máy tính chạy nhanh hơn","Khôi phục lại được dữ liệu khi xảy ra sự cố như hỏng máy, xoá nhầm hay nhiễm mã độc","Giúp thêm được nhiều người dùng cùng lúc","Tự động sửa lỗi chính tả trong dữ liệu"],"a":"Khôi phục lại được dữ liệu khi xảy ra sự cố như hỏng máy, xoá nhầm hay nhiễm mã độc","h":"Bản sao lưu phát huy tác dụng khi bản chính gặp chuyện.","e":"Bản sao lưu là nguồn để khôi phục dữ liệu khi bản chính bị mất hoặc hư hỏng do sự cố.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Khi cấp quyền truy cập CSDL cho nhân viên, cách làm an toàn nhất là:","o":["Cấp toàn quyền cho mọi người để tiện làm việc","Chỉ cấp đúng những quyền cần thiết cho công việc của từng người","Cho mọi người dùng chung một tài khoản quản trị","Không đặt mật khẩu để đăng nhập nhanh hơn"],"a":"Chỉ cấp đúng những quyền cần thiết cho công việc của từng người","h":"Cách làm này được gọi là nguyên tắc quyền tối thiểu.","e":"Nguyên tắc quyền tối thiểu giúp hạn chế thiệt hại và rò rỉ dữ liệu khi một tài khoản bị lạm dụng hoặc bị đánh cắp.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Học sâu (deep learning) trong trí tuệ nhân tạo được hiểu là:","o":["Việc dạy máy tính bằng cách viết sẵn mọi quy tắc xử lí","Phương pháp học máy dùng mạng nơ-ron nhân tạo gồm nhiều lớp để tự rút ra đặc trưng từ dữ liệu lớn","Kĩ thuật sao lưu dữ liệu theo nhiều lớp","Chương trình dịch ngôn ngữ tự nhiên đầu tiên trên thế giới"],"a":"Phương pháp học máy dùng mạng nơ-ron nhân tạo gồm nhiều lớp để tự rút ra đặc trưng từ dữ liệu lớn","h":"Chữ 'sâu' gắn với số lớp của mạng nơ-ron.","e":"Học sâu là một nhánh của học máy, dùng mạng nơ-ron nhiều lớp và dữ liệu lớn để mô hình tự học các đặc trưng.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"AI tạo sinh (AI sinh nội dung) có khả năng nổi bật nào?","o":["Tạo ra nội dung mới như văn bản, hình ảnh, âm thanh dựa trên dữ liệu đã học","Tự sửa chữa phần cứng máy tính khi hỏng","Thay thế hoàn toàn hệ điều hành","Tăng dung lượng bộ nhớ của máy tính"],"a":"Tạo ra nội dung mới như văn bản, hình ảnh, âm thanh dựa trên dữ liệu đã học","h":"Các chatbot viết văn và công cụ vẽ tranh theo mô tả thuộc nhóm này.","e":"AI tạo sinh học từ dữ liệu có sẵn rồi sinh ra nội dung mới tương tự, như viết đoạn văn hay vẽ tranh theo yêu cầu.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Deepfake là gì?","o":["Một loại vi rút máy tính nguy hiểm","Hình ảnh, video hoặc giọng nói giả mạo do AI tạo ra, ghép mặt hoặc giọng của người này vào người khác","Phần mềm tăng độ nét cho ảnh cũ","Mạng xã hội dành riêng cho lập trình viên"],"a":"Hình ảnh, video hoặc giọng nói giả mạo do AI tạo ra, ghép mặt hoặc giọng của người này vào người khác","h":"Tên gọi này gắn với các video giả mặt người nổi tiếng.","e":"Deepfake dùng AI để tạo nội dung giả rất giống thật, thường nhằm lừa đảo hoặc bôi nhọ nên cần cảnh giác.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Vì sao AI tạo sinh có thể làm tin giả lan truyền nhanh hơn trước?","o":["Vì AI chỉ tạo tin giả vào ban đêm","Vì nó tạo được bài viết, ảnh, video giả rất giống thật trong thời gian ngắn, khiến người xem khó phân biệt","Vì mạng xã hội bắt buộc phải đăng tin do AI viết","Vì tin giả luôn nhận được nhiều lượt thích hơn tin thật"],"a":"Vì nó tạo được bài viết, ảnh, video giả rất giống thật trong thời gian ngắn, khiến người xem khó phân biệt","h":"Hãy nghĩ tới tốc độ và độ giống thật của nội dung do AI tạo ra.","e":"Chi phí tạo nội dung giả gần như bằng không và độ giống thật cao khiến tin giả được sản xuất hàng loạt và khó nhận ra.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Một hệ thống AI tuyển dụng được huấn luyện chủ yếu bằng hồ sơ của một nhóm ứng viên nhất định. Nguy cơ lớn nhất là gì?","o":["Hệ thống chạy chậm hơn bình thường","Kết quả đánh giá bị thiên lệch, thiếu công bằng với các nhóm ứng viên ít xuất hiện trong dữ liệu huấn luyện","Hồ sơ ứng viên bị in thừa ra hai bản","Hệ thống tự quên mật khẩu quản trị"],"a":"Kết quả đánh giá bị thiên lệch, thiếu công bằng với các nhóm ứng viên ít xuất hiện trong dữ liệu huấn luyện","h":"Dữ liệu đầu vào thế nào thì kết quả đầu ra có xu hướng thế ấy.","e":"Dữ liệu huấn luyện thiên lệch khiến mô hình học theo sự thiên lệch đó và cho kết quả không công bằng.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Bạn hỏi một chatbot AI về một cuốn sách, AI mô tả rất chi tiết dù cuốn sách đó không hề tồn tại. Hiện tượng này cho thấy điều gì?","o":["AI không bao giờ mắc lỗi","AI tạo sinh có thể bịa ra thông tin nghe rất thuyết phục, nên cần kiểm chứng bằng nguồn đáng tin cậy","Cuốn sách chắc chắn tồn tại nhưng rất ít người biết","Chatbot đang cố tình đùa với người dùng"],"a":"AI tạo sinh có thể bịa ra thông tin nghe rất thuyết phục, nên cần kiểm chứng bằng nguồn đáng tin cậy","h":"AI tạo câu trả lời nghe hợp lí chứ không tra cứu sự thật.","e":"AI tạo sinh dự đoán nội dung hợp lí theo mẫu ngôn ngữ chứ không tự kiểm chứng sự thật, nên có thể đưa ra thông tin sai mà vẫn rất tự tin.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Một mô hình AI được huấn luyện bằng dữ liệu thu thập tràn lan trên Internet mà không qua kiểm chứng. Nguy cơ đúng nhất là:","o":["Mô hình sẽ luôn khách quan và chính xác tuyệt đối","Mô hình học cả thông tin sai và định kiến trong dữ liệu, rồi tái tạo lại chúng trong các câu trả lời","Mô hình tự động xoá hết dữ liệu xấu","Mô hình chỉ trả lời được bằng tiếng Anh"],"a":"Mô hình học cả thông tin sai và định kiến trong dữ liệu, rồi tái tạo lại chúng trong các câu trả lời","h":"Chất lượng đầu ra phụ thuộc trực tiếp vào chất lượng đầu vào.","e":"Dữ liệu huấn luyện chưa kiểm chứng khiến AI học và lặp lại cả những thông tin sai và định kiến có trong dữ liệu.","t":"tin-lop12","g":12,"l":"kho"},{"p":"Tường lửa (firewall) trong hệ thống mạng có vai trò chính là gì?","o":["Tăng tốc độ đường truyền Internet","Kiểm soát dữ liệu ra vào mạng và ngăn chặn các kết nối trái phép","Lưu trữ bản sao của mọi tệp tin","Diệt mọi loại vi rút trên máy tính"],"a":"Kiểm soát dữ liệu ra vào mạng và ngăn chặn các kết nối trái phép","h":"Hãy hình dung tường lửa như một chốt kiểm soát ở cổng ra vào.","e":"Tường lửa chỉ cho phép các kết nối hợp lệ đi qua và chặn các truy cập trái phép vào hệ thống mạng.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Cập nhật hệ điều hành và phần mềm thường xuyên giúp bảo vệ máy tính chủ yếu vì:","o":["Bản cập nhật làm giao diện đẹp hơn","Bản cập nhật vá các lỗ hổng bảo mật đã được phát hiện","Bản cập nhật xoá bớt tệp rác trong máy","Bản cập nhật giúp tăng thời lượng pin"],"a":"Bản cập nhật vá các lỗ hổng bảo mật đã được phát hiện","h":"Tin tặc thường nhắm vào những điểm yếu đã bị công bố.","e":"Tin tặc thường khai thác các lỗ hổng đã biết; cập nhật kịp thời là cách vá những lỗ hổng đó.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Mã độc tống tiền (ransomware) gây hại bằng cách nào?","o":["Làm màn hình nhấp nháy liên tục","Mã hoá dữ liệu của nạn nhân và đòi tiền chuộc để mở khoá","Tự động gửi thư rác quảng cáo","Chiếm quyền điều khiển chuột máy tính"],"a":"Mã hoá dữ liệu của nạn nhân và đòi tiền chuộc để mở khoá","h":"Tên gọi của nó gắn với hai chữ: mã độc và tiền chuộc.","e":"Ransomware mã hoá tệp tin khiến nạn nhân không dùng được dữ liệu và đòi tiền chuộc để cung cấp khoá giải mã.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Máy tính của một cơ quan bị ransomware mã hoá toàn bộ dữ liệu, nhưng cơ quan có bản sao lưu độc lập được cập nhật thường xuyên. Lợi ích lớn nhất của bản sao lưu lúc này là:","o":["Giúp bắt được kẻ tấn công ngay lập tức","Khôi phục lại dữ liệu để tiếp tục công việc mà không phải trả tiền chuộc","Tự động giải mã mọi tệp đã bị mã hoá","Ngăn ransomware lây ngược về thời điểm trước khi bị tấn công"],"a":"Khôi phục lại dữ liệu để tiếp tục công việc mà không phải trả tiền chuộc","h":"Bản sao lưu sạch và tách biệt là lối thoát khi dữ liệu chính đã bị khoá.","e":"Bản sao lưu sạch, tách biệt cho phép khôi phục dữ liệu sau sự cố mà không phụ thuộc vào kẻ tấn công.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Vì sao chuyên gia khuyến cáo không nên trì hoãn các bản cập nhật bảo mật của hệ điều hành?","o":["Vì bản cập nhật chỉ có hiệu lực trong vòng 24 giờ","Vì lỗ hổng chưa được vá là cửa ngõ mà tin tặc đang tích cực khai thác","Vì máy tính sẽ tự tắt nếu không cập nhật","Vì nhà sản xuất sẽ thu thêm phí nếu cập nhật muộn"],"a":"Vì lỗ hổng chưa được vá là cửa ngõ mà tin tặc đang tích cực khai thác","h":"Khoảng thời gian giữa lúc lỗ hổng bị công bố và lúc được vá là lúc nguy hiểm nhất.","e":"Khi lỗ hổng đã bị công bố mà chưa được vá, máy tính ở trạng thái dễ bị tấn công nhất.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Một người sao lưu dữ liệu bằng cách chép sang một thư mục khác trên cùng ổ cứng của chính máy tính đó. Khi máy bị ransomware tấn công, điều gì dễ xảy ra?","o":["Bản sao lưu hoàn toàn an toàn vì nằm ở thư mục khác","Bản sao lưu cũng bị mã hoá theo vì nằm trên cùng hệ thống bị tấn công","Ransomware tự bỏ qua các thư mục có tên là sao lưu","Dữ liệu gốc tự khôi phục từ bản sao lưu"],"a":"Bản sao lưu cũng bị mã hoá theo vì nằm trên cùng hệ thống bị tấn công","h":"Sao lưu an toàn phải tách biệt khỏi hệ thống chính.","e":"Sao lưu trên cùng một máy không tách biệt nên mã độc vẫn tiếp cận và mã hoá được; cần sao lưu ra thiết bị ngoài hoặc đám mây tách biệt.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Dữ liệu lớn (Big Data) được hiểu là:","o":["Một tệp văn bản có dung lượng trên 1 GB","Các tập dữ liệu có khối lượng rất lớn, đa dạng và tăng nhanh, cần công nghệ riêng để lưu trữ và xử lí","Toàn bộ dữ liệu trong một máy tính cá nhân","Dữ liệu được in ra trên giấy khổ lớn"],"a":"Các tập dữ liệu có khối lượng rất lớn, đa dạng và tăng nhanh, cần công nghệ riêng để lưu trữ và xử lí","h":"Hãy nhớ ba đặc trưng: lớn, nhanh và đa dạng.","e":"Dữ liệu lớn có ba đặc trưng thường được nhắc tới: khối lượng rất lớn, tốc độ tạo ra nhanh và dạng dữ liệu đa dạng.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Cơ sở dữ liệu trên nền điện toán đám mây có đặc điểm nổi bật nào?","o":["Chỉ truy cập được từ một máy tính duy nhất","Dữ liệu lưu trên hệ thống máy chủ qua Internet nên có thể truy cập từ nhiều nơi, nhiều thiết bị","Không cần kết nối mạng vẫn dùng được ở mọi nơi","Dữ liệu tự động xoá sau 30 ngày"],"a":"Dữ liệu lưu trên hệ thống máy chủ qua Internet nên có thể truy cập từ nhiều nơi, nhiều thiết bị","h":"Người dùng không phải tự vận hành máy chủ riêng.","e":"CSDL đám mây đặt dữ liệu trên máy chủ trực tuyến, người dùng truy cập qua Internet từ nhiều thiết bị khác nhau.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Khai thác dữ liệu (data mining) từ kho dữ liệu lớn của một siêu thị nhằm mục đích chính là gì?","o":["Xoá bớt dữ liệu bán hàng cũ cho nhẹ máy","Tìm ra các quy luật hữu ích, ví dụ nhóm hàng thường được mua cùng nhau, để phục vụ kinh doanh","In hoá đơn cho khách nhanh hơn","Đổi tên các mặt hàng trong kho"],"a":"Tìm ra các quy luật hữu ích, ví dụ nhóm hàng thường được mua cùng nhau, để phục vụ kinh doanh","h":"Giống như đãi cát tìm vàng trong kho dữ liệu.","e":"Khai thác dữ liệu là quá trình phân tích khối dữ liệu lớn để rút ra tri thức và quy luật phục vụ việc ra quyết định.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Hệ thống đặt vé tàu trực tuyến dùng cơ sở dữ liệu chủ yếu để:","o":["Quản lí thông tin chuyến tàu, số ghế còn trống và vé đã bán, tránh bán trùng một ghế cho nhiều người","Trang trí giao diện trang web cho đẹp mắt","Phát nhạc cho hành khách nghe","Đo tốc độ chạy của đoàn tàu"],"a":"Quản lí thông tin chuyến tàu, số ghế còn trống và vé đã bán, tránh bán trùng một ghế cho nhiều người","h":"Hệ thống phải biết chính xác ghế nào còn, ghế nào đã bán.","e":"CSDL giúp hệ thống theo dõi chính xác tình trạng ghế và vé tại mọi thời điểm, tránh bán trùng.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Vì sao các hệ thống lớn như đặt vé, ngân hàng dùng một cơ sở dữ liệu tập trung thay vì để mỗi chi nhánh lưu dữ liệu riêng?","o":["Để mỗi chi nhánh có một số liệu khác nhau cho phong phú","Để mọi nơi cùng thấy dữ liệu mới nhất và nhất quán, tránh mâu thuẫn thông tin","Để phải mua thêm nhiều máy chủ hơn","Để nhân viên tra cứu khó khăn hơn"],"a":"Để mọi nơi cùng thấy dữ liệu mới nhất và nhất quán, tránh mâu thuẫn thông tin","h":"Một thay đổi chỉ cần cập nhật ở một nơi duy nhất.","e":"Dữ liệu tập trung đảm bảo tính nhất quán: thông tin được cập nhật một nơi và mọi điểm truy cập đều thấy giống nhau.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trang web bán vé xem phim có hàng nghìn người cùng đặt vé trong một phút. Yêu cầu quan trọng nhất đối với cơ sở dữ liệu của hệ thống là:","o":["Giao diện quản trị phải có nhiều màu sắc","Xử lí được nhiều giao dịch đồng thời mà vẫn đảm bảo đúng dữ liệu, không bán trùng một ghế cho hai người","Chỉ cần lưu được dữ liệu, tốc độ không quan trọng","Tự động giảm giá vé khi đông người truy cập"],"a":"Xử lí được nhiều giao dịch đồng thời mà vẫn đảm bảo đúng dữ liệu, không bán trùng một ghế cho hai người","h":"Hãy nghĩ tới điều gì xảy ra nếu hai người cùng mua chiếc ghế cuối cùng.","e":"Hệ thống phải đảm bảo tính toàn vẹn dữ liệu khi nhiều giao dịch diễn ra đồng thời, tránh xung đột như bán trùng ghế.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Học sinh yêu thích lập trình và muốn làm nghề phát triển phần mềm sau khi tốt nghiệp THPT. Hướng đi phù hợp là:","o":["Học đại học hoặc cao đẳng các ngành công nghệ thông tin, kĩ thuật phần mềm, hoặc các khoá đào tạo nghề lập trình","Chỉ cần nghỉ học ở nhà chơi trò chơi điện tử","Học bất kì ngành nào cũng ra làm lập trình viên được ngay","Chờ đến 30 tuổi mới bắt đầu học lập trình"],"a":"Học đại học hoặc cao đẳng các ngành công nghệ thông tin, kĩ thuật phần mềm, hoặc các khoá đào tạo nghề lập trình","h":"Ngành tin học có nhiều đường vào: đại học, cao đẳng và đào tạo nghề.","e":"Sau THPT, học sinh có thể theo đại học, cao đẳng nghề hoặc các khoá đào tạo lập trình để vào nghề phát triển phần mềm.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Tiếng Anh quan trọng với người làm nghề tin học chủ yếu vì:","o":["Mọi máy tính đều chỉ có bàn phím tiếng Anh","Phần lớn tài liệu kĩ thuật, ngôn ngữ lập trình và cộng đồng công nghệ sử dụng tiếng Anh","Không biết tiếng Anh thì không bật được máy tính","Các công ty tin học chỉ tuyển người nước ngoài"],"a":"Phần lớn tài liệu kĩ thuật, ngôn ngữ lập trình và cộng đồng công nghệ sử dụng tiếng Anh","h":"Hãy nghĩ tới ngôn ngữ của tài liệu hướng dẫn và thông báo lỗi.","e":"Đọc tài liệu, thông báo lỗi, hướng dẫn và trao đổi với cộng đồng lập trình quốc tế đều cần tiếng Anh.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Kĩ năng tự học có vai trò đặc biệt quan trọng trong nghề tin học vì:","o":["Trường học không dạy gì về tin học cả","Công nghệ thay đổi rất nhanh, người làm nghề phải liên tục cập nhật kiến thức và công cụ mới","Người làm tin học không bao giờ được đi đào tạo lại","Tự học tốt thì không cần làm việc nhóm nữa"],"a":"Công nghệ thay đổi rất nhanh, người làm nghề phải liên tục cập nhật kiến thức và công cụ mới","h":"Công cụ hôm nay hiện đại, vài năm sau có thể đã lỗi thời.","e":"Công cụ và công nghệ mới xuất hiện liên tục nên khả năng tự học quyết định việc theo kịp nghề.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Một kĩ thuật viên vô tình thao tác sai làm hệ thống của khách hàng ngừng hoạt động. Phẩm chất trung thực được thể hiện đúng nhất ở việc:","o":["Che giấu sự cố và hi vọng không ai phát hiện","Đổ lỗi cho phần mềm của hãng khác","Nhận lỗi, báo cáo đúng sự việc cho quản lí và khách hàng, đồng thời tìm cách khắc phục","Xoá nhật kí hệ thống để không còn bằng chứng"],"a":"Nhận lỗi, báo cáo đúng sự việc cho quản lí và khách hàng, đồng thời tìm cách khắc phục","h":"Trung thực bắt đầu từ việc dám nhận phần việc mình làm sai.","e":"Trung thực trong nghề là dám nhận trách nhiệm và thông tin minh bạch để sự cố được xử lí nhanh và đúng.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Người quản trị hệ thống có thể truy cập dữ liệu cá nhân của nhiều người dùng. Hành vi nào sau đây vi phạm đạo đức nghề nghiệp?","o":["Sao lưu dữ liệu định kì theo kế hoạch","Tự ý mở xem và kể lại thông tin riêng tư của người dùng khi không phục vụ công việc","Đặt mật khẩu mạnh cho tài khoản quản trị","Ghi nhật kí các thao tác bảo trì hệ thống"],"a":"Tự ý mở xem và kể lại thông tin riêng tư của người dùng khi không phục vụ công việc","h":"Quyền truy cập cao đi kèm trách nhiệm bảo mật cao.","e":"Dùng quyền quản trị để xâm phạm thông tin riêng tư của người khác là vi phạm đạo đức nghề nghiệp.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Một người bạn nhờ bạn — đang làm quản trị CSDL của trường — sửa tăng điểm cho bạn ấy trong hệ thống. Hành động đúng là:","o":["Giúp bạn vì chỉ thay đổi một con số nhỏ","Từ chối vì đó là gian lận, vi phạm đạo đức nghề nghiệp và quy định pháp luật","Sửa điểm nhưng ghi chú là do máy bị lỗi","Nhờ một người khác sửa thay để mình tránh bị phát hiện"],"a":"Từ chối vì đó là gian lận, vi phạm đạo đức nghề nghiệp và quy định pháp luật","h":"Tính toàn vẹn của dữ liệu là điều người làm nghề phải giữ.","e":"Sửa dữ liệu trái phép là hành vi gian lận; người làm nghề tin học phải từ chối và giữ tính toàn vẹn của dữ liệu.","t":"tin-lop12","g":12,"l":"kho"},{"p":"Khi tham gia tranh luận trên mạng xã hội, cách ứng xử văn minh là:","o":["Dùng lời lẽ gay gắt để thắng bằng được","Trình bày ý kiến rõ ràng, tôn trọng người khác, không công kích cá nhân","Đăng thông tin đời tư của đối phương lên mạng","Tạo nhiều tài khoản ảo để ủng hộ ý kiến của mình"],"a":"Trình bày ý kiến rõ ràng, tôn trọng người khác, không công kích cá nhân","h":"Tranh luận là trao đổi về ý kiến, không phải xúc phạm con người.","e":"Tranh luận văn minh là trao đổi về nội dung, giữ thái độ tôn trọng và không công kích cá nhân.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Về mặt pháp lí, người chia sẻ thông tin sai sự thật lên mạng xã hội gây ảnh hưởng xấu có thể phải đối mặt với điều gì?","o":["Không có hậu quả gì vì mạng xã hội là thế giới ảo","Có thể bị xử phạt hành chính hoặc chịu trách nhiệm theo quy định của pháp luật","Chỉ bị trừ điểm thi đua ở trường","Được nhiều người theo dõi hơn"],"a":"Có thể bị xử phạt hành chính hoặc chịu trách nhiệm theo quy định của pháp luật","h":"Hành vi trên mạng vẫn chịu sự điều chỉnh của pháp luật thật.","e":"Pháp luật Việt Nam có quy định xử lí hành vi đăng tải, chia sẻ thông tin sai sự thật trên mạng, mức xử lí tuỳ theo hậu quả gây ra.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Thấy một bài viết trên mạng đang xúc phạm, bêu riếu bạn của mình, việc làm đúng nhất là:","o":["Chia sẻ lại để nhiều người cùng biết","Nhảy vào bình luận xúc phạm lại người đăng bài","Không hùa theo, báo cáo bài viết với nhà quản trị nền tảng và động viên bạn mình","Chụp màn hình gửi đi nhiều nhóm khác nhau"],"a":"Không hùa theo, báo cáo bài viết với nhà quản trị nền tảng và động viên bạn mình","h":"Đừng tiếp tay lan truyền nội dung xấu, hãy dùng công cụ báo cáo.","e":"Không lan truyền nội dung xúc phạm, báo cáo với nền tảng và hỗ trợ người bị hại là cách ứng xử đúng.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Bạn đã chia sẻ một thông tin lên mạng và sau đó phát hiện đó là tin giả. Việc làm có trách nhiệm nhất là:","o":["Để nguyên vì đằng nào cũng đã có nhiều người xem rồi","Xoá bài và đăng đính chính công khai để những người đã xem không tiếp tục hiểu sai","Chia sẻ thêm một tin khác để lấn át tin cũ","Đổi tên tài khoản để tránh bị nhận ra"],"a":"Xoá bài và đăng đính chính công khai để những người đã xem không tiếp tục hiểu sai","h":"Sửa sai công khai giúp ngăn thông tin giả lan thêm.","e":"Đính chính công khai giúp ngăn thông tin sai tiếp tục lan truyền và thể hiện trách nhiệm của người chia sẻ.","t":"tin-lop12","g":12,"l":"kho"},{"p":"Trong phần mềm Scratch, khu vực nơi nhân vật biểu diễn và di chuyển được gọi là gì?","o":["Sân khấu","Thư mục","Bàn phím","Khối lệnh"],"a":"Sân khấu","h":"Hãy nhớ lại màn hình chính của Scratch, nơi con mèo đứng và đi lại.","e":"Khu vực nhân vật biểu diễn trong Scratch được gọi là Sân khấu.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong Scratch, hình con mèo mặc định và các hình khác được điều khiển để hoạt động được gọi chung là gì?","o":["Âm thanh","Nhân vật","Phông nền","Khối lệnh màu tím"],"a":"Nhân vật","h":"Đây là đối tượng mà em kéo thả khối lệnh để ra lệnh cho nó.","e":"Các đối tượng được lập trình để hoạt động trong Scratch gọi là nhân vật (mặc định là con mèo).","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Khi em bấm vào lá cờ xanh trong Scratch thì điều gì xảy ra?","o":["Máy tính tắt","Nhân vật bị xoá","Chương trình bắt đầu chạy","Đổi ngôn ngữ của phần mềm"],"a":"Chương trình bắt đầu chạy","h":"Lá cờ xanh nằm ngay phía trên sân khấu.","e":"Bấm vào lá cờ xanh là lệnh bắt đầu chạy chương trình trong Scratch.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Muốn nhân vật trong Scratch bước đi về phía trước, em dùng khối lệnh nào?","o":["Khối nói 'Xin chào'","Khối chờ 1 giây","Khối đổi màu nhân vật","Khối di chuyển 10 bước"],"a":"Khối di chuyển 10 bước","h":"Hãy nghĩ đến nhóm khối lệnh Chuyển động.","e":"Khối 'di chuyển 10 bước' thuộc nhóm Chuyển động, giúp nhân vật tiến về phía trước.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Muốn nhân vật trong Scratch thay đổi hình dáng bên ngoài, ví dụ mặc thêm áo hoặc đổi kiểu dáng, em cần thay đổi phần nào?","o":["Trang phục của nhân vật","Âm thanh","Tên của tệp","Tốc độ con trỏ chuột"],"a":"Trang phục của nhân vật","h":"Trong Scratch có một thẻ riêng để chỉnh sửa vẻ ngoài của nhân vật.","e":"Hình dáng bên ngoài của nhân vật được thay đổi ở phần Trang phục.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Tệp trong máy tính là gì?","o":["Một chiếc hộp đựng giấy tờ","Một tập hợp thông tin được lưu trong máy tính và có tên gọi","Một loại chuột máy tính","Một phím trên bàn phím"],"a":"Một tập hợp thông tin được lưu trong máy tính và có tên gọi","h":"Bức tranh em vẽ và lưu lại trong máy là một ví dụ của điều này.","e":"Tệp là tập hợp thông tin (văn bản, hình ảnh, âm thanh...) được lưu trong máy tính và có tên gọi riêng.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Trong Scratch, khối lệnh 'lặp lại 10' có tác dụng gì?","o":["Lặp lại các khối lệnh bên trong đúng 10 lần","Dừng chương trình ngay lập tức","Thay đổi nhân vật khác","Xoá toàn bộ sân khấu"],"a":"Lặp lại các khối lệnh bên trong đúng 10 lần","h":"Số 10 trong tên khối lệnh chính là số lần thực hiện.","e":"Khối 'lặp lại 10' là khối vòng lặp, giúp các lệnh bên trong được thực hiện lặp lại 10 lần.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong Scratch, khối lệnh 'nếu ... thì ...' được dùng khi nào?","o":["Để nhân vật luôn luôn thực hiện lệnh","Để chỉ thực hiện các lệnh bên trong khi điều kiện đúng","Để xoá một biến số","Để tăng âm lượng của nhân vật"],"a":"Để chỉ thực hiện các lệnh bên trong khi điều kiện đúng","h":"Đây là khối điều kiện: có đúng thì mới làm, sai thì bỏ qua.","e":"Khối 'nếu ... thì ...' là khối điều kiện, các lệnh bên trong chỉ chạy khi điều kiện được thoả mãn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Trong một trò chơi Scratch, muốn ghi nhớ điểm số của người chơi đang thay đổi trong lúc chơi, em dùng thành phần nào?","o":["Trang phục","Phông nền","Biến số","Âm thanh"],"a":"Biến số","h":"Thành phần này có thể chứa một giá trị và giá trị đó thay đổi được.","e":"Biến số dùng để lưu trữ giá trị thay đổi trong khi chương trình chạy, ví dụ như điểm số của người chơi.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Muốn nhân vật Scratch nhảy lên nhảy xuống nhiều lần liên tục mà không phải kéo thả nhiều khối lệnh giống nhau, em nên dùng nhóm khối nào?","o":["Nhóm khối Sự kiện","Nhóm khối Âm thanh","Nhóm khối Bút vẽ","Nhóm khối Điều khiển có vòng lặp"],"a":"Nhóm khối Điều khiển có vòng lặp","h":"Vòng lặp giúp một hành động được thực hiện nhiều lần.","e":"Các khối vòng lặp trong nhóm Điều khiển giúp lặp lại hành động nhiều lần mà không cần viết lại lệnh.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Lưu trữ trên đám mây là hình thức lưu trữ như thế nào?","o":["Lưu dữ liệu vào thẻ nhớ cắm trong máy","Lưu dữ liệu trên các máy chủ thông qua Internet để truy cập được từ nhiều thiết bị","Lưu dữ liệu ra giấy rồi cất vào tủ","Lưu dữ liệu tạm thời rồi tự xoá sau 1 ngày"],"a":"Lưu dữ liệu trên các máy chủ thông qua Internet để truy cập được từ nhiều thiết bị","h":"Hãy nghĩ đến các dịch vụ như Google Drive mà em có thể mở tệp ở cả máy tính và điện thoại.","e":"Lưu trữ đám mây là lưu dữ liệu trên máy chủ qua Internet, giúp truy cập tệp từ nhiều thiết bị khác nhau.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Phần mềm bảng tính như Microsoft Excel được dùng chủ yếu để làm gì?","o":["Để vẽ tranh và tô màu","Để nghe nhạc và xem phim","Để làm việc với dữ liệu dạng bảng gồm hàng và cột, có thể tính toán","Để soạn thảo thư điện tử"],"a":"Để làm việc với dữ liệu dạng bảng gồm hàng và cột, có thể tính toán","h":"Tên gọi 'bảng tính' đã gợi ý về bảng và tính toán.","e":"Phần mềm bảng tính dùng để tổ chức dữ liệu theo hàng và cột và thực hiện các phép tính trên dữ liệu đó.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong bảng tính, mỗi vùng nhỏ nằm ở giao của một hàng và một cột được gọi là gì?","o":["Trang tính","Tệp tính","Thanh công thức","Ô tính"],"a":"Ô tính","h":"Đây là nơi em nhấp chuột vào để nhập một số liệu.","e":"Giao của một hàng và một cột trong bảng tính tạo thành một ô tính, là nơi chứa dữ liệu.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong Excel, ô tính nằm ở cột B và hàng 3 có địa chỉ là gì?","o":["B3","3B","B-3","Cột B hàng 3 không có địa chỉ"],"a":"B3","h":"Địa chỉ ô gồm chữ cái của cột viết trước, số của hàng viết sau.","e":"Địa chỉ ô tính được viết bằng chữ cái cột kết hợp số hàng, ô ở cột B hàng 3 có địa chỉ B3.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Sau khi nhập xong số liệu vào bảng tính, việc làm cần thiết để lần sau mở lại được bảng tính là gì?","o":["Đóng bảng tính mà không lưu","In bảng tính ra giấy rồi xoá tệp","Lưu bảng tính thành một tệp","Đổi tên của máy tính"],"a":"Lưu bảng tính thành một tệp","h":"Thao tác này thường dùng tổ hợp phím Ctrl + S.","e":"Cần lưu bảng tính thành tệp thì lần sau mới mở lại và sử dụng tiếp được.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Từ khoá tìm kiếm trên Internet là gì?","o":["Mật khẩu của máy tìm kiếm","Tên của trang web đầu tiên hiện ra","Địa chỉ nhà của người tìm kiếm","Các từ quan trọng được gõ vào ô tìm kiếm để tìm đúng thông tin cần thiết"],"a":"Các từ quan trọng được gõ vào ô tìm kiếm để tìm đúng thông tin cần thiết","h":"Khi em gõ 'thời tiết Hà Nội hôm nay', các từ em gõ chính là thứ đang được hỏi.","e":"Từ khoá là các từ quan trọng người dùng nhập vào máy tìm kiếm để tìm thông tin mong muốn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Khi tìm thông tin để làm bài tập, nguồn thông tin nào sau đây đáng tin cậy hơn cả?","o":["Trang web chính thức của cơ quan nhà nước hoặc của trường học","Một bình luận không rõ người viết trên mạng xã hội","Trang web lạ không ghi nguồn và tác giả","Tin nhắn chuyển tiếp trong nhóm chat"],"a":"Trang web chính thức của cơ quan nhà nước hoặc của trường học","h":"Hãy chọn nguồn có cơ quan, tổ chức chịu trách nhiệm về nội dung.","e":"Trang web chính thức của cơ quan nhà nước, trường học có tổ chức chịu trách nhiệm nên thông tin đáng tin cậy hơn.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Em đọc được một tin giật gân trên mạng xã hội nhưng chưa rõ đúng sai. Việc làm đúng nhất là gì?","o":["Chia sẻ ngay cho bạn bè cùng biết","Kiểm chứng thông tin ở nhiều nguồn đáng tin cậy trước khi tin và chia sẻ","Tin ngay vì tin có nhiều lượt thích","Coi như tin thật vì có kèm hình ảnh"],"a":"Kiểm chứng thông tin ở nhiều nguồn đáng tin cậy trước khi tin và chia sẻ","h":"Đừng vội tin hay chia sẻ khi chưa chắc chắn.","e":"Cần kiểm chứng thông tin từ nhiều nguồn đáng tin cậy trước khi tin và chia sẻ để tránh lan truyền tin sai.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Khi tìm kiếm thông tin trên mạng, kết quả hiện ra đầu tiên thì sao?","o":["Chưa chắc đã đúng và đáng tin nhất, cần kiểm tra thêm","Luôn luôn là thông tin đúng nhất","Chỉ là quảng cáo, không bao giờ nên xem","Máy tính đã kiểm chứng đúng hết rồi"],"a":"Chưa chắc đã đúng và đáng tin nhất, cần kiểm tra thêm","h":"Thứ tự hiện ra không đồng nghĩa với độ tin cậy.","e":"Kết quả đầu tiên chưa chắc đáng tin nhất; cần đối chiếu với các nguồn uy tín khác.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Vì sao khi tìm kiếm thông tin, em không nên chỉ dựa vào kết quả đầu tiên hiện ra?","o":["Vì kết quả đầu tiên luôn luôn sai","Vì máy tìm kiếm không cho mở kết quả đầu tiên","Vì kết quả đầu tiên chỉ mở được trên điện thoại","Vì kết quả đầu tiên có thể là quảng cáo hoặc chưa chính xác, cần đối chiếu thêm các nguồn khác"],"a":"Vì kết quả đầu tiên có thể là quảng cáo hoặc chưa chính xác, cần đối chiếu thêm các nguồn khác","h":"Thứ tự xuất hiện không đồng nghĩa với độ chính xác.","e":"Kết quả tìm kiếm đầu tiên có thể là quảng cáo hoặc thông tin chưa được kiểm chứng, vì vậy cần xem và đối chiếu nhiều nguồn.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Trong Scratch, khối 'lặp lại liên tục' khác khối 'lặp lại 10' ở điểm nào?","o":["Khối 'lặp lại liên tục' chạy chậm hơn","Khối 'lặp lại liên tục' lặp không giới hạn số lần cho đến khi chương trình dừng, còn 'lặp lại 10' chỉ lặp đúng 10 lần","Khối 'lặp lại liên tục' chỉ dùng cho âm thanh","Hai khối hoàn toàn giống nhau"],"a":"Khối 'lặp lại liên tục' lặp không giới hạn số lần cho đến khi chương trình dừng, còn 'lặp lại 10' chỉ lặp đúng 10 lần","h":"Hãy chú ý đến số lần lặp của mỗi khối.","e":"Khối 'lặp lại liên tục' lặp vô hạn cho đến khi dừng chương trình, trong khi 'lặp lại 10' lặp với số lần xác định.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Một thuật toán tốt cần bảo đảm điều gì?","o":["Các bước rõ ràng, có thứ tự, hữu hạn và thực hiện được","Càng nhiều bước càng tốt","Chỉ có máy tính mới hiểu được","Không cần sắp xếp thứ tự các bước"],"a":"Các bước rõ ràng, có thứ tự, hữu hạn và thực hiện được","h":"Thuật toán là dãy bước giải quyết một việc cụ thể.","e":"Thuật toán gồm các bước rõ ràng theo thứ tự, số bước hữu hạn và mỗi bước đều thực hiện được.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi mô tả thuật toán bằng sơ đồ khối, hình ô-van (hình bầu dục) thường thể hiện điều gì?","o":["Một phép tính cần thực hiện","Điểm bắt đầu hoặc kết thúc của thuật toán","Một điều kiện cần kiểm tra","Dữ liệu cần in ra giấy"],"a":"Điểm bắt đầu hoặc kết thúc của thuật toán","h":"Mỗi sơ đồ khối đều có điểm mở đầu và điểm kết thúc.","e":"Trong sơ đồ khối, hình ô-van quy ước dùng để thể hiện điểm bắt đầu hoặc kết thúc của thuật toán.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Chương trình máy tính là gì?","o":["Danh sách các phần mềm bán trong cửa hàng","Bản hướng dẫn sử dụng máy tính bằng giấy","Dãy các lệnh được viết bằng ngôn ngữ lập trình để máy tính thực hiện theo một thuật toán","Tên gọi khác của màn hình máy tính"],"a":"Dãy các lệnh được viết bằng ngôn ngữ lập trình để máy tính thực hiện theo một thuật toán","h":"Thuật toán khi được viết ra bằng ngôn ngữ lập trình sẽ trở thành điều này.","e":"Chương trình là dãy lệnh viết bằng ngôn ngữ lập trình, thể hiện thuật toán để máy tính thực hiện.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Xét bài toán: nhập hai số a và b, tính và in ra tổng của chúng. Đầu vào và đầu ra của bài toán là gì?","o":["Đầu vào là tổng, đầu ra là a và b","Đầu vào là bàn phím, đầu ra là màn hình","Đầu vào là máy tính, đầu ra là chương trình","Đầu vào là hai số a và b, đầu ra là tổng của a và b"],"a":"Đầu vào là hai số a và b, đầu ra là tổng của a và b","h":"Đầu vào là dữ kiện được cho ban đầu, đầu ra là kết quả cần tìm.","e":"Bài toán nhận đầu vào là hai số a và b, xử lí cộng hai số và cho đầu ra là tổng của chúng.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Máy tính điện tử ENIAC ra đời năm 1946, sử dụng bóng đèn điện tử chân không, thuộc thế hệ máy tính thứ mấy?","o":["Thế hệ thứ nhất","Thế hệ thứ hai","Thế hệ thứ ba","Thế hệ thứ tư"],"a":"Thế hệ thứ nhất","h":"Linh kiện bóng đèn điện tử chân không là đặc trưng của thế hệ đầu tiên.","e":"ENIAC dùng bóng đèn điện tử chân không nên thuộc thế hệ máy tính thứ nhất.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Máy tính thế hệ thứ hai sử dụng linh kiện điện tử chính nào thay cho bóng đèn chân không?","o":["Vi mạch tích hợp IC","Bóng bán dẫn (transistor)","Bộ vi xử lí","Đĩa quang"],"a":"Bóng bán dẫn (transistor)","h":"Linh kiện này nhỏ gọn và ít tốn điện hơn bóng đèn chân không rất nhiều.","e":"Máy tính thế hệ thứ hai dùng bóng bán dẫn (transistor) làm linh kiện chính, giúp máy nhỏ hơn và nhanh hơn thế hệ thứ nhất.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Số 9 trong hệ thập phân được biểu diễn trong hệ nhị phân là gì?","o":["1000","1010","1001","1111"],"a":"1001","h":"Hãy phân tích 9 thành tổng của các luỹ thừa của 2: 8 + 1.","e":"9 = 8 + 1 = 1×2³ + 0×2² + 0×2¹ + 1×2⁰ nên biểu diễn nhị phân của 9 là 1001.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Vì sao máy tính sử dụng hệ nhị phân để lưu trữ và xử lí thông tin?","o":["Vì hệ nhị phân có nhiều chữ số hơn hệ thập phân","Vì con người quen đếm bằng hai ngón tay","Vì máy tính chỉ hiểu được hai chữ số 0 và 1","Vì các linh kiện điện tử có hai trạng thái dễ phân biệt là bật/tắt (có điện/không có điện), ứng với 1 và 0"],"a":"Vì các linh kiện điện tử có hai trạng thái dễ phân biệt là bật/tắt (có điện/không có điện), ứng với 1 và 0","h":"Hãy nghĩ đến trạng thái của một công tắc điện.","e":"Linh kiện điện tử chỉ có hai trạng thái ổn định dễ biểu diễn là bật và tắt, tương ứng hai chữ số 0 và 1 của hệ nhị phân.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Trong Python, câu lệnh print(\"Xin chào\") thực hiện việc gì?","o":["Nhận dữ liệu từ bàn phím","In dòng chữ Xin chào ra màn hình","Tạo một biến tên Xin chào","Dừng chương trình ngay lập tức"],"a":"In dòng chữ Xin chào ra màn hình","h":"Từ 'print' trong tiếng Anh liên quan đến việc hiển thị ra.","e":"Hàm print trong Python dùng để đưa dữ liệu ra màn hình, ở đây là dòng chữ Xin chào.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong Python, câu lệnh x = 5 có nghĩa là gì?","o":["So sánh x với số 5","In số 5 ra màn hình","Gán giá trị 5 cho biến x","Xoá biến x khỏi chương trình"],"a":"Gán giá trị 5 cho biến x","h":"Dấu = trong lập trình thường là phép gán, không phải phép so sánh.","e":"Câu lệnh x = 5 là phép gán, lưu giá trị 5 vào biến x để sử dụng trong chương trình.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong Python, hàm input() được dùng để làm gì?","o":["In kết quả ra màn hình","Thực hiện phép tính cộng","Tạo một số ngẫu nhiên","Nhận dữ liệu do người dùng nhập vào từ bàn phím"],"a":"Nhận dữ liệu do người dùng nhập vào từ bàn phím","h":"Từ 'input' có nghĩa là đưa vào.","e":"Hàm input() giúp chương trình nhận dữ liệu người dùng gõ từ bàn phím, dữ liệu nhận được ở dạng chuỗi.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho đoạn chương trình Python: tuoi = 15; nếu tuoi >= 18 thì in 'Đủ tuổi', ngược lại (else) in 'Chưa đủ tuổi'. Chương trình sẽ in ra dòng nào?","o":["Chưa đủ tuổi","Đủ tuổi","In cả hai dòng","Không in dòng nào"],"a":"Chưa đủ tuổi","h":"Hãy so sánh giá trị 15 với điều kiện >= 18.","e":"Vì tuoi = 15 nhỏ hơn 18 nên điều kiện sai, chương trình thực hiện nhánh else và in 'Chưa đủ tuổi'.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong Python, giá trị \"2026\" viết trong dấu ngoặc kép khác giá trị 2026 không có ngoặc kép ở điểm nào?","o":["Hai giá trị hoàn toàn giống nhau","\"2026\" là một chuỗi kí tự, còn 2026 là một số nguyên","\"2026\" là một số thập phân","2026 là một chuỗi kí tự, còn \"2026\" là số nguyên"],"a":"\"2026\" là một chuỗi kí tự, còn 2026 là một số nguyên","h":"Dấu ngoặc kép trong Python dùng để bao quanh một loại dữ liệu đặc biệt.","e":"Trong Python, dữ liệu đặt trong dấu ngoặc kép là chuỗi (str), còn 2026 không có ngoặc kép là số nguyên (int).","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Xác thực hai lớp (2FA) giúp tăng an toàn tài khoản vì lí do nào?","o":["Làm cho mật khẩu dài hơn tự động","Ngoài mật khẩu, kẻ xấu còn cần thêm mã xác thực từ thiết bị của người dùng","Giúp đăng nhập nhanh hơn","Tự động đổi mật khẩu mỗi ngày"],"a":"Ngoài mật khẩu, kẻ xấu còn cần thêm mã xác thực từ thiết bị của người dùng","h":"Hãy nghĩ xem sau khi nhập mật khẩu, hệ thống còn yêu cầu thêm gì.","e":"Xác thực hai lớp yêu cầu thêm một yếu tố nữa (mã OTP hoặc ứng dụng xác thực) nên dù lộ mật khẩu, kẻ xấu vẫn khó vào được tài khoản.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Trong Excel, để sắp xếp danh sách học sinh theo cột Điểm từ cao xuống thấp, ta chọn vùng dữ liệu rồi dùng lệnh nào?","o":["Data → Filter","Home → Find & Select","Data → Sort, chọn cột Điểm và thứ tự Z to A (lớn đến nhỏ)","Insert → Chart"],"a":"Data → Sort, chọn cột Điểm và thứ tự Z to A (lớn đến nhỏ)","h":"Sắp xếp dữ liệu nằm trong nhóm lệnh của thẻ Data.","e":"Lệnh Sort trong thẻ Data cho phép sắp xếp theo một hoặc nhiều cột; với số, thứ tự giảm dần là từ lớn đến nhỏ.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Tính năng lọc dữ liệu (Filter) trong Excel dùng để làm gì?","o":["Xoá vĩnh viễn các hàng không cần thiết","Đổi màu nền của bảng dữ liệu","Gộp nhiều ô thành một ô","Chỉ hiển thị các hàng thoả mãn điều kiện, các hàng còn lại tạm ẩn đi"],"a":"Chỉ hiển thị các hàng thoả mãn điều kiện, các hàng còn lại tạm ẩn đi","h":"Lọc không xoá dữ liệu, chỉ thay đổi cách hiển thị.","e":"Filter giúp xem nhanh nhóm dữ liệu theo điều kiện (ví dụ chỉ xem học sinh nữ); bỏ lọc thì toàn bộ dữ liệu lại hiện ra.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Ô A1 chứa điểm 8. Công thức =IF(A1>=8,\"Giỏi\",\"Khá\") cho kết quả nào?","o":["Giỏi","Khá","8","Báo lỗi"],"a":"Giỏi","h":"Hãy xét điều kiện A1>=8 có đúng không.","e":"Điểm 8 thoả mãn điều kiện >=8 nên hàm IF trả về giá trị khi điều kiện đúng là \"Giỏi\".","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Để đếm số học sinh có điểm từ 8 trở lên trong vùng B2:B31, công thức đúng là:","o":["=SUMIF(B2:B31,\">=8\")","=COUNTIF(B2:B31,\">=8\")","=COUNT(B2:B31)","=AVERAGEIF(B2:B31,\">=8\")"],"a":"=COUNTIF(B2:B31,\">=8\")","h":"Đếm theo điều kiện thì dùng hàm có cả COUNT và IF.","e":"COUNTIF đếm số ô trong vùng thoả mãn điều kiện cho trước; ở đây điều kiện là \">=8\".","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Khi muốn so sánh trực quan số lượng học sinh của 4 lớp bằng biểu đồ trong Excel, sau khi chọn bảng dữ liệu ta thực hiện:","o":["Vào thẻ Data → chọn Sort","Vào thẻ Home → chọn Conditional Formatting","Vào thẻ Insert → chọn kiểu biểu đồ cột (Column)","Vào thẻ Formulas → chọn Insert Function"],"a":"Vào thẻ Insert → chọn kiểu biểu đồ cột (Column)","h":"Biểu đồ được chèn từ thẻ Insert.","e":"Thẻ Insert chứa nhóm Charts để chèn các kiểu biểu đồ; biểu đồ cột thích hợp để so sánh số lượng giữa các nhóm.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trong cơ sở dữ liệu quan hệ, một bảng (table) được tổ chức gồm:","o":["Các tệp và thư mục","Các trang và các đoạn","Các ô tính và công thức","Các hàng và các cột"],"a":"Các hàng và các cột","h":"Hãy hình dung một bảng dữ liệu quen thuộc như danh sách lớp.","e":"Bảng trong CSDL quan hệ gồm các cột (thuộc tính) và các hàng (bản ghi) giao nhau tạo thành dữ liệu có cấu trúc.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong một bảng của CSDL quan hệ, 'trường' (field) và 'bản ghi' (record) tương ứng với:","o":["Cột và hàng","Hàng và cột","Tệp và thư mục","Khoá và quan hệ"],"a":"Cột và hàng","h":"Mỗi cột mô tả một thuộc tính chung cho mọi dòng dữ liệu.","e":"Trường là một cột, mô tả một thuộc tính (ví dụ Họ tên); bản ghi là một hàng, chứa dữ liệu của một đối tượng cụ thể.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Khoá chính (primary key) của một bảng là gì?","o":["Cột chứa mật khẩu của bảng","Một trường (hoặc tập hợp trường) mà giá trị của nó xác định duy nhất mỗi bản ghi trong bảng","Cột đầu tiên của bảng","Trường dùng để sắp xếp bảng theo thứ tự bảng chữ cái"],"a":"Một trường (hoặc tập hợp trường) mà giá trị của nó xác định duy nhất mỗi bản ghi trong bảng","h":"Nhờ khoá chính ta phân biệt được hai bản ghi khác nhau.","e":"Khoá chính đảm bảo mỗi bản ghi là duy nhất: giá trị khoá không được trùng lặp và không được để trống (NULL).","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Bảng HOCSINH có trường MaLop, bảng LOP có khoá chính MaLop. Trường MaLop trong bảng HOCSINH đóng vai trò gì để tạo quan hệ giữa hai bảng?","o":["Khoá chính","Chỉ mục","Khoá ngoại","Trường tính toán"],"a":"Khoá ngoại","h":"Nó tham chiếu tới khoá chính của bảng khác.","e":"Khoá ngoại là trường trong một bảng chứa giá trị của khoá chính ở bảng khác, nhờ đó hai bảng liên kết được với nhau.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Vì sao khi thiết kế CSDL, thông tin lớp học (tên lớp, giáo viên chủ nhiệm) được tách thành bảng LOP riêng thay vì ghi lặp lại trong mọi bản ghi học sinh?","o":["Để bảng học sinh trông ngắn hơn khi in","Vì Excel không cho ghi chữ trùng nhau","Để mỗi bảng chỉ có đúng 10 hàng","Tránh dư thừa dữ liệu và tránh mâu thuẫn khi cần sửa thông tin lớp"],"a":"Tránh dư thừa dữ liệu và tránh mâu thuẫn khi cần sửa thông tin lớp","h":"Nghĩ tới việc đổi tên giáo viên chủ nhiệm cho 40 học sinh cùng lớp.","e":"Tách bảng giúp mỗi thông tin chỉ lưu một nơi: khi sửa tên giáo viên chỉ sửa một bản ghi, tránh lặp lại và sai lệch dữ liệu.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Điểm khác nhau cơ bản giữa ảnh bitmap và ảnh vector là gì?","o":["Ảnh bitmap lưu bằng các điểm ảnh (pixel), ảnh vector lưu bằng các đối tượng hình học và công thức toán học","Ảnh bitmap luôn có dung lượng nhỏ hơn ảnh vector","Ảnh vector không thể phóng to","Ảnh bitmap chỉ có hai màu đen trắng"],"a":"Ảnh bitmap lưu bằng các điểm ảnh (pixel), ảnh vector lưu bằng các đối tượng hình học và công thức toán học","h":"Khác biệt nằm ở cách máy tính lưu trữ hình ảnh.","e":"Ảnh bitmap ghép từ lưới pixel nên phóng to dễ bị vỡ hạt; ảnh vector mô tả bằng đường nét toán học nên phóng to vẫn nét.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong phần mềm chỉnh sửa ảnh, 'lớp' (layer) có tác dụng gì?","o":["Làm tăng dung lượng tệp ảnh lên gấp đôi","Cho phép chỉnh sửa từng phần của ảnh độc lập mà không ảnh hưởng tới phần khác","Tự động nén ảnh khi lưu","Chia ảnh thành các ô vuông bằng nhau"],"a":"Cho phép chỉnh sửa từng phần của ảnh độc lập mà không ảnh hưởng tới phần khác","h":"Hãy tưởng tượng các tấm kính trong suốt chồng lên nhau.","e":"Mỗi layer như một tấm phim trong suốt chứa một phần của bức ảnh; ta có thể sửa, ẩn hoặc di chuyển từng lớp riêng biệt.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Thao tác nào sau đây thuộc về chỉnh sửa video cơ bản?","o":["Viết mã nguồn cho trang web","Thiết kế cơ sở dữ liệu cho ứng dụng","Cắt ghép các đoạn clip, chèn chữ, thêm nhạc nền và xuất video","Cài đặt hệ điều hành cho máy quay"],"a":"Cắt ghép các đoạn clip, chèn chữ, thêm nhạc nền và xuất video","h":"Chỉnh sửa video làm việc với các đoạn hình ảnh và âm thanh theo dòng thời gian.","e":"Biên tập video cơ bản gồm cắt, ghép clip trên timeline, thêm tiêu đề/phụ đề, âm thanh và xuất ra tệp video hoàn chỉnh.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Âm thanh số được tạo ra bằng cách lấy mẫu (sampling) tín hiệu âm thanh liên tục. Tần số lấy mẫu càng cao thì:","o":["Âm thanh càng bị méo","Thời lượng âm thanh càng dài","Âm thanh chỉ còn một kênh mono","Chất lượng âm thanh càng tốt và dung lượng tệp càng lớn"],"a":"Chất lượng âm thanh càng tốt và dung lượng tệp càng lớn","h":"Lấy mẫu dày hơn thì ghi lại sóng âm chính xác hơn nhưng tốn nhiều dữ liệu hơn.","e":"Tần số lấy mẫu cao (ví dụ 44 100 Hz của CD) ghi lại sóng âm chi tiết hơn nên âm thanh trung thực hơn, đổi lại tệp lớn hơn.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Ghép nối định dạng tệp với đúng loại nội dung: MP3, MP4, PNG lần lượt là:","o":["Âm thanh, video, hình ảnh","Hình ảnh, âm thanh, video","Video, hình ảnh, âm thanh","Âm thanh, hình ảnh, video"],"a":"Âm thanh, video, hình ảnh","h":"MP3 gắn liền với nhạc, MP4 gắn liền với phim.","e":"MP3 là định dạng âm thanh nén, MP4 là định dạng video phổ biến, PNG là định dạng hình ảnh hỗ trợ nền trong suốt.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Công việc chính của lập trình viên (developer) là gì?","o":["Kiểm tra và sửa chữa đường truyền mạng","Phân tích yêu cầu, viết mã nguồn, kiểm tra và bảo trì phần mềm","Thiết kế giao diện đồ hoạ cho quảng cáo","Lắp ráp và sửa chữa phần cứng máy tính"],"a":"Phân tích yêu cầu, viết mã nguồn, kiểm tra và bảo trì phần mềm","h":"Tên gọi của nghề gắn với việc 'lập trình'.","e":"Lập trình viên biến yêu cầu bài toán thành chương trình bằng ngôn ngữ lập trình, đồng thời sửa lỗi và nâng cấp phần mềm theo thời gian.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Người quản trị cơ sở dữ liệu (DBA) chịu trách nhiệm chính về việc nào sau đây?","o":["Viết nội dung quảng cáo cho website","Thiết kế logo cho hệ thống","Đảm bảo CSDL hoạt động ổn định, an toàn, sao lưu và phân quyền truy cập dữ liệu","Bán và phân phối phần mềm"],"a":"Đảm bảo CSDL hoạt động ổn định, an toàn, sao lưu và phân quyền truy cập dữ liệu","h":"Hãy nghĩ tới người 'giữ kho' dữ liệu của cả tổ chức.","e":"DBA quản lí toàn bộ vòng đời dữ liệu: tổ chức lưu trữ, bảo mật, phân quyền, sao lưu và khôi phục khi có sự cố.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Kiểm thử viên phần mềm (tester) thực hiện công việc nào?","o":["Quản lí lương cho nhân viên công ty","Cài đặt mạng LAN cho văn phòng","Viết tài liệu hướng dẫn sử dụng máy in","Thiết kế các trường hợp kiểm thử, chạy thử phần mềm để tìm lỗi và báo cáo cho đội phát triển"],"a":"Thiết kế các trường hợp kiểm thử, chạy thử phần mềm để tìm lỗi và báo cáo cho đội phát triển","h":"Công việc này diễn ra trước khi phần mềm đến tay người dùng.","e":"Tester xây dựng kịch bản kiểm thử (test case), thực thi và ghi nhận lỗi để đội phát triển sửa, giúp phần mềm đạt chất lượng trước khi phát hành.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Điều kiện bắt buộc để áp dụng tìm kiếm nhị phân trên một danh sách là gì?","o":["Danh sách phải đã được sắp xếp","Danh sách phải có ít hơn 10 phần tử","Danh sách chỉ chứa các số nguyên dương","Danh sách phải lưu trong tệp văn bản"],"a":"Danh sách phải đã được sắp xếp","h":"Thuật toán so sánh với phần tử giữa rồi loại bỏ một nửa danh sách.","e":"Tìm kiếm nhị phân chỉ đúng trên dãy đã sắp xếp, vì sau mỗi lần so sánh với phần tử giữa ta loại được một nửa dãy khỏi vùng tìm.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Với danh sách đã sắp xếp gồm 1 000 phần tử, tìm kiếm nhị phân cần tối đa khoảng bao nhiêu lần so sánh để tìm một phần tử?","o":["Khoảng 1 000 lần","Khoảng 10 lần","Khoảng 500 lần","Khoảng 100 lần"],"a":"Khoảng 10 lần","h":"Mỗi lần so sánh, vùng tìm kiếm giảm đi một nửa: 2 mũ mấy thì vượt 1 000?","e":"Mỗi bước vùng tìm giảm một nửa; 2^10 = 1 024 nên tối đa khoảng 10 lần so sánh, nhanh hơn hẳn tìm tuần tự (tối đa 1 000 lần).","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Thuật toán sắp xếp nổi bọt (bubble sort) hoạt động theo nguyên lí nào?","o":["Chia danh sách thành hai nửa rồi trộn lại","Chọn phần tử ở giữa làm chốt rồi phân hoạch","Lặp lại việc so sánh và đổi chỗ các cặp phần tử kề nhau sai thứ tự, phần tử lớn nhất 'nổi' dần về cuối","Đếm số lần xuất hiện của từng giá trị"],"a":"Lặp lại việc so sánh và đổi chỗ các cặp phần tử kề nhau sai thứ tự, phần tử lớn nhất 'nổi' dần về cuối","h":"Tên gọi của thuật toán gợi ý cách các phần tử di chuyển.","e":"Sắp xếp nổi bọt duyệt dãy nhiều lượt, đổi chỗ các cặp kề nhau nếu sai thứ tự, sau mỗi lượt phần tử lớn nhất về đúng vị trí cuối.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong Python, cho danh sách a = [3, 1, 4]. Sau khi thực hiện a.append(1) và a.sort(), danh sách a là:","o":["[3, 1, 4, 1]","[4, 3, 1, 1]","[1, 3, 4]","[1, 1, 3, 4]"],"a":"[1, 1, 3, 4]","h":"append thêm phần tử vào cuối, sort sắp xếp tăng dần tại chỗ.","e":"append(1) làm a thành [3, 1, 4, 1]; sort() sắp xếp tăng dần thành [1, 1, 3, 4].","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Cho xâu s = \"Tin hoc\". Kết quả của s.upper() và len(s) lần lượt là:","o":["\"TIN HOC\" và 7","\"tin hoc\" và 7","\"TIN HOC\" và 6","\"Tin Hoc\" và 8"],"a":"\"TIN HOC\" và 7","h":"upper() chuyển mọi chữ cái thành chữ hoa; len đếm cả dấu cách.","e":"s.upper() cho \"TIN HOC\"; xâu \"Tin hoc\" có 7 kí tự kể cả dấu cách ở giữa.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Cho hàm: def f(n): return n * 2. Kết quả của biểu thức f(3) + f(\"A\") là gì?","o":["\"6AA\"","Báo lỗi TypeError vì không thể cộng số nguyên 6 với xâu \"AA\"","\"AA6\"","12"],"a":"Báo lỗi TypeError vì không thể cộng số nguyên 6 với xâu \"AA\"","h":"Hãy tính riêng f(3) và f(\"A\") rồi mới xét phép cộng.","e":"f(3) = 6; f(\"A\") = \"A\" * 2 = \"AA\" (nhân xâu với số nguyên là lặp lại xâu); phép cộng 6 + \"AA\" giữa số và xâu không thực hiện được nên Python báo lỗi TypeError.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Một thuật toán có độ phức tạp thời gian O(n²) và một thuật toán O(n) cùng giải một bài toán. Khi kích thước dữ liệu n tăng lên rất lớn, nhận định nào đúng?","o":["Thuật toán O(n²) luôn nhanh hơn","Hai thuật toán luôn tốn thời gian bằng nhau","Thuật toán O(n) tăng thời gian chậm hơn nên hiệu quả hơn với dữ liệu lớn","Độ phức tạp không ảnh hưởng tới thời gian chạy"],"a":"Thuật toán O(n) tăng thời gian chậm hơn nên hiệu quả hơn với dữ liệu lớn","h":"Hãy so sánh tốc độ tăng của n và n² khi n lớn dần.","e":"Độ phức tạp mô tả tốc độ tăng thời gian theo kích thước đầu vào; O(n) tăng tuyến tính nên với n lớn sẽ nhanh hơn hẳn O(n²).","t":"tin-lop11","g":11,"l":"kho"},{"p":"Hàm đệ quy tính giai thừa được định nghĩa: f(0) = 1 và f(n) = n * f(n-1) với n > 0. Giá trị f(4) bằng bao nhiêu?","o":["10","16","12","24"],"a":"24","h":"Hãy tính lần lượt f(1), f(2), f(3) rồi f(4).","e":"f(1) = 1, f(2) = 2, f(3) = 6, f(4) = 4 × 6 = 24; điều kiện dừng f(0) = 1 giúp đệ quy kết thúc.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Câu lệnh SQL nào lấy họ tên và điểm của tất cả học sinh trong bảng HOCSINH có điểm từ 8 trở lên?","o":["SELECT HoTen, Diem FROM HOCSINH WHERE Diem >= 8","GET HoTen, Diem FROM HOCSINH IF Diem >= 8","SELECT HoTen, Diem IN HOCSINH WHEN Diem >= 8","SHOW HoTen, Diem FROM HOCSINH WHERE Diem >= 8"],"a":"SELECT HoTen, Diem FROM HOCSINH WHERE Diem >= 8","h":"Cú pháp truy vấn gồm SELECT … FROM … WHERE …","e":"SELECT liệt kê các cột cần lấy, FROM chỉ bảng nguồn, WHERE đặt điều kiện lọc bản ghi (Diem >= 8).","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Để hiển thị danh sách học sinh theo điểm giảm dần, câu lệnh SQL cần thêm mệnh đề nào?","o":["GROUP BY Diem","ORDER BY Diem DESC","SORT BY Diem DOWN","ARRANGE Diem DESC"],"a":"ORDER BY Diem DESC","h":"Mệnh đề sắp xếp trong SQL bắt đầu bằng ORDER BY.","e":"ORDER BY Diem DESC sắp xếp kết quả theo cột Diem giảm dần; ASC (mặc định) là tăng dần.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Câu lệnh nào thêm một học sinh mới vào bảng HOCSINH(MaHS, HoTen)?","o":["ADD INTO HOCSINH VALUES ('HS10', 'Lan')","PUT HOCSINH VALUES ('HS10', 'Lan')","INSERT INTO HOCSINH VALUES ('HS10', 'Lan')","NEW RECORD HOCSINH ('HS10', 'Lan')"],"a":"INSERT INTO HOCSINH VALUES ('HS10', 'Lan')","h":"Lệnh chèn bản ghi mới bắt đầu bằng INSERT INTO.","e":"INSERT INTO <bảng> VALUES (...) thêm một bản ghi mới; còn UPDATE dùng để sửa dữ liệu đã có, SELECT chỉ để truy vấn.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Nhận định nào đúng về các câu lệnh SQL?","o":["SELECT dùng để sửa dữ liệu trong bảng","DELETE dùng để tạo bảng mới","INSERT dùng để sắp xếp kết quả truy vấn","UPDATE dùng để thay đổi giá trị của các bản ghi đã có, còn SELECT chỉ đọc dữ liệu mà không làm thay đổi bảng"],"a":"UPDATE dùng để thay đổi giá trị của các bản ghi đã có, còn SELECT chỉ đọc dữ liệu mà không làm thay đổi bảng","h":"Phân biệt nhóm lệnh truy vấn (đọc) với nhóm lệnh thay đổi dữ liệu.","e":"SELECT là lệnh truy vấn, không thay đổi dữ liệu; INSERT thêm, UPDATE sửa và DELETE xoá bản ghi trong bảng.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Khi máy tính được kết nối với Internet, em có thể làm được việc nào sau đây?","o":["Xem bài giảng, đọc truyện và tìm thông tin ở khắp nơi trên thế giới","Máy tính tự chạy nhanh gấp đôi","Máy tính không cần dùng điện vẫn chạy được","Máy tính tự nói chuyện được với em"],"a":"Xem bài giảng, đọc truyện và tìm thông tin ở khắp nơi trên thế giới","h":"Internet nối các máy tính ở khắp nơi lại với nhau.","e":"Internet là mạng máy tính toàn cầu, giúp em học tập, đọc truyện và tìm thông tin từ khắp nơi trên thế giới.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Vì sao người ta gọi Internet là mạng máy tính toàn cầu?","o":["Vì Internet kết nối rất nhiều máy tính ở khắp nơi trên thế giới lại với nhau","Vì Internet chỉ có ở duy nhất một trường học","Vì máy tính nào cũng in hình quả địa cầu","Vì Internet là tên của một trò chơi"],"a":"Vì Internet kết nối rất nhiều máy tính ở khắp nơi trên thế giới lại với nhau","h":"Hãy nghĩ xem Internet có ở những nơi nào trên thế giới.","e":"Internet kết nối hàng tỉ máy tính và thiết bị ở khắp các nước trên thế giới nên được gọi là mạng máy tính toàn cầu.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Ở nhà em, điện thoại, máy tính bảng và tivi thông minh cùng kết nối vào mạng Wi-Fi của gia đình. Các thiết bị này được nối với nhau tạo thành gì?","o":["Một phần mềm vẽ tranh","Một mạng máy tính","Một thư mục lớn","Một chiếc máy in"],"a":"Một mạng máy tính","h":"Các thiết bị nối với nhau để chia sẻ thông tin với nhau.","e":"Khi các thiết bị được kết nối với nhau để liên lạc và chia sẻ thông tin, chúng tạo thành một mạng máy tính, dù là mạng nhỏ trong gia đình.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Khi đang xem video trên mạng, em thấy một video có nội dung xấu và đáng sợ. Em nên làm gì?","o":["Gửi video đó cho các bạn cùng xem","Bấm vào tất cả quảng cáo hiện trên màn hình","Tắt video đó đi và nói với bố mẹ hoặc thầy cô","Tiếp tục xem cho đến hết video"],"a":"Tắt video đó đi và nói với bố mẹ hoặc thầy cô","h":"Gặp điều không hay trên mạng, em hãy nhờ người lớn giúp.","e":"Khi gặp nội dung xấu trên mạng, em cần tắt ngay và báo cho bố mẹ hoặc thầy cô để được giúp đỡ.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em muốn xem phim hoạt hình trên mạng. Cách làm nào sau đây là an toàn nhất?","o":["Xem trên trang quen thuộc dành cho thiếu nhi và nhờ người lớn giúp khi cần","Bấm vào bất kì quảng cáo nào hiện ra trên màn hình","Tự tải mọi bộ phim từ các trang lạ về máy","Xem một mình và giấu không cho bố mẹ biết"],"a":"Xem trên trang quen thuộc dành cho thiếu nhi và nhờ người lớn giúp khi cần","h":"Chỉ xem ở những nơi quen thuộc, đáng tin cậy.","e":"Xem phim ở các trang quen thuộc dành cho thiếu nhi và có người lớn bên cạnh giúp em tránh được nội dung xấu và quảng cáo lừa đảo.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Trong máy tính, thư mục là gì?","o":["Là nơi dùng để chứa các tệp, giúp sắp xếp dữ liệu gọn gàng","Là một loại trò chơi trên máy tính","Là bộ phận phát ra âm thanh","Là sợi dây nối máy tính với ổ điện"],"a":"Là nơi dùng để chứa các tệp, giúp sắp xếp dữ liệu gọn gàng","h":"Thư mục giống như một ngăn tủ để cất đồ.","e":"Thư mục là nơi chứa các tệp và thư mục con, giúp em sắp xếp dữ liệu trong máy tính gọn gàng, ngăn nắp.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em vẽ được rất nhiều bức tranh bằng máy tính và muốn cất riêng chúng vào một chỗ cho dễ tìm. Em nên làm gì?","o":["Để các bức tranh rải rác khắp nơi trong máy tính","Tạo một thư mục mới và lưu các bức tranh vào thư mục đó","Xoá hết các bức tranh đi","Đổi tên cho chiếc máy tính"],"a":"Tạo một thư mục mới và lưu các bức tranh vào thư mục đó","h":"Muốn đồ vật gọn gàng, em xếp chúng vào cùng một ngăn.","e":"Tạo một thư mục riêng để chứa các bức tranh giúp em cất giữ và tìm lại tranh nhanh chóng, không bị lẫn với tệp khác.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Hôm qua em đã lưu tệp tranh vào thư mục có tên 'Tranh của em'. Hôm nay muốn mở lại bức tranh đó, em tìm ở đâu?","o":["Vẽ lại một bức tranh hoàn toàn khác","Hỏi máy tính bằng cách hét thật to","Mở thư mục 'Tranh của em' và chọn tệp tranh đã lưu","Tìm trong thùng rác ở góc lớp học"],"a":"Mở thư mục 'Tranh của em' và chọn tệp tranh đã lưu","h":"Hãy nhớ lại hôm qua em đã lưu tệp vào đâu.","e":"Tệp được lưu ở thư mục nào thì em mở đúng thư mục đó để tìm và mở lại tệp.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Khi nhắn tin, trò chuyện với bạn qua mạng, em nên ứng xử như thế nào?","o":["Nói năng lịch sự, tôn trọng bạn như khi nói chuyện trực tiếp","Nói thế nào cũng được vì bạn không nhìn thấy mình","Dùng lời lẽ trêu chọc, chế giễu bạn","Giả làm người khác để nhắn tin trêu bạn"],"a":"Nói năng lịch sự, tôn trọng bạn như khi nói chuyện trực tiếp","h":"Dù ở trên mạng, em vẫn đang nói chuyện với người thật.","e":"Khi giao tiếp qua mạng, em cần nói năng lịch sự và tôn trọng người khác giống như khi nói chuyện trực tiếp.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em thấy một bạn trong lớp bị nhiều người nói xấu, trêu chọc trong nhóm trò chuyện trên mạng. Em nên làm gì?","o":["Không hùa theo và nói với thầy cô hoặc bố mẹ để giúp bạn","Cùng vào trêu chọc bạn cho vui","Chụp lại màn hình rồi gửi cho thật nhiều người xem","Mặc kệ vì chuyện đó không liên quan đến mình"],"a":"Không hùa theo và nói với thầy cô hoặc bố mẹ để giúp bạn","h":"Bắt nạt bạn trên mạng cũng là việc làm sai.","e":"Em không nên hùa theo việc trêu chọc bạn mà cần báo với thầy cô hoặc bố mẹ để kịp thời giúp đỡ bạn.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Em thấy một bức tranh rất đẹp trên mạng do một bạn khác vẽ. Việc làm nào sau đây là đúng?","o":["Xoá tên của bạn đó trên bức tranh đi","Xin phép bạn đó và khi dùng thì ghi rõ tranh là của bạn","Tự ý lấy tranh về và nói đó là tranh của mình","Mang bức tranh đó bán lấy tiền"],"a":"Xin phép bạn đó và khi dùng thì ghi rõ tranh là của bạn","h":"Đồ của người khác, muốn dùng thì phải xin phép.","e":"Bức tranh là sản phẩm của người vẽ; em cần xin phép và ghi rõ tên người vẽ khi sử dụng, đó là tôn trọng bản quyền.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Bạn em chép nguyên một bài văn hay trên mạng rồi nộp cho cô giáo và nói là tự mình viết. Theo em, việc làm đó như thế nào?","o":["Đúng, vì chép như vậy sẽ được điểm cao","Không sao, miễn là bạn chép chữ thật đẹp","Sai, vì lấy bài của người khác rồi nhận là của mình là không trung thực","Đúng, vì bài văn trên mạng thì ai dùng cũng được"],"a":"Sai, vì lấy bài của người khác rồi nhận là của mình là không trung thực","h":"Em hãy nghĩ: bài văn đó thật sự là của ai?","e":"Chép bài của người khác rồi nhận là của mình là việc làm sai và không trung thực; em nên tự viết bài hoặc ghi rõ nguồn khi tham khảo.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Muốn tạo một thư mục mới trên màn hình nền (Desktop), em nháy chuột phải vào vùng trống rồi chọn lệnh nào?","o":["Xoá (Delete)","Mới (New) rồi chọn Thư mục (Folder)","Mở (Open)","Đổi tên (Rename)"],"a":"Mới (New) rồi chọn Thư mục (Folder)","h":"Hãy nhớ thực đơn hiện ra khi em nháy chuột phải.","e":"Để tạo thư mục mới, em nháy chuột phải vào vùng trống, chọn Mới (New) rồi chọn Thư mục (Folder) và đặt tên cho thư mục.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Em muốn sao chép một tệp sang thư mục khác mà tệp gốc vẫn còn nguyên ở chỗ cũ. Em dùng cặp lệnh nào?","o":["Sao chép (Copy) rồi Dán (Paste)","Cắt (Cut) rồi Dán (Paste)","Xoá (Delete) rồi Dán (Paste)","Đổi tên (Rename) rồi Lưu (Save)"],"a":"Sao chép (Copy) rồi Dán (Paste)","h":"Sao chép nghĩa là tạo thêm một bản giống hệt.","e":"Lệnh Sao chép (Copy) tạo một bản sao của tệp và lệnh Dán (Paste) đặt bản sao vào thư mục mới, tệp gốc vẫn còn nguyên.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Em muốn di chuyển hẳn một tệp sang thư mục khác, để thư mục cũ không còn tệp đó nữa. Em dùng cặp lệnh nào?","o":["Cắt (Cut) rồi Dán (Paste)","Chỉ chọn lệnh Dán (Paste)","Sao chép (Copy) rồi Dán (Paste)","Đổi tên (Rename) cho tệp đó"],"a":"Cắt (Cut) rồi Dán (Paste)","h":"Di chuyển khác sao chép ở chỗ tệp gốc có còn hay không.","e":"Lệnh Cắt (Cut) rồi Dán (Paste) sẽ chuyển hẳn tệp sang thư mục mới và thư mục cũ không còn tệp đó nữa.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Em chọn một tệp không cần dùng nữa rồi nhấn phím Delete trên bàn phím. Tệp đó sẽ được chuyển đến đâu?","o":["Bay lên mạng Internet","Vào chiếc USB của bạn ngồi bên cạnh","Vào Thùng rác (Recycle Bin) trên màn hình nền","Vào thư mục Âm nhạc"],"a":"Vào Thùng rác (Recycle Bin) trên màn hình nền","h":"Trên màn hình nền có một biểu tượng hình thùng rác.","e":"Tệp bị xoá được chuyển vào Thùng rác (Recycle Bin); khi cần, em vẫn có thể khôi phục lại tệp từ đó.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Em muốn tìm cách trồng cây đậu trên Internet. Em nên gõ từ khoá nào vào ô tìm kiếm để có kết quả đúng ý nhất?","o":["Cách trồng cây đậu","Cây","Cách","Đậu"],"a":"Cách trồng cây đậu","h":"Từ khoá cần nói rõ đúng điều em muốn tìm.","e":"Từ khoá gồm các từ chính, rõ ràng như 'cách trồng cây đậu' sẽ giúp máy tìm kiếm cho kết quả đúng ý nhất.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Khi làm bài tập, em tìm được nhiều trang web cùng nói về một nội dung. Em nên ưu tiên đọc trang nào?","o":["Trang không ghi rõ là của ai, ở đâu","Trang của trường học, thư viện hoặc báo, đài chính thống","Trang có thật nhiều quảng cáo trúng thưởng","Trang bắt em nhập số điện thoại mới cho đọc"],"a":"Trang của trường học, thư viện hoặc báo, đài chính thống","h":"Hãy chọn nguồn thông tin mà em có thể tin cậy.","e":"Các trang của trường học, thư viện, báo và đài chính thống thường có thông tin được kiểm chứng nên đáng tin cậy hơn.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Mẹ em nói 'Bật nhạc giúp tôi' và chiếc loa thông minh tự phát nhạc. Loa làm được việc đó nhờ khả năng nào của trí tuệ nhân tạo (AI)?","o":["Nghe và hiểu được giọng nói của con người","Tự nghĩ ra một bài hát hoàn toàn mới","Nhìn thấy khuôn mặt của mẹ","Kết nối được với máy in"],"a":"Nghe và hiểu được giọng nói của con người","h":"Loa thông minh nghe được mệnh lệnh bằng lời nói.","e":"Nhờ trí tuệ nhân tạo, loa thông minh có thể nghe, hiểu giọng nói của con người và làm theo yêu cầu.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Điện thoại của bố em tự mở khoá ngay khi bố nhìn vào màn hình, còn người khác nhìn vào thì không mở được. Điện thoại đã dùng công nghệ nào?","o":["Nhận diện khuôn mặt","Ghi âm giọng nói","Định vị vệ tinh","Quét mã vạch hàng hoá"],"a":"Nhận diện khuôn mặt","h":"Điện thoại 'nhìn' vào đâu để biết đó là bố em?","e":"Điện thoại dùng công nghệ nhận diện khuôn mặt, một ứng dụng của trí tuệ nhân tạo, để nhận ra đúng chủ nhân và mở khoá.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây thể hiện máy tính hỗ trợ em sáng tạo?","o":["Dùng máy tính để nghe một bài hát","Dùng máy tính để tính một phép cộng","Dùng phần mềm vẽ và soạn thảo để tự thiết kế một tấm thiệp chúc mừng","Dùng máy tính để xem một bộ phim"],"a":"Dùng phần mềm vẽ và soạn thảo để tự thiết kế một tấm thiệp chúc mừng","h":"Sáng tạo là tự mình làm ra một sản phẩm mới.","e":"Máy tính hỗ trợ sáng tạo khi em dùng các phần mềm vẽ, soạn thảo, trình chiếu để tự làm ra sản phẩm của mình như tấm thiệp, bức tranh hay bài trình chiếu.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Em quay được video buổi dã ngoại của lớp. Muốn cắt bỏ đoạn bị rung và ghép các đoạn hay thành một video hoàn chỉnh, em cần dùng loại phần mềm nào?","o":["Phần mềm bảng tính","Phần mềm biên tập (dựng) video","Phần mềm soạn thảo văn bản","Trình duyệt web"],"a":"Phần mềm biên tập (dựng) video","h":"Mỗi loại phần mềm làm một việc riêng.","e":"Phần mềm biên tập video giúp em cắt, ghép các đoạn video và thêm chữ, nhạc để tạo thành một video hoàn chỉnh.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Em làm xong bài trình chiếu của nhóm. Muốn bạn cùng nhóm ở nhà bạn ấy cũng xem và sửa được bài, em dùng cách nào với lưu trữ đám mây?","o":["Tải tệp lên đám mây rồi gửi đường liên kết (link) chia sẻ cho bạn","In bài ra giấy rồi chụp ảnh gửi cho bạn","Kể lại bằng miệng cho bạn nghe qua điện thoại","Xoá bài đi rồi sang nhà bạn làm lại"],"a":"Tải tệp lên đám mây rồi gửi đường liên kết (link) chia sẻ cho bạn","h":"Đám mây giúp chia sẻ tệp qua mạng Internet.","e":"Khi tệp được tải lên đám mây, em chỉ cần gửi đường liên kết chia sẻ là bạn có thể mở xem và cùng chỉnh sửa tệp đó qua Internet.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Khi một tệp được chia sẻ qua đám mây, các bạn trong nhóm có thể làm gì với tệp đó?","o":["Mỗi bạn đều mở được cùng một tệp để xem và cùng chỉnh sửa","Chỉ một bạn xem được, các bạn khác thì không","Tệp sẽ tự biến mất sau một phút","Tệp chỉ xem được sau khi in ra giấy"],"a":"Mỗi bạn đều mở được cùng một tệp để xem và cùng chỉnh sửa","h":"Chia sẻ qua đám mây là để mọi người cùng làm việc trên một tệp.","e":"Tệp chia sẻ qua đám mây cho phép nhiều người cùng mở, xem và chỉnh sửa trên cùng một tệp, rất tiện cho làm việc nhóm.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Em bắt đầu soạn bài trên máy tính của trường, về nhà mở máy tính bảng ra vẫn thấy đúng bài đang soạn dở đó. Vì sao lại như vậy?","o":["Bài văn tự bay qua không khí về nhà em","Có người mang bài về nhà giúp em","Vì tệp được lưu trên đám mây nên mở được trên nhiều thiết bị khi em đăng nhập","Máy tính bảng tự chép bài từ trường về nhà"],"a":"Vì tệp được lưu trên đám mây nên mở được trên nhiều thiết bị khi em đăng nhập","h":"Tệp không nằm trong một chiếc máy cụ thể thì ở đâu?","e":"Tệp lưu trên đám mây nằm trên mạng Internet, nên em đăng nhập tài khoản của mình trên thiết bị nào cũng mở được đúng tệp đó.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong bảng tính, em phát hiện mình gõ nhầm số liệu trong ô B2. Cách sửa đúng là gì?","o":["Tắt máy tính đi rồi bật lại","Chọn ô B2, gõ lại số đúng rồi nhấn phím Enter","Xoá toàn bộ bảng tính rồi làm lại từ đầu","Đổi tên tệp bảng tính"],"a":"Chọn ô B2, gõ lại số đúng rồi nhấn phím Enter","h":"Muốn sửa nội dung của ô nào, em làm việc ngay tại ô đó.","e":"Để sửa dữ liệu trong một ô, em chọn ô đó rồi gõ lại nội dung đúng và nhấn Enter; không cần xoá cả bảng tính.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong bảng tính, muốn một ô tự tính kết quả của 12 cộng 8, em gõ vào ô đó nội dung nào?","o":["=12+8","12+8","Cộng 12 với 8","12 và 8"],"a":"=12+8","h":"Công thức trong bảng tính luôn bắt đầu bằng một dấu đặc biệt.","e":"Công thức trong bảng tính luôn bắt đầu bằng dấu =, ví dụ =12+8; ngoài phép cộng, em còn tính được phép trừ, nhân, chia trong ô tính.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Em lập trình trò chơi trong Scratch: nếu nhân vật chạm vào quả táo thì điểm số mới tăng lên. Em dùng khối lệnh nào để kiểm tra điều kiện rồi mới tăng điểm?","o":["Khối 'nếu ... thì ...'","Khối 'lặp lại 10 lần'","Khối 'nói Xin chào!'","Khối 'phát ra âm thanh'"],"a":"Khối 'nếu ... thì ...'","h":"Khối này chỉ thực hiện lệnh khi điều kiện đúng.","e":"Khối 'nếu ... thì ...' giúp chương trình kiểm tra một điều kiện (như chạm vào quả táo) và chỉ thực hiện lệnh bên trong khi điều kiện đó đúng.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Trong Scratch, em muốn nhân vật A nói xong lời thoại thì nhân vật B mới xuất hiện. Em nên dùng cặp khối lệnh nào?","o":["Khối 'lặp lại liên tục' ở nhân vật B","Khối 'đổi trang phục' ở nhân vật A","'Phát thông điệp' ở nhân vật A và 'Khi tôi nhận được thông điệp' ở nhân vật B","Khối 'di chuyển 10 bước' ở cả hai nhân vật"],"a":"'Phát thông điệp' ở nhân vật A và 'Khi tôi nhận được thông điệp' ở nhân vật B","h":"Hai nhân vật cần 'báo tin' cho nhau để phối hợp.","e":"Khối 'phát thông điệp' và khối 'khi tôi nhận được thông điệp' giúp các nhân vật trong Scratch báo tin cho nhau để hoạt động đúng thứ tự.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Muốn gõ tiếng Việt có dấu bằng kiểu gõ Telex trên máy tính, em cần làm gì với phần mềm bộ gõ như Unikey hoặc EVKey?","o":["Chỉ cần mở phần mềm soạn thảo là đủ","Đổi bàn phím sang một bàn phím khác","Tắt hẳn phần mềm bộ gõ đi","Bật phần mềm bộ gõ và chọn kiểu gõ Telex"],"a":"Bật phần mềm bộ gõ và chọn kiểu gõ Telex","h":"Bộ gõ phải đang chạy và được chọn đúng kiểu gõ thì em mới gõ được dấu.","e":"Để gõ tiếng Việt kiểu Telex, em cần bật phần mềm bộ gõ (như Unikey, EVKey) ở chế độ tiếng Việt và chọn kiểu gõ Telex.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong kiểu gõ Telex, muốn gõ chữ 'â' em gõ phím nào hai lần?","o":["Gõ 'oo' hai lần","Gõ 'ee' hai lần","Gõ 'aa' hai lần","Gõ 'uu' hai lần"],"a":"Gõ 'aa' hai lần","h":"Chữ 'â' là chữ 'a' đội thêm chiếc mũ.","e":"Trong Telex, gõ 'aa' sẽ được chữ 'â'. Ví dụ muốn gõ từ 'cân', em gõ 'caan'.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Muốn gõ từ 'trăng' bằng kiểu gõ Telex, em gõ dãy phím nào?","o":["trawng","traang","trwanq","trzng"],"a":"trawng","h":"Chữ 'ă' trong Telex được gõ bằng 'aw'.","e":"Trong Telex, 'aw' cho chữ 'ă', nên từ 'trăng' được gõ là 'trawng'.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Muốn gõ từ 'đỏ' bằng kiểu gõ Telex, em gõ dãy phím nào?","o":["doz","ddof","dor","ddor"],"a":"ddor","h":"Chữ 'đ' gõ bằng 'dd', còn dấu hỏi gõ bằng phím 'r'.","e":"Trong Telex, 'dd' cho chữ 'đ' và phím 'r' cho dấu hỏi, nên từ 'đỏ' được gõ là 'ddor'.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong kiểu gõ Telex, các phím s, f, r, x, j lần lượt dùng để gõ các dấu thanh nào?","o":["Dấu hỏi, dấu sắc, dấu nặng, dấu huyền, dấu ngã","Dấu huyền, dấu hỏi, dấu ngã, dấu nặng, dấu sắc","Dấu nặng, dấu ngã, dấu hỏi, dấu huyền, dấu sắc","Dấu sắc, dấu huyền, dấu hỏi, dấu ngã, dấu nặng"],"a":"Dấu sắc, dấu huyền, dấu hỏi, dấu ngã, dấu nặng","h":"Em hãy nhớ theo thứ tự: s là sắc, f là huyền, r là hỏi, x là ngã, j là nặng.","e":"Trong Telex: s = dấu sắc, f = dấu huyền, r = dấu hỏi, x = dấu ngã, j = dấu nặng.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Cách gõ Telex nào sau đây cho ra đúng từ 'bánh'?","o":["bahns","bansh","basnh","banhs"],"a":"basnh","h":"Dấu sắc (phím s) được gõ ngay sau chữ cái mang dấu là chữ 'a'.","e":"Từ 'bánh' có dấu sắc ở chữ 'a' nên gõ phím 's' ngay sau 'a': 'basnh'. Gõ dấu ngay sau chữ cái mang dấu giúp gõ nhanh và đúng.","t":"tin-lop4","g":4,"l":"thach-thuc"},{"p":"Muốn gõ chữ hoa có dấu 'Ấ' bằng kiểu gõ Telex, em gõ thế nào?","o":["Chỉ cần gõ 'AS' là đủ","Không gõ được chữ hoa có dấu bằng Telex","Gõ 'aas' rồi thu nhỏ chữ lại","Gõ chữ A hoa rồi gõ tiếp 'a' và 's' (thành 'AAS')"],"a":"Gõ chữ A hoa rồi gõ tiếp 'a' và 's' (thành 'AAS')","h":"Chữ 'Ấ' gồm chữ A hoa, thêm mũ (a) và thêm dấu sắc (s).","e":"Để gõ 'Ấ', em gõ chữ A hoa (nhấn Shift + A), rồi gõ tiếp 'a' để thêm mũ và 's' để thêm dấu sắc, tức dãy 'AAS'.","t":"tin-lop4","g":4,"l":"thach-thuc"},{"p":"Trong kiểu gõ Telex, em vừa gõ dấu nhưng bị nhầm dấu. Phím nào giúp em xoá dấu vừa gõ để gõ lại dấu khác?","o":["Phím q","Phím w","Phím z","Phím j"],"a":"Phím z","h":"Phím này nằm ở hàng phím dưới cùng, gần phím Shift.","e":"Trong Telex, phím 'z' dùng để xoá dấu vừa gõ. Ví dụ gõ 'hos' được 'hó', nhấn thêm 'z' sẽ bỏ dấu sắc thành 'ho'.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Em nói với trợ lí ảo trên điện thoại: 'Nhắc tôi học bài lúc 7 giờ tối.' Trợ lí ảo sẽ làm gì?","o":["Tắt điện thoại để em tập trung","Gọi điện ngay cho cô giáo của em","Tự học bài thay cho em","Đặt lời nhắc và đến 7 giờ tối sẽ nhắc em học bài"],"a":"Đặt lời nhắc và đến 7 giờ tối sẽ nhắc em học bài","h":"Trợ lí ảo nghe hiểu lời nói của em và làm theo việc em nhờ.","e":"Trợ lí ảo dùng trí tuệ nhân tạo để nghe và hiểu lệnh bằng giọng nói, ví dụ đặt lời nhắc, trả lời câu hỏi hay bật nhạc theo yêu cầu.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Vì sao ứng dụng nghe nhạc, xem video thường gợi ý đúng bài hát hoặc video mà em thích?","o":["Vì có người ngồi xem em đang làm gì suốt ngày","Vì em đã xem hết mọi bài hát trên ứng dụng","Vì ứng dụng chọn ngẫu nhiên bất kì bài nào","Vì trí tuệ nhân tạo ghi nhớ những gì em đã xem, đã nghe và đoán sở thích của em"],"a":"Vì trí tuệ nhân tạo ghi nhớ những gì em đã xem, đã nghe và đoán sở thích của em","h":"Ứng dụng học từ thói quen xem và nghe của chính em.","e":"Trí tuệ nhân tạo phân tích những video, bài hát em từng xem và nghe để gợi ý nội dung tương tự mà em có thể thích.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Em gặp một câu tiếng Anh chưa hiểu nghĩa. Công cụ dịch máy như Google Dịch giúp em việc gì?","o":["Dịch câu tiếng Anh đó sang tiếng Việt để em hiểu nghĩa","Dạy em phát âm giống hệt người nước ngoài ngay lập tức","Làm bài kiểm tra tiếng Anh thay cho em","Xoá câu tiếng Anh đó đi"],"a":"Dịch câu tiếng Anh đó sang tiếng Việt để em hiểu nghĩa","h":"Dịch máy là công cụ đổi một ngôn ngữ sang ngôn ngữ khác.","e":"Dịch máy dùng trí tuệ nhân tạo để dịch chữ và cả câu giữa các ngôn ngữ, giúp em hiểu nghĩa của từ hoặc câu tiếng nước ngoài.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Em hỏi chatbot AI để hỗ trợ học bài. Cách dùng nào sau đây là đúng và thông minh nhất?","o":["Chép nguyên mọi câu trả lời của chatbot vào vở","Tin ngay mọi điều chatbot nói vì máy tính không bao giờ sai","Nghe chatbot giải thích, gợi ý cách làm rồi tự làm bài và kiểm tra lại","Nhờ chatbot làm bài hộ để em đi chơi"],"a":"Nghe chatbot giải thích, gợi ý cách làm rồi tự làm bài và kiểm tra lại","h":"Chatbot là bạn hỗ trợ, nhưng người học bài vẫn phải là em.","e":"Chatbot AI đôi khi cũng trả lời chưa đúng. Em nên dùng chatbot để được giải thích, gợi ý, sau đó tự làm bài và đối chiếu với sách vở để kiểm chứng.","t":"tin-lop12","g":12,"l":"thach-thuc"},{"p":"Em hướng camera điện thoại vào một cây hoa lạ và điện thoại hiện tên của loài hoa đó. Điện thoại làm được việc này nhờ khả năng nào của trí tuệ nhân tạo?","o":["Nhận diện hình ảnh để đoán vật trong ảnh","Dịch ngôn ngữ","Gợi ý bài hát","Đặt lời nhắc bằng giọng nói"],"a":"Nhận diện hình ảnh để đoán vật trong ảnh","h":"Điện thoại 'nhìn' bức ảnh và đoán đó là vật gì.","e":"Trí tuệ nhân tạo có khả năng nhận diện hình ảnh: phân tích hình ảnh từ camera để nhận biết cây cối, đồ vật, con vật hay chữ viết.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Khi em chơi trò chơi một mình với 'máy', nhân vật đối thủ tự biết né tránh và đuổi theo em. Điều đó là nhờ đâu?","o":["Nhân vật tự chạy lung tung không theo quy tắc nào","Trò chơi được nối với tivi nên nhân vật tự chạy","Có một bạn khác đang lén điều khiển giúp máy","Trí tuệ nhân tạo điều khiển nhân vật của máy theo các tình huống trong trò chơi"],"a":"Trí tuệ nhân tạo điều khiển nhân vật của máy theo các tình huống trong trò chơi","h":"Trong trò chơi, 'máy' cũng biết 'suy nghĩ' theo cách đã được lập trình sẵn.","e":"Nhiều trò chơi dùng trí tuệ nhân tạo để điều khiển nhân vật đối thủ, giúp chúng di chuyển, né tránh và phản ứng như một người chơi thật.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Khi trò chuyện với chatbot AI trên mạng, việc nào sau đây là an toàn cho em?","o":["Cho chatbot biết họ tên, địa chỉ nhà và tên trường của em","Gửi ảnh cá nhân của em cho chatbot xem","Không cho chatbot biết thông tin cá nhân của em và gia đình","Cho chatbot mật khẩu tài khoản của em để nó nhớ giúp"],"a":"Không cho chatbot biết thông tin cá nhân của em và gia đình","h":"Thông tin cá nhân phải được giữ kín với mọi 'người lạ', kể cả chatbot.","e":"Dù chatbot trò chuyện thân thiện, em tuyệt đối không chia sẻ họ tên đầy đủ, địa chỉ nhà, tên trường hay mật khẩu cho chatbot hay bất kì ai trên mạng.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong Scratch, muốn có thêm một nhân vật mới cho chương trình, em làm thế nào?","o":["Nháy vào nút 'Chọn một nhân vật' để lấy nhân vật từ thư viện hoặc tự vẽ","Tắt Scratch rồi mở lại","Nhấn phím cách trên bàn phím","Nháy đúp vào sân khấu"],"a":"Nháy vào nút 'Chọn một nhân vật' để lấy nhân vật từ thư viện hoặc tự vẽ","h":"Nút thêm nhân vật nằm ở góc dưới bên phải, trong khu vực danh sách nhân vật.","e":"Trong Scratch, em nháy vào nút 'Chọn một nhân vật' để thêm nhân vật có sẵn trong thư viện, hoặc tự vẽ, tải ảnh lên làm nhân vật mới.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong Scratch, khối lệnh 'xoay 15 độ' (hình mũi tên cong) có tác dụng gì?","o":["Làm nhân vật biến mất","Làm nhân vật nói một câu","Làm nhân vật to lên","Làm nhân vật quay (xoay) một góc 15 độ"],"a":"Làm nhân vật quay (xoay) một góc 15 độ","h":"Hãy để ý mũi tên cong trên khối lệnh, nó chỉ hướng quay.","e":"Khối 'xoay 15 độ' thuộc nhóm Chuyển động, giúp nhân vật quay một góc 15 độ theo chiều kim đồng hồ (hoặc ngược chiều với khối xoay còn lại).","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong Scratch, khối lệnh 'khi bấm vào lá cờ xanh' nằm trong nhóm khối lệnh nào?","o":["Nhóm Chuyển động","Nhóm Âm thanh","Nhóm Sự kiện","Nhóm Hiển thị"],"a":"Nhóm Sự kiện","h":"Đây là khối lệnh bắt đầu chương trình khi có một việc xảy ra.","e":"Khối 'khi bấm vào lá cờ xanh' thuộc nhóm Sự kiện. Nó thường được đặt trên cùng để bắt đầu chạy các khối lệnh bên dưới khi em bấm lá cờ xanh.","t":"tin-lop4","g":4,"l":"thach-thuc"},{"p":"Muốn điều khiển nhân vật Scratch di chuyển mỗi khi em bấm phím mũi tên trên bàn phím, em dùng khối lệnh bắt đầu nào?","o":["Khối 'khi phím mũi tên được bấm' trong nhóm Sự kiện","Khối 'nói Xin chào!' trong nhóm Hiển thị","Khối 'phát âm thanh' trong nhóm Âm thanh","Khối 'chờ 1 giây' trong nhóm Điều khiển"],"a":"Khối 'khi phím mũi tên được bấm' trong nhóm Sự kiện","h":"Muốn chương trình chạy khi em bấm phím, khối bắt đầu phải nhắc tới phím đó.","e":"Khối 'khi phím ... được bấm' trong nhóm Sự kiện giúp chương trình bắt đầu chạy mỗi khi em bấm phím đã chọn, rất hay dùng để điều khiển nhân vật trong trò chơi.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Khi em dùng khối lệnh 'nói' cho nhân vật Scratch, điều gì xuất hiện trên sân khấu?","o":["Nhân vật phát ra tiếng nói thật","Một bong bóng chứa lời nói hiện lên phía trên đầu nhân vật","Nhân vật đổi màu ngay lập tức","Sân khấu đổi hình nền mới"],"a":"Một bong bóng chứa lời nói hiện lên phía trên đầu nhân vật","h":"Hãy tưởng tượng nhân vật trong truyện tranh khi đang nói chuyện.","e":"Khối 'nói' trong nhóm Hiển thị làm xuất hiện một bong bóng lời nói phía trên đầu nhân vật, giống như nhân vật đang nói câu chữ em viết trong khối lệnh.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong Scratch, khối lệnh 'chờ 1 giây' có tác dụng gì?","o":["Làm chương trình dừng lại 1 giây rồi mới chạy tiếp","Xoá nhân vật sau 1 giây","Làm nhân vật chạy nhanh hơn trong 1 giây","Kết thúc chương trình sau 1 giây"],"a":"Làm chương trình dừng lại 1 giây rồi mới chạy tiếp","h":"Khối này giống như em đếm 'một' rồi mới làm việc tiếp theo.","e":"Khối 'chờ 1 giây' thuộc nhóm Điều khiển, giúp chương trình tạm dừng đúng 1 giây trước khi thực hiện khối lệnh tiếp theo, ví dụ để nhân vật đi chậm lại.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Muốn nhân vật mèo trong Scratch kêu 'meo' khi chương trình chạy, em dùng khối lệnh nào?","o":["Khối 'nói Meo!' trong nhóm Hiển thị","Khối 'phát âm thanh Meow' trong nhóm Âm thanh","Khối 'di chuyển 10 bước' trong nhóm Chuyển động","Khối 'đổi màu' trong nhóm Hiển thị"],"a":"Khối 'phát âm thanh Meow' trong nhóm Âm thanh","h":"Âm thanh thật được phát ra từ nhóm khối có hình chiếc loa.","e":"Khối 'phát âm thanh ...' trong nhóm Âm thanh giúp nhân vật phát ra tiếng như tiếng mèo kêu, tiếng trống hay bản nhạc ngắn.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong Scratch, khối lệnh 'lặp lại 4' giúp em việc gì?","o":["Tạo ra 4 nhân vật giống hệt nhau","Làm các khối lệnh bên trong lặp lại 4 lần mà không cần xếp lại nhiều lần","Làm nhân vật to lên gấp 4 lần","Chạy chương trình nhanh gấp 4 lần bình thường"],"a":"Làm các khối lệnh bên trong lặp lại 4 lần mà không cần xếp lại nhiều lần","h":"Hãy nghĩ tới việc nhân vật phải đi một đoạn đường giống nhau nhiều lần.","e":"Khối 'lặp lại ...' thuộc nhóm Điều khiển. Các khối lệnh đặt bên trong nó sẽ được thực hiện lặp đi lặp lại đúng số lần em chọn.","t":"tin-lop4","g":4,"l":"thach-thuc"},{"p":"Trong Scratch, muốn nhân vật vừa đi vừa để lại nét vẽ trên sân khấu, em cần thêm nhóm khối lệnh nào?","o":["Nhóm Bút (thêm từ phần mở rộng)","Nhóm Âm thanh","Nhóm Cảm biến","Không cần thêm gì, nhân vật tự vẽ được"],"a":"Nhóm Bút (thêm từ phần mở rộng)","h":"Nhóm khối này được thêm vào bằng nút ở góc dưới bên trái màn hình Scratch.","e":"Để nhân vật vẽ được, em nháy vào nút thêm phần mở rộng ở góc dưới bên trái và chọn nhóm Bút, sau đó dùng khối 'đặt bút xuống' để nhân vật vẽ theo đường đi.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong Scratch, muốn nhân vật mèo trở nên to hơn trên sân khấu, em dùng khối lệnh nào?","o":["Khối 'di chuyển 10 bước'","Khối 'đặt kích thước thành 150%' trong nhóm Hiển thị","Khối 'nói To lên!'","Khối 'xoay 15 độ'"],"a":"Khối 'đặt kích thước thành 150%' trong nhóm Hiển thị","h":"Số phần trăm càng lớn thì nhân vật càng to.","e":"Khối 'đặt kích thước thành ...%' trong nhóm Hiển thị giúp thay đổi độ lớn của nhân vật: trên 100% thì to lên, dưới 100% thì nhỏ đi.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trên bảng hiệu ở cổng trường có dòng chữ 'Khu vực nguy hiểm, không leo trèo'. Sau khi đọc bảng hiệu, em nên quyết định thế nào?","o":["Vẫn leo trèo vì bảng hiệu chỉ để trang trí","Không leo trèo ở khu vực đó để giữ an toàn","Rủ thêm bạn cùng leo cho vui","Chụp ảnh bảng hiệu rồi leo lên"],"a":"Không leo trèo ở khu vực đó để giữ an toàn","h":"Bảng hiệu là nguồn thông tin giúp em biết việc nên và không nên làm.","e":"Bảng hiệu, biển báo là nguồn thông tin quanh em. Đọc và làm theo thông tin trên bảng hiệu giúp em quyết định đúng và an toàn.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Sáng nay, loa phát thanh của trường thông báo: 'Giờ sinh hoạt lớp chuyển sang cuối buổi chiều.' Thông tin này giúp em việc gì?","o":["Biết để chuẩn bị và tham gia sinh hoạt lớp đúng giờ mới","Biết để nghỉ học luôn từ sáng","Chẳng giúp gì, em không cần quan tâm","Biết để rủ bạn trốn sinh hoạt lớp"],"a":"Biết để chuẩn bị và tham gia sinh hoạt lớp đúng giờ mới","h":"Loa phát thanh của trường là nơi thông báo những thay đổi quan trọng.","e":"Thông báo qua loa phát thanh là nguồn thông tin chính thức của nhà trường. Nghe thông tin giúp em biết thay đổi và chuẩn bị cho phù hợp.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Tối nay em mở thời khoá biểu ra xem và thấy ngày mai có môn Tin học. Dựa vào thông tin đó, em nên làm gì?","o":["Không cần chuẩn bị gì thêm","Chuẩn bị sách, vở Tin học cho vào cặp để mai mang đi học","Xin nghỉ học môn Tin học","Mang tất cả sách của cả tuần cho chắc"],"a":"Chuẩn bị sách, vở Tin học cho vào cặp để mai mang đi học","h":"Thời khoá biểu cho em biết ngày mai học những môn nào.","e":"Thời khoá biểu là nguồn thông tin giúp em biết lịch học từng ngày, từ đó quyết định chuẩn bị đúng sách vở cho ngày hôm sau.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Một bạn trong lớp nói: 'Nghe nói ngày mai cả trường được nghỉ học đấy!' nhưng cô giáo chưa hề thông báo. Em nên làm gì?","o":["Tin ngay và ngày mai ở nhà luôn","Đi loan tin cho cả lớp cùng biết","Chờ thông báo chính thức của cô giáo hoặc nhà trường rồi mới tin","Tự viết giấy xin nghỉ nộp cho cô"],"a":"Chờ thông báo chính thức của cô giáo hoặc nhà trường rồi mới tin","h":"Không phải thông tin nào nghe được cũng đã đúng, em cần kiểm tra nguồn tin.","e":"Thông tin nghe truyền miệng có thể chưa đúng. Em nên chờ và tin vào thông báo chính thức từ cô giáo, nhà trường trước khi quyết định.","t":"tin-lop3","g":3,"l":"thach-thuc"},{"p":"Trong Scratch, muốn nhân vật tự vẽ một bông hoa có nhiều cánh giống nhau, em nên làm thế nào?","o":["Xếp thật nhiều khối vẽ bằng tay, cánh nào cũng xếp lại từ đầu","Đặt một khối 'lặp lại' bên trong một khối 'lặp lại' khác (lặp lồng nhau)","Chỉ dùng một khối di chuyển duy nhất","Tắt máy rồi vẽ bằng bút chì"],"a":"Đặt một khối 'lặp lại' bên trong một khối 'lặp lại' khác (lặp lồng nhau)","h":"Một vòng lặp vẽ một cánh hoa, vòng lặp bên ngoài giúp lặp lại việc vẽ nhiều cánh.","e":"Vòng lặp lồng nhau là khi một khối 'lặp lại' nằm trong một khối 'lặp lại' khác. Cách này giúp vẽ các hình có nhiều phần giống nhau như bông hoa nhiều cánh hay hàng rào.","t":"tin-lop5","g":5,"l":"thach-thuc"},{"p":"Em làm trò chơi Scratch: khi biến Điểm đạt từ 10 trở lên, nhân vật nói 'Thắng rồi!'. Em cần kết hợp những khối lệnh nào?","o":["Khối 'nếu ... thì ...' kiểm tra điều kiện 'Điểm lớn hơn hoặc bằng 10' cùng khối 'nói'","Chỉ cần khối 'nói' là đủ","Khối 'chờ 10 giây' cùng khối 'di chuyển'","Khối 'phát âm thanh' cùng khối 'xoay'"],"a":"Khối 'nếu ... thì ...' kiểm tra điều kiện 'Điểm lớn hơn hoặc bằng 10' cùng khối 'nói'","h":"Muốn chương trình tự kiểm tra điểm số, em cần một khối điều kiện đọc giá trị của biến.","e":"Kết hợp biến với điều kiện: khối 'nếu Điểm ≥ 10 thì' sẽ kiểm tra giá trị biến Điểm, đúng điều kiện thì thực hiện lệnh bên trong, ví dụ cho nhân vật nói 'Thắng rồi!'.","t":"tin-lop5","g":5,"l":"thach-thuc"},{"p":"Trong trò chơi Scratch, em muốn nhân vật cứ nhặt táo để tăng điểm và trò chơi chỉ dừng lại khi Điểm bằng đúng 20. Khối lệnh nào phù hợp nhất?","o":["Khối 'lặp lại 20'","Khối 'lặp cho đến khi Điểm = 20'","Khối 'chờ 20 giây'","Khối 'lặp lại liên tục' không có điểm dừng"],"a":"Khối 'lặp cho đến khi Điểm = 20'","h":"Em cần một vòng lặp biết tự dừng khi đạt đúng điều kiện.","e":"Khối 'lặp cho đến khi ...' sẽ lặp các lệnh bên trong và chỉ dừng lại khi điều kiện đúng, ở đây là khi biến Điểm bằng 20, rất hợp cho trò chơi tính điểm.","t":"tin-lop5","g":5,"l":"thach-thuc"},{"p":"Vì sao em không nên dùng ngày sinh của mình (ví dụ 15082016) làm mật khẩu cho tài khoản học tập?","o":["Vì ngày sinh quá dài, gõ rất lâu","Vì ngày sinh là thông tin nhiều người biết, kẻ xấu dễ đoán ra mật khẩu","Vì máy tính không cho dùng số làm mật khẩu","Vì ngày sinh chỉ dùng được cho một tài khoản"],"a":"Vì ngày sinh là thông tin nhiều người biết, kẻ xấu dễ đoán ra mật khẩu","h":"Mật khẩu tốt phải là điều chỉ riêng em biết và người khác khó đoán.","e":"Ngày sinh, tên của em hay tên thú cưng là những thông tin dễ bị người khác biết và đoán được. Em nên đặt mật khẩu khó đoán và giữ kín, không chia sẻ cho ai.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Cả nhà em sắp đi du lịch xa một tuần. Việc làm nào sau đây là an toàn nhất?","o":["Đăng lên mạng: 'Cả nhà mình đi du lịch, nhà không có ai ở nhà một tuần!'","Kể cho mọi người lạ trên mạng biết lịch đi của gia đình","Không đăng thông tin cả nhà vắng nhà lên mạng để tránh kẻ xấu biết","Gửi địa chỉ nhà cho bạn trên mạng để bạn qua trông nhà"],"a":"Không đăng thông tin cả nhà vắng nhà lên mạng để tránh kẻ xấu biết","h":"Thông tin về lịch trình của gia đình cũng là thông tin cá nhân cần giữ kín.","e":"Đăng chuyện cả nhà đi vắng lên mạng có thể khiến kẻ xấu biết nhà không có người và lợi dụng. Thông tin cá nhân và lịch trình gia đình cần được giữ kín.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Khi đang chơi trò chơi trực tuyến, một người lạ trong trò chơi gửi cho em hình ảnh xấu và lời lẽ khó chịu. Em nên làm gì?","o":["Gửi lại hình ảnh xấu hơn cho người đó","Chuyển tiếp hình ảnh đó cho các bạn cùng xem","Không trả lời, chặn người đó và báo ngay cho bố mẹ hoặc thầy cô","Tiếp tục nói chuyện để xem người đó là ai"],"a":"Không trả lời, chặn người đó và báo ngay cho bố mẹ hoặc thầy cô","h":"Khi gặp nội dung xấu trên mạng, người lớn là người giúp em xử lí an toàn nhất.","e":"Gặp nội dung xấu hay người lạ làm phiền trên mạng, em không nên đáp trả hay chia sẻ tiếp. Hãy chặn tài khoản đó và báo ngay cho bố mẹ, thầy cô để được giúp đỡ.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Một tài khoản lạ gửi vào nhóm trò chuyện của lớp đường link 'Nhận quà miễn phí, bấm ngay kẻo hết!'. Em nên làm gì?","o":["Bấm ngay vào link để nhận quà trước các bạn","Gửi link đó cho nhiều bạn khác cùng nhận quà","Không bấm vào link lạ và báo cho cô giáo hoặc bố mẹ biết","Nhập họ tên và địa chỉ vào link để nhận quà"],"a":"Không bấm vào link lạ và báo cho cô giáo hoặc bố mẹ biết","h":"Đường link lạ hứa tặng quà thường là bẫy lừa đảo.","e":"Các đường link lạ hứa tặng quà miễn phí thường là bẫy để lừa lấy thông tin hoặc làm hại thiết bị. Em không nên bấm vào và cần báo cho người lớn biết.","t":"tin-lop4","g":4,"l":"thach-thuc"},{"p":"Tệp tranh em lưu có tên là 'BaiVe1'. Muốn đổi tên tệp thành 'TranhTet' cho dễ nhớ, em làm thế nào?","o":["Xoá tệp đi rồi vẽ lại tranh mới","Nháy chuột phải vào tệp, chọn 'Đổi tên' (Rename) rồi gõ tên mới","Mở tệp tranh lên và xoá hết hình bên trong","Không thể đổi tên tệp sau khi đã lưu"],"a":"Nháy chuột phải vào tệp, chọn 'Đổi tên' (Rename) rồi gõ tên mới","h":"Thực đơn chuột phải trên tệp có lệnh dành riêng cho việc đổi tên.","e":"Muốn đổi tên tệp, em nháy chuột phải vào tệp và chọn 'Đổi tên' (Rename), sau đó gõ tên mới và nhấn Enter. Nội dung bên trong tệp vẫn giữ nguyên.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em lỡ tay xoá mất tệp tranh mà mình rất thích. Em có thể tìm lại tệp đó ở đâu trên máy tính?","o":["Trong Thùng rác (Recycle Bin), em có thể khôi phục lại tệp","Tệp đã biến mất vĩnh viễn, không tìm lại được ở đâu nữa","Trong thư mục nhạc của máy tính","Trên màn hình nền, tệp sẽ tự hiện lại"],"a":"Trong Thùng rác (Recycle Bin), em có thể khôi phục lại tệp","h":"Tệp vừa bị xoá chưa mất hẳn, nó được chuyển vào một nơi chứa đồ đã xoá.","e":"Khi em xoá tệp, tệp được chuyển vào Thùng rác (Recycle Bin) chứ chưa mất hẳn. Em có thể mở Thùng rác và khôi phục lại tệp nếu cần.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi tìm kiếm thông tin trên Internet, cách chọn từ khóa nào giúp kết quả sát với nhu cầu nhất?","o":["Dùng một câu thật dài, càng nhiều chữ càng tốt","Dùng từ khóa ngắn gọn, đúng trọng tâm; đặt cụm từ trong dấu ngoặc kép khi cần tìm chính xác nguyên văn","Chỉ cần gõ một chữ bất kì liên quan đến chủ đề","Sao chép nguyên cả đoạn văn cần tìm vào ô tìm kiếm"],"a":"Dùng từ khóa ngắn gọn, đúng trọng tâm; đặt cụm từ trong dấu ngoặc kép khi cần tìm chính xác nguyên văn","h":"Từ khóa quyết định phần lớn chất lượng của kết quả tìm kiếm.","e":"Từ khóa ngắn gọn, đúng trọng tâm giúp công cụ tìm kiếm hiểu đúng nhu cầu; dấu ngoặc kép giúp tìm đúng cụm từ nguyên văn, thu hẹp kết quả thừa.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Dấu hiệu nào dưới đây cho thấy một trang web có độ tin cậy cao hơn các trang khác?","o":["Trang có thật nhiều quảng cáo nhấp nháy","Tiêu đề bài viết giật gân, gây tò mò mạnh","Ghi rõ tác giả, cơ quan chủ quản và ngày đăng hoặc ngày cập nhật thông tin","Trang không ghi nguồn gốc của thông tin"],"a":"Ghi rõ tác giả, cơ quan chủ quản và ngày đăng hoặc ngày cập nhật thông tin","h":"Hãy nghĩ xem em kiểm tra điều gì đầu tiên khi muốn biết một bài viết có đáng tin hay không.","e":"Trang web minh bạch về tác giả, cơ quan chủ quản và thời gian cập nhật thường đáng tin hơn, vì người đọc có thể kiểm chứng nguồn gốc thông tin.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Đọc được một thông tin gây chú ý trên mạng xã hội, cách kiểm chứng tốt nhất là gì?","o":["Đối chiếu thông tin với các nguồn chính thống, uy tín khác trước khi tin và chia sẻ","Chia sẻ ngay cho bạn bè để cùng bàn luận","Tin ngay nếu bài viết có rất nhiều lượt thích","Tin nếu đã có nhiều người chia sẻ lại"],"a":"Đối chiếu thông tin với các nguồn chính thống, uy tín khác trước khi tin và chia sẻ","h":"Lượt thích và lượt chia sẻ không phải là thước đo độ đúng sai của thông tin.","e":"Thông tin trên mạng xã hội có thể chưa được kiểm chứng; đối chiếu với nhiều nguồn chính thống, uy tín là cách đáng tin cậy để xác thực.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Nhận định nào đúng về thông tin trên Internet?","o":["Thông tin nào xuất hiện trên Internet cũng chính xác","Chỉ cần tìm thấy trên mạng là có thể dùng ngay vào bài tập","Thông tin trên Internet do nhà nước kiểm duyệt hết nên luôn đúng","Thông tin trên Internet rất phong phú nhưng không phải thông tin nào cũng chính xác, cần kiểm chứng trước khi sử dụng"],"a":"Thông tin trên Internet rất phong phú nhưng không phải thông tin nào cũng chính xác, cần kiểm chứng trước khi sử dụng","h":"Ai cũng có thể đăng tải thông tin lên Internet.","e":"Bất kì ai cũng có thể đăng thông tin lên Internet nên chất lượng không đồng đều; người dùng cần chọn lọc và kiểm chứng trước khi sử dụng.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi đánh giá độ tin cậy của một thông tin trên mạng, yếu tố nào quan trọng nhất?","o":["Số lượt xem của bài viết","Nguồn gốc xuất xứ và uy tín của tác giả, tổ chức đăng tải thông tin","Bài viết có hình ảnh minh họa đẹp hay không","Số lượng bình luận dưới bài viết"],"a":"Nguồn gốc xuất xứ và uy tín của tác giả, tổ chức đăng tải thông tin","h":"Một thông tin được nhiều người xem chưa chắc đã đúng.","e":"Độ tin cậy của thông tin phụ thuộc chủ yếu vào nguồn gốc và uy tín của người, tổ chức đăng tải, không phụ thuộc vào lượt xem hay hình ảnh.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Tin giả (fake news) trên mạng thường có đặc điểm nào?","o":["Luôn ghi nguồn trích dẫn rõ ràng, đầy đủ","Được đăng tải trên các báo chính thống","Tiêu đề giật gân, kích động cảm xúc, nội dung thiếu nguồn kiểm chứng","Luôn ghi rõ ngày tháng và tác giả"],"a":"Tiêu đề giật gân, kích động cảm xúc, nội dung thiếu nguồn kiểm chứng","h":"Tin giả thường đánh vào cảm xúc để người đọc chia sẻ thật nhanh.","e":"Tin giả thường dùng tiêu đề giật gân, kích động cảm xúc và không có nguồn kiểm chứng nhằm thu hút lượt xem, lượt chia sẻ.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Việc làm nào dưới đây vi phạm bản quyền phần mềm?","o":["Cài đặt và sử dụng phần mềm thương mại khi chưa mua bản quyền và không được nhà phát hành cho phép","Sử dụng phần mềm miễn phí, mã nguồn mở theo đúng giấy phép đi kèm","Dùng bản dùng thử mà nhà phát hành cung cấp","Tự viết một chương trình máy tính của riêng mình"],"a":"Cài đặt và sử dụng phần mềm thương mại khi chưa mua bản quyền và không được nhà phát hành cho phép","h":"Phần mềm thương mại được bảo hộ quyền tác giả như các sản phẩm trí tuệ khác.","e":"Phần mềm là sản phẩm trí tuệ được pháp luật bảo hộ; sử dụng phần mềm thương mại mà không có bản quyền là hành vi vi phạm bản quyền.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi lấy một đoạn văn hoặc hình ảnh trên Internet đưa vào bài làm của mình, em nên làm gì cho đúng?","o":["Xóa tên tác giả để bài làm trông như của mình","Cứ sử dụng thoải mái vì đã đăng lên mạng là của chung","Chỉ cần không ai phát hiện là được","Ghi rõ nguồn trích dẫn và chỉ sử dụng trong phạm vi được phép"],"a":"Ghi rõ nguồn trích dẫn và chỉ sử dụng trong phạm vi được phép","h":"Tôn trọng quyền tác giả bắt đầu từ việc ghi nguồn khi trích dẫn.","e":"Trích dẫn nội dung của người khác phải ghi rõ nguồn và tuân thủ phạm vi sử dụng cho phép; tự nhận là của mình là vi phạm đạo đức và bản quyền.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Hành vi nào thể hiện ứng xử có văn hóa trên môi trường mạng?","o":["Đăng ảnh của người khác lên mạng khi chưa được đồng ý","Tôn trọng người khác, tranh luận bằng lời lẽ lịch sự, không xúc phạm","Bình luận bằng những lời lẽ kích động cho vui","Chia sẻ mọi thông tin nhìn thấy mà không cần kiểm chứng"],"a":"Tôn trọng người khác, tranh luận bằng lời lẽ lịch sự, không xúc phạm","h":"Ứng xử trên mạng cũng cần tuân theo các chuẩn mực như ngoài đời thật.","e":"Ứng xử có văn hóa trên mạng là tôn trọng người khác, giao tiếp lịch sự và có trách nhiệm với thông tin mình đăng tải, chia sẻ.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Việc tự ý chia sẻ thông tin cá nhân của người khác lên mạng xã hội khi chưa được người đó đồng ý là hành vi như thế nào?","o":["Hoàn toàn bình thường, ai cũng làm","Chỉ sai khi gây ra hậu quả rất lớn","Xâm phạm quyền riêng tư của người khác và có thể vi phạm pháp luật","Được phép nếu người đó là bạn bè của mình"],"a":"Xâm phạm quyền riêng tư của người khác và có thể vi phạm pháp luật","h":"Thông tin cá nhân thuộc về chính chủ nhân của nó.","e":"Thông tin cá nhân được pháp luật bảo vệ; tự ý công khai thông tin của người khác là xâm phạm quyền riêng tư và có thể bị xử lí theo pháp luật.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Nhận định nào đúng về phần mềm mã nguồn mở?","o":["Người dùng được sử dụng, sao chép và chỉnh sửa phần mềm theo các điều kiện của giấy phép đi kèm","Mã nguồn mở nghĩa là không có bản quyền, ai muốn làm gì cũng được","Phần mềm mã nguồn mở chỉ được xem mã nguồn chứ không được sử dụng","Phần mềm mã nguồn mở phải trả phí như phần mềm thương mại"],"a":"Người dùng được sử dụng, sao chép và chỉnh sửa phần mềm theo các điều kiện của giấy phép đi kèm","h":"Mã nguồn mở vẫn đi kèm một giấy phép sử dụng cụ thể.","e":"Phần mềm mã nguồn mở cho phép dùng, sao chép, chỉnh sửa nhưng vẫn phải tuân theo điều kiện của giấy phép kèm theo, chứ không phải không có bản quyền.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Em nhận được tin nhắn từ một người lạ tự xưng là quản trị viên, yêu cầu cung cấp mật khẩu tài khoản học trực tuyến. Em nên làm gì?","o":["Cung cấp ngay vì đó là quản trị viên","Chỉ gửi một nửa mật khẩu cho an toàn","Đổi mật khẩu mới rồi gửi cho người đó","Không cung cấp, vì đây có thể là hành vi lừa đảo nhằm chiếm đoạt tài khoản"],"a":"Không cung cấp, vì đây có thể là hành vi lừa đảo nhằm chiếm đoạt tài khoản","h":"Mật khẩu là thông tin bí mật, không ai được quyền hỏi xin.","e":"Quản trị viên thật không bao giờ yêu cầu người dùng cung cấp mật khẩu; những tin nhắn như vậy thường là lừa đảo để chiếm đoạt tài khoản.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong học tập, phần mềm mô phỏng được sử dụng chủ yếu để làm gì?","o":["Soạn thảo văn bản và trình bày bài viết","Nghe nhạc và xem phim giải trí","Mô hình hóa hiện tượng, quá trình để quan sát và làm thí nghiệm ảo thay cho thí nghiệm thật khó thực hiện hoặc nguy hiểm","Chỉnh sửa ảnh và thiết kế đồ họa"],"a":"Mô hình hóa hiện tượng, quá trình để quan sát và làm thí nghiệm ảo thay cho thí nghiệm thật khó thực hiện hoặc nguy hiểm","h":"Có những hiện tượng không thể quan sát trực tiếp bằng mắt hoặc bằng thí nghiệm thật trong lớp học.","e":"Phần mềm mô phỏng tái hiện các hiện tượng, quá trình trên máy tính, giúp học sinh quan sát và thí nghiệm ảo an toàn, kể cả với hiện tượng khó hoặc nguy hiểm ngoài thực tế.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Lợi ích nổi bật của việc làm thí nghiệm bằng phần mềm mô phỏng là gì?","o":["An toàn, tiết kiệm chi phí và có thể lặp lại nhiều lần, thay đổi thông số dễ dàng","Thay thế hoàn toàn được mọi thí nghiệm thật trong thực tế","Từ nay không cần mua sắm thiết bị thí nghiệm thật nữa","Kết quả mô phỏng hiển nhiên đúng nên không cần kiểm chứng"],"a":"An toàn, tiết kiệm chi phí và có thể lặp lại nhiều lần, thay đổi thông số dễ dàng","h":"Thí nghiệm ảo có những ưu điểm mà thí nghiệm thật khó có được về chi phí và sự an toàn.","e":"Thí nghiệm bằng mô phỏng an toàn, ít tốn kém, dễ lặp lại và dễ thay đổi thông số; tuy vậy nó hỗ trợ chứ không thay thế hoàn toàn thí nghiệm thật.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi dùng phần mềm mô phỏng để khám phá một hiện tượng, cách làm nào giúp rút ra kết luận đúng đắn nhất?","o":["Chỉ chạy mô phỏng đúng một lần rồi kết luận ngay","Thay đổi từng thông số đầu vào một cách có chủ đích, quan sát và ghi lại sự thay đổi của kết quả","Thay đổi tất cả các thông số cùng một lúc cho nhanh","Không cần ghi chép, chỉ cần nhìn qua kết quả"],"a":"Thay đổi từng thông số đầu vào một cách có chủ đích, quan sát và ghi lại sự thay đổi của kết quả","h":"Muốn biết một yếu tố ảnh hưởng thế nào, phải tách nó ra để quan sát riêng.","e":"Thay đổi từng thông số và ghi lại kết quả giúp xác định rõ ảnh hưởng của từng yếu tố lên hiện tượng, từ đó rút ra kết luận chính xác.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Ví dụ nào dưới đây là ứng dụng của phần mềm mô phỏng trong học tập?","o":["Phần mềm soạn thảo văn bản","Phần mềm trình chiếu bài giảng","Phần mềm phát nhạc trực tuyến","Mô phỏng hệ Mặt Trời, thí nghiệm ảo về mạch điện trên máy tính"],"a":"Mô phỏng hệ Mặt Trời, thí nghiệm ảo về mạch điện trên máy tính","h":"Phần mềm mô phỏng tái hiện lại một hiện tượng hoặc hệ thống trong thực tế.","e":"Mô phỏng hệ Mặt Trời hay thí nghiệm ảo về mạch điện là những ứng dụng điển hình của phần mềm mô phỏng trong học tập các môn khoa học.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong bảng tính, hàm SUMIF được dùng để làm gì?","o":["Tính tổng các ô thỏa mãn một điều kiện cho trước","Đếm số ô có chứa dữ liệu","Tính giá trị trung bình của một vùng dữ liệu","Sắp xếp dữ liệu theo thứ tự tăng dần"],"a":"Tính tổng các ô thỏa mãn một điều kiện cho trước","h":"Chữ IF trong tên hàm gợi ý về điều kiện.","e":"SUMIF tính tổng chỉ với những ô thỏa mãn điều kiện đặt ra, ví dụ tổng tiền hàng của riêng một loại mặt hàng.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong bảng tính, công thức =COUNTIF(B2:B10,\">5\") cho kết quả là gì?","o":["Tổng của tất cả các ô có giá trị lớn hơn 5","Số ô còn trống trong vùng B2:B10","Số ô trong vùng B2:B10 có giá trị lớn hơn 5","Giá trị lớn nhất trong vùng B2:B10"],"a":"Số ô trong vùng B2:B10 có giá trị lớn hơn 5","h":"COUNT là đếm, khác với SUM là tính tổng.","e":"COUNTIF đếm số ô thỏa mãn điều kiện; công thức trên đếm số ô trong vùng B2:B10 có giá trị lớn hơn 5.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Trong bảng tính, địa chỉ hỗn hợp như $A1 hoặc A$1 có ý nghĩa gì khi sao chép công thức?","o":["Ô đó chứa giá trị tiền tệ nên phải có dấu $","Ô đó đã bị khóa, không ai sửa được nội dung","Đó là dấu hiệu công thức bị lỗi","Phần có dấu $ (cột hoặc hàng) được cố định, phần không có dấu $ thay đổi tương đối khi sao chép công thức"],"a":"Phần có dấu $ (cột hoặc hàng) được cố định, phần không có dấu $ thay đổi tương đối khi sao chép công thức","h":"Địa chỉ hỗn hợp là sự kết hợp giữa địa chỉ tuyệt đối và địa chỉ tương đối.","e":"Trong địa chỉ hỗn hợp, thành phần đứng sau dấu $ (tên cột hoặc số hàng) được giữ cố định khi sao chép, thành phần còn lại thay đổi theo vị trí mới.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Bảng điểm của lớp có hàng chục học sinh. Muốn xem nhanh chỉ những học sinh có điểm từ 8 trở lên, em nên dùng tính năng nào của bảng tính?","o":["Sắp xếp (Sort) toàn bộ bảng theo thứ tự giảm dần","Lọc dữ liệu (Filter) theo điều kiện điểm lớn hơn hoặc bằng 8","Đổi màu chữ của các dòng điểm cao","Ẩn bớt các cột không cần thiết"],"a":"Lọc dữ liệu (Filter) theo điều kiện điểm lớn hơn hoặc bằng 8","h":"Ta chỉ muốn tạm thời nhìn thấy các dòng thỏa mãn điều kiện, các dòng khác ẩn đi.","e":"Tính năng lọc dữ liệu cho phép chỉ hiển thị những dòng thỏa mãn điều kiện (điểm ≥ 8) và tạm ẩn các dòng còn lại mà không xóa dữ liệu.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong bảng tính tiền bán hàng, đơn giá chung được ghi tại ô B2 và công thức tính tiền cho từng mặt hàng phải nhân với ô này. Khi sao chép công thức xuống nhiều hàng, vì sao nên viết địa chỉ đơn giá là $B$2?","o":["Để khi sao chép công thức, địa chỉ ô đơn giá vẫn cố định tại B2, không bị trôi theo hàng","Để công thức trông đẹp và chuyên nghiệp hơn","Để ô B2 không bao giờ bị xóa mất","Để bảng tính tính toán nhanh hơn"],"a":"Để khi sao chép công thức, địa chỉ ô đơn giá vẫn cố định tại B2, không bị trôi theo hàng","h":"Địa chỉ tương đối sẽ tự thay đổi khi công thức được sao chép sang ô khác.","e":"Địa chỉ tuyệt đối $B$2 giữ nguyên tham chiếu tới ô đơn giá khi sao chép công thức, tránh việc địa chỉ bị trôi thành B3, B4... gây sai kết quả.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Tác động tích cực nào của công nghệ thông tin đối với đời sống xã hội là rõ rệt nhất?","o":["Con người không cần học tập, lao động nữa","Máy tính sẽ thay thế hoàn toàn con người trong mọi công việc","Giúp học tập, làm việc, liên lạc và tiếp cận thông tin trở nên nhanh chóng, thuận tiện","Chỉ giúp ích cho việc chơi trò chơi điện tử"],"a":"Giúp học tập, làm việc, liên lạc và tiếp cận thông tin trở nên nhanh chóng, thuận tiện","h":"Hãy nhớ lại những việc em làm hằng ngày nhờ có điện thoại và Internet.","e":"Công nghệ thông tin giúp con người học tập, làm việc, liên lạc và khai thác thông tin hiệu quả hơn, tác động tích cực tới mọi mặt của đời sống xã hội.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Mặt trái của công nghệ thông tin mà học sinh cần cảnh giác là gì?","o":["Sử dụng máy tính một lần là hỏng mắt ngay","Công nghệ thông tin hoàn toàn không có mặt trái nào","Chỉ người lớn mới bị ảnh hưởng bởi mặt trái của Internet","Nguy cơ nghiện Internet, lộ thông tin cá nhân và tiếp xúc với nội dung xấu nếu sử dụng thiếu kiểm soát"],"a":"Nguy cơ nghiện Internet, lộ thông tin cá nhân và tiếp xúc với nội dung xấu nếu sử dụng thiếu kiểm soát","h":"Mặt trái thường đến từ cách sử dụng thiếu kiểm soát, không phải từ bản thân công nghệ.","e":"Lạm dụng Internet có thể gây nghiện, rò rỉ thông tin cá nhân và tiếp xúc nội dung độc hại; người dùng cần sử dụng công nghệ một cách chủ động, có kiểm soát.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Nhóm nghề nghiệp nào dưới đây thuộc lĩnh vực công nghệ thông tin?","o":["Thợ sửa chữa xe máy, thợ điện dân dụng","Lập trình viên, kĩ sư phần mềm, quản trị mạng","Đầu bếp, nhân viên phục vụ nhà hàng","Bác sĩ phẫu thuật, y tá bệnh viện"],"a":"Lập trình viên, kĩ sư phần mềm, quản trị mạng","h":"Đó là những nghề làm việc trực tiếp với phần mềm, hệ thống máy tính và mạng.","e":"Lập trình viên, kĩ sư phần mềm và quản trị mạng là những nghề tiêu biểu của lĩnh vực công nghệ thông tin, đang có nhu cầu nhân lực lớn.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Webcam (camera gắn với máy tính) có chức năng chính là gì?","o":["Thu hình ảnh và đưa hình ảnh vào máy tính","Phát âm thanh ra môi trường bên ngoài","In văn bản và hình ảnh ra giấy","Lưu trữ dữ liệu lâu dài cho máy tính"],"a":"Thu hình ảnh và đưa hình ảnh vào máy tính","h":"Hãy nghĩ xem webcam giúp đưa thông tin dạng gì vào máy tính.","e":"Webcam là thiết bị vào: nó thu hình ảnh (và chuyển động) từ bên ngoài rồi đưa vào máy tính, ví dụ khi học trực tuyến hay gọi video.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Bộ xử lí trung tâm (CPU) thường được ví với bộ phận nào của con người, vì nó điều khiển và xử lí mọi hoạt động của máy tính?","o":["Đôi tay","Bộ não","Đôi mắt","Trái tim"],"a":"Bộ não","h":"Bộ phận nào của con người điều khiển toàn bộ hoạt động của cơ thể?","e":"CPU được ví như bộ não của máy tính vì nó tiếp nhận, xử lí thông tin và điều khiển các bộ phận khác hoạt động nhịp nhàng.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Muốn đưa một bức ảnh chụp trên giấy vào máy tính để lưu trữ và chỉnh sửa, em nên dùng thiết bị nào?","o":["Loa","Máy in","Máy quét (scanner)","Màn hình"],"a":"Máy quét (scanner)","h":"Cần một thiết bị vào có khả năng 'đọc' hình ảnh từ trên giấy.","e":"Máy quét là thiết bị vào dùng để quét văn bản, hình ảnh trên giấy và chuyển thành dữ liệu đưa vào máy tính.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi tắt máy tính, dữ liệu đang lưu trong bộ phận nào sau đây sẽ bị mất?","o":["Ổ đĩa cứng (HDD hoặc SSD)","Đĩa CD, DVD","Thẻ nhớ, USB","Bộ nhớ trong (RAM)"],"a":"Bộ nhớ trong (RAM)","h":"Bộ nhớ trong chỉ lưu tạm dữ liệu khi máy đang hoạt động.","e":"Bộ nhớ trong (RAM) chỉ lưu dữ liệu tạm thời khi máy đang bật; khi tắt máy, dữ liệu trong RAM bị mất. Muốn giữ lâu dài phải lưu vào bộ nhớ ngoài như ổ đĩa cứng, USB.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Một hệ thống máy tính muốn hoạt động được cần có hai thành phần chính nào?","o":["Phần cứng và phần mềm","Màn hình và bàn phím","Chuột và loa","Máy in và máy quét"],"a":"Phần cứng và phần mềm","h":"Một thành phần là các thiết bị nhìn thấy, sờ được; thành phần còn lại là các chương trình.","e":"Máy tính là một hệ thống gồm phần cứng (các thiết bị vật lí) và phần mềm (các chương trình). Thiếu phần mềm, phần cứng không thể hoạt động được.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong các phần mềm sau, phần mềm nào là phần mềm hệ thống?","o":["Phần mềm vẽ tranh","Hệ điều hành Windows","Trò chơi điện tử","Phần mềm soạn thảo văn bản"],"a":"Hệ điều hành Windows","h":"Phần mềm hệ thống quản lí và điều khiển toàn bộ máy tính, các phần mềm khác chạy trên nền của nó.","e":"Hệ điều hành (như Windows) là phần mềm hệ thống: nó quản lí phần cứng và điều phối mọi hoạt động của máy tính. Các phần mềm còn lại là phần mềm ứng dụng phục vụ công việc cụ thể.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Trong một mạng máy tính, máy chủ (server) có vai trò gì?","o":["Là máy tính yếu nhất trong mạng","Chỉ dùng để chơi trò chơi điện tử","Cung cấp dịch vụ, dữ liệu và tài nguyên cho các máy khác trong mạng","Không kết nối với bất kì máy nào khác"],"a":"Cung cấp dịch vụ, dữ liệu và tài nguyên cho các máy khác trong mạng","h":"Tên gọi 'máy chủ' gợi ý vai trò phục vụ các máy còn lại.","e":"Máy chủ là máy tính có cấu hình mạnh, chuyên cung cấp dịch vụ và tài nguyên (dữ liệu, trang web, thư điện tử...) cho các máy khách (client) trong mạng.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Địa chỉ thư điện tử (email) có đặc điểm nào sau đây?","o":["Luôn bắt đầu bằng cụm www","Gồm hai phần ngăn cách nhau bởi dấu #","Không chứa kí tự @","Gồm tên người dùng và tên miền, ngăn cách nhau bởi kí tự @"],"a":"Gồm tên người dùng và tên miền, ngăn cách nhau bởi kí tự @","h":"Hãy nhớ lại dạng của một địa chỉ email mà em từng thấy, ví dụ hocsinh@gmail.com.","e":"Địa chỉ email có dạng: tên người dùng@tên miền, ví dụ hocsinh@gmail.com. Kí tự @ là dấu hiệu không thể thiếu của địa chỉ thư điện tử.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Để truy cập và xem các trang web trên Internet, em cần dùng loại phần mềm nào?","o":["Trình duyệt web (ví dụ: Chrome, Cốc Cốc)","Phần mềm nén và giải nén tệp","Phần mềm diệt virus","Phần mềm gõ tiếng Việt"],"a":"Trình duyệt web (ví dụ: Chrome, Cốc Cốc)","h":"Em vẫn thường mở phần mềm này mỗi khi vào đọc tin tức hay tra cứu trên mạng.","e":"Trình duyệt web là phần mềm giúp người dùng truy cập, hiển thị và tương tác với các trang web trên Internet, ví dụ Chrome, Cốc Cốc, Firefox.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Địa chỉ của một trang web (ví dụ: www.vietnamnet.vn) có tác dụng gì?","o":["Giúp máy tính chạy nhanh hơn","Giúp xác định và truy cập đúng trang web đó trên Internet","Giúp lưu trữ tệp tin trong máy tính","Giúp kết nối chuột với máy tính"],"a":"Giúp xác định và truy cập đúng trang web đó trên Internet","h":"Tương tự địa chỉ nhà giúp ta tìm đến đúng một ngôi nhà.","e":"Mỗi trang web có một địa chỉ riêng. Gõ đúng địa chỉ vào trình duyệt, em sẽ truy cập được đúng trang web mình cần.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Lợi ích nào sau đây là lợi ích của mạng máy tính?","o":["Làm cho máy tính trở nên nặng hơn","Chỉ dùng để trang trí phòng máy","Giúp các máy tính chia sẻ dữ liệu và dùng chung thiết bị, ví dụ dùng chung một máy in","Thay thế hoàn toàn con người trong mọi công việc"],"a":"Giúp các máy tính chia sẻ dữ liệu và dùng chung thiết bị, ví dụ dùng chung một máy in","h":"Khi nhiều máy nối với nhau, chúng có thể dùng chung những gì?","e":"Nhờ nối mạng, các máy tính có thể trao đổi, chia sẻ dữ liệu và dùng chung tài nguyên như máy in, máy quét, giúp tiết kiệm và thuận tiện.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Bạn An pha một ấm trà theo các bước: đun sôi nước; cho trà vào ấm; rót nước sôi vào ấm; chờ vài phút; rót trà ra cốc. Việc thực hiện công việc theo từng bước như vậy là ví dụ về khái niệm nào?","o":["Phần cứng","Mạng máy tính","Dữ liệu","Thuật toán"],"a":"Thuật toán","h":"Khái niệm chỉ một dãy các bước được sắp xếp theo trình tự để hoàn thành một công việc.","e":"Thuật toán là dãy các chỉ dẫn (các bước) được sắp xếp theo trình tự xác định để giải quyết một vấn đề hay thực hiện một công việc, giống như các bước pha trà.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Cho bài toán: 'Biết chiều dài và chiều rộng của một hình chữ nhật, hãy tính chu vi của hình chữ nhật đó'. Đầu vào của bài toán này là gì?","o":["Chu vi của hình chữ nhật","Chiều dài và chiều rộng của hình chữ nhật","Công thức tính chu vi","Chiếc máy tính dùng để tính"],"a":"Chiều dài và chiều rộng của hình chữ nhật","h":"Đầu vào là những dữ kiện đã cho, cần có trước khi bắt đầu giải bài toán.","e":"Đầu vào là những thông tin đã biết ban đầu: chiều dài và chiều rộng. Chu vi là kết quả cần tìm, tức là đầu ra của bài toán.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Câu nói: 'Nếu trời mưa thì mang theo ô, còn nếu không mưa thì không cần mang' thể hiện cấu trúc điều khiển nào trong thuật toán?","o":["Cấu trúc rẽ nhánh","Cấu trúc lặp","Cấu trúc tuần tự","Không thuộc cấu trúc nào"],"a":"Cấu trúc rẽ nhánh","h":"Việc làm tiếp theo phụ thuộc vào việc kiểm tra một điều kiện đúng hay sai.","e":"Đây là cấu trúc rẽ nhánh: tùy thuộc điều kiện 'trời mưa' đúng hay sai mà ta chọn thực hiện hành động khác nhau.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Việc 'gõ cửa, nếu chưa có ai ra mở thì gõ lại, cứ thế cho đến khi có người mở cửa' thể hiện cấu trúc điều khiển nào trong thuật toán?","o":["Cấu trúc tuần tự","Cấu trúc rẽ nhánh","Cấu trúc lặp","Cấu trúc lưu trữ"],"a":"Cấu trúc lặp","h":"Một hành động được thực hiện nhiều lần cho đến khi đạt một điều kiện nào đó.","e":"Hành động gõ cửa được thực hiện lại nhiều lần cho đến khi có người mở cửa — đó là cấu trúc lặp, với số lần lặp chưa biết trước và dừng khi điều kiện thỏa mãn.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Vì sao các bước trong một thuật toán phải được mô tả rõ ràng, chính xác và xác định?","o":["Để thuật toán trông dài và phức tạp hơn","Để trang trí cho bài làm thêm đẹp","Để máy tính luôn chạy nhanh hơn","Để người hoặc máy thực hiện đúng theo, không gây hiểu nhầm và cho kết quả như mong muốn"],"a":"Để người hoặc máy thực hiện đúng theo, không gây hiểu nhầm và cho kết quả như mong muốn","h":"Nếu một bước được viết mơ hồ, người thực hiện có thể hiểu theo nhiều cách khác nhau.","e":"Mỗi bước của thuật toán phải rõ ràng, chính xác để người (hoặc máy) thực hiện hiểu đúng và làm đúng, tránh hiểu nhầm dẫn đến kết quả sai.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Cách đặt tên tệp nào sau đây giúp em dễ tìm lại và hiểu ngay nội dung của tệp nhất?","o":["BaiTapToan_Tuan5.docx","abcxyz.docx","tai lieu 1 2 3.docx","khongtenmoi.docx"],"a":"BaiTapToan_Tuan5.docx","h":"Tên tệp nên gợi nhớ môn học, nội dung và thời điểm của tệp.","e":"Tên tệp 'BaiTapToan_Tuan5.docx' cho biết rõ môn học và nội dung (bài tập Toán tuần 5) nên dễ tìm và dễ nhận biết; các tên còn lại không mang ý nghĩa rõ ràng.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Tệp (file) và thư mục (folder) khác nhau ở điểm cơ bản nào?","o":["Tệp và thư mục hoàn toàn giống nhau","Thư mục là nơi chứa các tệp và thư mục khác, còn tệp là một đơn vị lưu trữ dữ liệu như văn bản, hình ảnh, âm thanh","Tệp có thể chứa thư mục, còn thư mục thì không chứa được gì","Thư mục chỉ để trang trí, không có tác dụng lưu trữ"],"a":"Thư mục là nơi chứa các tệp và thư mục khác, còn tệp là một đơn vị lưu trữ dữ liệu như văn bản, hình ảnh, âm thanh","h":"Hãy liên tưởng thư mục như một ngăn tủ, còn tệp như những đồ vật đặt trong ngăn tủ đó.","e":"Thư mục dùng để tổ chức, chứa các tệp và các thư mục con. Tệp là đơn vị lưu trữ một dữ liệu cụ thể, ví dụ một văn bản, một bức ảnh hay một bản nhạc.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Muốn chèn một hình ảnh đang lưu trong máy tính vào văn bản, em thường dùng lệnh nào?","o":["Home → Paste","File → Save","Insert → Pictures (Chèn → Ảnh)","View → Print Layout"],"a":"Insert → Pictures (Chèn → Ảnh)","h":"Lệnh nằm trong thẻ chuyên dùng để chèn thêm các đối tượng vào văn bản.","e":"Để chèn ảnh từ máy tính vào văn bản, em chọn thẻ Insert (Chèn) rồi chọn Pictures (Ảnh), sau đó chọn tệp ảnh cần chèn.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Sau khi làm xong một bài trình chiếu, muốn lưu bài thành một tệp trong máy tính để lần sau mở lại, em làm thế nào?","o":["Tắt máy tính luôn sau khi trình chiếu xong","Chụp ảnh màn hình của từng trang chiếu","In bài trình chiếu ra giấy","Chọn File → Save (Lưu), đặt tên tệp và chọn thư mục để lưu"],"a":"Chọn File → Save (Lưu), đặt tên tệp và chọn thư mục để lưu","h":"Cần dùng lệnh lưu trong phần mềm và đặt một cái tên cho tệp bài trình chiếu.","e":"Để lưu bài trình chiếu thành tệp, em chọn File → Save (hoặc nhấn Ctrl + S), đặt tên tệp và chọn thư mục lưu; lần sau mở tệp đó ra là tiếp tục xem và chỉnh sửa được.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong bảng tính, muốn tính tổng các số trong vùng A1:A10, em dùng công thức nào?","o":["=SUM(A1:A10)","=SUM(A1+A10)","=TOTAL(A1:A10)","=A1:A10"],"a":"=SUM(A1:A10)","h":"Hàm tính tổng trong bảng tính có tên tiếng Anh mang nghĩa là 'tổng'.","e":"Hàm SUM dùng để tính tổng các số trong một vùng ô; =SUM(A1:A10) tính tổng tất cả các số từ ô A1 đến ô A10.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong bảng tính, khi sắp xếp dữ liệu theo thứ tự giảm dần, các giá trị sẽ được xếp như thế nào?","o":["Từ nhỏ đến lớn","Từ lớn đến nhỏ","Theo thứ tự người nhập dữ liệu","Ngẫu nhiên, không theo quy tắc nào"],"a":"Từ lớn đến nhỏ","h":"'Giảm dần' có thể hình dung như đi từ cao xuống thấp.","e":"Sắp xếp giảm dần xếp các giá trị từ lớn nhất xuống nhỏ nhất; ngược lại, sắp xếp tăng dần là từ nhỏ đến lớn.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong bảng tính, số 1500000 khi được định dạng có dấu phân cách hàng nghìn sẽ hiển thị như thế nào?","o":["1500000,0","1.500.000.000","1.500.000","1500.000"],"a":"1.500.000","h":"Cứ mỗi nhóm ba chữ số, tính từ phải sang trái, lại có một dấu phân cách.","e":"Dấu phân cách hàng nghìn giúp đọc số lớn dễ hơn: 1500000 hiển thị thành 1.500.000, giá trị của số không thay đổi.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong bảng tính, công thức tại ô B2 là =$A$1+C2. Khi sao chép công thức này xuống ô B3, công thức ở ô B3 sẽ là gì?","o":["=$A$2+C3","=A1+C3","=$A$1+C2","=$A$1+C3"],"a":"=$A$1+C3","h":"Phần địa chỉ có dấu $ sẽ giữ nguyên khi sao chép; phần không có dấu $ thay đổi theo vị trí mới.","e":"$A$1 là địa chỉ tuyệt đối nên không đổi khi sao chép; C2 là địa chỉ tương đối, khi xuống một hàng sẽ thành C3. Vậy công thức ở B3 là =$A$1+C3.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Trong bảng tính, khi chèn thêm một cột trống mới vào bên trái cột C, điều gì sẽ xảy ra?","o":["Một cột trống được chèn vào, các cột cũ từ C trở đi dịch sang phải","Cột C bị xoá và thay bằng cột trống","Một cột trống được chèn vào phía bên phải cột C","Toàn bộ dữ liệu trong bảng tính bị xoá"],"a":"Một cột trống được chèn vào, các cột cũ từ C trở đi dịch sang phải","h":"Hãy nhớ lại thao tác chèn thêm hàng mà em đã học và áp dụng tương tự cho cột.","e":"Chèn cột mới không làm mất dữ liệu: cột trống xuất hiện tại vị trí chèn, các cột phía sau dịch sang phải một vị trí.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong bảng tính, em chỉ muốn in vùng dữ liệu A1:E20 mà không in phần còn lại của trang tính. Em nên làm gì?","o":["Xoá tạm phần dữ liệu còn lại rồi mới in","Chọn vùng A1:E20 và đặt làm vùng in (Print Area)","In cả trang rồi cắt bỏ phần thừa","Sao chép vùng đó sang một tệp khác rồi in tệp đó"],"a":"Chọn vùng A1:E20 và đặt làm vùng in (Print Area)","h":"Phần mềm bảng tính có một chức năng riêng để giới hạn phần dữ liệu được in ra giấy.","e":"Đặt vùng in (Print Area) giúp chỉ in đúng phần dữ liệu đã chọn, không cần xoá hay di chuyển phần còn lại của trang tính.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Thuật toán cần in ra màn hình câu 'Xin chào' đúng 10 lần. Thuật toán nên dùng cấu trúc nào?","o":["Cấu trúc tuần tự với một lệnh in duy nhất","Cấu trúc rẽ nhánh dạng thiếu","Cấu trúc lặp với số lần lặp biết trước","Cấu trúc lặp kiểm tra điều kiện không xác định"],"a":"Cấu trúc lặp với số lần lặp biết trước","h":"Khi đã biết chắc chắn phải thực hiện lại một việc bao nhiêu lần, em dùng dạng lặp nào?","e":"Vì số lần in đã biết trước là 10, ta dùng cấu trúc lặp với số lần biết trước và đặt lệnh in bên trong vòng lặp.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong thuật toán, biến được dùng để làm gì?","o":["Trang trí để thuật toán trông đẹp hơn","Lưu trữ một giá trị cố định, không bao giờ thay đổi","Đặt tên cho các bước của thuật toán","Lưu trữ dữ liệu và giá trị của nó có thể thay đổi trong quá trình thực hiện thuật toán"],"a":"Lưu trữ dữ liệu và giá trị của nó có thể thay đổi trong quá trình thực hiện thuật toán","h":"Tên gọi 'biến' gợi ý điều gì về giá trị được lưu trong đó?","e":"Biến là nơi lưu trữ dữ liệu trong quá trình thực hiện thuật toán; giá trị của biến có thể thay đổi khi thuật toán chạy.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Mô tả thuật toán bằng cách liệt kê các bước có nghĩa là gì?","o":["Dùng ngôn ngữ tự nhiên viết lần lượt từng bước thực hiện của thuật toán","Vẽ các hình khối và mũi tên nối với nhau","Viết thuật toán bằng một ngôn ngữ lập trình","Dùng bảng số liệu để ghi lại kết quả"],"a":"Dùng ngôn ngữ tự nhiên viết lần lượt từng bước thực hiện của thuật toán","h":"Ngoài cách dùng sơ đồ khối, còn cách mô tả nào chỉ dùng lời văn theo thứ tự các bước?","e":"Liệt kê các bước là cách mô tả thuật toán bằng ngôn ngữ tự nhiên theo đúng trình tự thực hiện; cách dùng các hình khối và mũi tên là mô tả bằng sơ đồ khối.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Ý tưởng của thuật toán tìm số lớn nhất trong một dãy số là gì?","o":["Cộng tất cả các số trong dãy rồi chia cho số lượng số","Giả sử số đầu tiên là lớn nhất, rồi lần lượt so sánh với các số còn lại, gặp số lớn hơn thì thay thế","Sắp xếp dãy số rồi lấy số nằm ở giữa dãy","Nhân tất cả các số trong dãy với nhau"],"a":"Giả sử số đầu tiên là lớn nhất, rồi lần lượt so sánh với các số còn lại, gặp số lớn hơn thì thay thế","h":"Hãy tưởng tượng em lần lượt xét từng số và so với số lớn nhất đang ghi nhớ trong đầu.","e":"Thuật toán dùng một biến ghi nhớ số lớn nhất, khởi đầu bằng số đầu tiên rồi so sánh lần lượt với từng số còn lại; nếu gặp số lớn hơn thì cập nhật lại biến đó.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Nhận định nào đúng về bộ nhớ RAM trong máy tính?","o":["RAM lưu trữ dữ liệu lâu dài kể cả khi đã tắt máy","RAM là thiết bị lưu trữ ngoài của máy tính","RAM là bộ nhớ trong, dữ liệu trong RAM bị mất khi mất điện hoặc tắt máy","RAM chứa chương trình giúp khởi động máy tính"],"a":"RAM là bộ nhớ trong, dữ liệu trong RAM bị mất khi mất điện hoặc tắt máy","h":"RAM chỉ hoạt động được khi máy tính đang có điện và đang bật.","e":"RAM là bộ nhớ trong, dùng để lưu tạm dữ liệu trong lúc máy hoạt động; khi mất điện hoặc tắt máy, toàn bộ dữ liệu trong RAM bị xoá.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Bộ nhớ ROM trong máy tính có vai trò gì?","o":["Lưu trữ ảnh và video của người dùng","Chứa dữ liệu tạm thời khi mở phần mềm","Làm tăng dung lượng lưu trữ cho máy tính","Chứa các thông tin và chương trình cơ bản giúp khởi động máy tính"],"a":"Chứa các thông tin và chương trình cơ bản giúp khởi động máy tính","h":"ROM chứa thông tin có sẵn từ nhà sản xuất, phục vụ ngay từ lúc máy vừa được bật lên.","e":"ROM chứa sẵn các chương trình cơ bản do nhà sản xuất nạp vào, giúp máy tính thực hiện quá trình khởi động; thông tin trong ROM không bị mất khi tắt máy.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Một thẻ nhớ có dung lượng 64 GB và một thẻ nhớ có dung lượng 16 GB. Thẻ nhớ 64 GB lưu được lượng dữ liệu gấp khoảng mấy lần thẻ nhớ 16 GB?","o":["4 lần","2 lần","8 lần","48 lần"],"a":"4 lần","h":"Lấy dung lượng của thẻ lớn chia cho dung lượng của thẻ nhỏ.","e":"64 : 16 = 4, vậy thẻ nhớ 64 GB lưu được lượng dữ liệu gấp khoảng 4 lần thẻ nhớ 16 GB.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Mật khẩu nào sau đây là mật khẩu mạnh?","o":["12345678","H&c9#mX2!","tenem2012","abcdefgh"],"a":"H&c9#mX2!","h":"Mật khẩu mạnh kết hợp nhiều loại kí tự khác nhau và không đoán được từ thông tin cá nhân.","e":"Mật khẩu mạnh gồm chữ hoa, chữ thường, chữ số và kí tự đặc biệt, đủ dài và không chứa thông tin cá nhân dễ đoán như tên hay năm sinh.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Vì sao không nên dùng chung một mật khẩu cho tất cả các tài khoản?","o":["Vì mỗi tài khoản luôn yêu cầu một định dạng mật khẩu khác nhau","Vì dùng chung mật khẩu khiến máy tính chạy chậm hơn","Vì nếu một tài khoản bị lộ mật khẩu, kẻ xấu có thể đăng nhập vào mọi tài khoản còn lại","Vì mật khẩu dùng chung lâu ngày sẽ tự hết hạn"],"a":"Vì nếu một tài khoản bị lộ mật khẩu, kẻ xấu có thể đăng nhập vào mọi tài khoản còn lại","h":"Hãy nghĩ xem điều gì xảy ra nếu mật khẩu dùng chung đó bị lộ ở một nơi.","e":"Dùng chung một mật khẩu rất nguy hiểm: chỉ cần lộ ở một tài khoản, kẻ xấu sẽ dùng chính mật khẩu đó để thử đăng nhập tất cả tài khoản khác của em.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Em thấy một bức ảnh đẹp trên mạng và muốn đăng lại lên trang mạng xã hội của mình. Cách làm đúng là gì?","o":["Cứ đăng lại, vì ảnh đã đăng lên mạng là của chung mọi người","Tải ảnh về, xoá tên tác giả rồi đăng như ảnh của mình","Chỉnh sửa ảnh đi một chút là ảnh trở thành của mình","Xin phép tác giả, hoặc ghi rõ nguồn và tên tác giả khi đăng lại"],"a":"Xin phép tác giả, hoặc ghi rõ nguồn và tên tác giả khi đăng lại","h":"Bức ảnh là sản phẩm sáng tạo của người khác, cũng giống như bài văn hay bức tranh do chính em làm ra.","e":"Hình ảnh có bản quyền của tác giả; khi đăng lại cần xin phép hoặc ghi rõ nguồn và tên tác giả, không được nhận là của mình.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Xác thực hai lớp (xác thực hai yếu tố) giúp bảo vệ tài khoản như thế nào?","o":["Ngoài mật khẩu, tài khoản còn yêu cầu thêm một mã xác nhận nữa, nên kẻ xấu dù biết mật khẩu cũng khó đăng nhập được","Tự động thay đổi mật khẩu mỗi ngày cho người dùng","Giúp đăng nhập nhanh hơn mà không cần mật khẩu","Lưu mật khẩu vào hai nơi khác nhau để khỏi bị quên"],"a":"Ngoài mật khẩu, tài khoản còn yêu cầu thêm một mã xác nhận nữa, nên kẻ xấu dù biết mật khẩu cũng khó đăng nhập được","h":"'Hai lớp' nghĩa là phải qua hai bước kiểm tra mới vào được tài khoản.","e":"Xác thực hai lớp yêu cầu thêm một mã xác nhận (thường gửi về điện thoại) bên cạnh mật khẩu, nên dù mật khẩu bị lộ, kẻ xấu vẫn khó chiếm được tài khoản.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong phần mềm trình chiếu, ngoài văn bản và hình ảnh, em còn có thể chèn thêm đối tượng nào vào trang chiếu để bài trình bày sinh động hơn?","o":["Chỉ chèn được bảng số liệu","Chèn được âm thanh và video","Không chèn thêm được đối tượng nào khác","Chỉ chèn được các biểu tượng cảm xúc"],"a":"Chèn được âm thanh và video","h":"Trang chiếu còn hỗ trợ các tệp đa phương tiện có tiếng và có chuyển động.","e":"Phần mềm trình chiếu cho phép chèn âm thanh và video vào trang chiếu, giúp bài trình bày trực quan và sinh động hơn.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Mẫu bố cục (layout) của trang chiếu có tác dụng gì?","o":["Quyết định hiệu ứng khi chuyển từ trang này sang trang khác","Tự động viết nội dung cho trang chiếu","Quy định sẵn vị trí sắp xếp của tiêu đề, nội dung và hình ảnh trên trang chiếu","Thay đổi màu nền cho tất cả các trang chiếu"],"a":"Quy định sẵn vị trí sắp xếp của tiêu đề, nội dung và hình ảnh trên trang chiếu","h":"Khi tạo một trang chiếu mới, em thường chọn mẫu đã có sẵn chỗ dành cho tiêu đề và nội dung.","e":"Mẫu bố cục định sẵn cách sắp xếp các thành phần như tiêu đề, văn bản, hình ảnh trên trang chiếu, giúp trình bày nhanh và thống nhất.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Hiệu ứng cho đối tượng khác hiệu ứng chuyển trang trong trình chiếu ở điểm nào?","o":["Hai loại hiệu ứng này hoàn toàn giống nhau","Hiệu ứng cho đối tượng chỉ áp dụng được cho văn bản","Hiệu ứng chuyển trang áp dụng cho từng chữ trong trang chiếu","Hiệu ứng cho đối tượng tác động lên từng đối tượng trong một trang, còn hiệu ứng chuyển trang tác động khi chuyển từ trang này sang trang khác"],"a":"Hiệu ứng cho đối tượng tác động lên từng đối tượng trong một trang, còn hiệu ứng chuyển trang tác động khi chuyển từ trang này sang trang khác","h":"Hãy chú ý phạm vi tác động: bên trong một trang hay giữa hai trang với nhau.","e":"Hiệu ứng cho đối tượng làm từng đối tượng (chữ, hình ảnh) xuất hiện hoặc chuyển động trong trang; hiệu ứng chuyển trang tạo sự chuyển đổi giữa hai trang chiếu liên tiếp.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Xét hàm Python sau:\n\ndef chao(ten):\n    return 'Xin chào ' + ten\n\nTrong hàm trên, từ khóa return có vai trò gì?","o":["Trả về giá trị 'Xin chào ' + ten cho nơi gọi hàm","In giá trị ra màn hình rồi kết thúc chương trình","Khai báo biến ten là biến toàn cục","Bắt đầu một vòng lặp bên trong hàm"],"a":"Trả về giá trị 'Xin chào ' + ten cho nơi gọi hàm","h":"Hãy nghĩ xem khi ta viết x = chao('An') thì biến x nhận được gì.","e":"return gửi giá trị về cho nơi gọi hàm để tiếp tục sử dụng trong chương trình; việc in ra màn hình là nhiệm vụ của print().","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho đoạn chương trình Python:\n\na = [3, 5]\na.append(7)\nprint(a)\n\nKết quả in ra là gì?","o":["[3, 5]","[3, 5, 7]","[7, 3, 5]","[3, 5, 7, 7]"],"a":"[3, 5, 7]","h":"Phương thức append() thêm một phần tử vào cuối danh sách.","e":"append(7) thêm số 7 vào cuối danh sách [3, 5], nên danh sách trở thành [3, 5, 7].","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho đoạn chương trình Python:\n\ndiem = [8, 9, 7, 10, 6]\nprint(len(diem))\n\nKết quả in ra là gì?","o":["40","10","5","4"],"a":"5","h":"len() cho biết số phần tử có trong danh sách, không phải tổng các phần tử.","e":"Danh sách diem có 5 phần tử nên len(diem) bằng 5. (40 là tổng các phần tử, 10 là phần tử lớn nhất — đều không phải đáp án.)","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho đoạn chương trình Python:\n\ntong = 0\nfor x in [2, 4, 6]:\n    tong = tong + x\nprint(tong)\n\nKết quả in ra là gì?","o":["6","8","246","12"],"a":"12","h":"Vòng lặp lấy lần lượt từng phần tử 2, 4, 6 và cộng dồn vào biến tong.","e":"tong thay đổi lần lượt: 0 + 2 = 2, 2 + 4 = 6, 6 + 6 = 12, nên kết quả in ra là 12.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Một chương trình Python chạy được bình thường, không hề báo lỗi, nhưng kết quả tính toán lại sai so với yêu cầu. Đây là loại lỗi nào?","o":["Lỗi logic","Lỗi cú pháp","Lỗi do phần cứng máy tính","Lỗi do mất kết nối mạng"],"a":"Lỗi logic","h":"Nếu viết sai quy tắc của ngôn ngữ, chương trình đã không thể chạy được ngay từ đầu.","e":"Chương trình vẫn chạy nhưng cho kết quả sai nghĩa là cách xử lí, thuật toán chưa đúng — đó là lỗi logic. Lỗi cú pháp sẽ khiến chương trình không chạy được.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong Python, một biến được tạo ra bên trong thân hàm (ví dụ gán x = 5 ở trong hàm) thường có đặc điểm gì?","o":["Tự động dùng chung được ở mọi nơi trong chương trình","Chỉ có hiệu lực bên trong hàm đó, được gọi là biến cục bộ","Không bao giờ thay đổi được giá trị","Luôn nhận giá trị mặc định bằng 0 ở ngoài hàm"],"a":"Chỉ có hiệu lực bên trong hàm đó, được gọi là biến cục bộ","h":"Chữ 'cục bộ' gợi ý phạm vi sử dụng bị giới hạn trong một khu vực nhất định.","e":"Biến tạo trong hàm là biến cục bộ: chỉ tồn tại và dùng được bên trong hàm; khi hàm kết thúc, biến không còn hiệu lực ở bên ngoài.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong cơ sở dữ liệu, 'truy vấn dữ liệu' là hoạt động nào?","o":["Sao chép toàn bộ cơ sở dữ liệu sang một máy khác","Xóa các bản ghi không còn dùng đến","Tìm kiếm và lấy ra những dữ liệu thỏa mãn điều kiện cho trước","Đổi tên các bảng trong cơ sở dữ liệu"],"a":"Tìm kiếm và lấy ra những dữ liệu thỏa mãn điều kiện cho trước","h":"Ví dụ: tìm tất cả học sinh có điểm trung bình từ 8,0 trở lên.","e":"Truy vấn là thao tác khai thác dữ liệu: người dùng đưa ra điều kiện và hệ quản trị CSDL trả về các bản ghi thỏa mãn điều kiện đó.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Khi truy vấn danh sách học sinh, muốn kết quả hiện ra theo thứ tự điểm từ cao xuống thấp, ta cần làm gì?","o":["Xóa bớt các bản ghi có điểm thấp","Đổi khoá chính của bảng thành trường Điểm","Nhập lại toàn bộ dữ liệu theo đúng thứ tự mong muốn","Chỉ định sắp xếp giảm dần theo trường Điểm trong câu truy vấn"],"a":"Chỉ định sắp xếp giảm dần theo trường Điểm trong câu truy vấn","h":"Dữ liệu gốc không cần thay đổi, chỉ cách trình bày kết quả truy vấn thay đổi.","e":"Câu truy vấn có thể kèm yêu cầu sắp xếp tăng dần hoặc giảm dần theo một trường, ví dụ giảm dần theo Điểm, mà không cần sửa dữ liệu gốc.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Một cửa hàng đã đổi giá bán của một mặt hàng nhưng chưa cập nhật vào cơ sở dữ liệu. Hậu quả trực tiếp nhất là gì?","o":["Thông tin lấy ra từ cơ sở dữ liệu không còn đúng với thực tế, gây sai lệch khi bán hàng và thống kê","Toàn bộ cơ sở dữ liệu tự động bị xóa","Máy tính không thể thực hiện truy vấn được nữa","Khoá chính của bảng tự động thay đổi"],"a":"Thông tin lấy ra từ cơ sở dữ liệu không còn đúng với thực tế, gây sai lệch khi bán hàng và thống kê","h":"Cơ sở dữ liệu chỉ hữu ích khi thông tin trong đó phản ánh đúng tình hình hiện tại.","e":"Dữ liệu không được cập nhật kịp thời sẽ trở nên lạc hậu, khiến việc tra cứu giá, bán hàng và lập báo cáo dựa trên đó đều bị sai lệch.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Mã hóa dữ liệu khi truyền qua mạng giúp bảo vệ thông tin chủ yếu vì lí do nào?","o":["Làm cho dữ liệu được truyền đi nhanh hơn","Biến dữ liệu thành dạng khó đọc được nếu không có khóa giải mã, nên kẻ lạ chặn được cũng không hiểu nội dung","Giúp dữ liệu không bao giờ bị mất trên đường truyền","Tự động phát hiện và xóa các thư rác"],"a":"Biến dữ liệu thành dạng khó đọc được nếu không có khóa giải mã, nên kẻ lạ chặn được cũng không hiểu nội dung","h":"Hãy hình dung nội dung được 'khóa' lại trong suốt quá trình truyền đi.","e":"Mã hóa biến dữ liệu thành dạng mật mã; chỉ người có khóa phù hợp mới giải mã được, nhờ đó thông tin được bảo mật khi truyền qua mạng.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"'Phần mềm độc hại' (malware) là tên gọi chung cho nhóm nào sau đây?","o":["Các phần mềm dùng để soạn thảo văn bản và học tập","Các phần mềm miễn phí trên Internet","Virus, sâu máy tính, phần mềm gián điệp và các chương trình gây hại khác","Các phần mềm đã hết hạn bản quyền sử dụng"],"a":"Virus, sâu máy tính, phần mềm gián điệp và các chương trình gây hại khác","h":"Từ 'mal' trong malware bắt nguồn từ tiếng Anh với nghĩa xấu, độc hại.","e":"Malware là thuật ngữ chung chỉ mọi phần mềm được tạo ra để gây hại, phá hoại hệ thống hoặc đánh cắp thông tin, như virus, trojan, spyware.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Vì sao người dùng nên sao lưu (backup) dữ liệu quan trọng một cách định kì?","o":["Để máy tính chạy nhanh hơn","Để tăng dung lượng trống của ổ cứng","Để người khác không xem được dữ liệu","Để có bản dự phòng khôi phục lại khi dữ liệu gốc bị mất, hỏng hoặc bị mã hóa đòi tiền chuộc"],"a":"Để có bản dự phòng khôi phục lại khi dữ liệu gốc bị mất, hỏng hoặc bị mã hóa đòi tiền chuộc","h":"Hãy nghĩ đến tình huống ổ cứng bị hỏng hoặc máy tính nhiễm mã độc.","e":"Sao lưu định kì tạo ra bản sao dự phòng, giúp khôi phục dữ liệu khi xảy ra sự cố như hỏng thiết bị, xóa nhầm hay bị phần mềm mã hóa dữ liệu đòi tiền chuộc (ransomware).","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Dấu hiệu nào sau đây cho thấy một thư điện tử có khả năng là thư lừa đảo (phishing)?","o":["Thư giục giã, dọa khóa tài khoản và yêu cầu bấm vào một liên kết lạ để nhập mật khẩu","Thư có ghi đúng họ tên của người nhận","Thư được gửi đến vào ban ngày","Thư được viết bằng tiếng Việt có đầy đủ dấu"],"a":"Thư giục giã, dọa khóa tài khoản và yêu cầu bấm vào một liên kết lạ để nhập mật khẩu","h":"Kẻ lừa đảo thường tạo cảm giác khẩn cấp để người nhận hành động vội vàng, không kịp suy nghĩ.","e":"Thư phishing thường giả mạo tổ chức uy tín, gây áp lực về thời gian và dẫn người nhận tới trang web giả để đánh cắp mật khẩu, thông tin cá nhân.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Một người chọn mua hàng trên một trang bán hàng trực tuyến, thanh toán bằng thẻ qua mạng và được giao hàng tận nhà. Toàn bộ hoạt động này là ví dụ của khái niệm nào?","o":["Chính phủ điện tử","Thương mại điện tử","Điện toán đám mây","Truyền thông xã hội"],"a":"Thương mại điện tử","h":"Hãy chú ý: việc chọn hàng và thanh toán đều diễn ra qua mạng Internet.","e":"Mua bán hàng hoá, dịch vụ thông qua Internet (chọn hàng, thanh toán trực tuyến, giao nhận hàng) chính là hoạt động thương mại điện tử.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Dịch vụ công trực tuyến (chính phủ điện tử) mang lại lợi ích nào cho người dân?","o":["Người dân phải đến cơ quan nhà nước nhiều lần hơn","Chỉ người dân ở thành phố lớn mới sử dụng được","Làm thủ tục hành chính qua mạng, tiết kiệm thời gian đi lại và chờ đợi","Thay thế hoàn toàn mọi cơ quan nhà nước"],"a":"Làm thủ tục hành chính qua mạng, tiết kiệm thời gian đi lại và chờ đợi","h":"Ví dụ: nộp hồ sơ làm giấy tờ qua Cổng Dịch vụ công Quốc gia ngay tại nhà.","e":"Dịch vụ công trực tuyến cho phép người dân nộp và theo dõi hồ sơ qua mạng, giúp giảm thời gian, chi phí đi lại và tăng tính minh bạch.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Nghề phân tích dữ liệu (khoa học dữ liệu) thuộc nhóm nghề nào và công việc chính là gì?","o":["Nhóm nghề xây dựng; thiết kế bản vẽ các công trình","Nhóm nghề y tế; khám và chữa bệnh cho bệnh nhân","Nhóm nghề nông nghiệp; dự báo năng suất mùa vụ","Nhóm nghề công nghệ thông tin; xử lí, phân tích dữ liệu để rút ra thông tin hỗ trợ việc ra quyết định"],"a":"Nhóm nghề công nghệ thông tin; xử lí, phân tích dữ liệu để rút ra thông tin hỗ trợ việc ra quyết định","h":"Công việc này gắn liền với máy tính, số liệu và các công cụ phân tích hiện đại.","e":"Phân tích dữ liệu/khoa học dữ liệu là nghề CNTT tiêu biểu trong xã hội tri thức: dùng công cụ và thuật toán để khai thác dữ liệu, tìm quy luật, dự báo và hỗ trợ ra quyết định.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Ngoài kiến thức chuyên môn, người làm công nghệ thông tin rất cần có kĩ năng nào sau đây?","o":["Tư duy logic, khả năng tự học công nghệ mới và kĩ năng làm việc nhóm","Thuộc lòng mọi câu lệnh của đúng một ngôn ngữ lập trình","Kĩ năng biểu diễn và thuyết trình trên sân khấu lớn","Sức khỏe để làm việc nặng ngoài trời trong thời gian dài"],"a":"Tư duy logic, khả năng tự học công nghệ mới và kĩ năng làm việc nhóm","h":"Công nghệ thay đổi rất nhanh, nên người làm CNTT không thể chỉ dựa vào những gì đã học một lần.","e":"Người làm CNTT cần tư duy logic để giải quyết vấn đề, tinh thần tự học liên tục vì công nghệ đổi mới nhanh, cùng kĩ năng làm việc nhóm và giao tiếp khi tham gia các dự án.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Một bài trình chiếu thường gồm nhiều trang nối tiếp nhau. Mỗi trang như vậy được gọi là gì?","o":["Trang chiếu","Thư mục","Bàn phím","Tệp tranh"],"a":"Trang chiếu","h":"Hãy nghĩ đến từng tờ giấy trong một cuốn vở trình bày.","e":"Bài trình chiếu gồm nhiều trang chiếu. Mỗi trang chiếu có thể chứa chữ, hình ảnh để em trình bày một ý cho mọi người cùng xem.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em làm một bài trình chiếu về các con vật để giới thiệu với cả lớp. Bài trình chiếu giúp em việc gì?","o":["Giúp em chơi trò chơi nhanh hơn","Giúp em xoá hết các tệp trong máy tính","Giúp em trình bày ý của mình bằng chữ và hình ảnh cho mọi người cùng xem","Giúp máy tính chạy nhanh hơn"],"a":"Giúp em trình bày ý của mình bằng chữ và hình ảnh cho mọi người cùng xem","h":"Nhờ bài trình chiếu, cả lớp có thể nhìn thấy điều em muốn nói.","e":"Bài trình chiếu là cách trình bày thông tin bằng các trang chiếu có chữ và hình ảnh, giúp người xem dễ hiểu điều em muốn giới thiệu.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em muốn xem hình ảnh và thông tin về cây hoa hồng trên máy tính. Em nên làm gì?","o":["Tắt máy tính và đi ngủ","Dùng máy tính để tìm và xem thông tin về cây hoa hồng","Xoá hết các phần mềm trong máy","Gõ bàn phím thật nhanh"],"a":"Dùng máy tính để tìm và xem thông tin về cây hoa hồng","h":"Máy tính có thể giúp em tìm hiểu về cây cối, con vật trong tự nhiên.","e":"Nhờ máy tính và các phần mềm, em có thể xem hình ảnh, đọc thông tin về cây cối, hoa lá và nhiều điều thú vị trong thế giới tự nhiên.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Lớp em muốn tìm hiểu về con voi nhưng không thể đến vườn thú. Máy tính giúp lớp em bằng cách nào?","o":["Máy tính đưa cả lớp đến vườn thú","Máy tính tự vẽ con voi thay cho em","Máy tính cho em xem hình ảnh, video và đọc thông tin về con voi","Máy tính làm bài tập thay cho em"],"a":"Máy tính cho em xem hình ảnh, video và đọc thông tin về con voi","h":"Em có thể nhìn thấy con voi ngay trên màn hình.","e":"Máy tính giúp em tìm hiểu thế giới tự nhiên bằng cách cho xem hình ảnh, video và thông tin về các con vật, cây cối dù em đang ở bất cứ đâu.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Để đánh răng đúng cách, em thực hiện các việc sau: lấy kem lên bàn chải, chải răng, súc miệng sạch. Các việc này cần được làm như thế nào?","o":["Làm việc nào trước cũng được","Làm theo từng bước, đúng thứ tự từ đầu đến cuối","Chỉ làm bước cuối cùng","Làm tất cả các bước cùng một lúc"],"a":"Làm theo từng bước, đúng thứ tự từ đầu đến cuối","h":"Nếu súc miệng trước rồi mới chải răng thì răng có sạch không?","e":"Mỗi công việc thường gồm nhiều bước. Em cần thực hiện các bước theo đúng trình tự, từ bước đầu tiên đến bước cuối cùng thì công việc mới hoàn thành tốt.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em xếp cặp sách để đi học theo các bước: mở cặp, cho sách vở vào, cho hộp bút vào, đóng cặp lại. Nếu em bỏ qua bước cho sách vở vào thì điều gì xảy ra?","o":["Cặp vẫn đầy đủ sách vở","Cặp sách tự đầy lên","Không có gì thay đổi","Đến lớp em sẽ không có sách vở để học"],"a":"Đến lớp em sẽ không có sách vở để học","h":"Mỗi bước trong công việc đều quan trọng, thiếu một bước thì kết quả sẽ thế nào?","e":"Khi thực hiện công việc theo các bước, em không nên bỏ qua hay làm lộn thứ tự các bước, vì thiếu một bước thì công việc sẽ không đạt kết quả như mong muốn.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Sáng nay trời mưa. Em quyết định: 'Nếu trời mưa thì em mang áo mưa, nếu trời nắng thì em đội mũ.' Cách quyết định này dựa vào điều gì?","o":["Dựa vào may rủi","Dựa vào điều kiện thời tiết lúc đó","Dựa vào màu áo em thích","Không dựa vào điều gì cả"],"a":"Dựa vào điều kiện thời tiết lúc đó","h":"Trời mưa và trời nắng là hai tình huống khác nhau, em chọn cách làm khác nhau.","e":"Nhiều công việc được thực hiện theo điều kiện: nếu điều kiện này xảy ra thì làm cách này, nếu điều kiện khác thì làm cách khác. Nhờ xem xét điều kiện, em chọn được việc làm phù hợp.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Đèn giao thông chuyển sang màu đỏ. Người đi đường dừng lại chờ đèn xanh. Việc dừng lại này là vì điều kiện nào?","o":["Vì đèn đỏ báo phải dừng lại","Vì đường quá rộng","Vì trời sắp tối","Vì xe hết xăng"],"a":"Vì đèn đỏ báo phải dừng lại","h":"Màu của đèn giao thông cho em biết nên đi hay nên dừng.","e":"Đèn đỏ là điều kiện để người đi đường quyết định dừng lại, đèn xanh là điều kiện để được đi tiếp. Đây là ví dụ về công việc được thực hiện theo điều kiện.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em muốn vẽ một bức tranh tặng mẹ nhưng vẽ tay chưa đẹp. Máy tính có thể trợ giúp em như thế nào?","o":["Máy tính không giúp được gì","Máy tính tự đi tặng tranh cho mẹ","Em dùng phần mềm vẽ tranh trên máy tính để vẽ và tô màu cho bức tranh","Máy tính giúp em ngủ ngon hơn"],"a":"Em dùng phần mềm vẽ tranh trên máy tính để vẽ và tô màu cho bức tranh","h":"Em đã học vẽ tranh bằng phần mềm nào trên máy tính rồi nhỉ?","e":"Máy tính trợ giúp em trong nhiều công việc: vẽ tranh bằng phần mềm vẽ, học bài, tìm thông tin... Em vẫn là người thực hiện công việc, máy tính là công cụ trợ giúp.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em cần tìm hiểu cách trồng cây đậu để làm bài tập. Việc làm nào sau đây cho thấy em biết nhờ máy tính trợ giúp?","o":["Ngồi chờ bạn làm hộ","Bỏ qua bài tập, không làm nữa","Xé vở bài tập đi","Dùng máy tính để tìm và xem thông tin về cách trồng cây đậu"],"a":"Dùng máy tính để tìm và xem thông tin về cách trồng cây đậu","h":"Máy tính chứa rất nhiều thông tin hữu ích cho việc học của em.","e":"Khi gặp công việc cần tìm hiểu thông tin, em có thể nhờ máy tính trợ giúp để tìm kiếm và xem thông tin. Nhờ vậy, công việc của em được thực hiện nhanh hơn và tốt hơn.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Để bắt đầu tạo một bài trình chiếu trên máy tính, em cần làm gì trước tiên?","o":["Mở phần mềm trình chiếu và tạo một bài trình chiếu mới","Tắt màn hình máy tính","Xoá hết các tệp trong máy","Rút dây điện của máy tính"],"a":"Mở phần mềm trình chiếu và tạo một bài trình chiếu mới","h":"Em cần có phần mềm nào để làm các trang chiếu?","e":"Muốn tạo bài trình chiếu, em mở phần mềm trình chiếu, tạo bài mới rồi thêm các trang chiếu và gõ nội dung, chèn hình ảnh vào từng trang.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Bài trình chiếu của em đã có trang đầu tiên. Em muốn thêm một trang chiếu mới để viết tiếp nội dung. Em cần làm gì?","o":["Đóng phần mềm lại","Chèn thêm một trang chiếu mới vào bài trình chiếu","Xoá trang đầu tiên đi","In bài trình chiếu ra giấy"],"a":"Chèn thêm một trang chiếu mới vào bài trình chiếu","h":"Một bài trình chiếu có thể gồm nhiều trang chiếu nối tiếp nhau.","e":"Trong phần mềm trình chiếu, em có thể chèn thêm nhiều trang chiếu mới để trình bày đủ các ý. Mỗi trang chiếu trình bày một phần nội dung của bài.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trên trang chiếu, dòng tiêu đề bị nhỏ quá, cả lớp ngồi xa không đọc được. Em nên chỉnh sửa như thế nào?","o":["Xoá dòng tiêu đề đi","Đổi cả bài trình chiếu sang bài khác","Tắt máy chiếu","Tăng cỡ chữ cho dòng tiêu đề to hơn"],"a":"Tăng cỡ chữ cho dòng tiêu đề to hơn","h":"Chữ to hơn thì mọi người dễ đọc hơn.","e":"Định dạng văn bản trên trang chiếu gồm việc chỉnh cỡ chữ, màu chữ, kiểu chữ... Tăng cỡ chữ cho tiêu đề giúp người xem ở xa cũng đọc được nội dung.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Em muốn dòng chữ trên trang chiếu nằm ở giữa trang cho đẹp. Em dùng cách định dạng nào?","o":["Căn lề giữa","Căn lề trái","Xoá bỏ dòng chữ","Sao chép dòng chữ"],"a":"Căn lề giữa","h":"Hãy nghĩ đến các nút căn lề: trái, giữa, phải.","e":"Khi định dạng văn bản trên trang chiếu, em có thể chọn cách căn lề: căn trái, căn giữa hoặc căn phải. Căn lề giữa giúp dòng chữ nằm cân đối ở giữa trang.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Hiệu ứng chuyển trang trong bài trình chiếu có tác dụng gì?","o":["Giúp máy tính chạy nhanh hơn","Giúp xoá nội dung trên trang chiếu","Giúp các trang chiếu xuất hiện sinh động khi chuyển từ trang này sang trang khác","Giúp tăng âm lượng của loa"],"a":"Giúp các trang chiếu xuất hiện sinh động khi chuyển từ trang này sang trang khác","h":"Hãy tưởng tượng trang chiếu mới hiện ra một cách đẹp mắt khi em bấm chuyển trang.","e":"Hiệu ứng chuyển trang là cách trang chiếu mới xuất hiện khi trình chiếu, ví dụ mờ dần, đẩy sang, lật trang... giúp bài trình chiếu sinh động và hấp dẫn hơn.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Khi trình chiếu, em muốn trang chiếu mới xuất hiện từ từ, mờ dần hiện rõ lên. Em nên chọn loại hiệu ứng nào?","o":["Hiệu ứng âm thanh","Hiệu ứng gõ chữ nhanh","Hiệu ứng chuyển trang kiểu mờ dần","Không cần hiệu ứng gì"],"a":"Hiệu ứng chuyển trang kiểu mờ dần","h":"Tên của hiệu ứng nói lên cách trang chiếu xuất hiện.","e":"Phần mềm trình chiếu có nhiều hiệu ứng chuyển trang như mờ dần, đẩy, lật... Chọn hiệu ứng mờ dần sẽ giúp trang chiếu mới hiện lên từ từ, nhẹ nhàng.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Em gõ nhầm một từ trong đoạn văn bản và muốn sửa lại riêng từ đó. Việc làm đúng là gì?","o":["Xoá cả đoạn văn rồi gõ lại từ đầu","Chọn từ gõ nhầm, xoá đi và gõ lại cho đúng","Đóng văn bản lại không sửa nữa","In văn bản ra giấy rồi lấy bút sửa"],"a":"Chọn từ gõ nhầm, xoá đi và gõ lại cho đúng","h":"Em chỉ cần sửa đúng chỗ bị nhầm thôi.","e":"Khi chỉnh sửa văn bản, em chọn phần văn bản cần sửa rồi xoá đi và gõ lại cho đúng. Cách này nhanh và không làm mất các phần văn bản đã đúng.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Một câu hay trong đoạn văn của em cần xuất hiện thêm một lần nữa ở đoạn dưới. Em nên dùng thao tác nào để không phải gõ lại?","o":["Cắt đoạn văn đi","Xoá câu đó đi","Đổi màu chữ của câu đó","Sao chép câu đó rồi dán vào vị trí mới"],"a":"Sao chép câu đó rồi dán vào vị trí mới","h":"Thao tác này gồm hai bước: sao chép và dán.","e":"Sao chép giúp em tạo thêm một bản giống hệt của phần văn bản đã chọn, rồi dán vào vị trí mới. Nhờ vậy em không phải gõ lại và câu gốc vẫn còn nguyên. Còn khi dùng lệnh Cắt, đoạn văn sẽ rời khỏi vị trí cũ để dán sang vị trí mới.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong phần mềm Scratch, em ra lệnh cho nhân vật hoạt động bằng cách nào?","o":["Ghép các khối lệnh lại với nhau theo đúng thứ tự","Nói to vào màn hình máy tính","Vẽ các lệnh lên giấy rồi dán lên màn hình","Nhấn các phím bất kỳ trên bàn phím thật nhanh"],"a":"Ghép các khối lệnh lại với nhau theo đúng thứ tự","h":"Nhân vật trong Scratch chỉ làm theo các khối lệnh mà em xếp cho nó.","e":"Trong Scratch, em tạo chương trình bằng cách kéo và ghép các khối lệnh lại với nhau theo thứ tự. Nhân vật sẽ thực hiện lần lượt các lệnh đó, ví dụ di chuyển, xoay, nói lời thoại.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Em tạo một chương trình cho nhân vật mèo: đi thẳng 10 bước, rồi kêu 'meo'. Máy tính sẽ thực hiện chương trình như thế nào?","o":["Thực hiện các lệnh theo đúng thứ tự em đã sắp xếp","Thực hiện lệnh nào trước cũng được","Chỉ thực hiện lệnh cuối cùng","Tự bỏ qua các lệnh khó"],"a":"Thực hiện các lệnh theo đúng thứ tự em đã sắp xếp","h":"Chương trình giống như các bước làm một công việc, cần theo đúng trình tự.","e":"Khi chạy chương trình, máy tính thực hiện các lệnh lần lượt theo đúng thứ tự từ lệnh đầu đến lệnh cuối. Vì vậy em cần sắp xếp các lệnh cho đúng trình tự mong muốn.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Em rất thích một trò chơi trên máy tính. Cách chơi nào sau đây là đúng và tốt cho em?","o":["Chơi suốt cả ngày, bỏ cả ăn và học","Chơi thâu đêm cho đến khi mệt","Chơi một lúc vừa phải theo thời gian quy định, rồi nghỉ ngơi và học bài","Giấu bố mẹ chơi lúc nửa đêm"],"a":"Chơi một lúc vừa phải theo thời gian quy định, rồi nghỉ ngơi và học bài","h":"Chơi vui nhưng cũng cần bảo vệ mắt và không quên việc học.","e":"Chơi trò chơi trên máy tính giúp em thư giãn, nhưng em chỉ nên chơi trong thời gian vừa phải theo quy định của bố mẹ, thầy cô. Chơi quá lâu sẽ hại mắt và ảnh hưởng đến học tập, sức khoẻ.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trong cây thư mục trên máy tính, một thư mục nằm bên trong một thư mục khác được gọi là gì?","o":["Thư mục con","Thư mục gốc","Tệp tin","Ổ đĩa"],"a":"Thư mục con","h":"Hãy nhớ cách gọi quan hệ 'mẹ – con' giữa các thư mục lồng nhau.","e":"Thư mục chứa thư mục khác bên trong được gọi là thư mục mẹ, còn thư mục nằm bên trong thư mục mẹ được gọi là thư mục con. Các thư mục lồng nhau như vậy tạo thành cây thư mục, giúp em sắp xếp và tìm tệp dễ dàng.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Thư mục HocTap nằm trong thư mục Lop5, thư mục Lop5 nằm trong ổ đĩa D:. Đường dẫn đầy đủ tới thư mục HocTap là gì?","o":["D:\\Lop5","D:\\Lop5\\HocTap","HocTap\\Lop5\\D:","Lop5\\HocTap"],"a":"D:\\Lop5\\HocTap","h":"Đường dẫn được viết lần lượt từ ổ đĩa, qua thư mục mẹ, rồi mới tới thư mục cần tìm.","e":"Đường dẫn của một thư mục ghi theo thứ tự từ ngoài vào trong: tên ổ đĩa (D:), tiếp đến thư mục mẹ (Lop5), cuối cùng là chính thư mục đó (HocTap), các phần ngăn cách nhau bằng dấu \\. Vậy đường dẫn đầy đủ là D:\\Lop5\\HocTap.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Trong Scratch, biểu thức tính toán (ví dụ: Điểm + 5) được dùng để làm gì?","o":["Làm cho nhân vật nói ra một câu thoại","Di chuyển nhân vật đi một số bước","Tô màu lại cho sân khấu","Tính ra một giá trị mới bằng các phép tính cộng, trừ, nhân, chia"],"a":"Tính ra một giá trị mới bằng các phép tính cộng, trừ, nhân, chia","h":"Hãy nhìn vào ví dụ: 'Điểm + 5' chứa một phép tính quen thuộc.","e":"Biểu thức tính toán kết hợp các số, các biến với các phép toán cộng, trừ, nhân, chia để cho ra một giá trị. Ví dụ, khi biến Điểm bằng 7 thì biểu thức (Điểm + 5) cho kết quả là 12.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Trong Scratch, biểu thức so sánh (ví dụ: Điểm > 10) cho kết quả là gì?","o":["Đúng hoặc sai: đúng khi Điểm lớn hơn 10, sai khi không phải như vậy","Một con số bất kì từ 0 đến 100","Một dòng chữ hiện lên màn hình","Một âm thanh báo hiệu"],"a":"Đúng hoặc sai: đúng khi Điểm lớn hơn 10, sai khi không phải như vậy","h":"Biểu thức so sánh kiểm tra một điều kiện, giống như trả lời một câu hỏi 'có hay không'.","e":"Biểu thức so sánh dùng các phép so sánh như >, <, = để kiểm tra một điều kiện. Kết quả của nó chỉ có hai khả năng: đúng hoặc sai. Nhờ vậy chương trình biết có nên thực hiện một hành động nào đó hay không, thường dùng cùng khối lệnh 'nếu ... thì'.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Phần mềm đồ họa (phần mềm vẽ) trên máy tính giúp em làm công việc nào sau đây?","o":["Soạn thảo một đoạn văn dài","Gửi thư điện tử cho bạn bè","Vẽ, tô màu và chỉnh sửa hình ảnh để tạo ra tranh vẽ số","Tính toán với các bảng số liệu"],"a":"Vẽ, tô màu và chỉnh sửa hình ảnh để tạo ra tranh vẽ số","h":"Hãy nhớ các công cụ quen thuộc trong phần mềm vẽ: bút vẽ, tẩy, thùng sơn...","e":"Phần mềm đồ họa cung cấp các công cụ như bút vẽ, bút chì, tẩy, thùng sơn, hình khối... giúp em vẽ, tô màu và chỉnh sửa hình ảnh ngay trên máy tính, tạo ra các sản phẩm tranh vẽ số của riêng mình.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Em dùng phần mềm đồ họa vẽ xong một tấm thiệp chúc mừng sinh nhật bạn. Để giữ lại sản phẩm và sau này còn gửi cho bạn, em cần làm gì?","o":["Tắt máy ngay khi vừa vẽ xong","Lưu (Save) tấm thiệp thành một tệp hình ảnh trong máy tính","Chỉ cần nhớ trong đầu là đủ","Xóa thiệp đi rồi hôm sau vẽ lại"],"a":"Lưu (Save) tấm thiệp thành một tệp hình ảnh trong máy tính","h":"Nếu không làm việc này, sản phẩm của em sẽ biến mất khi đóng phần mềm.","e":"Sau khi tạo xong sản phẩm số bằng phần mềm đồ họa, em phải lưu lại thành một tệp hình ảnh (ví dụ tệp PNG hoặc JPG) thì sản phẩm mới không bị mất. Nhờ có tệp đó, em có thể mở lại, in ra giấy hoặc gửi tặng bạn.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Em tìm được một bức ảnh rất đẹp trên Internet do người khác chụp. Muốn dùng bức ảnh đó trong bài làm của mình cho đúng bản quyền, em nên làm gì?","o":["Cứ dùng thoải mái vì ảnh đã đăng lên mạng là của chung","Xóa tên tác giả đi rồi nhận là ảnh của mình","Chỉ cần không ai phát hiện ra là được","Xin phép tác giả khi cần và ghi rõ nguồn, tên tác giả của bức ảnh khi sử dụng"],"a":"Xin phép tác giả khi cần và ghi rõ nguồn, tên tác giả của bức ảnh khi sử dụng","h":"Hãy nghĩ xem việc làm nào tôn trọng công sức của người đã chụp bức ảnh.","e":"Hình ảnh và bài viết của người khác đều được bảo vệ bởi bản quyền. Khi sử dụng, em cần tôn trọng tác giả: xin phép khi cần thiết và luôn ghi rõ nguồn, tên tác giả. Tuyệt đối không được nhận sản phẩm của người khác làm của mình.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Trước khi viết chương trình Scratch cho một trò chơi, bạn An viết ra giấy: nhân vật xuất hiện ở đâu, di chuyển như thế nào, khi nào thì trò chơi kết thúc. Bản viết ra giấy đó được gọi là gì?","o":["Là mã nguồn để máy tính chạy trực tiếp","Là bản quyền của trò chơi","Là kịch bản — bản mô tả các sự việc và hành động sẽ xảy ra, giúp em hình dung trước khi viết chương trình","Là hướng dẫn cài đặt phần mềm"],"a":"Là kịch bản — bản mô tả các sự việc và hành động sẽ xảy ra, giúp em hình dung trước khi viết chương trình","h":"Giống như một vở kịch cần có bản viết trước khi diễn, trò chơi cũng cần có bản mô tả trước khi lập trình.","e":"Kịch bản là bản mô tả chi tiết các sự việc, hành động sẽ diễn ra trong chương trình hoặc trò chơi, được viết trước khi bắt tay vào lập trình. Có kịch bản rõ ràng, em sẽ hình dung được toàn bộ công việc, viết chương trình dễ dàng hơn và ít mắc lỗi hơn.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về dữ liệu và thông tin?","o":["Dữ liệu và thông tin là hai khái niệm hoàn toàn giống nhau","Dữ liệu là các dữ kiện như số liệu, kí tự, hình ảnh; thông tin là điều con người hiểu và rút ra được từ dữ liệu","Thông tin chỉ có thể tồn tại bên trong máy tính","Dữ liệu lúc nào cũng quan trọng hơn thông tin"],"a":"Dữ liệu là các dữ kiện như số liệu, kí tự, hình ảnh; thông tin là điều con người hiểu và rút ra được từ dữ liệu","h":"Hãy phân biệt 'nguyên liệu thô' với 'điều ta hiểu được' sau khi tiếp nhận nó.","e":"Dữ liệu là các dữ kiện thô như con số, kí tự, hình ảnh, âm thanh. Khi dữ liệu được tiếp nhận, xử lí và con người hiểu được ý nghĩa của nó thì dữ liệu trở thành thông tin. Ví dụ: dãy số 38,5 là dữ liệu; hiểu rằng 'bạn An sốt 38,5 độ' là thông tin.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Sách giáo khoa, biển báo giao thông và thẻ nhớ USB có điểm chung nào sau đây?","o":["Đều là vật mang tin, tức là vật dùng để lưu trữ và truyền tải thông tin","Đều là các thiết bị điện tử hiện đại","Đều chỉ được dùng trong trường học","Đều có khả năng tự xử lí thông tin như máy tính"],"a":"Đều là vật mang tin, tức là vật dùng để lưu trữ và truyền tải thông tin","h":"Cả ba thứ này đều 'chứa đựng' một điều gì đó để người khác tiếp nhận sau.","e":"Vật mang tin là vật chứa đựng thông tin để lưu trữ và truyền đi. Sách giáo khoa mang thông tin bằng chữ và hình ảnh, biển báo giao thông mang thông tin bằng kí hiệu, còn thẻ nhớ USB mang thông tin dưới dạng dữ liệu số trong máy tính.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Quá trình xử lí thông tin của máy tính gồm các hoạt động nào, theo đúng thứ tự?","o":["Lưu trữ, truyền, thu nhận, xử lí","Xử lí, thu nhận, truyền, lưu trữ","Thu nhận thông tin, xử lí, lưu trữ, truyền (xuất) thông tin","Chỉ gồm duy nhất một hoạt động là xử lí"],"a":"Thu nhận thông tin, xử lí, lưu trữ, truyền (xuất) thông tin","h":"Hãy hình dung: muốn làm việc, trước hết máy tính phải 'nhận' được thông tin vào đã.","e":"Máy tính xử lí thông tin theo một quá trình gồm bốn hoạt động: thu nhận thông tin (nhập dữ liệu vào), xử lí thông tin (tính toán, biến đổi), lưu trữ thông tin (ghi nhớ lại) và truyền thông tin (xuất kết quả ra ngoài, ví dụ hiển thị lên màn hình).","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Em nhập điểm các môn vào máy tính để tính điểm trung bình: máy tính cộng các điểm lại rồi chia cho số môn, kết quả được lưu vào tệp và hiện lên màn hình. Việc máy tính 'cộng và chia' thuộc hoạt động nào trong quá trình xử lí thông tin?","o":["Thu nhận thông tin","Lưu trữ thông tin","Truyền thông tin","Xử lí thông tin"],"a":"Xử lí thông tin","h":"Cộng và chia là các phép tính toán, biến đổi dữ liệu đã nhập vào.","e":"Nhập điểm vào máy là thu nhận thông tin; cộng và chia để tính điểm trung bình là xử lí thông tin (biến đổi dữ liệu đầu vào thành kết quả); ghi kết quả vào tệp là lưu trữ; hiển thị lên màn hình là truyền (xuất) thông tin.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Sơ đồ tư duy là gì?","o":["Một sơ đồ trình bày thông tin một cách trực quan, gồm chủ đề trung tâm và các nhánh tỏa ra chứa các ý liên quan","Một bảng tính dùng để cộng các số liệu","Một sơ đồ khối mô tả thuật toán bằng hình thoi và hình chữ nhật","Một trò chơi trí tuệ trên máy tính"],"a":"Một sơ đồ trình bày thông tin một cách trực quan, gồm chủ đề trung tâm và các nhánh tỏa ra chứa các ý liên quan","h":"Hãy hình dung một cái cây: thân cây ở giữa và các cành tỏa ra xung quanh.","e":"Sơ đồ tư duy là một sơ đồ trình bày thông tin trực quan: ở giữa là chủ đề trung tâm, xung quanh là các nhánh chứa những ý chính và ý nhỏ liên quan. Sơ đồ tư duy giúp em ghi nhớ, hệ thống kiến thức và nảy ra ý tưởng mới dễ dàng hơn. Cần phân biệt với sơ đồ khối dùng để mô tả thuật toán.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Bạn Minh vẽ sơ đồ tư duy cho chủ đề 'Kế hoạch ôn tập': một ô ở giữa ghi 'Ôn tập', từ ô đó tỏa ra các đường nối tới 'Toán', 'Tiếng Việt', 'Tin học', mỗi môn lại có thêm các ý nhỏ hơn. Ô ở giữa và các đường tỏa ra lần lượt được gọi là gì?","o":["Là tiêu đề bài và các đoạn văn","Là hình ảnh minh họa và các chú thích","Là từ khóa chính và các từ khóa phụ","Ô ở giữa là chủ đề trung tâm; các đường tỏa ra là các nhánh (nhánh chính nối với chủ đề, nhánh con nối với nhánh chính)"],"a":"Ô ở giữa là chủ đề trung tâm; các đường tỏa ra là các nhánh (nhánh chính nối với chủ đề, nhánh con nối với nhánh chính)","h":"Ô ở giữa giữ vai trò 'trung tâm' của toàn bộ sơ đồ.","e":"Trong sơ đồ tư duy, ô ở giữa là chủ đề trung tâm — nội dung chính cần trình bày. Các đường tỏa ra từ chủ đề trung tâm là các nhánh: nhánh nối trực tiếp với chủ đề trung tâm là nhánh chính (ở đây là các môn học), nhánh nhỏ hơn nối tiếp từ nhánh chính là nhánh con (các ý nhỏ của từng môn).","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Ngôn ngữ lập trình là gì?","o":["Ngôn ngữ dùng để viết các lệnh cho máy tính, gồm các ký hiệu và quy tắc riêng","Ngôn ngữ máy tính dùng để trò chuyện với con người","Một phần mềm dùng để soạn thảo văn bản","Tiếng nói của người lập trình viên khi làm việc"],"a":"Ngôn ngữ dùng để viết các lệnh cho máy tính, gồm các ký hiệu và quy tắc riêng","h":"Muốn ra lệnh cho máy tính, con người phải viết bằng một loại ngôn ngữ đặc biệt.","e":"Ngôn ngữ lập trình là ngôn ngữ nhân tạo gồm các ký hiệu và quy tắc, dùng để viết chương trình (dãy lệnh) cho máy tính thực hiện. Ví dụ: Scratch, Python, C++.","t":"tin-lop6","g":6,"l":"nhe-nhang"},{"p":"Con người viết chương trình bằng ngôn ngữ lập trình (gần gũi với ngôn ngữ của con người), nhưng máy tính chỉ hiểu được ngôn ngữ máy gồm các dãy bit 0 và 1. Để máy tính thực hiện được chương trình đã viết, cần nhờ tới công cụ nào?","o":["Phần mềm soạn thảo văn bản","Chương trình dịch — công cụ dịch chương trình từ ngôn ngữ lập trình sang ngôn ngữ máy","Trình duyệt web","Phần mềm trình chiếu"],"a":"Chương trình dịch — công cụ dịch chương trình từ ngôn ngữ lập trình sang ngôn ngữ máy","h":"Giống như cần một người phiên dịch khi hai bên nói hai thứ tiếng khác nhau.","e":"Chương trình dịch là công cụ có nhiệm vụ dịch (chuyển đổi) chương trình viết bằng ngôn ngữ lập trình sang ngôn ngữ máy mà máy tính hiểu được. Nhờ chương trình dịch, các lệnh em viết ra mới được máy tính thực hiện.","t":"tin-lop6","g":6,"l":"thu-thach"},{"p":"Để áp dụng được thuật toán tìm kiếm nhị phân, dãy dữ liệu cần thoả mãn điều kiện nào?","o":["Dãy đã được sắp xếp theo một thứ tự nhất định (tăng dần hoặc giảm dần)","Dãy có số phần tử là số chẵn","Dãy chỉ gồm các số nguyên dương","Dãy được nhập vào từ bàn phím"],"a":"Dãy đã được sắp xếp theo một thứ tự nhất định (tăng dần hoặc giảm dần)","h":"Tìm kiếm nhị phân dựa vào việc so sánh với phần tử ở giữa để loại bỏ một nửa dãy, điều này chỉ đúng khi dãy có thứ tự.","e":"Thuật toán tìm kiếm nhị phân chỉ áp dụng được trên dãy đã sắp xếp. Nhờ dãy có thứ tự, sau mỗi lần so sánh với phần tử ở giữa, ta biết chắc giá trị cần tìm nằm ở nửa nào của dãy và loại bỏ được nửa còn lại.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong thuật toán tìm kiếm nhị phân, sau mỗi bước so sánh phần tử ở giữa với giá trị cần tìm (và chưa tìm thấy), điều gì xảy ra?","o":["Dãy được sắp xếp lại từ đầu","Thuật toán dừng lại và kết luận không tìm thấy","Một nửa dãy bị loại bỏ, việc tìm kiếm chỉ tiếp tục trên nửa còn lại","Thuật toán quay lại kiểm tra từ phần tử đầu tiên của dãy"],"a":"Một nửa dãy bị loại bỏ, việc tìm kiếm chỉ tiếp tục trên nửa còn lại","h":"Hãy nghĩ đến ý tưởng 'chia đôi' dãy trong mỗi bước của thuật toán.","e":"Mỗi bước của tìm kiếm nhị phân so sánh giá trị cần tìm với phần tử ở giữa dãy. Nếu chưa bằng, dựa vào thứ tự đã sắp xếp, ta loại bỏ được một nửa dãy chắc chắn không chứa giá trị cần tìm và chỉ tìm tiếp trên nửa còn lại. Nhờ vậy thuật toán thực hiện rất nhanh.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Ý tưởng chính của thuật toán sắp xếp nổi bọt (Bubble Sort) là gì?","o":["Chia dãy thành hai nửa rồi sắp xếp từng nửa","So sánh từng cặp phần tử kề nhau và đổi chỗ nếu chúng đứng ngược thứ tự, lặp lại cho đến khi dãy được sắp xếp","Tìm phần tử nhỏ nhất của dãy rồi đưa lên đầu dãy","Đếm số lần xuất hiện của từng giá trị trong dãy"],"a":"So sánh từng cặp phần tử kề nhau và đổi chỗ nếu chúng đứng ngược thứ tự, lặp lại cho đến khi dãy được sắp xếp","h":"Tên gọi 'nổi bọt' gợi ý các phần tử nhẹ (nhỏ) dần 'nổi' lên phía đầu dãy qua các lần đổi chỗ với phần tử kề bên.","e":"Sắp xếp nổi bọt xét lần lượt từng cặp phần tử kề nhau; nếu cặp đó đứng ngược thứ tự mong muốn thì đổi chỗ chúng. Quá trình được lặp lại qua nhiều lượt cho tới khi không còn cặp nào bị ngược thứ tự, tức dãy đã được sắp xếp xong.","t":"tin-lop7","g":7,"l":"nhe-nhang"},{"p":"Dùng thuật toán sắp xếp nổi bọt để sắp xếp dãy theo thứ tự tăng dần. Sau khi kết thúc lượt đổi chỗ đầu tiên (xét các cặp kề nhau từ đầu đến cuối dãy), phần tử nào chắc chắn đã nằm ở cuối dãy?","o":["Phần tử nhỏ nhất của dãy","Phần tử ở giữa dãy","Phần tử xuất hiện đầu tiên trong dãy ban đầu","Phần tử lớn nhất của dãy"],"a":"Phần tử lớn nhất của dãy","h":"Trong một lượt, phần tử lớn hơn trong mỗi cặp sẽ bị đẩy dần về phía cuối dãy.","e":"Khi xét các cặp kề nhau và đổi chỗ nếu ngược thứ tự (sắp xếp tăng dần), phần tử lớn nhất sẽ liên tục 'thắng' trong các lần so sánh và bị đẩy về cuối dãy. Vì vậy sau lượt đầu tiên, phần tử lớn nhất chắc chắn ở vị trí cuối cùng.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Dùng thuật toán tìm kiếm tuần tự để tìm một giá trị trong dãy gồm 20 phần tử. Trong trường hợp xấu nhất, thuật toán phải thực hiện bao nhiêu lần so sánh?","o":["1 lần so sánh","20 lần so sánh","10 lần so sánh","Không cần so sánh lần nào"],"a":"20 lần so sánh","h":"Tìm kiếm tuần tự kiểm tra lần lượt từng phần tử từ đầu dãy; trường hợp xấu nhất xảy ra khi giá trị cần tìm ở cuối dãy hoặc không có trong dãy.","e":"Tìm kiếm tuần tự so sánh giá trị cần tìm với từng phần tử theo thứ tự từ đầu dãy và chỉ dừng khi tìm thấy hoặc đã xét hết dãy. Trường hợp xấu nhất là giá trị nằm ở vị trí cuối cùng (hoặc không xuất hiện), khi đó thuật toán phải so sánh đủ 20 lần với cả 20 phần tử.","t":"tin-lop7","g":7,"l":"thu-thach"},{"p":"Nhóm nghề nghiệp nào sau đây thuộc lĩnh vực công nghệ thông tin?","o":["Bác sĩ, giáo viên, kiến trúc sư, kế toán","Thợ điện, thợ cơ khí, tài xế, đầu bếp","Lập trình viên, quản trị mạng, kĩ sư phần mềm, chuyên viên an toàn thông tin","Nông dân, ngư dân, thợ xây, thợ may"],"a":"Lập trình viên, quản trị mạng, kĩ sư phần mềm, chuyên viên an toàn thông tin","h":"Hãy chọn nhóm nghề mà công việc gắn trực tiếp với máy tính, phần mềm và mạng máy tính.","e":"Nhóm nghề đặc trưng của tin học gồm: lập trình viên (viết phần mềm), quản trị mạng (vận hành hệ thống mạng), kĩ sư phần mềm, chuyên viên an toàn thông tin/bảo mật, kĩ thuật viên sửa chữa máy tính, thiết kế đồ hoạ số... Các nghề còn lại thuộc lĩnh vực nông nghiệp, xây dựng, giao thông.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Người làm việc trong lĩnh vực công nghệ thông tin cần có những phẩm chất nào sau đây?","o":["Tư duy logic, cẩn thận, tỉ mỉ, kiên trì và ham học hỏi công nghệ mới","Sức khoẻ dẻo dai để lao động ngoài trời trong thời gian dài","Giọng hát hay và khả năng biểu diễn trước đám đông","Khéo tay trong việc trồng trọt và chăn nuôi"],"a":"Tư duy logic, cẩn thận, tỉ mỉ, kiên trì và ham học hỏi công nghệ mới","h":"Công nghệ thay đổi liên tục và công việc với máy tính đòi hỏi độ chính xác cao — hãy chọn nhóm phẩm chất phù hợp với đặc điểm đó.","e":"Người làm nghề tin học cần tư duy logic để phân tích và giải quyết vấn đề, tính cẩn thận và tỉ mỉ vì một lỗi nhỏ trong chương trình hay hệ thống cũng có thể gây hậu quả lớn; đồng thời công nghệ thay đổi rất nhanh nên phải kiên trì và thường xuyên học hỏi, cập nhật kiến thức mới.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trong soạn thảo văn bản, em nên dùng danh sách dạng liệt kê có thứ tự (đánh số 1, 2, 3...) trong trường hợp nào?","o":["Khi muốn trang trí cho đầu mỗi đoạn văn","Khi thứ tự của các mục có ý nghĩa quan trọng, ví dụ các bước thực hiện một công việc","Khi danh sách chỉ có đúng một mục","Khi muốn các mục được in đậm toàn bộ"],"a":"Khi thứ tự của các mục có ý nghĩa quan trọng, ví dụ các bước thực hiện một công việc","h":"Hãy phân biệt hai dạng liệt kê: đánh số thứ tự và dấu đầu dòng — mỗi dạng phù hợp với một kiểu nội dung khác nhau.","e":"Danh sách có thứ tự (đánh số 1, 2, 3...) dùng khi thứ tự các mục quan trọng, chẳng hạn các bước hướng dẫn thực hiện; còn danh sách không có thứ tự dùng dấu đầu dòng khi các mục ngang hàng, không cần phân biệt trước sau.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Sau khi chèn hình ảnh vào văn bản, em muốn phần chữ được sắp xếp bao quanh hình ảnh thay vì bị đẩy xuống dòng dưới. Em cần làm gì?","o":["Xoá toàn bộ văn bản xung quanh hình ảnh","Tăng độ phân giải của hình ảnh lên cao nhất","Chuyển hình ảnh sang định dạng đen trắng","Chọn kiểu bố trí để văn bản bao quanh hình ảnh (ví dụ kiểu Square)"],"a":"Chọn kiểu bố trí để văn bản bao quanh hình ảnh (ví dụ kiểu Square)","h":"Cách hình ảnh 'chung sống' với chữ trong văn bản được quyết định bởi kiểu bố trí (layout) của hình ảnh.","e":"Khi chèn hình ảnh vào văn bản, ta có thể thay đổi cách bố trí (layout) của ảnh so với văn bản: ảnh nằm trong dòng chữ như một kí tự, hoặc văn bản bao quanh ảnh (kiểu Square), ảnh nằm trên/dưới văn bản... Muốn chữ bao quanh ảnh, cần chọn kiểu bố trí văn bản bao quanh hình ảnh.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trong phần mềm chỉnh sửa ảnh, để thêm một dòng chữ (ví dụ chú thích tên địa danh) lên bức ảnh, em sử dụng công cụ nào?","o":["Công cụ Chữ (Text), thường có biểu tượng chữ T","Công cụ Cắt ảnh (Crop)","Công cụ Tẩy (Eraser)","Công cụ Đổ màu (Fill)"],"a":"Công cụ Chữ (Text), thường có biểu tượng chữ T","h":"Hãy nhớ biểu tượng quen thuộc hình chữ T trên thanh công cụ của các phần mềm chỉnh sửa ảnh.","e":"Trong các phần mềm chỉnh sửa ảnh, công cụ Chữ (Text) — thường có biểu tượng chữ T trên thanh công cụ — cho phép gõ nội dung chữ lên ảnh, sau đó có thể chọn phông chữ, cỡ chữ, màu chữ và vị trí cho phù hợp.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Em đã thêm dòng chữ lên bức ảnh nhưng dòng chữ bị chìm vào nền, khó đọc. Hiệu ứng nào sau đây giúp dòng chữ nổi bật và có chiều sâu hơn?","o":["Hiệu ứng làm mờ toàn bộ bức ảnh","Hiệu ứng lật ngược bức ảnh","Hiệu ứng bóng đổ (shadow)","Hiệu ứng chuyển ảnh thành tranh vẽ chì"],"a":"Hiệu ứng bóng đổ (shadow)","h":"Hiệu ứng này tạo ra một lớp bóng mờ ngay phía sau đối tượng, giống như bóng của vật dưới ánh sáng.","e":"Hiệu ứng bóng đổ tạo một bóng mờ phía sau đối tượng hoặc dòng chữ, giúp chúng tách khỏi nền và nổi bật hơn, tạo cảm giác có chiều sâu. Đây là một trong các hiệu ứng thường được áp dụng cho văn bản và đối tượng trên ảnh bên cạnh hiệu ứng viền, làm mờ, phát sáng...","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Khi trình bày thông tin trong trao đổi và hợp tác (ví dụ báo cáo kết quả làm việc nhóm), vì sao nên sử dụng các công cụ trực quan như sơ đồ tư duy, biểu đồ, hình ảnh?","o":["Giúp bài trình bày có dung lượng tệp lớn hơn","Giúp thông tin dễ hiểu, dễ nhớ và người tiếp nhận nắm bắt ý chính nhanh hơn","Giúp che giấu những nội dung chưa chuẩn bị kĩ","Giúp kéo dài thời gian trình bày của nhóm"],"a":"Giúp thông tin dễ hiểu, dễ nhớ và người tiếp nhận nắm bắt ý chính nhanh hơn","h":"Hãy nghĩ đến sự khác nhau khi tiếp nhận một trang chữ dài với một trang có sơ đồ, biểu đồ và hình ảnh rõ ràng.","e":"Khi trao đổi và hợp tác, việc trình bày thông tin bằng sơ đồ tư duy, bảng biểu, biểu đồ, hình ảnh minh hoạ giúp thông tin trở nên trực quan: người nghe/người đọc dễ hiểu, dễ ghi nhớ và nắm được ý chính nhanh hơn so với chỉ trình bày bằng đoạn văn dài.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong hoạt động hợp tác của nhóm, việc sử dụng các công cụ trực tuyến (như Google Docs, Google Slides) để cùng soạn thảo tài liệu mang lại lợi ích gì nổi bật nhất?","o":["Tài liệu không bao giờ bị mất kết nối Internet","Chỉ một người duy nhất được quyền mở tài liệu","Tài liệu tự động viết thay toàn bộ nội dung cho nhóm","Nhiều thành viên có thể cùng xem và chỉnh sửa tài liệu tại các thời điểm, địa điểm khác nhau"],"a":"Nhiều thành viên có thể cùng xem và chỉnh sửa tài liệu tại các thời điểm, địa điểm khác nhau","h":"Hãy nhớ điểm mạnh lớn nhất của tài liệu trực tuyến so với tệp tài liệu gửi qua lại giữa các thành viên.","e":"Các công cụ trực tuyến như Google Docs, Google Slides, Microsoft 365 cho phép chia sẻ tài liệu cho cả nhóm: mọi thành viên đều có thể xem, góp ý và chỉnh sửa trên cùng một tài liệu dù ở những nơi khác nhau, đồng thời theo dõi được các thay đổi — rất thuận tiện cho việc trao đổi và hợp tác.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Trong phần mềm bảng tính, công cụ xác thực dữ liệu (Data Validation) được sử dụng để làm gì?","o":["Đặt ra các điều kiện để kiểm tra và giới hạn dữ liệu được nhập vào ô, giúp giảm lỗi nhập liệu","Tự động sắp xếp dữ liệu theo thứ tự tăng dần","Tô màu nền cho các ô trong bảng tính","Tính tổng các số trong một cột"],"a":"Đặt ra các điều kiện để kiểm tra và giới hạn dữ liệu được nhập vào ô, giúp giảm lỗi nhập liệu","h":"Tên gọi 'xác thực dữ liệu' gợi ý việc kiểm tra tính đúng đắn của dữ liệu ngay từ lúc nhập vào.","e":"Công cụ xác thực dữ liệu (Data Validation) cho phép đặt điều kiện cho dữ liệu nhập vào ô, ví dụ chỉ cho nhập số nguyên trong một khoảng, chỉ cho chọn giá trị từ một danh sách có sẵn. Khi người dùng nhập dữ liệu không đúng điều kiện, phần mềm sẽ thông báo lỗi, nhờ đó bảng tính ít sai sót hơn.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Em lập bảng tính quản lí điểm của lớp, trong đó cột Điểm chỉ nhận các số nguyên từ 0 đến 10. Em nên thiết lập công cụ xác thực dữ liệu cho cột Điểm như thế nào?","o":["Chỉ cho phép nhập các số thập phân lớn hơn 10","Chỉ cho phép nhập ngày tháng năm sinh của học sinh","Chỉ cho phép nhập số nguyên từ 0 đến 10, nhập ngoài khoảng này sẽ bị báo lỗi","Chỉ cho phép nhập các môn học có tên trong danh sách"],"a":"Chỉ cho phép nhập số nguyên từ 0 đến 10, nhập ngoài khoảng này sẽ bị báo lỗi","h":"Điểm số trong trường hợp này phải là số nguyên và nằm trong một khoảng giá trị xác định.","e":"Với yêu cầu điểm số từ 0 đến 10, ta thiết lập xác thực dữ liệu cho các ô nhập điểm với điều kiện 'số nguyên nằm trong khoảng từ 0 đến 10'. Khi đó, nếu nhập giá trị ngoài khoảng (ví dụ 15 hoặc −2) hoặc nhập chữ, phần mềm sẽ hiện thông báo lỗi và không chấp nhận, giúp tránh sai sót khi nhập điểm.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Trong quá trình giải quyết vấn đề với sự trợ giúp của máy tính, bước nào cần được thực hiện đầu tiên?","o":["Đánh giá kết quả đạt được","Xác định rõ vấn đề cần giải quyết","Thực hiện ngay giải pháp đầu tiên nghĩ ra","Lựa chọn phần mềm đắt tiền nhất để sử dụng"],"a":"Xác định rõ vấn đề cần giải quyết","h":"Trước khi tìm cách giải quyết bất cứ việc gì, ta cần biết chính xác 'việc' đó là gì.","e":"Quá trình giải quyết vấn đề thường gồm các bước: xác định vấn đề; tìm hiểu, phân tích vấn đề; đề xuất các giải pháp; lựa chọn giải pháp; thực hiện giải pháp và đánh giá kết quả. Bước đầu tiên luôn là xác định rõ vấn đề cần giải quyết — hiểu đúng vấn đề thì mới tìm được cách giải quyết phù hợp.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi giải quyết vấn đề, sự trợ giúp của máy tính thể hiện rõ nhất ở khía cạnh nào?","o":["Sử dụng máy tính để xử lí nhanh, chính xác khối lượng dữ liệu lớn và thử nghiệm các phương án bằng mô phỏng","Để máy tính tự xác định vấn đề và tự chịu trách nhiệm về kết quả","Chỉ dùng máy tính để gõ lại văn bản của bài giải quyết vấn đề","Dùng máy tính thay con người trong mọi bước, kể cả quyết định cuối cùng"],"a":"Sử dụng máy tính để xử lí nhanh, chính xác khối lượng dữ liệu lớn và thử nghiệm các phương án bằng mô phỏng","h":"Hãy nhớ những khả năng vượt trội của máy tính so với con người: tốc độ, độ chính xác và xử lí dữ liệu lớn.","e":"Máy tính trợ giúp con người giải quyết vấn đề nhờ khả năng tính toán, xử lí khối lượng dữ liệu lớn với tốc độ nhanh và độ chính xác cao; đồng thời có thể mô phỏng, thử nghiệm nhiều phương án khác nhau trên máy trước khi áp dụng vào thực tế, giúp tiết kiệm thời gian, chi phí và hạn chế rủi ro.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Kịch bản video là gì?","o":["Tệp video thành phẩm sau khi đã xuất ra","Danh sách các phần mềm làm video được cài trong máy","Bản quảng cáo giới thiệu video sau khi đăng lên mạng","Bản mô tả chi tiết nội dung video gồm thứ tự các cảnh, hình ảnh, lời thoại, âm thanh dự kiến cho từng cảnh"],"a":"Bản mô tả chi tiết nội dung video gồm thứ tự các cảnh, hình ảnh, lời thoại, âm thanh dự kiến cho từng cảnh","h":"Giống như kịch bản của một vở kịch hay một bộ phim, kịch bản video được viết ra trước khi bắt tay vào thực hiện.","e":"Kịch bản video là bản mô tả chi tiết những gì sẽ có trong video: thứ tự xuất hiện của các cảnh, hình ảnh minh hoạ, lời thoại/lời bình, nhạc và âm thanh cho từng phần. Việc xây dựng kịch bản trước khi dựng giúp video có nội dung mạch lạc, không bỏ sót ý và tiết kiệm thời gian quay, dựng.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Trước khi bắt đầu dựng video, em cần chuẩn bị những dữ liệu nào?","o":["Chỉ cần một tệp văn bản chứa toàn bộ lời thoại","Chỉ cần cài đặt phần mềm làm video, không cần dữ liệu nào khác","Các đoạn video đã quay, hình ảnh, tệp âm thanh (nhạc, lời bình) và nội dung chữ cần chèn","Chỉ cần một chiếc máy quay, dữ liệu sẽ tự xuất hiện khi dựng"],"a":"Các đoạn video đã quay, hình ảnh, tệp âm thanh (nhạc, lời bình) và nội dung chữ cần chèn","h":"Video thành phẩm được ghép từ nhiều loại dữ liệu khác nhau — hãy liệt kê những loại dữ liệu đó.","e":"Bước chuẩn bị dữ liệu gồm: quay và thu thập các đoạn video, chuẩn bị hình ảnh minh hoạ, các tệp âm thanh như nhạc nền, tiếng động, bản ghi âm lời bình và nội dung các dòng chữ sẽ chèn vào video. Chuẩn bị đầy đủ dữ liệu trước giúp quá trình dựng video diễn ra thuận lợi, đúng kịch bản.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Những chức năng nào sau đây là chức năng chính của phần mềm làm video?","o":["Cắt, ghép các đoạn video; sắp xếp thứ tự các cảnh; thêm nhạc, chữ và hiệu ứng chuyển cảnh","Soạn thảo văn bản và in ấn tài liệu","Lập trình trò chơi và ứng dụng điện thoại","Quản lí điểm số học sinh trong lớp học"],"a":"Cắt, ghép các đoạn video; sắp xếp thứ tự các cảnh; thêm nhạc, chữ và hiệu ứng chuyển cảnh","h":"Hãy hình dung các thao tác cơ bản khi biến nhiều đoạn video rời rạc thành một video hoàn chỉnh.","e":"Phần mềm làm video (như các phần mềm biên tập video thông dụng) có các chức năng chính: cắt bỏ đoạn thừa, ghép nối và sắp xếp các đoạn video theo kịch bản; chèn nhạc nền, lời bình; thêm chữ, tiêu đề; tạo hiệu ứng chuyển cảnh giữa các đoạn và xuất video thành phẩm.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Sau khi hoàn thành video, em muốn đăng video lên mạng để chia sẻ với mọi người. Việc làm nào sau đây là đúng và an toàn?","o":["Tải bất kì bản nhạc nổi tiếng nào về lồng vào video mà không cần quan tâm nguồn gốc","Chỉ sử dụng nhạc, hình ảnh được phép dùng (miễn phí bản quyền hoặc có ghi nguồn, có sự cho phép) và không đăng tải thông tin cá nhân nhạy cảm","Ghi đầy đủ địa chỉ nhà và số điện thoại của các thành viên trong nhóm vào cuối video","Sao chép toàn bộ video của người khác và đăng lại dưới tên của mình"],"a":"Chỉ sử dụng nhạc, hình ảnh được phép dùng (miễn phí bản quyền hoặc có ghi nguồn, có sự cho phép) và không đăng tải thông tin cá nhân nhạy cảm","h":"Video khi đăng lên mạng cũng phải tuân thủ các quy định về bản quyền và an toàn thông tin như mọi sản phẩm số khác.","e":"Khi xuất và chia sẻ video, cần tôn trọng bản quyền: chỉ dùng nhạc, hình ảnh, đoạn video của người khác khi được phép sử dụng (ví dụ kho nhạc miễn phí bản quyền) hoặc ghi rõ nguồn theo yêu cầu của tác giả; đồng thời không đưa thông tin cá nhân nhạy cảm của mình và người khác lên video công khai để bảo đảm an toàn.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về mối quan hệ giữa thông tin và dữ liệu?","o":["Dữ liệu là thông tin đã được đưa vào máy tính để xử lí và được biểu diễn dưới dạng dãy bit","Thông tin và dữ liệu là hai khái niệm hoàn toàn giống nhau, không có gì khác biệt","Dữ liệu chỉ tồn tại trong sách vở, còn thông tin chỉ tồn tại trong máy tính","Thông tin là dãy bit 0 và 1, còn dữ liệu là những gì con người hiểu được"],"a":"Dữ liệu là thông tin đã được đưa vào máy tính để xử lí và được biểu diễn dưới dạng dãy bit","h":"Hãy nhớ: con người tiếp nhận thông tin, còn máy tính chỉ xử lí được dữ liệu ở dạng số hoá.","e":"Thông tin là những dữ kiện có ý nghĩa, giúp con người hiểu biết về thế giới. Khi thông tin được đưa vào máy tính để lưu trữ và xử lí, nó trở thành dữ liệu và được biểu diễn dưới dạng dãy bit (0 và 1).","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Tin học là ngành khoa học nghiên cứu về điều gì?","o":["Cách chế tạo các linh kiện điện tử như chip và bo mạch","Việc xử lí thông tin một cách tự động bằng máy tính điện tử","Cách sử dụng thành thạo các phần mềm văn phòng","Việc sản xuất các thiết bị thông minh trong gia đình"],"a":"Việc xử lí thông tin một cách tự động bằng máy tính điện tử","h":"Tên gọi 'tin học' gắn liền với hai yếu tố: thông tin và tính tự động của máy tính.","e":"Tin học là ngành khoa học nghiên cứu các phương pháp, công nghệ xử lí thông tin một cách tự động dựa trên máy tính điện tử. Nhờ máy tính, các công việc thu thập, lưu trữ, xử lí và truyền thông tin được thực hiện nhanh và chính xác.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Một đoạn văn bản khi được lưu trữ trong máy tính sẽ được biểu diễn như thế nào?","o":["Dưới dạng hình chụp lại từng trang giấy","Dưới dạng các sóng âm thanh liên tục","Mỗi kí tự được gán một mã số theo bảng mã và được lưu dưới dạng dãy bit nhị phân","Dưới dạng các nét vẽ tự do không theo quy tắc nào"],"a":"Mỗi kí tự được gán một mã số theo bảng mã và được lưu dưới dạng dãy bit nhị phân","h":"Máy tính chỉ hiểu được số 0 và 1, nên mỗi kí tự phải được 'đánh số' trước khi lưu.","e":"Để máy tính lưu trữ và xử lí được văn bản, mỗi kí tự (chữ cái, chữ số, dấu câu...) được gán một mã số duy nhất theo một bảng mã thống nhất, và mã số đó được biểu diễn thành dãy bit nhị phân.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Vì sao ngày nay người ta dùng bảng mã Unicode thay cho bảng mã ASCII khi gõ văn bản tiếng Việt?","o":["Vì Unicode giúp văn bản có dung lượng nhỏ hơn ASCII rất nhiều","Vì ASCII chỉ dùng được trên máy tính cũ, không chạy được trên điện thoại","Vì Unicode cho phép gõ văn bản mà không cần bàn phím","Vì ASCII không có đủ mã cho các kí tự có dấu của tiếng Việt và nhiều ngôn ngữ khác, còn Unicode mã hoá được hầu hết các kí tự trên thế giới"],"a":"Vì ASCII không có đủ mã cho các kí tự có dấu của tiếng Việt và nhiều ngôn ngữ khác, còn Unicode mã hoá được hầu hết các kí tự trên thế giới","h":"Hãy nghĩ xem bảng mã ASCII có đủ chỗ cho các chữ như 'ă', 'â', 'ế', 'ộ' hay không.","e":"Bảng mã ASCII chuẩn chỉ có 128 mã, đủ cho các kí tự tiếng Anh cơ bản, không thể biểu diễn các chữ có dấu của tiếng Việt. Unicode dùng số lượng mã rất lớn, mã hoá được kí tự của hầu hết các ngôn ngữ trên thế giới, trong đó có tiếng Việt.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Số thập phân 13 được biểu diễn trong hệ nhị phân là:","o":["1101","1011","1110","1001"],"a":"1101","h":"Hãy phân tích 13 thành tổng các luỹ thừa của 2: 13 = 8 + 4 + 1.","e":"13 = 8 + 4 + 0 + 1 = 1×2³ + 1×2² + 0×2¹ + 1×2⁰ nên biểu diễn nhị phân của 13 là 1101.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Số nhị phân 10110 có giá trị trong hệ thập phân là bao nhiêu?","o":["20","22","24","18"],"a":"22","h":"Hãy tính tổng theo các luỹ thừa của 2 ứng với các bit 1: 10110 = 16 + 4 + 2.","e":"10110₂ = 1×2⁴ + 0×2³ + 1×2² + 1×2¹ + 0×2⁰ = 16 + 0 + 4 + 2 + 0 = 22.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Một mệnh đề lôgic (ví dụ: 'Hôm nay trời mưa') trong máy tính chỉ có thể nhận những giá trị nào?","o":["Một trong ba giá trị: đúng, sai hoặc không xác định","Bất kì số nguyên nào từ 0 đến 100","Đúng (True) hoặc Sai (False)","Chỉ nhận giá trị Đúng (True)"],"a":"Đúng (True) hoặc Sai (False)","h":"Dữ liệu lôgic là kiểu dữ liệu đơn giản nhất, thường được lưu bằng đúng 1 bit.","e":"Dữ liệu lôgic chỉ gồm hai giá trị: Đúng (True) và Sai (False), thường được biểu diễn bằng 1 bit (1 cho Đúng, 0 cho Sai). Đây là cơ sở cho các phép toán lôgic và câu lệnh điều kiện trong lập trình.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho A = True và B = False. Giá trị của biểu thức (A or B) và biểu thức (A and B) lần lượt là:","o":["True và True","False và False","False và True","True và False"],"a":"True và False","h":"Phép OR chỉ cho kết quả False khi cả hai đều False; phép AND chỉ cho kết quả True khi cả hai đều True.","e":"A or B: vì A = True nên kết quả là True (chỉ cần một mệnh đề đúng). A and B: vì B = False nên kết quả là False (phép AND đòi hỏi cả hai cùng đúng). Vậy kết quả lần lượt là True và False.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Khi số hoá âm thanh, quá trình 'lấy mẫu' có nghĩa là gì?","o":["Đo và ghi lại giá trị của tín hiệu âm thanh tại những thời điểm cách đều nhau","Cắt bỏ những đoạn âm thanh bị nhiễu trong bản ghi","Chép bản ghi âm thanh từ thiết bị này sang thiết bị khác","Tăng âm lượng của bản ghi lên mức tối đa"],"a":"Đo và ghi lại giá trị của tín hiệu âm thanh tại những thời điểm cách đều nhau","h":"Tín hiệu âm thanh gốc là liên tục, máy tính phải 'chụp' lại nó tại nhiều thời điểm rời rạc.","e":"Âm thanh tự nhiên là tín hiệu liên tục. Để số hoá, người ta đo giá trị của tín hiệu tại các thời điểm cách đều nhau (lấy mẫu) rồi mã hoá các giá trị đó thành dãy bit. Số lần lấy mẫu trong một giây gọi là tần số lấy mẫu; tần số lấy mẫu càng cao, âm thanh số hoá càng trung thực.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Vì sao khi phóng to một bức ảnh bitmap (ảnh điểm) lên quá nhiều lần, ảnh bị 'vỡ hạt', nhìn rõ từng ô vuông nhỏ?","o":["Vì màn hình không hiển thị được ảnh có dung lượng lớn","Vì ảnh bitmap được tạo thành từ một lưới các điểm ảnh (pixel) có kích thước cố định, phóng to làm mỗi điểm ảnh trở thành một ô vuông nhìn thấy được","Vì ảnh bitmap tự động bị giảm chất lượng sau một thời gian lưu trữ","Vì các điểm ảnh trong ảnh bitmap luôn chuyển động khi phóng to"],"a":"Vì ảnh bitmap được tạo thành từ một lưới các điểm ảnh (pixel) có kích thước cố định, phóng to làm mỗi điểm ảnh trở thành một ô vuông nhìn thấy được","h":"Hãy nhớ ảnh bitmap được cấu tạo từ những phần tử nhỏ nhất nào và mỗi phần tử chỉ có một màu duy nhất.","e":"Ảnh bitmap là lưới các điểm ảnh (pixel), mỗi điểm ảnh lưu một màu duy nhất. Số điểm ảnh theo chiều ngang × chiều dọc gọi là độ phân giải của ảnh. Khi phóng to quá mức, từng điểm ảnh hiện rõ thành ô vuông khiến ảnh bị vỡ hạt; ảnh có độ phân giải càng cao thì càng chi tiết và phóng to được nhiều hơn.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Phần mềm Inkscape được giới thiệu trong SGK Tin học 10 thuộc loại phần mềm nào?","o":["Phần mềm chỉnh sửa ảnh chụp chuyên nghiệp","Phần mềm soạn thảo văn bản có chèn hình ảnh","Phần mềm thiết kế đồ hoạ vector, mã nguồn mở và miễn phí","Phần mềm dựng phim và biên tập video"],"a":"Phần mềm thiết kế đồ hoạ vector, mã nguồn mở và miễn phí","h":"Điểm đặc trưng của loại phần mềm này: hình ảnh được tạo từ các đối tượng hình học nên phóng to không vỡ.","e":"Inkscape là phần mềm thiết kế đồ hoạ vector mã nguồn mở, miễn phí. Đồ hoạ vector tạo hình từ các đối tượng hình học (điểm, đường, hình) được mô tả bằng thông số, nên sản phẩm có thể phóng to, thu nhỏ mà không bị vỡ hạt như ảnh bitmap.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong phần mềm đồ hoạ vector, các hình cơ bản như hình chữ nhật, elip, đa giác, ngôi sao được gọi chung là gì và có đặc điểm nào?","o":["Là các điểm ảnh, mỗi hình chỉ gồm một điểm ảnh duy nhất","Là các tệp tin riêng biệt không thể chỉnh sửa sau khi vẽ","Là các kí tự đặc biệt trong bảng mã Unicode","Là các đối tượng đồ hoạ; mỗi đối tượng có thể thay đổi thuộc tính như kích thước, màu sắc, vị trí một cách độc lập"],"a":"Là các đối tượng đồ hoạ; mỗi đối tượng có thể thay đổi thuộc tính như kích thước, màu sắc, vị trí một cách độc lập","h":"Trong đồ hoạ vector, ta làm việc với từng 'vật thể' riêng thay vì với từng điểm ảnh.","e":"Đồ hoạ vector được xây dựng từ các đối tượng đồ hoạ (hình chữ nhật, elip, đa giác, ngôi sao...). Mỗi đối tượng tồn tại độc lập với các thuộc tính riêng như kích thước, vị trí, màu nền, màu viền, nên có thể chọn, di chuyển và chỉnh sửa từng đối tượng mà không ảnh hưởng tới các đối tượng khác.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong đồ hoạ vector, một đối tượng đường (path) được cấu tạo từ những thành phần nào?","o":["Từ các điểm nút (điểm neo) và các đoạn thẳng hoặc đường cong nối các điểm nút đó","Từ hàng nghìn điểm ảnh xếp thành hàng dài","Từ các kí tự liên tiếp nhau không có khoảng trắng","Từ nhiều lớp (layer) chồng lên nhau"],"a":"Từ các điểm nút (điểm neo) và các đoạn thẳng hoặc đường cong nối các điểm nút đó","h":"Khi dùng công cụ Pen/Bút để vẽ, em lần lượt đặt các điểm trên trang vẽ và nối chúng lại.","e":"Đối tượng đường (path) trong đồ hoạ vector gồm các điểm nút (điểm neo) được nối với nhau bằng các đoạn thẳng hoặc đường cong. Thay đổi vị trí các điểm nút hoặc điều chỉnh tay nắm cong sẽ làm thay đổi hình dạng của đường, đây là cách tạo ra các hình vẽ tự do và uốn lượn.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong thiết kế đồ hoạ, việc phân chia các đối tượng vào những lớp (layer) khác nhau có tác dụng chính là gì?","o":["Làm cho tệp đồ hoạ có dung lượng nhỏ đi một nửa","Giúp quản lí và chỉnh sửa từng nhóm đối tượng một cách độc lập; thứ tự các lớp quyết định đối tượng nào nằm trên, đối tượng nào nằm dưới khi hiển thị","Tự động đổi màu toàn bộ bản vẽ sang dạng đen trắng","Bắt buộc mọi đối tượng phải nằm trên cùng một lớp mới in được"],"a":"Giúp quản lí và chỉnh sửa từng nhóm đối tượng một cách độc lập; thứ tự các lớp quyết định đối tượng nào nằm trên, đối tượng nào nằm dưới khi hiển thị","h":"Hãy hình dung các lớp như những tấm phim trong suốt xếp chồng lên nhau.","e":"Lớp (layer) giống như các tấm phim trong suốt xếp chồng lên nhau, mỗi lớp chứa một nhóm đối tượng. Làm việc theo lớp giúp chỉnh sửa từng phần mà không ảnh hưởng phần khác, đồng thời thứ tự xếp lớp quyết định đối tượng ở lớp trên sẽ che đối tượng ở lớp dưới khi hiển thị và khi xuất bản phẩm.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Vì sao người ta cần dùng ngôn ngữ lập trình bậc cao thay vì viết chương trình trực tiếp bằng ngôn ngữ máy (dãy số 0 và 1)?","o":["Vì ngôn ngữ máy chạy chậm hơn ngôn ngữ bậc cao rất nhiều","Vì máy tính ngày nay không còn hiểu được ngôn ngữ máy nữa","Vì ngôn ngữ bậc cao có các câu lệnh gần với ngôn ngữ tự nhiên, dễ học, dễ viết và ít phụ thuộc vào từng loại máy tính","Vì ngôn ngữ bậc cao không cần tuân theo quy tắc cú pháp nào"],"a":"Vì ngôn ngữ bậc cao có các câu lệnh gần với ngôn ngữ tự nhiên, dễ học, dễ viết và ít phụ thuộc vào từng loại máy tính","h":"Hãy so sánh việc đọc dãy số 0/1 với việc đọc các từ khoá như print, if, while.","e":"Ngôn ngữ máy gồm các dãy bit khó nhớ, khó viết và phụ thuộc chặt chẽ vào từng loại máy. Ngôn ngữ lập trình bậc cao dùng từ khoá và cú pháp gần với ngôn ngữ tự nhiên, giúp người lập trình dễ học, dễ viết, dễ kiểm tra lỗi và chương trình có thể chạy trên nhiều loại máy khác nhau.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Python thuộc nhóm ngôn ngữ thông dịch. Điều đó có nghĩa là:","o":["Chương trình được dịch toàn bộ sang ngôn ngữ máy một lần trước khi chạy, tạo thành tệp thực thi độc lập","Chương trình Python có thể chạy mà không cần bất kì phần mềm hỗ trợ nào","Python tự động dịch các câu tiếng Anh sang tiếng Việt","Chương trình được trình thông dịch dịch và thực hiện từng lệnh (từng dòng) ngay trong quá trình chạy"],"a":"Chương trình được trình thông dịch dịch và thực hiện từng lệnh (từng dòng) ngay trong quá trình chạy","h":"Hãy liên hệ với 'phiên dịch viên' dịch từng câu trong hội thoại, khác với 'biên dịch' dịch cả cuốn sách trước.","e":"Ngôn ngữ thông dịch như Python có trình thông dịch đọc và thực hiện chương trình theo từng lệnh khi chạy, không tạo ra tệp mã máy độc lập trước đó. Nhờ vậy việc viết và thử chương trình thuận tiện, nhưng máy phải có trình thông dịch mới chạy được chương trình.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Xét định nghĩa hàm: def tinh_tong(a, b): return a + b. Khi viết lệnh gọi tinh_tong(3, 5) thì các giá trị 3 và 5 được gọi là gì?","o":["Đối số (tham số thực) truyền cho hàm khi gọi hàm","Tham số hình thức của hàm","Biến toàn cục của chương trình","Giá trị mặc định của hàm"],"a":"Đối số (tham số thực) truyền cho hàm khi gọi hàm","h":"Cần phân biệt: biến viết trong ngoặc khi ĐỊNH NGHĨA hàm và giá trị cụ thể khi GỌI hàm có tên gọi khác nhau.","e":"Trong định nghĩa hàm, a và b là các tham số hình thức (tham số). Khi gọi hàm tinh_tong(3, 5), các giá trị cụ thể 3 và 5 được gọi là đối số (tham số thực); chúng lần lượt được gán cho a và b để hàm thực hiện.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Cho chương trình Python sau:\n\ndef gioi_thieu(ten, lop='10A1'):\n    return 'Học sinh ' + ten + ' học lớp ' + lop\n\nprint(gioi_thieu('Bình'))\n\nKết quả in ra là gì?","o":["Học sinh Bình học lớp ","Học sinh Bình học lớp 10A1","Chương trình báo lỗi vì thiếu đối số thứ hai","Học sinh  học lớp 10A1"],"a":"Học sinh Bình học lớp 10A1","h":"Tham số lop đã có giá trị mặc định nên khi gọi hàm không bắt buộc phải truyền giá trị cho nó.","e":"Tham số lop có giá trị mặc định là '10A1'. Khi gọi gioi_thieu('Bình') mà không truyền đối số cho lop, hàm dùng giá trị mặc định nên kết quả là 'Học sinh Bình học lớp 10A1'.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Mục đích chính của việc kiểm thử chương trình là gì?","o":["Làm cho chương trình chạy nhanh hơn trên mọi máy tính","Dịch chương trình từ ngôn ngữ bậc cao sang ngôn ngữ máy","Phát hiện các lỗi còn tiềm ẩn và kiểm tra xem chương trình có thực hiện đúng yêu cầu đặt ra hay không trước khi đưa vào sử dụng","Làm cho mã nguồn của chương trình ngắn gọn hơn"],"a":"Phát hiện các lỗi còn tiềm ẩn và kiểm tra xem chương trình có thực hiện đúng yêu cầu đặt ra hay không trước khi đưa vào sử dụng","h":"Kiểm thử được thực hiện bằng cách chạy chương trình với nhiều bộ dữ liệu khác nhau và so sánh kết quả với kết quả đúng đã biết.","e":"Kiểm thử là quá trình chạy chương trình với các bộ dữ liệu kiểm thử để phát hiện lỗi và xác nhận chương trình cho kết quả đúng theo yêu cầu. Chỉ sau khi kiểm thử đạt yêu cầu, chương trình mới được đưa vào sử dụng thực tế.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Khi xây dựng bộ dữ liệu kiểm thử cho một chương trình, ngoài các trường hợp thông thường, người kiểm thử cần đưa thêm loại trường hợp nào để dễ phát hiện lỗi?","o":["Các trường hợp sao chép y hệt trường hợp thông thường","Các trường hợp chỉ gồm dữ liệu trống, không có giá trị nào","Các trường hợp có dữ liệu càng dài càng tốt, không cần biết kết quả đúng","Các trường hợp đặc biệt và trường hợp biên, ví dụ giá trị đầu vào lớn nhất, nhỏ nhất hoặc bất thường"],"a":"Các trường hợp đặc biệt và trường hợp biên, ví dụ giá trị đầu vào lớn nhất, nhỏ nhất hoặc bất thường","h":"Lỗi chương trình thường 'núp' ở những tình huống ít gặp nhất chứ không phải ở tình huống quen thuộc.","e":"Một bộ dữ liệu kiểm thử tốt gồm cả trường hợp thông thường lẫn các trường hợp đặc biệt, trường hợp biên (giá trị ở giới hạn lớn nhất/nhỏ nhất, giá trị bất thường). Các lỗi lôgic thường chỉ bộc lộ ở những trường hợp biên này, nên thiếu chúng thì kiểm thử sẽ bỏ sót lỗi.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Chức năng chính của hệ điều hành trong máy tính là gì?","o":["Soạn thảo văn bản và làm bảng tính","Quản lí, điều phối các thiết bị phần cứng và cung cấp môi trường để các phần mềm ứng dụng hoạt động","Chơi trò chơi và nghe nhạc","Thiết kế đồ hoạ chuyên nghiệp"],"a":"Quản lí, điều phối các thiết bị phần cứng và cung cấp môi trường để các phần mềm ứng dụng hoạt động","h":"Hãy nghĩ xem phần mềm nào phải chạy trước tiên để các phần mềm khác có thể hoạt động trên máy tính.","e":"Hệ điều hành là phần mềm hệ thống quan trọng nhất: nó quản lí và điều phối mọi thiết bị phần cứng (CPU, bộ nhớ, ổ đĩa, thiết bị ngoại vi), đồng thời tạo môi trường để người dùng cài đặt và chạy các phần mềm ứng dụng. Soạn thảo văn bản, nghe nhạc hay thiết kế đồ hoạ là công việc của phần mềm ứng dụng.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Phần mềm nào sau đây là một hệ điều hành?","o":["Microsoft Windows","Microsoft Word","Google Chrome","Adobe Photoshop"],"a":"Microsoft Windows","h":"Hãy phân biệt phần mềm hệ thống với các phần mềm ứng dụng quen thuộc.","e":"Microsoft Windows là hệ điều hành — phần mềm hệ thống quản lí phần cứng và điều hành hoạt động của máy tính. Microsoft Word là phần mềm soạn thảo văn bản, Google Chrome là trình duyệt web, Adobe Photoshop là phần mềm chỉnh sửa ảnh; cả ba đều là phần mềm ứng dụng chạy trên nền hệ điều hành.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Hệ điều hành Linux được coi là hệ điều hành nguồn mở vì lí do nào sau đây?","o":["Vì Linux luôn được bán kèm theo máy tính mới","Vì Linux chỉ chạy được trên các máy chủ lớn","Vì mã nguồn của Linux được công khai, người dùng được phép sử dụng, sao chép, chỉnh sửa và phân phối lại theo giấy phép nguồn mở","Vì Linux không cần cài đặt mà chạy trực tiếp trên Internet"],"a":"Vì mã nguồn của Linux được công khai, người dùng được phép sử dụng, sao chép, chỉnh sửa và phân phối lại theo giấy phép nguồn mở","h":"Đặc trưng của phần mềm nguồn mở nằm ở việc mã nguồn của nó có được công khai hay không.","e":"Phần mềm nguồn mở là phần mềm mà mã nguồn được công bố công khai, cho phép mọi người tự do sử dụng, sao chép, nghiên cứu, chỉnh sửa và phân phối lại theo điều khoản giấy phép. Linux là ví dụ tiêu biểu của hệ điều hành nguồn mở, đối lập với các hệ điều hành nguồn đóng như Windows hay macOS.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Để lưu trữ lâu dài toàn bộ dữ liệu học tập, ảnh và video có dung lượng rất lớn (hàng trăm GB) trên máy tính cá nhân, thiết bị lưu trữ nào sau đây phù hợp nhất?","o":["Đĩa CD-ROM có dung lượng khoảng 700 MB","Thẻ nhớ điện thoại dung lượng 16 GB","USB dung lượng 32 GB","Ổ cứng HDD/SSD trong máy tính, có dung lượng lớn tới hàng nghìn GB (nhiều TB)"],"a":"Ổ cứng HDD/SSD trong máy tính, có dung lượng lớn tới hàng nghìn GB (nhiều TB)","h":"Hãy so sánh dung lượng của các thiết bị lưu trữ được nêu ra.","e":"Ổ cứng (HDD hoặc SSD) lắp trong máy tính có dung lượng lớn nhất trong các lựa chọn, thường từ vài trăm GB đến nhiều TB, phù hợp để lưu trữ lâu dài khối lượng dữ liệu lớn. CD-ROM chỉ chứa khoảng 700 MB, thẻ nhớ 16 GB hay USB 32 GB chỉ thích hợp để sao chép, mang theo lượng dữ liệu nhỏ.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Em đã lưu một tệp báo cáo trên máy tính từ lâu nhưng không nhớ rõ tệp nằm trong thư mục nào, chỉ nhớ tên tệp có chứa từ 'BaoCao'. Cách tìm tệp nhanh nhất là gì?","o":["Mở lần lượt tất cả các thư mục trên ổ đĩa để tìm","Dùng công cụ tìm kiếm của hệ điều hành, nhập từ khoá 'BaoCao' và có thể lọc thêm theo loại tệp hoặc ngày sửa đổi","Đổi tên tất cả các thư mục cho dễ nhớ rồi tìm lại","Xoá bớt các tệp không cần thiết để danh sách tệp ngắn lại"],"a":"Dùng công cụ tìm kiếm của hệ điều hành, nhập từ khoá 'BaoCao' và có thể lọc thêm theo loại tệp hoặc ngày sửa đổi","h":"Hệ điều hành có sẵn công cụ giúp tìm tệp theo tên mà không cần nhớ vị trí lưu.","e":"Mọi hệ điều hành đều có công cụ tìm kiếm tệp tin: chỉ cần nhập một phần tên tệp mà em nhớ được, hệ điều hành sẽ quét và liệt kê các tệp khớp, em còn có thể thu hẹp kết quả bằng cách lọc theo loại tệp, kích thước hay ngày sửa đổi. Việc mở từng thư mục thủ công mất rất nhiều thời gian và dễ bỏ sót.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Cách sao lưu dữ liệu nào sau đây an toàn nhất cho các tệp tin quan trọng?","o":["Ngoài bản chính trên máy tính, lưu thêm ít nhất một bản sao dự phòng trên thiết bị lưu trữ ngoài hoặc dịch vụ lưu trữ đám mây","Chỉ lưu một bản duy nhất trên màn hình nền (Desktop) của máy tính","Lưu thêm một bản sao trong cùng thư mục với tệp gốc","Đổi đuôi của tệp tin để tránh bị xoá nhầm"],"a":"Ngoài bản chính trên máy tính, lưu thêm ít nhất một bản sao dự phòng trên thiết bị lưu trữ ngoài hoặc dịch vụ lưu trữ đám mây","h":"Hãy nghĩ xem điều gì xảy ra nếu ổ cứng của máy tính bị hỏng hoàn toàn.","e":"Sao lưu an toàn nghĩa là bản sao phải nằm ở một nơi độc lập với bản chính: nếu máy tính hỏng, mất hoặc nhiễm mã độc thì bản sao trên ổ cứng ngoài hay trên đám mây vẫn còn nguyên. Lưu thêm bản sao trong cùng thư mục hoặc cùng ổ đĩa không có tác dụng khi ổ đĩa đó bị hỏng.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong Python, khai báo nào sau đây tạo ra một mảng hai chiều (bảng) gồm 2 hàng, mỗi hàng có 3 số 0?","o":["a = [0, 0, 0, 0, 0, 0]","a = [[0, 0], [0, 0], [0, 0]]","a = [[0, 0, 0], [0, 0, 0]]","a = [[0, 0, 0]]"],"a":"a = [[0, 0, 0], [0, 0, 0]]","h":"Mảng hai chiều trong Python là một danh sách mà mỗi phần tử lại là một danh sách (một hàng).","e":"Mảng hai chiều được biểu diễn bằng danh sách của các danh sách: mỗi danh sách con là một hàng. a = [[0, 0, 0], [0, 0, 0]] có 2 danh sách con (2 hàng), mỗi danh sách con có 3 phần tử (3 cột). Phương án [[0, 0], [0, 0], [0, 0]] tạo bảng 3 hàng × 2 cột; [0, 0, 0, 0, 0, 0] chỉ là mảng một chiều.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Cho bảng điểm a = [[7, 8], [9, 6]] trong Python. Giá trị của biểu thức a[0][0] + a[1][1] bằng bao nhiêu?","o":["15","13","17","16"],"a":"13","h":"a[i][j] là phần tử ở hàng i, cột j (chỉ số hàng và cột đều bắt đầu từ 0).","e":"a[0][0] là phần tử ở hàng 0, cột 0, tức là 7. a[1][1] là phần tử ở hàng 1, cột 1, tức là 6. Vậy a[0][0] + a[1][1] = 7 + 6 = 13.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Độ phức tạp thời gian của một thuật toán dùng để đánh giá điều gì?","o":["Số dòng lệnh của chương trình viết thuật toán đó","Dung lượng bộ nhớ tối đa mà chương trình chiếm khi chạy","Thời gian chạy chính xác tính bằng giây trên mọi máy tính","Mức độ tăng của thời gian thực hiện thuật toán khi kích thước dữ liệu đầu vào tăng lên"],"a":"Mức độ tăng của thời gian thực hiện thuật toán khi kích thước dữ liệu đầu vào tăng lên","h":"Độ phức tạp thời gian không cho biết thời gian chạy tuyệt đối mà cho biết xu hướng tăng của thời gian theo dữ liệu.","e":"Độ phức tạp thời gian mô tả tốc độ tăng trưởng của thời gian thực hiện thuật toán theo kích thước đầu vào n, thường viết bằng kí hiệu O như O(n), O(n²). Nó không phụ thuộc vào tốc độ của từng máy tính cụ thể nên dùng để so sánh, đánh giá các thuật toán với nhau. Dung lượng bộ nhớ là độ phức tạp không gian, là khái niệm khác.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Một thuật toán có độ phức tạp thời gian O(n²). Khi kích thước dữ liệu đầu vào tăng gấp đôi (từ n lên 2n), thời gian thực hiện của thuật toán tăng khoảng bao nhiêu lần?","o":["Tăng khoảng 2 lần","Không thay đổi","Tăng khoảng 4 lần","Tăng khoảng 8 lần"],"a":"Tăng khoảng 4 lần","h":"Với độ phức tạp O(n²), thời gian tỉ lệ với bình phương của kích thước dữ liệu.","e":"Thời gian thực hiện của thuật toán O(n²) tỉ lệ với n². Khi dữ liệu tăng gấp đôi, thời gian tăng (2n)²/n² = 4 lần. Đây là lí do các thuật toán O(n²) trở nên rất chậm khi xử lí dữ liệu lớn, trong khi thuật toán O(n) chỉ tăng thời gian gấp đôi trong tình huống tương tự.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Khi kiểm thử một chương trình, người ta chạy chương trình với các bộ dữ liệu kiểm thử đã chuẩn bị trước chủ yếu nhằm mục đích gì?","o":["Phát hiện lỗi của chương trình bằng cách đối chiếu kết quả thu được với kết quả đúng đã biết trước","Làm cho chương trình chạy nhanh hơn","Dịch chương trình thành ngôn ngữ máy","Rút ngắn độ dài mã nguồn của chương trình"],"a":"Phát hiện lỗi của chương trình bằng cách đối chiếu kết quả thu được với kết quả đúng đã biết trước","h":"Kiểm thử gắn liền với việc tìm ra những chỗ chương trình cho kết quả sai.","e":"Kiểm thử chương trình là quá trình chạy chương trình với các bộ dữ liệu kiểm thử (test case) mà kết quả đúng đã được tính trước, rồi đối chiếu với kết quả chương trình cho ra. Chênh lệch giữa hai kết quả giúp phát hiện và khoanh vùng lỗi để sửa. Kiểm thử không làm chương trình nhanh hơn hay dịch chương trình sang ngôn ngữ máy.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Một chương trình yêu cầu nhập điểm số là số thực trong khoảng từ 0 đến 10. Bộ dữ liệu kiểm thử nào sau đây chú trọng kiểm tra các trường hợp biên?","o":["Chỉ gồm các giá trị điểm ở giữa khoảng, ví dụ 5 và 6","Gồm nhiều giá trị nguyên bất kì từ 1 đến 9","Gồm các giá trị thập phân như 7,5 và 8,25","Gồm các giá trị tại biên và sát ngoài biên: 0, 10, −0,5 và 10,5"],"a":"Gồm các giá trị tại biên và sát ngoài biên: 0, 10, −0,5 và 10,5","h":"Trường hợp biên là các giá trị nằm đúng tại giới hạn cho phép và ngay sát phía ngoài giới hạn đó.","e":"Lỗi chương trình rất hay xảy ra tại các giá trị biên: điểm 0 và 10 là hai đầu mút của khoảng hợp lệ, còn −0,5 và 10,5 nằm ngay ngoài khoảng để kiểm tra chương trình có từ chối đúng các giá trị không hợp lệ hay không. Chỉ kiểm thử với các giá trị ở giữa khoảng sẽ bỏ sót nhóm lỗi quan trọng này.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Câu lệnh import math đặt ở đầu chương trình Python có tác dụng gì?","o":["Khai báo một biến mới tên là math","Nạp thư viện math vào chương trình để có thể sử dụng các hàm toán học có sẵn như math.sqrt(), math.sin()","In chữ 'math' ra màn hình","Xoá các hàm toán học khỏi chương trình"],"a":"Nạp thư viện math vào chương trình để có thể sử dụng các hàm toán học có sẵn như math.sqrt(), math.sin()","h":"Từ khoá import liên quan đến việc đưa một thư viện có sẵn vào chương trình.","e":"Python cung cấp nhiều thư viện (mô đun) có sẵn chứa các hàm đã được viết và kiểm thử kĩ. Câu lệnh import math nạp thư viện toán học math, sau đó chương trình dùng các hàm của thư viện qua cú pháp math.sqrt(), math.sin()... mà không cần tự viết lại các hàm đó.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Việc thiết kế chương trình theo mô đun và sử dụng các thư viện có sẵn mang lại lợi ích quan trọng nào sau đây?","o":["Chương trình luôn chạy nhanh hơn mọi cách viết khác","Không cần kiểm thử chương trình nữa","Chương trình dễ bảo trì, dễ kiểm thử từng phần và có thể tái sử dụng các phần đã viết cho nhiều chương trình khác","Mã nguồn trở nên dài hơn và khó quản lí hơn"],"a":"Chương trình dễ bảo trì, dễ kiểm thử từng phần và có thể tái sử dụng các phần đã viết cho nhiều chương trình khác","h":"Hãy nghĩ đến việc chia một công việc lớn thành các phần nhỏ, độc lập và dùng lại được.","e":"Thiết kế theo mô đun chia chương trình thành các phần nhỏ, mỗi phần lo một nhiệm vụ rõ ràng: mỗi mô đun có thể được viết, kiểm thử và sửa lỗi độc lập, sau đó tái sử dụng trong nhiều chương trình. Dùng thư viện có sẵn giúp tiết kiệm thời gian vì không phải viết lại các chức năng phổ biến đã được kiểm chứng. Tuy nhiên chương trình vẫn cần được kiểm thử đầy đủ.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Một hệ cơ sở dữ liệu (theo nghĩa đầy đủ) bao gồm các thành phần chính nào?","o":["Cơ sở dữ liệu, hệ quản trị cơ sở dữ liệu và các phần mềm ứng dụng (cùng người sử dụng) khai thác cơ sở dữ liệu đó","Chỉ gồm các bảng dữ liệu được lưu trên đĩa","Chỉ gồm máy chủ và hệ điều hành","Gồm trình duyệt web và mạng Internet"],"a":"Cơ sở dữ liệu, hệ quản trị cơ sở dữ liệu và các phần mềm ứng dụng (cùng người sử dụng) khai thác cơ sở dữ liệu đó","h":"Hãy phân biệt ba khái niệm: cơ sở dữ liệu, hệ quản trị cơ sở dữ liệu và hệ cơ sở dữ liệu.","e":"Hệ cơ sở dữ liệu là một hệ thống hoàn chỉnh gồm: cơ sở dữ liệu (tập dữ liệu được tổ chức), hệ quản trị cơ sở dữ liệu (phần mềm tạo lập, cập nhật và truy xuất dữ liệu) và các phần mềm ứng dụng cùng người sử dụng khai thác dữ liệu đó. Chỉ riêng các bảng dữ liệu thì mới là cơ sở dữ liệu, chưa phải là hệ cơ sở dữ liệu.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong cơ sở dữ liệu thư viện, bảng SACH có các cột MaSach, TenSach, TacGia, NamXB và mỗi dòng của bảng chứa thông tin về một cuốn sách cụ thể. Phát biểu nào sau đây đúng?","o":["Mỗi cột của bảng là một bản ghi, mỗi dòng của bảng là một trường","Cả bảng chỉ gồm một trường duy nhất là TenSach","Mỗi dòng là một trường, mỗi cột là một thuộc tính của sách","Mỗi cột (MaSach, TenSach, TacGia, NamXB) là một trường mô tả một thuộc tính của sách; mỗi dòng là một bản ghi chứa thông tin về một cuốn sách cụ thể"],"a":"Mỗi cột (MaSach, TenSach, TacGia, NamXB) là một trường mô tả một thuộc tính của sách; mỗi dòng là một bản ghi chứa thông tin về một cuốn sách cụ thể","h":"Hãy nhớ: trường tương ứng với cột (thuộc tính), bản ghi tương ứng với hàng (một đối tượng cụ thể).","e":"Trong một bảng của cơ sở dữ liệu quan hệ: mỗi cột được gọi là một trường (field), mô tả một thuộc tính chung của các đối tượng (mã sách, tên sách, tác giả, năm xuất bản); mỗi hàng được gọi là một bản ghi (record), chứa trọn vẹn thông tin về một đối tượng cụ thể, ở đây là một cuốn sách.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Vì sao trường Họ và tên học sinh KHÔNG nên được chọn làm khoá chính của bảng HOCSINH?","o":["Vì trường họ và tên chứa chữ cái chứ không chứa số","Vì nhiều học sinh có thể trùng họ và tên, trong khi giá trị của khoá chính phải khác nhau để phân biệt duy nhất từng bản ghi và không được để trống","Vì họ và tên của học sinh viết quá dài","Vì khoá chính bắt buộc phải viết bằng tiếng Anh"],"a":"Vì nhiều học sinh có thể trùng họ và tên, trong khi giá trị của khoá chính phải khác nhau để phân biệt duy nhất từng bản ghi và không được để trống","h":"Hãy nhớ điều kiện bắt buộc đối với các giá trị của khoá chính trong một bảng.","e":"Khoá chính dùng để xác định duy nhất mỗi bản ghi trong bảng, vì vậy các giá trị của khoá chính không được trùng nhau và không được để trống. Họ và tên không đảm bảo tính duy nhất vì nhiều học sinh có thể trùng cả họ lẫn tên, nên người ta thường dùng mã học sinh làm khoá chính.","t":"tin-lop11","g":11,"l":"thu-thach"},{"p":"Trong cơ sở dữ liệu quan hệ, kết quả của một câu lệnh truy vấn SELECT là gì?","o":["Một tệp âm thanh chứa dữ liệu của bảng","Một giá trị số duy nhất","Một bảng kết quả gồm các bản ghi và các trường thoả mãn yêu cầu của câu truy vấn","Toàn bộ phần cứng của máy chủ cơ sở dữ liệu"],"a":"Một bảng kết quả gồm các bản ghi và các trường thoả mãn yêu cầu của câu truy vấn","h":"Truy vấn trích rút một phần dữ liệu từ (các) bảng có sẵn và trình bày lại dưới dạng quen thuộc.","e":"Câu lệnh SELECT không làm thay đổi dữ liệu gốc mà trích rút ra một bảng kết quả: gồm những bản ghi thoả mãn điều kiện (mệnh đề WHERE) và những trường được liệt kê sau SELECT. Người dùng xem và sử dụng bảng kết quả này như một bảng dữ liệu thông thường.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Một bức ảnh ghép gồm lớp dưới là ảnh phong cảnh, lớp trên là ảnh chân dung đã xoá nền nên các vùng xung quanh nhân vật trở nên trong suốt. Khi xem bức ảnh đã ghép, những vùng trong suốt của lớp trên sẽ hiển thị gì?","o":["Phần phong cảnh của lớp dưới sẽ hiện lên qua các vùng trong suốt đó","Các vùng trong suốt tự động chuyển thành màu trắng","Các vùng trong suốt tự động chuyển thành màu đen","Lớp chân dung sẽ bị xoá khỏi bức ảnh"],"a":"Phần phong cảnh của lớp dưới sẽ hiện lên qua các vùng trong suốt đó","h":"Hãy hình dung các lớp ảnh như những tấm kính trong chồng lên nhau.","e":"Các lớp (layer) trong phần mềm chỉnh sửa ảnh hoạt động giống như các tấm phim trong suốt xếp chồng: tại những vùng trong suốt của một lớp, ta nhìn thấy nội dung của các lớp nằm bên dưới. Nhờ vậy, khi xoá nền của ảnh chân dung (lớp trên), phần phong cảnh của lớp dưới hiện lên và hai ảnh hoà thành một bức ảnh ghép hoàn chỉnh.","t":"tin-lop11","g":11,"l":"kho"},{"p":"Trong phần mềm biên tập phim, vùng dòng thời gian (timeline) được sử dụng để làm gì?","o":["Lưu trữ toàn bộ các tệp video gốc của dự án","Chỉnh sửa màu sắc cho từng bức ảnh tĩnh","Tạo hiệu ứng chữ chạy cho tiêu đề phim","Sắp xếp, cắt và ghép nối các đoạn video, âm thanh theo đúng trình tự thời gian xuất hiện trong bộ phim"],"a":"Sắp xếp, cắt và ghép nối các đoạn video, âm thanh theo đúng trình tự thời gian xuất hiện trong bộ phim","h":"Tên gọi 'dòng thời gian' gợi ý đến trình tự trước – sau của các cảnh trong phim.","e":"Dòng thời gian (timeline) là khu vực làm việc chính của phần mềm biên tập phim: các đoạn video, hình ảnh và âm thanh được đặt nối tiếp nhau trên đó theo trục thời gian. Người dựng phim cắt bỏ phần thừa, sắp xếp lại thứ tự các cảnh và đồng bộ hình ảnh với âm thanh ngay trên dòng thời gian này.","t":"tin-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong cấu trúc một trang HTML cơ bản, toàn bộ nội dung hiển thị trên cửa sổ trình duyệt (văn bản, hình ảnh, liên kết…) được đặt trong cặp thẻ nào?","o":["<head> … </head>","<body> … </body>","<title> … </title>","<html> … </html>"],"a":"<body> … </body>","h":"Phần đầu <head> chứa thông tin mô tả về trang, không hiển thị trực tiếp nội dung.","e":"Một trang HTML gồm thẻ <html> bao ngoài cùng; bên trong có phần <head> chứa thông tin mô tả trang (tiêu đề thẻ tab, khai báo bảng mã…) và phần <body> chứa toàn bộ nội dung được hiển thị cho người xem.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong HTML, cặp thẻ nào sau đây tạo tiêu đề có cỡ chữ lớn nhất, và thẻ nào tạo một đoạn văn bản thông thường?","o":["Tiêu đề lớn nhất: <h1>; đoạn văn: <p>","Tiêu đề lớn nhất: <h6>; đoạn văn: <p>","Tiêu đề lớn nhất: <h1>; đoạn văn: <div>","Tiêu đề lớn nhất: <title>; đoạn văn: <text>"],"a":"Tiêu đề lớn nhất: <h1>; đoạn văn: <p>","h":"HTML có 6 mức tiêu đề, đánh số từ 1 đến 6, số càng nhỏ chữ càng lớn.","e":"HTML cung cấp 6 mức tiêu đề từ <h1> (lớn nhất, quan trọng nhất) đến <h6> (nhỏ nhất). Đoạn văn bản thông thường được tạo bằng thẻ <p> (paragraph).","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Muốn chèn một hình ảnh vào trang web và tạo một liên kết tới trang khác, bạn cần dùng đúng cặp thẻ và thuộc tính nào?","o":["Chèn ảnh: <img href=\"anh.jpg\">; liên kết: <a src=\"trang.html\">","Chèn ảnh: <image link=\"anh.jpg\">; liên kết: <link href=\"trang.html\">","Chèn ảnh: <img src=\"anh.jpg\">; liên kết: <a href=\"trang.html\">","Chèn ảnh: <a src=\"anh.jpg\">; liên kết: <img href=\"trang.html\">"],"a":"Chèn ảnh: <img src=\"anh.jpg\">; liên kết: <a href=\"trang.html\">","h":"Thuộc tính chỉ đường dẫn của tệp ảnh có tên bắt đầu bằng chữ s, còn thuộc tính địa chỉ đích của liên kết có tên bắt đầu bằng chữ h.","e":"Thẻ <img> dùng thuộc tính src để chỉ đường dẫn tới tệp hình ảnh. Thẻ <a> (anchor) tạo liên kết, dùng thuộc tính href để chỉ địa chỉ trang đích; nội dung nằm giữa <a> và </a> là phần người dùng nhấp vào.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Trong HTML, để tạo một danh sách được đánh số thứ tự tự động (1, 2, 3…) và một danh sách chỉ có dấu đầu dòng, bạn dùng các thẻ nào?","o":["Cả hai đều dùng <ul>, khác nhau ở thuộc tính type","Đánh số: <li>; dấu đầu dòng: <ul>","Đánh số: <ol>; dấu đầu dòng: <li>","Đánh số: <ol>; dấu đầu dòng: <ul>; mỗi mục trong cả hai đều dùng thẻ <li>"],"a":"Đánh số: <ol>; dấu đầu dòng: <ul>; mỗi mục trong cả hai đều dùng thẻ <li>","h":"Tên thẻ là viết tắt tiếng Anh: ol = ordered list (danh sách có thứ tự), ul = unordered list (danh sách không thứ tự).","e":"Danh sách có thứ tự dùng thẻ <ol>, danh sách không thứ tự dùng thẻ <ul>. Trong cả hai loại, mỗi mục của danh sách đều được viết bằng thẻ <li> (list item).","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Phát biểu nào phân biệt đúng vai trò của HTML và CSS trong một trang web?","o":["HTML dùng để trang trí màu sắc, CSS dùng để viết nội dung văn bản","HTML và CSS là hai tên gọi khác nhau của cùng một ngôn ngữ","HTML xây dựng cấu trúc và nội dung của trang; CSS quy định cách trình bày, định dạng (màu sắc, phông chữ, bố cục) cho các phần tử HTML","CSS dùng để lưu trữ dữ liệu của trang web, HTML dùng để hiển thị dữ liệu đó"],"a":"HTML xây dựng cấu trúc và nội dung của trang; CSS quy định cách trình bày, định dạng (màu sắc, phông chữ, bố cục) cho các phần tử HTML","h":"Hãy liên tưởng: HTML giống như khung xương và nội dung của ngôi nhà, CSS giống như sơn, trang trí.","e":"HTML (HyperText Markup Language) tạo nên cấu trúc và nội dung của trang web. CSS (Cascading Style Sheets) là ngôn ngữ định dạng, quy định cách các phần tử HTML được hiển thị: màu chữ, màu nền, phông chữ, kích thước, vị trí… Tách CSS khỏi HTML giúp trang web dễ chỉnh sửa giao diện mà không phải sửa nội dung.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong CSS, để áp dụng một định dạng cho mọi phần tử HTML có thuộc tính class=\"tieude\", bộ chọn (selector) nào sau đây được viết đúng?","o":["#tieude","class.tieude","*tieude",".tieude"],"a":".tieude","h":"Bộ chọn lớp bắt đầu bằng một dấu đặc biệt, khác với bộ chọn theo id (dấu #).","e":"Trong CSS: bộ chọn theo tên thẻ viết thẳng tên thẻ (ví dụ p, h1); bộ chọn theo lớp (class) bắt đầu bằng dấu chấm, ví dụ .tieude; bộ chọn theo id bắt đầu bằng dấu #, ví dụ #tieude. Một lớp có thể gán cho nhiều phần tử, còn id thường chỉ dùng cho một phần tử duy nhất.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Trong CSS, để đặt màu chữ là xanh dương, màu nền là vàng nhạt và phông chữ là Arial cho một phần tử, nhóm thuộc tính nào được dùng đúng?","o":["color: blue; background-color: lightyellow; font-family: Arial;","text-color: blue; background: lightyellow; font: Arial;","color: blue; bgcolor: lightyellow; font-name: Arial;","font-color: blue; background-color: lightyellow; text-font: Arial;"],"a":"color: blue; background-color: lightyellow; font-family: Arial;","h":"Thuộc tính đặt màu chữ trong CSS có tên rất ngắn, trùng với từ tiếng Anh chỉ 'màu sắc'.","e":"Trong CSS: thuộc tính color đặt màu chữ; background-color đặt màu nền; font-family đặt phông chữ (có thể liệt kê nhiều phông dự phòng cách nhau bằng dấu phẩy). Các tên như text-color, bgcolor, font-name không phải thuộc tính CSS chuẩn (bgcolor là thuộc tính HTML cũ, không nên dùng).","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Theo mô hình hộp (box model) trong CSS, phát biểu nào phân biệt đúng padding và margin của một phần tử?","o":["Padding là khoảng trống bên ngoài đường viền, margin là khoảng đệm bên trong đường viền","Padding là khoảng đệm giữa nội dung và đường viền của chính phần tử (bên trong); margin là khoảng trống từ đường viền của phần tử tới các phần tử xung quanh (bên ngoài)","Padding và margin là hai tên gọi của cùng một khoảng trống","Padding chỉ dùng cho hình ảnh, margin chỉ dùng cho văn bản"],"a":"Padding là khoảng đệm giữa nội dung và đường viền của chính phần tử (bên trong); margin là khoảng trống từ đường viền của phần tử tới các phần tử xung quanh (bên ngoài)","h":"Đi từ trong ra ngoài, hộp phần tử gồm: nội dung → padding → đường viền (border) → margin.","e":"Mỗi phần tử HTML được xem như một hộp gồm: nội dung (content) ở giữa, bao quanh bởi padding (khoảng đệm trong, nằm giữa nội dung và đường viền, có màu nền của phần tử), border (đường viền) và margin (khoảng trống ngoài cùng, trong suốt, tách phần tử này với các phần tử kề bên).","t":"tin-lop12","g":12,"l":"kho"},{"p":"Trong mạng máy tính, 'giao thức mạng' (protocol) được hiểu là gì?","o":["Một thiết bị dùng để kết nối các máy tính trong mạng","Một phần mềm chống virus cho hệ thống mạng","Tốc độ truyền dữ liệu tối đa của một đường truyền","Tập hợp các quy tắc, quy ước mà các thiết bị phải tuân theo khi truyền và nhận dữ liệu trên mạng"],"a":"Tập hợp các quy tắc, quy ước mà các thiết bị phải tuân theo khi truyền và nhận dữ liệu trên mạng","h":"Nhờ có giao thức chung, các máy tính của nhiều hãng khác nhau vẫn 'hiểu' được nhau khi trao đổi dữ liệu.","e":"Giao thức mạng là tập hợp các quy tắc quy định cách thức đóng gói, truyền, nhận và xử lí dữ liệu giữa các thiết bị trên mạng. Nhờ tuân theo cùng một giao thức, các thiết bị khác nhau vẫn giao tiếp được với nhau, tương tự như hai người cần nói chung một ngôn ngữ để trò chuyện.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Khi bạn gõ địa chỉ một trang web bắt đầu bằng https:// thay vì http://, điểm khác biệt quan trọng nhất về mặt truyền dữ liệu là gì?","o":["HTTPS là giao thức có mã hoá, giúp dữ liệu truyền giữa trình duyệt và máy chủ được bảo mật hơn HTTP","HTTPS chỉ dùng cho các trang web của ngân hàng, HTTP dùng cho mọi trang còn lại","HTTPS giúp trang web tải nhanh hơn HTTP trong mọi trường hợp","HTTP và HTTPS hoàn toàn giống nhau, chỉ khác cách viết tên"],"a":"HTTPS là giao thức có mã hoá, giúp dữ liệu truyền giữa trình duyệt và máy chủ được bảo mật hơn HTTP","h":"Chữ 'S' trong HTTPS là viết tắt của Secure (an toàn). Các giao thức như HTTP, HTTPS thuộc bộ giao thức TCP/IP dùng trên Internet.","e":"HTTP là giao thức truyền siêu văn bản giữa trình duyệt và máy chủ web, dữ liệu truyền ở dạng không mã hoá. HTTPS là phiên bản bảo mật của HTTP: dữ liệu được mã hoá trước khi truyền, giúp chống nghe lén và giả mạo, vì vậy các trang đăng nhập, thanh toán đều dùng HTTPS. Cả hai đều hoạt động trên nền bộ giao thức TCP/IP của Internet.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Trong một mạng máy tính, phát biểu nào phân biệt đúng chức năng của switch (thiết bị chuyển mạch) và router (bộ định tuyến)?","o":["Switch kết nối mạng gia đình với Internet, router chỉ nối các máy trong cùng một phòng","Switch kết nối các thiết bị trong cùng một mạng LAN và chuyển dữ liệu tới đúng thiết bị đích trong mạng đó; router kết nối các mạng khác nhau với nhau, ví dụ nối mạng LAN với Internet","Switch và router có chức năng hoàn toàn giống nhau, chỉ khác tên gọi","Router dùng để lưu trữ dữ liệu, switch dùng để hiển thị hình ảnh"],"a":"Switch kết nối các thiết bị trong cùng một mạng LAN và chuyển dữ liệu tới đúng thiết bị đích trong mạng đó; router kết nối các mạng khác nhau với nhau, ví dụ nối mạng LAN với Internet","h":"Hãy nhớ phạm vi hoạt động: switch làm việc bên trong một mạng, router làm việc giữa các mạng.","e":"Switch kết nối các thiết bị trong cùng một mạng cục bộ (LAN) và chuyển tiếp dữ liệu tới đúng cổng có thiết bị đích. Router kết nối nhiều mạng khác nhau và chọn đường đi cho dữ liệu giữa các mạng, điển hình là nối mạng LAN ở nhà/trường học với Internet. Modem là thiết bị khác: nó chuyển đổi tín hiệu giữa đường truyền của nhà cung cấp dịch vụ và tín hiệu số của mạng máy tính.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Trường học muốn thiết kế một mạng LAN đơn giản cho phòng máy gồm 20 máy tính, tất cả đều truy cập được Internet qua một đường truyền duy nhất. Sơ đồ kết nối hợp lí nhất là gì?","o":["Mỗi máy tính nối trực tiếp với một modem riêng để ra Internet","Nối các máy tính thành một vòng tròn khép kín, không cần thiết bị trung tâm nào","Tất cả máy tính nối vào một switch; switch nối với router; router nối với modem/đường truyền Internet của nhà cung cấp dịch vụ","Chỉ cần nối tất cả máy tính với nhau bằng cáp, mạng sẽ tự động có Internet"],"a":"Tất cả máy tính nối vào một switch; switch nối với router; router nối với modem/đường truyền Internet của nhà cung cấp dịch vụ","h":"Hãy xếp các thiết bị theo thứ tự luồng dữ liệu: máy tính → thiết bị tập trung trong LAN → thiết bị nối ra ngoài → đường truyền Internet.","e":"Trong mạng LAN hình sao, các máy tính nối về thiết bị trung tâm là switch để trao đổi dữ liệu nội bộ. Switch nối lên router để định tuyến dữ liệu ra vào mạng; router nối với modem/đường truyền của nhà cung cấp dịch vụ Internet. Cách bố trí này dễ quản lí, dễ mở rộng thêm máy và chỉ một đường truyền Internet dùng chung cho cả phòng.","t":"tin-lop12","g":12,"l":"kho"},{"p":"Khi xây dựng một trang web, công việc nào thuộc bước CHUẨN BỊ, được thực hiện trước tiên?","o":["Xác định mục đích của trang web, đối tượng người xem và nội dung cần đưa lên trang","Viết mã HTML và CSS cho từng trang con","Đưa trang web lên máy chủ để xuất bản","Kiểm tra và sửa lỗi hiển thị trên các trình duyệt khác nhau"],"a":"Xác định mục đích của trang web, đối tượng người xem và nội dung cần đưa lên trang","h":"Giống như xây nhà cần bản thiết kế, làm web cần rõ 'làm để làm gì, cho ai xem' trước khi bắt tay viết mã.","e":"Quy trình xây dựng trang web thường gồm: (1) Chuẩn bị — xác định mục đích, đối tượng người dùng, nội dung và cấu trúc trang; (2) Xây dựng — thiết kế giao diện, viết mã HTML/CSS, tạo các phần đầu, thân, chân trang, liên kết; (3) Kiểm tra, hoàn thiện; (4) Xuất bản lên máy chủ. Làm tốt bước chuẩn bị giúp việc xây dựng nhanh và đúng hướng.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Một học sinh đã viết xong các tệp HTML/CSS của trang web trên máy tính cá nhân. Muốn mọi người trên Internet truy cập được trang web đó, bạn ấy cần làm gì?","o":["Chỉ cần đặt các tệp vào thư mục dùng chung trong mạng LAN của trường","In địa chỉ thư mục chứa tệp trên máy cá nhân ra giấy để mọi người gõ theo","Gửi các tệp qua email cho từng người muốn xem","Đưa (tải) các tệp trang web lên một máy chủ web (dịch vụ lưu trữ web/hosting), thường gắn với một tên miền để người dùng truy cập qua trình duyệt"],"a":"Đưa (tải) các tệp trang web lên một máy chủ web (dịch vụ lưu trữ web/hosting), thường gắn với một tên miền để người dùng truy cập qua trình duyệt","h":"Tệp nằm trên máy cá nhân thì chỉ mình bạn xem được; trang web phải 'ở' trên một máy chủ luôn kết nối Internet.","e":"Để xuất bản trang web, các tệp HTML, CSS, hình ảnh… phải được tải lên máy chủ web (web server) của một dịch vụ lưu trữ (hosting). Máy chủ này hoạt động liên tục và phản hồi mỗi khi có người truy cập qua tên miền hoặc địa chỉ của trang. Có thể tạo trang bằng trình soạn thảo văn bản/mã nguồn (như Notepad++, Visual Studio Code) hoặc các phần mềm, nền tảng tạo web chuyên dụng rồi xuất bản theo cách này.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Việc nào sau đây thuộc công việc bảo trì máy tính ĐỊNH KÌ?","o":["Thay ổ cứng mới khi ổ cứng cũ đã hỏng hoàn toàn","Cài lại hệ điều hành sau khi máy bị nhiễm virus nặng","Vệ sinh bụi cho quạt và khe tản nhiệt, cập nhật hệ điều hành và phần mềm diệt virus theo lịch đều đặn","Mang máy ra tiệm khi máy không khởi động được nữa"],"a":"Vệ sinh bụi cho quạt và khe tản nhiệt, cập nhật hệ điều hành và phần mềm diệt virus theo lịch đều đặn","h":"Bảo trì định kì là việc làm thường xuyên để PHÒNG hỏng hóc, khác với sửa chữa chỉ làm khi máy đã hỏng.","e":"Bảo trì định kì gồm các việc làm thường xuyên theo kế hoạch nhằm giữ máy hoạt động ổn định và phòng ngừa sự cố: vệ sinh phần cứng (bụi ở quạt, khe tản nhiệt), cập nhật hệ điều hành và phần mềm, quét virus, dọn dẹp tệp rác, sao lưu dữ liệu. Còn thay linh kiện hỏng hay cài lại máy sau sự cố là công việc sửa chữa, không phải bảo trì định kì.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Một chiếc máy tính sau một thời gian sử dụng xuất hiện đồng thời các hiện tượng: chạy chậm bất thường dù không mở nhiều chương trình, quạt tản nhiệt kêu to và máy nóng nhanh, thỉnh thoảng tự khởi động lại. Nhận định và cách xử lí hợp lí nhất là gì?","o":["Đây là hiện tượng bình thường của mọi máy tính, không cần làm gì","Máy có dấu hiệu cần được kiểm tra, bảo trì/sửa chữa: vệ sinh hệ thống tản nhiệt, kiểm tra phần cứng và phần mềm để tìm nguyên nhân, thay vì tiếp tục sử dụng đến khi hỏng hẳn","Chỉ cần tắt máy để qua đêm là máy sẽ tự trở lại bình thường","Nên xoá toàn bộ dữ liệu cá nhân ngay vì chắc chắn ổ cứng đã hỏng hoàn toàn"],"a":"Máy có dấu hiệu cần được kiểm tra, bảo trì/sửa chữa: vệ sinh hệ thống tản nhiệt, kiểm tra phần cứng và phần mềm để tìm nguyên nhân, thay vì tiếp tục sử dụng đến khi hỏng hẳn","h":"Hãy chú ý cụm dấu hiệu: chậm + nóng + quạt kêu to thường liên quan đến tản nhiệt bị bụi bẩn hoặc linh kiện xuống cấp.","e":"Máy chạy chậm bất thường, nóng nhanh, quạt kêu to thường do hệ thống tản nhiệt bám bụi, keo tản nhiệt khô hoặc quạt xuống cấp khiến máy quá nhiệt và tự khởi động lại để bảo vệ linh kiện; cũng có thể kèm nguyên nhân phần mềm. Đây là dấu hiệu điển hình cho thấy máy cần được kiểm tra, bảo trì và sửa chữa kịp thời — tiếp tục dùng khi quá nhiệt có thể làm hỏng nặng thêm phần cứng.","t":"tin-lop12","g":12,"l":"kho"},{"p":"Trong quá trình làm video, bảng phân cảnh (storyboard) được lập ra để làm gì?","o":["Mô tả trước nội dung, hình ảnh của từng cảnh quay để việc quay và dựng video thuận lợi","Tăng dung lượng của tệp video","Tự động chèn nhạc nền vào video","Thay thế hoàn toàn cho phần mềm dựng video"],"a":"Mô tả trước nội dung, hình ảnh của từng cảnh quay để việc quay và dựng video thuận lợi","h":"Storyboard giống như 'bản vẽ thiết kế' của video.","e":"Bảng phân cảnh giúp người làm hình dung trước từng cảnh: quay cái gì, ở đâu, góc máy thế nào, nhờ đó quay và dựng video nhanh và ít thiếu sót.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi dựng video, thao tác cắt (trim) một đoạn video clip có tác dụng gì?","o":["Loại bỏ phần đầu hoặc phần cuối không cần thiết của đoạn clip","Làm cho âm thanh của video to hơn","Thay đổi màu sắc của toàn bộ video","Chuyển video thành tệp âm thanh"],"a":"Loại bỏ phần đầu hoặc phần cuối không cần thiết của đoạn clip","h":"Nghĩ tới việc dùng kéo cắt bỏ hai đầu của một sợi dây.","e":"Cắt (trim) giúp bỏ đi những phần thừa, phần quay hỏng ở đầu hoặc cuối mỗi đoạn clip trước khi ghép chúng lại với nhau.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Hiệu ứng chuyển cảnh (transition) trong phần mềm làm video được dùng để làm gì?","o":["Tạo sự chuyển đổi mượt mà, tự nhiên giữa hai đoạn clip liên tiếp","Tăng tốc độ phát của video","Xoá âm thanh của đoạn clip","Nén video thành tệp nhỏ hơn"],"a":"Tạo sự chuyển đổi mượt mà, tự nhiên giữa hai đoạn clip liên tiếp","h":"Nếu không có hiệu ứng này, hình ảnh sẽ nhảy đột ngột từ cảnh này sang cảnh khác.","e":"Hiệu ứng chuyển cảnh như mờ dần, trượt, lật trang... giúp việc chuyển từ đoạn clip này sang đoạn clip khác êm và dễ xem hơn.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Một video hoàn chỉnh thường kết hợp những thành phần nào sau đây?","o":["Hình ảnh động, lời thoại hoặc thuyết minh, nhạc nền và hiệu ứng âm thanh","Chỉ có hình ảnh động, không có âm thanh","Chỉ có văn bản chạy trên màn hình","Chỉ có nhạc nền, không có hình ảnh"],"a":"Hình ảnh động, lời thoại hoặc thuyết minh, nhạc nền và hiệu ứng âm thanh","h":"Video là sản phẩm đa phương tiện.","e":"Video là sản phẩm đa phương tiện kết hợp hình ảnh, âm thanh (lời thoại, nhạc nền, hiệu ứng) và có thể cả chữ, giúp truyền tải thông tin sinh động.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi xuất (export) video để chia sẻ lên mạng xã hội hoặc gửi cho bạn bè, định dạng tệp nào sau đây được dùng phổ biến nhất?","o":["MP4","DOCX","XLSX","PPTX"],"a":"MP4","h":"Đây cũng là định dạng của hầu hết video em xem trên điện thoại.","e":"MP4 là định dạng video phổ biến nhất vì tương thích với hầu hết thiết bị, trang web và có dung lượng hợp lí.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Chèn tiêu đề và phụ đề chữ vào video mang lại lợi ích gì rõ nhất?","o":["Giúp người xem hiểu nội dung ngay cả khi không nghe được âm thanh và nắm được ý chính của video","Làm cho tệp video có dung lượng nhỏ hơn","Tự động dịch video sang mọi ngôn ngữ","Thay thế được phần quay phim"],"a":"Giúp người xem hiểu nội dung ngay cả khi không nghe được âm thanh và nắm được ý chính của video","h":"Hãy nghĩ tới lúc em xem video ở nơi ồn ào hoặc phải tắt tiếng.","e":"Tiêu đề và phụ đề giúp video dễ hiểu, dễ tiếp cận hơn, kể cả với người xem ở nơi ồn ào, tắt tiếng hoặc khiếm thính.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Tính chất nào sau đây là yêu cầu bắt buộc mà mọi thuật toán phải có?","o":["Phải kết thúc sau một số hữu hạn bước thực hiện","Phải có càng nhiều bước thực hiện càng tốt","Phải được viết bằng tiếng Anh","Phải có ít nhất một nghìn bước"],"a":"Phải kết thúc sau một số hữu hạn bước thực hiện","h":"Một dãy chỉ dẫn chạy mãi không bao giờ dừng thì không giải quyết được vấn đề gì.","e":"Thuật toán phải có tính dừng (tính hữu hạn): sau một số hữu hạn bước, thuật toán phải kết thúc và cho ra kết quả; nếu không, nó không thể dùng để giải quyết vấn đề.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Sơ đồ khối (lưu đồ) được sử dụng trong giải quyết vấn đề với mục đích chính nào?","o":["Mô tả thuật toán bằng hình vẽ trực quan để dễ hiểu, dễ kiểm tra và dễ chuyển thành chương trình","Trang trí cho bài trình bày đẹp hơn","Lưu trữ dữ liệu lâu dài","Kết nối các máy tính thành mạng"],"a":"Mô tả thuật toán bằng hình vẽ trực quan để dễ hiểu, dễ kiểm tra và dễ chuyển thành chương trình","h":"Con người thường hiểu hình vẽ nhanh hơn đọc một đoạn văn dài.","e":"Sơ đồ khối dùng các hình chuẩn (bắt đầu/kết thúc, xử lí, điều kiện...) để biểu diễn các bước của thuật toán một cách trực quan, dễ theo dõi và phát hiện sai sót.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Trong sơ đồ khối mô tả thuật toán, khối hình thoi thường được dùng để thể hiện bước nào?","o":["Kiểm tra một điều kiện (đúng hoặc sai) để rẽ nhánh","Bắt đầu hoặc kết thúc thuật toán","Thực hiện một phép tính","Nhập dữ liệu từ bàn phím"],"a":"Kiểm tra một điều kiện (đúng hoặc sai) để rẽ nhánh","h":"Từ khối này thường có hai mũi tên đi ra: một cho trường hợp Đúng, một cho trường hợp Sai.","e":"Trong sơ đồ khối, hình thoi là khối điều kiện: tuỳ kết quả kiểm tra là đúng hay sai, thuật toán sẽ đi theo các nhánh khác nhau.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Khi gặp một bài toán lớn, phức tạp, việc chia bài toán thành các bài toán nhỏ hơn đơn giản hơn mang lại lợi ích gì?","o":["Giúp việc giải quyết dễ dàng hơn vì mỗi bài toán nhỏ dễ hiểu, dễ làm và dễ kiểm tra","Làm cho bài toán trở nên khó hơn","Làm tăng số lỗi của chương trình","Chỉ có tác dụng làm bài toán dài hơn"],"a":"Giúp việc giải quyết dễ dàng hơn vì mỗi bài toán nhỏ dễ hiểu, dễ làm và dễ kiểm tra","h":"Đây là cách nghĩ 'chia để trị' rất quen thuộc trong tin học.","e":"Phân rã bài toán là kĩ thuật quan trọng: chia vấn đề lớn thành các vấn đề nhỏ, giải quyết từng phần rồi kết hợp lại, giúp công việc rõ ràng và dễ kiểm soát.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Chuyên viên an toàn thông tin (an ninh mạng) làm công việc chính nào?","o":["Bảo vệ hệ thống máy tính và dữ liệu, phòng chống các cuộc tấn công và truy cập trái phép","Thiết kế bìa sách và áp phích quảng cáo","Sửa chữa đường dây điện trong toà nhà","Bán các thiết bị điện tử tại cửa hàng"],"a":"Bảo vệ hệ thống máy tính và dữ liệu, phòng chống các cuộc tấn công và truy cập trái phép","h":"Nghề này giống như 'người gác cổng' cho hệ thống số.","e":"Chuyên viên an toàn thông tin theo dõi, phát hiện và ngăn chặn các nguy cơ tấn công mạng, bảo vệ dữ liệu cho tổ chức và người dùng.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Quản trị cơ sở dữ liệu là người đảm nhiệm công việc nào?","o":["Tổ chức, lưu trữ, sao lưu và bảo đảm an toàn, tính sẵn sàng cho dữ liệu của một tổ chức","Vẽ các nhân vật cho trò chơi điện tử","Lắp ráp linh kiện máy tính","Viết bài quảng cáo cho doanh nghiệp"],"a":"Tổ chức, lưu trữ, sao lưu và bảo đảm an toàn, tính sẵn sàng cho dữ liệu của một tổ chức","h":"Dữ liệu của trường học, bệnh viện, ngân hàng đều cần người trông coi chuyên nghiệp.","e":"Quản trị cơ sở dữ liệu chịu trách nhiệm thiết kế cấu trúc lưu trữ, phân quyền truy cập, sao lưu và khôi phục dữ liệu khi có sự cố.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Người biên tập video (video editor) trong lĩnh vực sáng tạo nội dung số làm công việc chính nào?","o":["Cắt ghép, chỉnh sửa hình ảnh và âm thanh để tạo thành video hoàn chỉnh theo kịch bản","Sửa chữa máy quay phim","Bán quảng cáo trên truyền hình","Viết kịch bản phim truyền hình dài tập"],"a":"Cắt ghép, chỉnh sửa hình ảnh và âm thanh để tạo thành video hoàn chỉnh theo kịch bản","h":"Đây là nghề đứng sau hầu hết video em xem trên mạng.","e":"Biên tập video là nghề dùng phần mềm dựng video để cắt ghép cảnh quay, chèn nhạc, chữ, hiệu ứng, tạo ra sản phẩm video hoàn chỉnh.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Việc tham quan, trải nghiệm thực tế tại các doanh nghiệp công nghệ thông tin giúp học sinh điều gì trong hướng nghiệp?","o":["Hiểu rõ công việc thực tế của các nghề tin học để lựa chọn hướng học tập phù hợp với bản thân","Được cấp chứng chỉ hành nghề ngay lập tức","Không cần học thêm môn Tin học nữa","Được tuyển dụng ngay khi chưa tốt nghiệp"],"a":"Hiểu rõ công việc thực tế của các nghề tin học để lựa chọn hướng học tập phù hợp với bản thân","h":"Trăm nghe không bằng một thấy.","e":"Trải nghiệm thực tế giúp học sinh hình dung đúng về nghề nghiệp tin học, từ đó định hướng học tập và rèn luyện kĩ năng phù hợp từ sớm.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Việc sao lưu (backup) dữ liệu quan trọng một cách định kì giúp ích gì rõ nhất?","o":["Có bản dự phòng để khôi phục dữ liệu khi máy hỏng, mất máy hoặc dữ liệu bị mã độc phá hoại","Làm cho máy tính chạy nhanh hơn","Tăng dung lượng ổ cứng của máy","Giúp máy tính không cần mật khẩu nữa"],"a":"Có bản dự phòng để khôi phục dữ liệu khi máy hỏng, mất máy hoặc dữ liệu bị mã độc phá hoại","h":"Giống như việc photocopy một tài liệu quý để cất ở nơi khác.","e":"Sao lưu tạo ra bản sao của dữ liệu ở nơi khác (ổ cứng ngoài, đám mây...); khi bản gốc bị mất hay hỏng, ta vẫn khôi phục lại được từ bản sao.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong một hệ thống thông tin của trường học, việc phân quyền truy cập dữ liệu (ví dụ: chỉ giáo viên mới sửa được điểm) có tác dụng gì?","o":["Bảo vệ dữ liệu, tránh bị sửa đổi hoặc xem trái phép bởi người không có trách nhiệm","Làm cho hệ thống chạy chậm hơn","Giúp mọi người đều sửa được mọi dữ liệu","Trang trí cho giao diện phần mềm"],"a":"Bảo vệ dữ liệu, tránh bị sửa đổi hoặc xem trái phép bởi người không có trách nhiệm","h":"Không phải ai cũng được cầm chìa khoá của mọi phòng.","e":"Phân quyền truy cập giới hạn mỗi người chỉ thao tác được với phần dữ liệu thuộc trách nhiệm của mình, giúp bảo vệ tính đúng đắn và bí mật của dữ liệu.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Vì sao cần cập nhật phần mềm diệt virus (và hệ điều hành) thường xuyên?","o":["Để phần mềm nhận biết và ngăn chặn được các loại mã độc mới xuất hiện liên tục","Để thay đổi hình nền của máy tính","Để máy tính có thêm nhiều trò chơi","Để tăng tốc độ mạng Internet"],"a":"Để phần mềm nhận biết và ngăn chặn được các loại mã độc mới xuất hiện liên tục","h":"Mã độc mới xuất hiện mỗi ngày, 'vũ khí' phòng thủ cũng phải được làm mới.","e":"Các bản cập nhật bổ sung dữ liệu nhận diện mã độc mới và vá các lỗ hổng bảo mật, giúp máy tính được bảo vệ trước những nguy cơ mới nhất.","t":"tin-lop9","g":9,"l":"thu-thach"},{"p":"Việc quét mã QR để trả tiền mua hàng thay cho tiền mặt thuộc hình thức nào?","o":["Thanh toán điện tử (thanh toán không dùng tiền mặt)","Thương mại truyền thống","Trao đổi hàng lấy hàng","Gửi tiết kiệm ngân hàng"],"a":"Thanh toán điện tử (thanh toán không dùng tiền mặt)","h":"Toàn bộ việc trả tiền diễn ra qua điện thoại và mạng Internet.","e":"Thanh toán bằng mã QR, ví điện tử hay chuyển khoản đều là thanh toán điện tử — một biểu hiện rõ rệt của kinh tế số, nhanh gọn và dễ theo dõi chi tiêu.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Lợi ích nổi bật nhất của học tập trực tuyến (học qua Internet) là gì?","o":["Người học có thể học mọi lúc, mọi nơi và học lại bài giảng nhiều lần theo nhu cầu","Người học không cần làm bài tập nữa","Người học không cần giáo viên hướng dẫn","Chỉ học được vào ban đêm"],"a":"Người học có thể học mọi lúc, mọi nơi và học lại bài giảng nhiều lần theo nhu cầu","h":"Chỉ cần một thiết bị có kết nối mạng là em có thể vào lớp.","e":"Học trực tuyến phá vỡ giới hạn về không gian và thời gian, giúp người học chủ động sắp xếp việc học và xem lại bài khi cần.","t":"tin-lop9","g":9,"l":"nhe-nhang"},{"p":"Chữ kí số được sử dụng trong các giao dịch điện tử chủ yếu để làm gì?","o":["Xác thực danh tính của người kí và tính toàn vẹn của văn bản, tài liệu điện tử","Làm cho văn bản có màu sắc đẹp hơn","Viết chữ thật đẹp lên màn hình","Nén tài liệu thành tệp nhỏ hơn"],"a":"Xác thực danh tính của người kí và tính toàn vẹn của văn bản, tài liệu điện tử","h":"Tương tự chữ kí tay và con dấu trên giấy, nhưng ở dạng số.","e":"Chữ kí số giúp chứng minh một văn bản điện tử đúng là của người kí và nội dung không bị thay đổi sau khi kí, có giá trị pháp lí trong giao dịch điện tử.","t":"tin-lop9","g":9,"l":"kho"},{"p":"Dòng khai báo DOCTYPE html ở đầu một tệp HTML có ý nghĩa gì?","o":["Khai báo cho trình duyệt biết tài liệu này được viết theo chuẩn HTML5","Tạo một tiêu đề cho trang web","Chèn một hình ảnh vào trang web","Kết thúc tài liệu HTML"],"a":"Khai báo cho trình duyệt biết tài liệu này được viết theo chuẩn HTML5","h":"Dòng này luôn đứng ở dòng đầu tiên của tệp HTML.","e":"Dòng DOCTYPE html thông báo với trình duyệt rằng tài liệu dùng chuẩn HTML5, giúp trình duyệt hiển thị trang đúng cách.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Nội dung đặt trong cặp thẻ title của một trang HTML sẽ hiển thị ở đâu?","o":["Trên thanh tiêu đề hoặc thẻ (tab) của cửa sổ trình duyệt","Ở giữa trang web với cỡ chữ lớn nhất","Ở cuối trang web","Trong thanh địa chỉ của trình duyệt"],"a":"Trên thanh tiêu đề hoặc thẻ (tab) của cửa sổ trình duyệt","h":"Hãy nhìn lên các tab đang mở trên trình duyệt của em.","e":"Thẻ title nằm trong phần head, dùng để đặt tên cho trang web; tên này hiển thị trên tab của trình duyệt và trong kết quả tìm kiếm.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong thẻ a của HTML, thuộc tính href dùng để làm gì?","o":["Chỉ định địa chỉ (URL) của trang hoặc tài nguyên mà liên kết trỏ tới","Đặt màu chữ cho liên kết","Tạo một đoạn văn mới","Chèn hình ảnh vào trang"],"a":"Chỉ định địa chỉ (URL) của trang hoặc tài nguyên mà liên kết trỏ tới","h":"Khi bấm vào liên kết, trình duyệt sẽ đi tới địa chỉ này.","e":"Thuộc tính href (ví dụ href=\"https://...\" ) chứa địa chỉ đích của liên kết; người dùng bấm vào nội dung trong thẻ a sẽ được chuyển tới địa chỉ đó.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Thuộc tính alt trong thẻ img của HTML có vai trò gì?","o":["Cung cấp văn bản thay thế mô tả hình ảnh, hiển thị khi ảnh không tải được và hỗ trợ người khiếm thị","Đặt kích thước cho hình ảnh","Tạo đường viền cho hình ảnh","Đổi tên tệp hình ảnh"],"a":"Cung cấp văn bản thay thế mô tả hình ảnh, hiển thị khi ảnh không tải được và hỗ trợ người khiếm thị","h":"Chữ 'alt' gợi ý tới 'alternative' — thay thế.","e":"Thuộc tính alt chứa mô tả ngắn về hình ảnh; khi ảnh lỗi không hiển thị được, trình duyệt hiện đoạn mô tả này, và phần mềm đọc màn hình dùng nó để đọc cho người khiếm thị.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Trong HTML, cặp thẻ nào được dùng để tạo một bảng dữ liệu?","o":["table","ul","form","div"],"a":"table","h":"Tên thẻ trùng với từ tiếng Anh chỉ 'cái bảng'.","e":"Thẻ table tạo bảng; bên trong, thẻ tr tạo từng hàng, thẻ td tạo ô dữ liệu và thẻ th tạo ô tiêu đề của bảng.","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Thẻ input trong biểu mẫu (form) HTML thường được dùng để làm gì?","o":["Tạo các ô cho người dùng nhập dữ liệu như văn bản, mật khẩu, ô đánh dấu","Tạo tiêu đề cho trang web","Chèn video vào trang web","Tạo bảng dữ liệu"],"a":"Tạo các ô cho người dùng nhập dữ liệu như văn bản, mật khẩu, ô đánh dấu","h":"Ví dụ quen thuộc: ô nhập tên đăng nhập và mật khẩu.","e":"Thẻ input tạo vùng nhập dữ liệu trong biểu mẫu; tuỳ thuộc tính type, nó có thể là ô văn bản, ô mật khẩu, nút chọn radio, hộp kiểm checkbox...","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong biểu mẫu HTML, khi cần cho người dùng nhập một đoạn văn bản dài nhiều dòng (ví dụ: phần góp ý), ta nên dùng thẻ nào?","o":["textarea","input kiểu text","select","label"],"a":"textarea","h":"Hãy nghĩ tới khung góp ý lớn trên các trang web.","e":"Thẻ textarea tạo vùng nhập văn bản nhiều dòng, phù hợp cho các nội dung dài như góp ý, mô tả; còn input kiểu text chỉ nhập được một dòng.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Để liên kết một tệp CSS ngoài (ví dụ style.css) vào trang HTML, ta dùng thẻ nào và đặt thẻ đó ở đâu?","o":["Thẻ link đặt trong phần head của trang","Thẻ style đặt ở cuối phần body","Thẻ a đặt trong phần body","Thẻ css đặt trong phần head"],"a":"Thẻ link đặt trong phần head của trang","h":"Liên kết tệp ngoài là một trong ba cách đưa CSS vào trang web.","e":"Thẻ link với thuộc tính rel=\"stylesheet\" và href trỏ tới tệp .css được đặt trong head; đây là cách nhúng CSS ngoài, giúp nhiều trang dùng chung một tệp định dạng.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Trong CSS, bộ chọn bắt đầu bằng dấu thăng kèm tên (ví dụ #tieude) sẽ áp dụng định dạng cho đối tượng nào?","o":["Phần tử duy nhất trong trang có thuộc tính id trùng với tên đó","Mọi phần tử trong trang","Mọi phần tử có class trùng với tên đó","Chỉ các phần tử tiêu đề h1"],"a":"Phần tử duy nhất trong trang có thuộc tính id trùng với tên đó","h":"Phân biệt với bộ chọn class vốn bắt đầu bằng dấu chấm.","e":"Bộ chọn id (bắt đầu bằng #) áp dụng cho phần tử có id tương ứng; theo quy ước, mỗi id chỉ dùng cho một phần tử duy nhất trong trang, khác với class có thể dùng cho nhiều phần tử.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Trong CSS, thuộc tính font-size dùng để làm gì?","o":["Đặt kích thước (cỡ) chữ cho phần tử","Đặt kiểu chữ hoa hoặc chữ thường","Đặt màu nền cho phần tử","Đặt khoảng cách giữa các dòng"],"a":"Đặt kích thước (cỡ) chữ cho phần tử","h":"Ví dụ: font-size: 20px.","e":"Thuộc tính font-size quy định cỡ chữ, thường đo bằng px; khác với font-family (phông chữ) và font-weight (độ đậm nhạt).","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong CSS, khai báo text-align: center có tác dụng gì?","o":["Căn giữa nội dung văn bản theo chiều ngang trong phần tử","Đặt văn bản thành chữ in hoa","Tăng khoảng cách giữa các từ","Đưa phần tử xuống giữa trang theo chiều dọc"],"a":"Căn giữa nội dung văn bản theo chiều ngang trong phần tử","h":"center trong tiếng Anh có nghĩa là 'ở giữa'.","e":"Thuộc tính text-align quy định cách căn văn bản theo chiều ngang: left (trái), right (phải), center (giữa), justify (căn đều hai bên).","t":"tin-lop12","g":12,"l":"nhe-nhang"},{"p":"Thẻ div trong HTML thường được sử dụng với mục đích chính nào?","o":["Nhóm các phần tử lại thành một khối để bố cục và định dạng chung","Tạo một liên kết tới trang khác","Tạo một ô nhập dữ liệu","Tạo tiêu đề lớn nhất cho trang"],"a":"Nhóm các phần tử lại thành một khối để bố cục và định dạng chung","h":"Hầu hết các khu vực trên một trang web (đầu trang, thực đơn, chân trang) đều là các khối như thế này.","e":"Thẻ div là phần tử dạng khối (block), dùng để chia trang thành các khu vực và nhóm các phần tử lại để áp dụng CSS bố cục, định dạng cho cả nhóm.","t":"tin-lop12","g":12,"l":"thu-thach"},{"p":"Điểm khác biệt cơ bản giữa thẻ span và thẻ div trong HTML là gì?","o":["span là phần tử dạng dòng (inline), chỉ chiếm độ rộng bằng nội dung; div là phần tử dạng khối (block), chiếm hết chiều ngang và xuống dòng mới","span dùng cho chữ, div dùng cho hình ảnh","span tạo được liên kết, div thì không","Hai thẻ hoàn toàn giống nhau, dùng thay thế cho nhau được"],"a":"span là phần tử dạng dòng (inline), chỉ chiếm độ rộng bằng nội dung; div là phần tử dạng khối (block), chiếm hết chiều ngang và xuống dòng mới","h":"Hãy so sánh khi cần định dạng riêng một vài chữ trong câu với khi cần tạo cả một khu vực riêng.","e":"span là phần tử inline, thường dùng để định dạng một phần nhỏ trong dòng văn bản; div là phần tử block, luôn bắt đầu ở dòng mới và chiếm toàn bộ chiều ngang khả dụng.","t":"tin-lop12","g":12,"l":"kho"},{"p":"Kĩ thuật viên máy tính (phần cứng) làm công việc chính nào?","o":["Lắp ráp, cài đặt, bảo trì và sửa chữa các thiết bị phần cứng máy tính","Viết nội dung quảng cáo cho cửa hàng","Thiết kế thời trang","Dạy học sinh sử dụng phần mềm văn phòng"],"a":"Lắp ráp, cài đặt, bảo trì và sửa chữa các thiết bị phần cứng máy tính","h":"Khi máy tính hỏng phần cứng, đây là người trực tiếp xử lí.","e":"Kĩ thuật viên phần cứng phụ trách lắp ráp máy tính, thay thế linh kiện, cài đặt hệ điều hành và khắc phục các sự cố về thiết bị.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Người thiết kế website (web designer) làm công việc chính nào?","o":["Thiết kế giao diện, bố cục và trải nghiệm sử dụng cho các trang web","Sửa chữa máy in và máy photocopy","Quản lí kho hàng của công ty","Vận hành máy chủ điện toán đám mây"],"a":"Thiết kế giao diện, bố cục và trải nghiệm sử dụng cho các trang web","h":"Nghề này kết hợp giữa thẩm mĩ và công nghệ.","e":"Web designer tạo ra diện mạo của trang web: màu sắc, bố cục, hình ảnh... sao cho đẹp và dễ sử dụng, thường kết hợp với lập trình viên để hoàn thiện trang web.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Một học sinh yêu thích vẽ, có năng khiếu thẩm mĩ và muốn làm việc trong lĩnh vực công nghệ thông tin. Nhóm nghề nào sau đây phù hợp nhất với bạn ấy?","o":["Thiết kế đồ hoạ và giao diện số","Quản trị hệ thống mạng","Lập trình hệ thống nhúng","Kiểm thử bảo mật"],"a":"Thiết kế đồ hoạ và giao diện số","h":"Hãy kết hợp sở thích cá nhân với đặc điểm của từng nghề.","e":"Thiết kế đồ hoạ số tận dụng năng khiếu vẽ và thẩm mĩ: thiết kế hình ảnh, giao diện phần mềm, trang web, sản phẩm truyền thông số.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Khi làm dự án tin học theo nhóm, kĩ năng hợp tác và giao tiếp tốt giúp ích điều gì rõ nhất?","o":["Các thành viên phối hợp nhịp nhàng, chia việc hợp lí và hoàn thành sản phẩm đúng yêu cầu, đúng hạn","Một người có thể làm thay toàn bộ công việc của nhóm","Nhóm không cần lập kế hoạch làm việc","Sản phẩm tự động không còn lỗi nào"],"a":"Các thành viên phối hợp nhịp nhàng, chia việc hợp lí và hoàn thành sản phẩm đúng yêu cầu, đúng hạn","h":"Sản phẩm tin học thường do nhiều người cùng làm: người thiết kế, người lập trình, người kiểm thử.","e":"Người làm tin học hiếm khi làm việc một mình; giao tiếp và hợp tác tốt giúp phân công rõ ràng, hỗ trợ lẫn nhau và tạo ra sản phẩm chất lượng.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Điểm ảnh (pixel) trong một bức ảnh số là gì?","o":["Phần tử nhỏ nhất cấu tạo nên bức ảnh, mỗi điểm mang một màu nhất định","Một loại máy ảnh kĩ thuật số","Đơn vị đo kích thước màn hình","Tên một phần mềm chỉnh sửa ảnh"],"a":"Phần tử nhỏ nhất cấu tạo nên bức ảnh, mỗi điểm mang một màu nhất định","h":"Khi phóng to ảnh lên rất nhiều lần, em sẽ nhìn thấy các ô vuông nhỏ.","e":"Ảnh số được tạo thành từ hàng triệu điểm ảnh (pixel) xếp cạnh nhau; mỗi điểm ảnh có một màu, và tổng thể chúng tạo nên hình ảnh mà ta nhìn thấy.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi cần chèn một bức ảnh vào trang trình chiếu hoặc gửi qua mạng mà vẫn giữ được phần nền trong suốt (ví dụ: logo không có nền trắng), ta nên dùng định dạng ảnh nào?","o":["PNG","JPG","BMP","GIF động"],"a":"PNG","h":"Định dạng JPG luôn có nền đặc, không trong suốt được.","e":"Định dạng PNG hỗ trợ kênh trong suốt (alpha), rất phù hợp cho logo, biểu tượng cần đặt lên các nền khác nhau; JPG không hỗ trợ tính năng này.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trong chỉnh sửa ảnh, tăng độ tương phản (contrast) có tác dụng gì?","o":["Làm cho vùng sáng sáng hơn, vùng tối tối hơn, giúp ảnh rõ nét và nổi bật hơn","Làm ảnh nhỏ đi một nửa","Đổi ảnh màu thành ảnh đen trắng","Xoá bỏ phông nền của ảnh"],"a":"Làm cho vùng sáng sáng hơn, vùng tối tối hơn, giúp ảnh rõ nét và nổi bật hơn","h":"Hãy so sánh một bức ảnh 'nhạt' với một bức ảnh 'đậm đà'.","e":"Độ tương phản là mức chênh lệch giữa vùng sáng và vùng tối; tăng tương phản vừa phải giúp ảnh sống động, rõ chi tiết hơn.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trong phần mềm chỉnh sửa ảnh, lớp (layer) được hiểu là gì?","o":["Một 'tờ giấy trong suốt' chứa một phần nội dung của ảnh; nhiều lớp xếp chồng lên nhau tạo thành bức ảnh hoàn chỉnh","Một bộ lọc màu có sẵn","Một công cụ để vẽ đường thẳng","Một định dạng tệp ảnh"],"a":"Một 'tờ giấy trong suốt' chứa một phần nội dung của ảnh; nhiều lớp xếp chồng lên nhau tạo thành bức ảnh hoàn chỉnh","h":"Hãy tưởng tượng việc vẽ từng chi tiết lên các tấm kính trong suốt rồi chồng lên nhau.","e":"Cơ chế lớp giúp chỉnh sửa từng phần của ảnh (nền, đối tượng, chữ...) một cách độc lập mà không ảnh hưởng tới các phần còn lại.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong phần mềm soạn thảo văn bản, phần chân trang (footer) thường được dùng để làm gì?","o":["Chèn nội dung lặp lại ở cuối mọi trang như số trang, tên tài liệu","Viết tiêu đề chính của văn bản","Chèn hình ảnh minh hoạ lớn","Lưu trữ các đoạn văn bị xoá"],"a":"Chèn nội dung lặp lại ở cuối mọi trang như số trang, tên tài liệu","h":"Đầu trang (header) và chân trang xuất hiện giống nhau trên mọi trang của văn bản.","e":"Footer là vùng ở cuối mỗi trang, thường dùng để đánh số trang hoặc ghi tên cơ quan, tên tài liệu; nội dung này được tự động lặp lại trên mọi trang.","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Tính năng Tìm kiếm và Thay thế (Find and Replace) trong soạn thảo văn bản giúp ích gì rõ nhất?","o":["Sửa nhanh một từ hoặc cụm từ xuất hiện nhiều lần trong toàn bộ văn bản chỉ bằng một thao tác","Tự động dịch văn bản sang tiếng Anh","Tự động viết tiếp đoạn văn","Kiểm tra kết nối Internet"],"a":"Sửa nhanh một từ hoặc cụm từ xuất hiện nhiều lần trong toàn bộ văn bản chỉ bằng một thao tác","h":"Ví dụ: đổi tên một nhân vật xuất hiện 50 lần trong truyện.","e":"Find and Replace cho phép tìm mọi vị trí của một từ/cụm từ và thay bằng nội dung mới cùng lúc, tiết kiệm thời gian và tránh sót lỗi so với sửa thủ công từng chỗ.","t":"tin-lop8","g":8,"l":"thu-thach"},{"p":"Trong phần mềm bảng tính, hàm AVERAGE dùng để làm gì?","o":["Tính giá trị trung bình cộng của một vùng dữ liệu số","Đếm số ô có dữ liệu","Tìm giá trị lớn nhất trong vùng dữ liệu","Tính tổng của một vùng dữ liệu"],"a":"Tính giá trị trung bình cộng của một vùng dữ liệu số","h":"Ví dụ quen thuộc: tính điểm trung bình môn học.","e":"Hàm AVERAGE tính trung bình cộng của các số trong vùng được chọn, thường dùng để tính điểm trung bình, nhiệt độ trung bình...","t":"tin-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong đồ hoạ vector, 'điểm neo' (node) trên một đường cong Bézier có vai trò gì?","o":["Là các điểm mà đường cong đi qua; di chuyển điểm neo hoặc các tay cầm sẽ làm thay đổi hình dạng của đường cong","Là điểm đánh dấu tâm của trang giấy","Là điểm lưu trữ màu sắc của hình","Là điểm bắt đầu của mọi văn bản"],"a":"Là các điểm mà đường cong đi qua; di chuyển điểm neo hoặc các tay cầm sẽ làm thay đổi hình dạng của đường cong","h":"Khi vẽ đường cong trong Inkscape, em kéo thả chính những điểm này.","e":"Đường cong Bézier được xác định bởi các điểm neo và các tay cầm (handle) điều hướng; chỉnh sửa vị trí của chúng sẽ uốn cong đường theo ý muốn.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong phần mềm đồ hoạ vector, thuộc tính 'màu tô' (fill) và 'màu viền' (stroke) của một đối tượng khác nhau ở điểm nào?","o":["Fill là màu của phần bên trong đối tượng, stroke là màu của đường viền bao quanh đối tượng","Fill dùng cho chữ, stroke dùng cho hình","Fill là màu nền trang giấy, stroke là màu của lưới","Hai thuộc tính hoàn toàn giống nhau"],"a":"Fill là màu của phần bên trong đối tượng, stroke là màu của đường viền bao quanh đối tượng","h":"Hãy hình dung một hình tròn: phần ruột và đường chu vi của nó.","e":"Mỗi đối tượng vector có hai vùng màu độc lập: fill tô phần trong, stroke tô đường biên; có thể đặt riêng màu, độ dày viền hoặc bỏ hẳn một trong hai.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Thao tác nhóm (group) các đối tượng trong phần mềm đồ hoạ vector có tác dụng gì?","o":["Gộp nhiều đối tượng thành một nhóm để di chuyển, phóng to thu nhỏ và chỉnh sửa cùng lúc như một đối tượng duy nhất","Xoá bỏ các đối tượng thừa","Chuyển các đối tượng thành ảnh bitmap","Tự động tô màu cho các đối tượng"],"a":"Gộp nhiều đối tượng thành một nhóm để di chuyển, phóng to thu nhỏ và chỉnh sửa cùng lúc như một đối tượng duy nhất","h":"Ví dụ: một bông hoa gồm cánh, nhuỵ và lá nên được xử lí như một khối thống nhất.","e":"Nhóm (group) giúp quản lí các đối tượng có liên quan: khi di chuyển hay thay đổi kích thước, toàn nhóm thay đổi theo tỉ lệ chung mà vị trí tương đối giữa các đối tượng không đổi.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Tệp có phần mở rộng .svg là loại tệp nào?","o":["Tệp đồ hoạ vector, thường được tạo và chỉnh sửa bằng các phần mềm như Inkscape","Tệp âm thanh","Tệp văn bản Word","Tệp bảng tính"],"a":"Tệp đồ hoạ vector, thường được tạo và chỉnh sửa bằng các phần mềm như Inkscape","h":"SVG là viết tắt của Scalable Vector Graphics.","e":"SVG là định dạng đồ hoạ vector phổ biến trên web: hình được mô tả bằng các đối tượng hình học nên phóng to thu nhỏ không bị vỡ hình.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Một biểu tượng (logo) được vẽ ở lớp dưới cùng bị một hình chữ nhật ở lớp trên che mất. Muốn logo hiện lên trên cùng, em cần làm gì?","o":["Di chuyển lớp (hoặc đối tượng) chứa logo lên phía trên các lớp còn lại","Xoá hình chữ nhật đi","Đổi màu của logo thành màu sáng hơn","Lưu lại tệp với tên khác"],"a":"Di chuyển lớp (hoặc đối tượng) chứa logo lên phía trên các lớp còn lại","h":"Trong đồ hoạ, đối tượng nào nằm ở lớp trên sẽ che đối tượng ở lớp dưới tại vùng chúng chồng lên nhau.","e":"Thứ tự xếp chồng quyết định phần nào của hình được nhìn thấy; đưa lớp chứa logo lên trên cùng sẽ làm logo hiển thị đầy đủ.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Vì sao các logo, biểu tượng thương hiệu thường được thiết kế bằng đồ hoạ vector thay vì ảnh bitmap?","o":["Vì đồ hoạ vector phóng to, thu nhỏ ở mọi kích thước (từ danh thiếp tới biển quảng cáo lớn) mà vẫn sắc nét, không vỡ hình","Vì tệp vector luôn có dung lượng lớn hơn","Vì đồ hoạ vector có nhiều màu hơn ảnh chụp","Vì ảnh bitmap không in được ra giấy"],"a":"Vì đồ hoạ vector phóng to, thu nhỏ ở mọi kích thước (từ danh thiếp tới biển quảng cáo lớn) mà vẫn sắc nét, không vỡ hình","h":"Logo phải dùng được ở rất nhiều kích cỡ khác nhau.","e":"Đối tượng vector được mô tả bằng công thức hình học nên khi thay đổi kích thước, máy tính tính lại đường nét một cách chính xác, hình luôn sắc nét; ảnh bitmap phóng to sẽ bị vỡ hạt.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Trong tin học, 1 byte bằng bao nhiêu bit?","o":["8 bit","10 bit","100 bit","1024 bit"],"a":"8 bit","h":"Bit là đơn vị nhỏ nhất; byte là đơn vị cơ bản để đo dung lượng.","e":"Theo quy ước, 1 byte gồm 8 bit; byte là đơn vị cơ bản để biểu diễn một kí tự và đo dung lượng bộ nhớ.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Số thập phân 25 được biểu diễn trong hệ nhị phân là:","o":["11001","10101","10011","11100"],"a":"11001","h":"Hãy chia dần cho 2 và ghi lại số dư theo thứ tự ngược.","e":"25 = 16 + 8 + 1 = 1×2⁴ + 1×2³ + 0×2² + 0×2¹ + 1×2⁰ nên viết trong hệ nhị phân là 11001.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Một bức ảnh số được tạo thành từ những phần tử nào?","o":["Các điểm ảnh (pixel), mỗi điểm ảnh lưu thông tin về màu sắc tại vị trí đó","Các đường cong vector","Các kí tự chữ cái","Các đoạn thẳng nối với nhau"],"a":"Các điểm ảnh (pixel), mỗi điểm ảnh lưu thông tin về màu sắc tại vị trí đó","h":"Khi phóng to ảnh lên rất nhiều, em nhìn thấy những ô vuông nhỏ li ti.","e":"Ảnh bitmap được cấu thành từ lưới các điểm ảnh; số điểm ảnh và lượng thông tin màu của mỗi điểm quyết định độ nét và dung lượng của ảnh.","t":"tin-lop10","g":10,"l":"nhe-nhang"},{"p":"Một bức ảnh có độ phân giải (số điểm ảnh) càng cao thì điều gì sau đây đúng?","o":["Ảnh càng chi tiết, sắc nét hơn nhưng dung lượng tệp cũng lớn hơn","Ảnh càng mờ hơn","Dung lượng tệp luôn nhỏ hơn","Ảnh chỉ hiển thị được màu đen trắng"],"a":"Ảnh càng chi tiết, sắc nét hơn nhưng dung lượng tệp cũng lớn hơn","h":"Nhiều điểm ảnh hơn nghĩa là nhiều thông tin hơn cần lưu trữ.","e":"Độ phân giải cao cho ảnh mịn và chi tiết hơn, nhưng số điểm ảnh lớn làm dung lượng tệp tăng lên đáng kể.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong mô hình màu RGB dùng để biểu diễn màu sắc trên màn hình, mỗi màu được tạo thành bằng cách pha trộn ba màu cơ bản nào?","o":["Đỏ, xanh lá và xanh dương","Đỏ, vàng và xanh dương","Đen, trắng và xám","Hồng, tím và cam"],"a":"Đỏ, xanh lá và xanh dương","h":"RGB là viết tắt từ tên tiếng Anh của ba màu này.","e":"RGB (Red, Green, Blue) pha trộn ánh sáng đỏ, xanh lá và xanh dương với các cường độ khác nhau để tạo ra hàng triệu màu hiển thị trên màn hình.","t":"tin-lop10","g":10,"l":"thu-thach"},{"p":"Trong mạch lôgic, cổng AND cho kết quả đầu ra bằng 1 (đúng) trong trường hợp nào?","o":["Chỉ khi tất cả các đầu vào đều bằng 1","Khi có ít nhất một đầu vào bằng 1","Khi tất cả các đầu vào đều bằng 0","Luôn luôn cho kết quả bằng 1"],"a":"Chỉ khi tất cả các đầu vào đều bằng 1","h":"AND trong tiếng Anh có nghĩa là 'và' — mọi điều kiện phải đồng thời thoả mãn.","e":"Cổng AND thực hiện phép 'và' lôgic: đầu ra chỉ đúng khi mọi đầu vào cùng đúng, tương tự mệnh đề 'A và B' chỉ đúng khi cả A và B đều đúng.","t":"tin-lop10","g":10,"l":"kho"},{"p":"Đồ dùng nào sau đây là sản phẩm công nghệ trong gia đình?","o":["Đèn học","Cái chổi tre","Chiếc nón lá","Cái rổ mây"],"a":"Đèn học","h":"Sản phẩm công nghệ thường dùng điện để hoạt động.","e":"Đèn học là sản phẩm công nghệ vì dùng điện để thắp sáng, giúp em học bài. Chổi tre, rổ mây và nón lá là đồ dùng làm thủ công.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Nồi cơm điện dùng để làm việc gì?","o":["Nấu cơm chín","Giặt quần áo","Là phẳng quần áo","Đun nước sôi"],"a":"Nấu cơm chín","h":"Tên của đồ dùng đã gợi ý công việc của nó.","e":"Nồi cơm điện là sản phẩm công nghệ dùng điện để nấu cơm chín cho cả nhà.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Nhờ có tivi, em có thể làm được việc gì?","o":["Tưới nước cho cây","Xem thời sự, phim và chương trình thiếu nhi","Giặt và phơi quần áo","Nấu cơm cho cả nhà"],"a":"Xem thời sự, phim và chương trình thiếu nhi","h":"Tivi có màn hình và phát ra âm thanh.","e":"Tivi giúp em xem tin tức, phim và các chương trình giải trí, học tập ngay tại nhà.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Điểm chung của đèn học, quạt điện, tivi và nồi cơm điện là gì?","o":["Đều phải cắm vào bếp gas mới chạy","Đều được làm bằng tre","Đều dùng để đựng thức ăn","Đều dùng điện để hoạt động"],"a":"Đều dùng điện để hoạt động","h":"Hãy nghĩ xem các đồ dùng này lấy năng lượng từ đâu.","e":"Đèn học, quạt điện, tivi và nồi cơm điện đều là sản phẩm công nghệ dùng điện để hoạt động.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Quạt điện trong nhà có tác dụng gì?","o":["Bảo quản thức ăn được lâu","Sưởi ấm phòng vào mùa đông","Làm mát cho người","Thắp sáng căn phòng"],"a":"Làm mát cho người","h":"Khi bật quạt, em cảm thấy có gió thổi.","e":"Quạt điện tạo ra gió giúp làm mát, khiến em cảm thấy dễ chịu trong những ngày nóng.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi học bài, ánh sáng của đèn học như thế nào là tốt cho mắt?","o":["Càng sáng chói càng tốt","Chỉ cần hơi mờ là được","Sáng vừa đủ, không chói và không tối","Chớp tắt liên tục"],"a":"Sáng vừa đủ, không chói và không tối","h":"Ánh sáng quá mạnh hay quá yếu đều làm mắt mau mỏi.","e":"Ánh sáng vừa đủ giúp em nhìn rõ chữ mà không bị chói hay mỏi mắt. Ánh sáng quá sáng hoặc quá tối đều hại mắt.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em thuận tay phải khi viết bài. Em nên đặt đèn học ở phía nào để tay không che mất ánh sáng?","o":["Phía bên phải","Ngay phía sau lưng","Ngay trên đầu chiếu thẳng xuống","Phía bên trái"],"a":"Phía bên trái","h":"Nếu đèn ở cùng phía với tay viết, tay sẽ đổ bóng lên trang vở.","e":"Người thuận tay phải nên đặt đèn ở phía bên trái để ánh sáng chiếu lên trang vở mà không bị bàn tay che khuất.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi ngồi học với đèn học, tư thế nào là đúng?","o":["Ngồi cúi sát mặt xuống vở","Ngồi thẳng lưng, mắt cách vở khoảng một gang tay lớn","Nằm dài ra bàn để học","Ngồi vắt chân lên ghế"],"a":"Ngồi thẳng lưng, mắt cách vở khoảng một gang tay lớn","h":"Tư thế đúng giúp em không bị gù lưng và cận thị.","e":"Ngồi thẳng lưng, giữ khoảng cách hợp lí giữa mắt và vở giúp bảo vệ cột sống và đôi mắt của em.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Vì sao không nên học bài chỉ với ánh sáng đèn học trong phòng tối om?","o":["Vì mắt phải điều tiết nhiều giữa vùng sáng và vùng tối nên mau mỏi","Vì đèn học tốn nhiều điện hơn","Vì đèn học sẽ nhanh hỏng","Vì chữ trong vở sẽ bị mờ đi"],"a":"Vì mắt phải điều tiết nhiều giữa vùng sáng và vùng tối nên mau mỏi","h":"Hãy nghĩ đến sự chênh lệch giữa chỗ có đèn và xung quanh tối.","e":"Phòng tối om khiến vùng có đèn và vùng xung quanh chênh lệch sáng quá nhiều, mắt phải điều tiết liên tục nên nhanh mỏi. Em nên bật thêm đèn phòng khi học.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Học xong, em nên làm gì với đèn học?","o":["Vẫn để đèn sáng rồi đi chơi","Che đèn bằng khăn","Để đèn sáng cả đêm","Tắt đèn học"],"a":"Tắt đèn học","h":"Việc này vừa an toàn vừa tiết kiệm điện.","e":"Học xong em nên tắt đèn học để tiết kiệm điện và giữ an toàn cho gia đình.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi quạt điện đang quay, em tuyệt đối không được làm việc gì?","o":["Nhìn vào quạt","Đứng xa quạt","Thò tay hoặc cho vật vào lồng quạt","Ngồi học gần quạt"],"a":"Thò tay hoặc cho vật vào lồng quạt","h":"Cánh quạt quay rất nhanh và có thể làm em bị thương.","e":"Cánh quạt quay nhanh sẽ làm đau, thậm chí gây thương tích nếu em thò tay hay cho vật vào lồng quạt.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Vì sao không nên để quạt thổi thẳng vào người trong thời gian lâu?","o":["Vì tốn nhiều tiền điện hơn","Vì quạt sẽ quay chậm lại","Vì dễ bị khô da, đau họng và cảm lạnh","Vì quạt sẽ bị mòn cánh"],"a":"Vì dễ bị khô da, đau họng và cảm lạnh","h":"Hãy nghĩ xem gió thổi lâu vào người ảnh hưởng gì đến sức khỏe.","e":"Gió quạt thổi thẳng và lâu vào người làm cơ thể mất nước, dễ khô họng, nhức đầu và cảm lạnh. Em nên cho quạt quay qua lại.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi không sử dụng quạt nữa, em nên làm gì?","o":["Để quạt quay cả ngày","Lấy áo phủ lên quạt đang quay","Tắt quạt đi","Tăng quạt lên số to nhất"],"a":"Tắt quạt đi","h":"Việc này giúp tiết kiệm điện và quạt bền hơn.","e":"Không dùng quạt nữa thì em nên tắt quạt để tiết kiệm điện và giúp quạt được nghỉ, bền lâu hơn.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Quạt điện bị đổ xuống sàn mà vẫn đang quay. Em nên xử lí thế nào cho an toàn?","o":["Chạy lại dựng quạt lên ngay khi cánh đang quay","Tắt quạt, rút phích cắm rồi mới dựng quạt lên và báo người lớn","Để kệ quạt nằm quay","Đỡ quạt bằng chân"],"a":"Tắt quạt, rút phích cắm rồi mới dựng quạt lên và báo người lớn","h":"Phải ngắt điện trước khi chạm vào quạt đang gặp sự cố.","e":"Khi quạt đổ mà vẫn quay, em cần tắt và rút điện trước rồi mới dựng lên, đồng thời báo người lớn kiểm tra để bảo đảm an toàn.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Em nên đặt quạt điện ở vị trí nào khi sử dụng?","o":["Ngay sát mép bàn cao","Trên nền nhà bằng phẳng, chắc chắn","Treo lơ lửng trên dây","Trên giường nệm mềm"],"a":"Trên nền nhà bằng phẳng, chắc chắn","h":"Vị trí đặt chắc chắn giúp quạt không bị rung và đổ.","e":"Đặt quạt trên mặt phẳng, chắc chắn giúp quạt đứng vững, không bị rung lắc hay đổ ngã khi đang quay.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây là nguy hiểm khi dùng điện?","o":["Tắt đèn khi ra khỏi phòng","Lau tay thật khô trước khi bật công tắc","Báo người lớn khi thấy dây điện bị hở","Chạm tay ướt vào ổ cắm hoặc công tắc điện"],"a":"Chạm tay ướt vào ổ cắm hoặc công tắc điện","h":"Nước dẫn điện, tay ướt chạm vào điện rất nguy hiểm.","e":"Tay ướt chạm vào ổ cắm hay công tắc có thể bị điện giật. Em luôn phải lau khô tay trước khi chạm vào thiết bị điện.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi muốn cắm phích cắm điện, em nên làm thế nào?","o":["Tự cắm bằng một tay khi tay đang ướt","Cắm lúc nào cũng được, không cần ai biết","Dùng vật bằng kim loại để đẩy phích vào ổ","Nhờ người lớn hoặc chỉ cắm khi được người lớn cho phép và hướng dẫn"],"a":"Nhờ người lớn hoặc chỉ cắm khi được người lớn cho phép và hướng dẫn","h":"Trẻ em chưa nên tự ý thao tác với ổ điện.","e":"Em chỉ nên cắm phích điện khi có người lớn cho phép và hướng dẫn để tránh bị điện giật.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Thấy một đoạn dây điện bị hở, trơ lõi đồng ra ngoài, em nên làm gì?","o":["Lấy băng dính tự quấn lại ngay","Sờ thử xem có điện không","Tránh xa và báo ngay cho người lớn","Kéo dây ra chỗ khác"],"a":"Tránh xa và báo ngay cho người lớn","h":"Dây điện hở có thể gây điện giật bất cứ lúc nào.","e":"Dây điện bị hở rất nguy hiểm. Em phải tránh xa và báo ngay cho người lớn xử lí, tuyệt đối không tự chạm vào.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi rút phích cắm ra khỏi ổ điện, em nên cầm vào đâu?","o":["Cầm vào phần lõi kim loại của phích","Cầm vào thân phích cắm rồi rút ra","Kéo mạnh sợi dây điện","Dùng hai tay kéo hai đầu dây"],"a":"Cầm vào thân phích cắm rồi rút ra","h":"Kéo dây lâu ngày sẽ làm dây bị đứt ngầm bên trong.","e":"Em nên cầm chắc vào thân phích cắm để rút. Kéo sợi dây sẽ làm dây nhanh hỏng, dễ hở điện gây nguy hiểm.","t":"tin-lop3","g":3,"l":"thu-thach"},{"p":"Trong những nơi sau đây, nơi nào em phải tránh xa vì nguy hiểm về điện?","o":["Sân chơi của trường","Thư viện trường","Tủ điện, cột điện và trạm biến áp","Phòng học"],"a":"Tủ điện, cột điện và trạm biến áp","h":"Những nơi này thường có biển cảnh báo nguy hiểm.","e":"Tủ điện, cột điện và trạm biến áp là nơi có điện nguy hiểm, thường gắn biển cấm. Em phải tránh xa và không leo trèo, thả diều gần đó.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi chọn chậu để trồng cây, em nên chọn chậu như thế nào?","o":["Chậu không cần đáy","Chậu càng nhỏ càng tốt","Chậu có lỗ thoát nước ở đáy","Chậu kín mít không có lỗ"],"a":"Chậu có lỗ thoát nước ở đáy","h":"Nước thừa trong chậu cần có đường thoát ra ngoài.","e":"Chậu có lỗ thoát nước ở đáy giúp nước thừa chảy ra ngoài, tránh làm cây bị úng và thối rễ.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Đất trồng cây trong chậu cần có đặc điểm gì?","o":["Cứng như đá","Đất sét dẻo quánh","Toàn cát khô","Tơi xốp, giữ ẩm và có chất dinh dưỡng"],"a":"Tơi xốp, giữ ẩm và có chất dinh dưỡng","h":"Rễ cây cần đất mềm để đâm sâu và hút nước.","e":"Đất tơi xốp giúp rễ cây dễ phát triển, giữ được ẩm và cung cấp chất dinh dưỡng cho cây lớn khỏe.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Khi gieo hạt vào chậu, em nên làm thế nào?","o":["Rắc hạt chồng chất lên nhau","Gieo hạt thật sâu xuống đáy chậu","Ném hạt vào chậu từ xa","Gieo hạt đều trên mặt đất, phủ một lớp đất mỏng rồi tưới nhẹ"],"a":"Gieo hạt đều trên mặt đất, phủ một lớp đất mỏng rồi tưới nhẹ","h":"Hạt cần đất và nước vừa đủ để nảy mầm.","e":"Gieo hạt đều, phủ lớp đất mỏng và tưới nhẹ giúp hạt có đủ ẩm để nảy mầm thành cây con.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Khi trồng cây con vào chậu, em cần chú ý điều gì?","o":["Bẻ cong rễ cây cho vừa chậu","Chôn cả lá cây xuống đất","Đặt cây thẳng, lấp đất vừa kín rễ và nén nhẹ quanh gốc","Để cây nằm nghiêng hẳn sang một bên"],"a":"Đặt cây thẳng, lấp đất vừa kín rễ và nén nhẹ quanh gốc","h":"Cây đứng thẳng và rễ được đất ôm chắc sẽ mau bén rễ.","e":"Trồng cây con thẳng, lấp đất kín rễ và nén nhẹ quanh gốc giúp cây đứng vững, rễ tiếp xúc tốt với đất để hút nước.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Tưới nước cho cây trong chậu như thế nào là đúng?","o":["Chỉ tưới khi thấy cây đã héo rũ","Tưới vừa đủ ẩm đất, tránh để chậu úng nước","Không cần tưới vì cây tự tìm nước","Tưới thật nhiều mỗi lần cho cây no nước cả tuần"],"a":"Tưới vừa đủ ẩm đất, tránh để chậu úng nước","h":"Thiếu nước cây khô héo, thừa nước cây cũng bị thối rễ.","e":"Em nên tưới nước vừa đủ để đất ẩm đều. Tưới quá nhiều gây úng, thối rễ; tưới quá ít cây sẽ khô héo.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Em nên đặt chậu cây ở nơi như thế nào?","o":["Ngay cạnh bếp lửa đang đun","Nơi có ánh sáng phù hợp và thoáng khí","Dưới gầm cầu thang không có ánh sáng","Trong tủ kín tối"],"a":"Nơi có ánh sáng phù hợp và thoáng khí","h":"Cây cần ánh sáng để quang hợp và lớn lên.","e":"Hầu hết cây cảnh cần ánh sáng và không khí thoáng để quang hợp, sinh trưởng khỏe mạnh. Để cây trong chỗ tối lâu ngày cây sẽ yếu và chết.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Bón phân cho cây trong chậu có tác dụng gì?","o":["Làm cho chậu nặng hơn","Làm đất khô nhanh hơn","Đuổi hết côn trùng trong nhà","Cung cấp thêm chất dinh dưỡng giúp cây lớn nhanh, lá xanh, hoa đẹp"],"a":"Cung cấp thêm chất dinh dưỡng giúp cây lớn nhanh, lá xanh, hoa đẹp","h":"Phân bón giống như thức ăn bổ sung cho cây.","e":"Bón phân đúng lượng giúp cây có thêm chất dinh dưỡng để phát triển, lá xanh tốt và ra hoa đẹp.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Vì sao em cần thường xuyên nhổ cỏ dại trong chậu cây?","o":["Vì cỏ dại làm đất chặt lại","Vì cỏ dại hút hết ánh sáng của phòng","Vì cỏ dại làm chậu trông xấu đi là chính","Vì cỏ dại tranh nước và chất dinh dưỡng của cây, còn là nơi trú của sâu bệnh"],"a":"Vì cỏ dại tranh nước và chất dinh dưỡng của cây, còn là nơi trú của sâu bệnh","h":"Cỏ dại mọc chung chậu sẽ chia phần ăn với cây của em.","e":"Cỏ dại cạnh tranh nước, dinh dưỡng với cây trồng và là nơi sâu bệnh trú ngụ, nên em cần nhổ bỏ thường xuyên.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Thấy lá cây có sâu ăn lá, em nên làm gì trước tiên?","o":["Bắt sâu, ngắt bỏ lá bị sâu ăn nhiều và báo người lớn nếu sâu quá nhiều","Vứt cả chậu cây đi","Phun bất cứ loại thuốc nào tìm thấy trong nhà","Để mặc sâu ăn hết lá"],"a":"Bắt sâu, ngắt bỏ lá bị sâu ăn nhiều và báo người lớn nếu sâu quá nhiều","h":"Xử lí bằng tay là cách an toàn nhất cho trẻ em.","e":"Em có thể bắt sâu bằng tay và ngắt bỏ lá hỏng. Nếu sâu nhiều, hãy báo người lớn, không tự ý dùng thuốc trừ sâu vì rất độc.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Thời điểm nào trong ngày thích hợp nhất để tưới cây vào mùa hè nắng nóng?","o":["Sáng sớm hoặc chiều mát","Lúc nào cũng giống nhau","Nửa đêm","Giữa trưa nắng gắt"],"a":"Sáng sớm hoặc chiều mát","h":"Tưới lúc nắng gắt, nước bốc hơi nhanh và cây dễ bị sốc nhiệt.","e":"Tưới cây vào sáng sớm hoặc chiều mát giúp cây hấp thụ nước tốt, tránh lãng phí nước và không làm cây bị sốc khi nắng gắt.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Cây trong chậu bị vàng lá và đất luôn ướt sũng. Nguyên nhân có thể là gì?","o":["Cây thiếu nắng hoàn toàn","Cây được bón phân đúng cách","Chậu cây quá đẹp","Tưới quá nhiều nước làm cây bị úng, thối rễ"],"a":"Tưới quá nhiều nước làm cây bị úng, thối rễ","h":"Đất luôn ướt sũng là dấu hiệu của việc thừa nước.","e":"Đất ướt sũng kéo dài khiến rễ thiếu không khí, bị thối, cây không hút được nước và dinh dưỡng nên vàng lá. Em cần giảm tưới và kiểm tra lỗ thoát nước.","t":"tin-lop4","g":4,"l":"thu-thach"},{"p":"Bộ lắp ghép mô hình kĩ thuật gồm những loại chi tiết nào sau đây?","o":["Chỉ có giấy màu và hồ dán","Thanh thẳng, thanh chữ L, thanh chữ U, bánh xe, trục, ốc và vít","Kim, chỉ và vải vụn","Đất nặn và que tre"],"a":"Thanh thẳng, thanh chữ L, thanh chữ U, bánh xe, trục, ốc và vít","h":"Các chi tiết trong bộ lắp ghép thường bằng nhựa hoặc kim loại và ghép được với nhau.","e":"Bộ lắp ghép mô hình kĩ thuật gồm các chi tiết như thanh thẳng, thanh chữ L, thanh chữ U, bánh xe, trục cùng ốc, vít để lắp thành nhiều mô hình khác nhau.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Khi lắp ghép một mô hình kĩ thuật, em nên làm như thế nào?","o":["Lắp tuỳ ý, không cần xem hướng dẫn","Chỉ chọn những chi tiết mình thích để lắp","Xem kĩ hướng dẫn, chọn đúng chi tiết và lắp theo từng bước","Lắp thật nhanh cho xong, thiếu chi tiết cũng được"],"a":"Xem kĩ hướng dẫn, chọn đúng chi tiết và lắp theo từng bước","h":"Mỗi mô hình đều có hướng dẫn lắp theo từng bước.","e":"Lắp theo hướng dẫn giúp em chọn đúng chi tiết và lắp đúng thứ tự các bước, để mô hình hoàn chỉnh và chắc chắn.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Để an toàn và giữ gìn bộ lắp ghép khi lắp mô hình, em cần làm gì?","o":["Không cho ốc, vít nhỏ vào miệng, để các chi tiết gọn gàng tránh rơi mất","Ngậm ốc, vít trong miệng cho tiện tay lắp","Vứt các chi tiết thừa ra sàn nhà","Dùng răng để vặn chặt ốc thay cho tua vít"],"a":"Không cho ốc, vít nhỏ vào miệng, để các chi tiết gọn gàng tránh rơi mất","h":"Ốc, vít là những chi tiết rất nhỏ, cần cẩn thận khi cầm và cất giữ.","e":"Ốc, vít nhỏ dễ rơi mất và nguy hiểm nếu cho vào miệng. Em cần để chi tiết gọn gàng, dùng dụng cụ đúng cách và thu dọn sau khi lắp.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Mô hình bập bênh hoạt động được là nhờ điều gì giúp hai đầu lần lượt nâng lên, hạ xuống?","o":["Nhờ bánh xe lăn trên mặt đất","Nhờ cánh quạt quay khi có gió","Nhờ nam châm hút các chi tiết","Nhờ thanh ngang đặt trên điểm tựa ở giữa, giống như một đòn bẩy"],"a":"Nhờ thanh ngang đặt trên điểm tựa ở giữa, giống như một đòn bẩy","h":"Bập bênh ở sân chơi cũng có một điểm tựa ở chính giữa.","e":"Mô hình bập bênh có thanh ngang gác lên điểm tựa ở giữa. Khi một đầu hạ xuống thì đầu kia được nâng lên, giống như nguyên lí đòn bẩy đơn giản.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Sau khi lắp xong mô hình robot, em nên làm gì?","o":["Cất ngay vào hộp, không cần kiểm tra","Kiểm tra các mối ghép đã chặt chưa và các bộ phận như đầu, thân, tay, chân đã đúng vị trí chưa","Tháo hết ốc, vít ra để lắp lại từ đầu","Nhờ bạn lắp lại hộ cho chắc chắn"],"a":"Kiểm tra các mối ghép đã chặt chưa và các bộ phận như đầu, thân, tay, chân đã đúng vị trí chưa","h":"Kiểm tra lại giúp em phát hiện chi tiết lắp sai hoặc còn lỏng.","e":"Sau khi lắp xong, em cần kiểm tra lại các mối ghép và vị trí các bộ phận của robot (đầu, thân, tay, chân hoặc bánh xe) để mô hình chắc chắn và đúng mẫu.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Đồ chơi nào sau đây là đồ chơi dân gian truyền thống của Việt Nam?","o":["Máy chơi điện tử cầm tay","Robot điều khiển từ xa","Đèn ông sao và tò he","Xe ô tô chạy bằng pin"],"a":"Đèn ông sao và tò he","h":"Đồ chơi dân gian thường được làm thủ công từ tre, giấy, bột gạo.","e":"Đèn ông sao, tò he, diều, trống bỏi là những đồ chơi dân gian truyền thống, gắn với tuổi thơ và các dịp lễ hội như Tết Trung thu. Em cần trân trọng và giữ gìn những đồ chơi truyền thống này.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Để làm một chiếc đèn lồng đơn giản, em cần những vật liệu chính nào?","o":["Vải và kim, chỉ","Đất sét và nước","Sắt, thép và đinh","Giấy màu (hoặc giấy bóng kính) và nẹp tre để làm khung"],"a":"Giấy màu (hoặc giấy bóng kính) và nẹp tre để làm khung","h":"Đèn lồng truyền thống có khung bằng tre và dán giấy bên ngoài.","e":"Đèn lồng thường được làm bằng khung nẹp tre uốn cong, bên ngoài dán giấy màu hoặc giấy bóng kính. Khi làm, em cần cẩn thận với kéo và hồ dán để sản phẩm đẹp và an toàn.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Trước khi cho đất vào chậu, nhiều người lót một lớp sỏi nhỏ ở đáy chậu. Việc đó giúp ích gì?","o":["Giúp thoát nước tốt, tránh úng cho cây","Làm cây ra hoa sớm","Giữ cho đất luôn khô","Làm chậu đẹp hơn"],"a":"Giúp thoát nước tốt, tránh úng cho cây","h":"Lớp sỏi tạo khoảng trống cho nước chảy xuống lỗ thoát.","e":"Lớp sỏi ở đáy chậu giúp nước thoát dễ dàng qua lỗ đáy, hạn chế đất bịt lỗ và giúp rễ cây không bị úng.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Vì sao chuồn chuồn thăng bằng có thể đứng vững trên đầu mỏ mà không ngã?","o":["Vì trọng tâm của chuồn chuồn thấp, nằm ngay dưới đầu mỏ nhờ phần đầu nặng và hai cánh xoè rộng","Vì chuồn chuồn được dán chặt bằng keo","Vì chuồn chuồn làm bằng nam châm","Vì có sợi dây buộc giữ chuồn chuồn lại"],"a":"Vì trọng tâm của chuồn chuồn thấp, nằm ngay dưới đầu mỏ nhờ phần đầu nặng và hai cánh xoè rộng","h":"Phần đầu mỏ nặng và hai cánh xoè ra giúp chuồn chuồn giữ thăng bằng.","e":"Chuồn chuồn thăng bằng thường làm bằng tre hoặc giấy, có phần đầu mỏ nặng và hai cánh xoè rộng sang hai bên nên trọng tâm thấp, nằm dưới điểm đặt, giúp nó đứng vững mà không ngã.","t":"tin-lop4","g":4,"l":"nhe-nhang"},{"p":"Máy thu thanh (ra-đi-ô) trong gia đình thường được dùng để làm gì?","o":["Nghe tin tức, dự báo thời tiết và âm nhạc","Xem các chương trình truyền hình","Nấu cơm cho gia đình","Quạt mát khi trời nóng"],"a":"Nghe tin tức, dự báo thời tiết và âm nhạc","h":"Máy thu thanh chỉ phát ra âm thanh, không có hình ảnh.","e":"Máy thu thanh (ra-đi-ô) thu sóng phát thanh để em nghe tin tức, dự báo thời tiết, kể chuyện và âm nhạc. Xem truyền hình là công việc của máy thu hình (ti vi).","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi xem ti vi, việc làm nào sau đây giúp bảo vệ đôi mắt của em?","o":["Ngồi sát màn hình để nhìn cho rõ","Ngồi cách ti vi một khoảng vừa phải, không xem quá lâu","Xem ti vi trong phòng tối om","Vừa xem ti vi vừa nằm nghiêng trên giường"],"a":"Ngồi cách ti vi một khoảng vừa phải, không xem quá lâu","h":"Mắt sẽ mỏi nếu ngồi quá gần màn hình hoặc xem trong thời gian dài.","e":"Khi xem ti vi, em nên ngồi cách màn hình một khoảng vừa phải, phòng đủ sáng và không xem quá lâu để mắt được nghỉ ngơi, tránh bị mỏi và cận thị.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi cần đưa kéo cho bạn trong giờ thủ công, em nên làm thế nào cho an toàn?","o":["Ném kéo qua cho bạn đỡ lấy","Cầm kéo chĩa phần lưỡi nhọn về phía bạn","Cầm phần lưỡi kéo quay về phía mình, đưa phần cán cho bạn cầm","Để kéo trên ghế cho bạn tự lấy"],"a":"Cầm phần lưỡi kéo quay về phía mình, đưa phần cán cho bạn cầm","h":"Phần cán kéo là phần an toàn để cầm nắm.","e":"Khi đưa kéo cho người khác, em cầm nhẹ phần lưỡi đã khép, quay lưỡi về phía mình và đưa phần cán ra trước để bạn cầm an toàn. Tuyệt đối không ném kéo hay chĩa lưỡi nhọn về phía bạn.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi dán giấy bằng hồ dán trong giờ thủ công, em nên làm thế nào?","o":["Bôi thật nhiều hồ cho thật chắc","Bôi hồ lên khắp mặt bàn cho dễ dán","Bôi hồ vào tay rồi mới quệt lên giấy","Chỉ lấy một lượng hồ vừa đủ, bôi đều và mỏng lên giấy"],"a":"Chỉ lấy một lượng hồ vừa đủ, bôi đều và mỏng lên giấy","h":"Dùng quá nhiều hồ sẽ làm giấy bị nhăn và ướt.","e":"Khi dán giấy, em chỉ cần lấy một lượng hồ vừa đủ, bôi đều và mỏng. Bôi quá nhiều hồ làm giấy nhăn, ướt, sản phẩm xấu và lãng phí vật liệu.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em muốn tự làm một ống đựng bút từ vật liệu tái chế. Vật liệu nào sau đây là phù hợp và an toàn?","o":["Một mảnh kính vỡ có cạnh sắc","Một hộp giấy cứng sạch hoặc chai nhựa đã rửa sạch, cắt gọn","Một lon thiếc có miệng sắc chưa xử lí","Một túi ni-lông mỏng"],"a":"Một hộp giấy cứng sạch hoặc chai nhựa đã rửa sạch, cắt gọn","h":"Vật liệu tái chế cần sạch và không có cạnh sắc làm đứt tay.","e":"Hộp giấy cứng sạch hoặc chai nhựa đã rửa sạch, cắt gọn và trang trí thêm là vật liệu phù hợp để làm ống đựng bút. Không dùng vật có cạnh sắc như kính vỡ hay miệng lon thiếc vì dễ làm đứt tay.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Biển báo giao thông do em làm trong giờ thủ công có ý nghĩa gì?","o":["Nhắc nhở mọi người chấp hành đúng luật giao thông để đi đường an toàn","Để trang trí cho lớp học thêm đẹp mà thôi","Để che nắng khi đi ngoài đường","Để làm đồ chơi tung hứng với bạn bè"],"a":"Nhắc nhở mọi người chấp hành đúng luật giao thông để đi đường an toàn","h":"Biển báo trên đường giúp người tham gia giao thông biết điều cần làm.","e":"Biển báo giao thông giúp nhắc nhở và hướng dẫn mọi người đi đường đúng luật, giữ an toàn cho bản thân và người khác. Khi làm biển báo, em dùng bìa cứng và màu vẽ để thể hiện đúng hình dáng, màu sắc của biển thật.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Em có thể làm đồ chơi từ những vật liệu sẵn có nào sau đây?","o":["Đất sét nặn mua ở hiệu sách là duy nhất","Chỉ có nhựa đúc sẵn trong cửa hàng đồ chơi","Giấy, bìa cứng, lá cây khô và vỏ hộp đã làm sạch","Pin cũ và dây điện hỏng"],"a":"Giấy, bìa cứng, lá cây khô và vỏ hộp đã làm sạch","h":"Nhiều đồ chơi đẹp được làm từ vật liệu quanh em trong nhà và vườn.","e":"Em có thể gấp, cắt, dán giấy và bìa cứng, dùng lá cây khô hay vỏ hộp sạch để làm nhiều đồ chơi thú vị như chong chóng giấy, con vật bằng lá. Không dùng pin cũ hay dây điện hỏng vì không an toàn.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Sau khi làm đồ chơi xong, em cần làm gì?","o":["Thu dọn giấy vụn, vật liệu thừa và rửa tay sạch sẽ","Để nguyên giấy vụn trên bàn cho bạn dọn","Vứt hết vật liệu thừa ra sân trường","Cất đồ chơi vào cặp ngay, không cần dọn dẹp"],"a":"Thu dọn giấy vụn, vật liệu thừa và rửa tay sạch sẽ","h":"Giữ vệ sinh sau khi làm thủ công giúp lớp học gọn gàng và bảo vệ sức khỏe.","e":"Sau khi làm đồ chơi, em cần thu dọn giấy vụn và vật liệu thừa vào thùng rác, cất dụng cụ gọn gàng và rửa tay sạch sẽ. Vật liệu còn dùng được thì giữ lại cho lần làm sau.","t":"tin-lop3","g":3,"l":"nhe-nhang"},{"p":"Khi có cháy, nổ hoặc tai nạn cần gọi công an, em gọi số điện thoại khẩn cấp nào?","o":["113","114","115","112"],"a":"113","h":"Số này gồm ba chữ số, bắt đầu bằng số 1 và kết thúc bằng số 3.","e":"Ở Việt Nam, 113 là số điện thoại khẩn cấp của công an, dùng khi có trộm cắp, cháy nổ lớn hoặc tai nạn cần công an giúp đỡ.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Khi phát hiện hỏa hoạn cần gọi cứu hỏa, em gọi số điện thoại nào?","o":["113","114","115","112"],"a":"114","h":"Hãy nghĩ đến số điện thoại của lính cứu hỏa.","e":"114 là số điện thoại của lực lượng cảnh sát phòng cháy chữa cháy, cần gọi ngay khi phát hiện hỏa hoạn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Khi có người bị thương nặng hoặc đau ốm cần cấp cứu, em gọi số điện thoại nào?","o":["113","114","115","112"],"a":"115","h":"Đây là số của xe cấp cứu chở người bệnh đến bệnh viện.","e":"115 là số điện thoại cấp cứu y tế, gọi khi có người bị thương nặng hoặc đau ốm nguy hiểm cần xe cấp cứu.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Vì sao không nên vừa sạc điện thoại vừa sử dụng?","o":["Vì điện thoại sẽ sạc chậm hơn","Vì điện thoại dễ bị rơi vỡ","Vì màn hình dễ bị xước","Vì pin có thể nóng lên, phồng hoặc cháy nổ, gây nguy hiểm"],"a":"Vì pin có thể nóng lên, phồng hoặc cháy nổ, gây nguy hiểm","h":"Hãy nghĩ đến điều nguy hiểm có thể xảy ra với viên pin khi vừa nạp điện vừa hoạt động.","e":"Vừa sạc vừa dùng khiến pin nóng lên nhanh, dễ bị phồng, cháy nổ và làm pin nhanh hỏng, rất nguy hiểm.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Để bảo vệ mắt khi sử dụng điện thoại, em nên làm gì?","o":["Không dùng điện thoại quá lâu liên tục, thỉnh thoảng cho mắt nghỉ ngơi","Dùng điện thoại càng lâu càng tốt để mắt quen dần","Chỉ dùng điện thoại trong phòng tối cho đỡ chói mắt","Dí điện thoại thật sát mắt để nhìn cho rõ"],"a":"Không dùng điện thoại quá lâu liên tục, thỉnh thoảng cho mắt nghỉ ngơi","h":"Mắt cũng cần được nghỉ ngơi giống như cơ thể sau khi học lâu.","e":"Nhìn màn hình quá lâu và quá gần khiến mắt mỏi, dễ bị cận thị. Em nên giữ khoảng cách hợp lí và cho mắt nghỉ sau mỗi khoảng thời gian sử dụng.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Ngăn đá của tủ lạnh thường dùng để làm gì?","o":["Để rau củ được tươi lâu","Làm đông đá và bảo quản thực phẩm đông lạnh","Để nguội thức ăn còn nóng","Để trứng và bơ"],"a":"Làm đông đá và bảo quản thực phẩm đông lạnh","h":"Ngăn này có nhiệt độ thấp nhất trong tủ lạnh.","e":"Ngăn đá có nhiệt độ rất thấp, dùng để làm nước đá và giữ đông thực phẩm như thịt, cá trong thời gian dài.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Vì sao không nên cho thức ăn còn nóng vào tủ lạnh?","o":["Vì thức ăn nóng sẽ làm mất mùi của tủ lạnh","Vì thức ăn nóng cho vào tủ sẽ bị chua ngay","Vì hơi nóng làm tủ phải hoạt động nhiều hơn, tốn điện và ảnh hưởng đến thực phẩm khác","Vì tủ lạnh sẽ bị cháy"],"a":"Vì hơi nóng làm tủ phải hoạt động nhiều hơn, tốn điện và ảnh hưởng đến thực phẩm khác","h":"Thức ăn nóng tỏa hơi nóng vào trong tủ lạnh.","e":"Thức ăn nóng làm nhiệt độ trong tủ tăng lên, tủ phải chạy nhiều hơn gây tốn điện, đồng thời ảnh hưởng đến chất lượng các thực phẩm khác. Hãy để thức ăn nguội bớt rồi mới cho vào tủ.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Thịt, cá sống mua về chưa dùng ngay nên bảo quản thế nào trong tủ lạnh?","o":["Để trần trên cánh cửa tủ lạnh","Để chung với rau sống trong ngăn rau","Để trên mặt bàn bếp cho thoáng","Cho vào hộp kín, để ở ngăn đá hoặc ngăn mát phía dưới"],"a":"Cho vào hộp kín, để ở ngăn đá hoặc ngăn mát phía dưới","h":"Thực phẩm sống cần được bọc kín và để tách biệt, ở nơi lạnh nhất.","e":"Thịt, cá sống cần cho vào hộp kín để tránh lây mùi và vi khuẩn sang thực phẩm khác, rồi để ở ngăn đá hoặc ngăn mát phía dưới.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Việc làm nào giúp tủ lạnh tiết kiệm điện?","o":["Đóng kín cửa tủ, không mở tủ quá lâu và quá nhiều lần","Mở cửa tủ thường xuyên để kiểm tra thức ăn","Đặt tủ lạnh sát bếp nấu cho tiện","Cho thật nhiều thức ăn nóng vào tủ cùng lúc"],"a":"Đóng kín cửa tủ, không mở tủ quá lâu và quá nhiều lần","h":"Mỗi lần mở cửa, hơi lạnh trong tủ sẽ thoát ra ngoài.","e":"Đóng kín cửa và hạn chế mở tủ giúp giữ hơi lạnh bên trong, tủ ít phải hoạt động nên tiết kiệm điện hơn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Rau, củ, quả thường được bảo quản ở ngăn nào của tủ lạnh?","o":["Ngăn đá","Ngăn chứa rau củ ở ngăn mát","Cánh cửa tủ","Phía trên nóc tủ lạnh"],"a":"Ngăn chứa rau củ ở ngăn mát","h":"Rau củ cần lạnh vừa phải, không cần đông đá.","e":"Rau, củ, quả được để trong ngăn chứa rau củ riêng ở ngăn mát để giữ độ tươi mà không bị đông đá làm hỏng.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Nếu cửa tủ lạnh đóng không kín thì điều gì sẽ xảy ra?","o":["Thực phẩm sẽ ngon hơn","Tủ lạnh sẽ chạy êm hơn","Hơi lạnh thoát ra ngoài, tủ tốn điện và thực phẩm dễ bị hỏng","Không có ảnh hưởng gì"],"a":"Hơi lạnh thoát ra ngoài, tủ tốn điện và thực phẩm dễ bị hỏng","h":"Cửa hở làm hơi lạnh bị thất thoát ra ngoài.","e":"Cửa tủ hở làm hơi lạnh thoát ra, máy nén phải chạy liên tục gây tốn điện và thực phẩm nhanh hỏng hơn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Trong mô hình xe điện chạy bằng pin, pin có vai trò gì?","o":["Làm cho bánh xe to hơn","Trang trí cho mô hình đẹp hơn","Làm cho thân xe nhẹ hơn","Cung cấp năng lượng điện cho động cơ hoạt động"],"a":"Cung cấp năng lượng điện cho động cơ hoạt động","h":"Pin giống như \"bình xăng\" cung cấp năng lượng cho xe điện.","e":"Pin là nguồn điện của mô hình, cung cấp năng lượng điện để động cơ hoạt động và làm xe chạy.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Bộ phận nào trong mô hình xe điện biến điện năng thành chuyển động làm xe chạy?","o":["Động cơ điện","Bánh xe","Thân xe","Công tắc"],"a":"Động cơ điện","h":"Bộ phận này quay và kéo theo bánh xe khi có điện chạy qua.","e":"Động cơ điện nhận điện từ pin và biến điện năng thành chuyển động quay, làm bánh xe quay và xe di chuyển.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Khi lắp, đấu nối dây điện cho mô hình xe điện, em cần chú ý điều gì?","o":["Đấu nối dây tuỳ ý thế nào cũng được","Nối đúng các cực của pin và động cơ theo sơ đồ hướng dẫn","Cầm dây điện khi tay đang ướt","Dùng càng nhiều pin càng tốt cho xe chạy nhanh"],"a":"Nối đúng các cực của pin và động cơ theo sơ đồ hướng dẫn","h":"Pin có cực dương và cực âm, cần nối cho đúng.","e":"Khi đấu nối cần nối đúng cực dương, cực âm của pin với động cơ theo sơ đồ; nối sai cực xe sẽ không chạy đúng hoặc chạy ngược.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Pin đã hết năng lượng sau khi sử dụng cần được xử lí thế nào?","o":["Vứt chung vào thùng rác sinh hoạt","Đem đốt cho cháy hết","Thu gom riêng và bỏ vào nơi quy định dành cho pin thải","Chôn xuống đất trong vườn"],"a":"Thu gom riêng và bỏ vào nơi quy định dành cho pin thải","h":"Pin thải chứa chất độc hại nên không được vứt bừa bãi.","e":"Pin thải chứa chất độc hại cho đất và nước nên phải thu gom riêng, bỏ vào thùng hoặc điểm thu gom pin thải theo quy định.","t":"tin-lop5","g":5,"l":"thu-thach"},{"p":"Khi bật công tắc mà mô hình xe điện không chạy, em nên kiểm tra điều gì trước tiên?","o":["Sơn lại thân xe cho mới","Thay cả bốn bánh xe","Đi mua một mô hình khác","Kiểm tra pin còn điện không và các mối nối dây có chắc không"],"a":"Kiểm tra pin còn điện không và các mối nối dây có chắc không","h":"Hãy kiểm tra nguồn điện và đường dây trước khi nghĩ đến hỏng hóc khác.","e":"Xe không chạy thường do hết pin hoặc mối nối dây bị lỏng, tuột. Kiểm tra pin và các mối nối trước là cách làm đúng và đơn giản nhất.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Trong mô hình máy phát điện gió, gió tạo ra điện bằng cách nào?","o":["Gió thổi trực tiếp vào bóng đèn làm đèn sáng","Gió làm nóng các dây điện để phát điện","Gió làm quay cánh quạt (tua-bin), chuyển động quay này làm máy phát tạo ra điện","Gió đẩy nước lên cao để tạo ra điện"],"a":"Gió làm quay cánh quạt (tua-bin), chuyển động quay này làm máy phát tạo ra điện","h":"Hãy quan sát cánh quạt của mô hình khi có gió thổi.","e":"Khi gió thổi, cánh quạt (tua-bin gió) quay và truyền chuyển động quay cho máy phát điện, từ đó tạo ra dòng điện thắp sáng bóng đèn trong mô hình.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Vì sao năng lượng gió được gọi là nguồn năng lượng sạch và tái tạo?","o":["Vì gió chỉ thổi vào ban ngày","Vì dùng gió không cần xây nhà máy","Vì gió có màu trong suốt, không nhìn thấy","Vì gió có sẵn trong tự nhiên, không bao giờ cạn và không thải khói bụi gây ô nhiễm"],"a":"Vì gió có sẵn trong tự nhiên, không bao giờ cạn và không thải khói bụi gây ô nhiễm","h":"Năng lượng tái tạo là nguồn năng lượng tự nhiên bổ sung liên tục, không cạn kiệt.","e":"Gió là nguồn năng lượng tái tạo: tự nhiên luôn tạo ra gió, dùng mãi không cạn. Phát điện bằng gió cũng không thải khói, bụi nên thân thiện với môi trường.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Tấm pin mặt trời trong mô hình điện mặt trời có nhiệm vụ gì?","o":["Biến ánh nắng mặt trời thành điện năng","Che nắng cho ngôi nhà mô hình","Phản chiếu ánh sáng để trang trí","Hút nước mưa vào bể chứa"],"a":"Biến ánh nắng mặt trời thành điện năng","h":"Khi có nắng chiếu vào tấm pin, bóng đèn trong mô hình sáng lên.","e":"Tấm pin mặt trời hấp thụ ánh nắng và biến đổi thành điện năng. Điện này có thể thắp sáng bóng đèn, chạy quạt nhỏ hoặc nạp vào pin dự trữ để dùng sau.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Điện mặt trời được ứng dụng ở đâu trong đời sống?","o":["Chỉ dùng trong phòng thí nghiệm của các nhà khoa học","Dùng để đun nấu thay thế hoàn toàn bếp ga","Dùng cho tàu ngầm chạy dưới đáy biển sâu","Thắp sáng đèn vườn, đèn đường và cấp điện cho máy tính bỏ túi"],"a":"Thắp sáng đèn vườn, đèn đường và cấp điện cho máy tính bỏ túi","h":"Nhiều đèn vườn tự sáng vào buổi tối nhờ tấm pin nhỏ trên nắp đèn.","e":"Điện mặt trời được dùng cho đèn vườn, đèn đường tự sáng khi trời tối, máy tính bỏ túi và cả hệ thống điện trên mái nhà. Đây là nguồn năng lượng tái tạo, sạch và tiết kiệm.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Công nghệ có vai trò như thế nào đối với đời sống con người?","o":["Làm cho cuộc sống trở nên khó khăn hơn","Chỉ phục vụ cho việc vui chơi giải trí","Không ảnh hưởng gì đến đời sống hằng ngày","Giúp cuộc sống tiện nghi, thoải mái và an toàn hơn"],"a":"Giúp cuộc sống tiện nghi, thoải mái và an toàn hơn","h":"Hãy nghĩ đến đèn điện, máy giặt giúp gia đình em mỗi ngày.","e":"Nhờ công nghệ, con người có đèn điện chiếu sáng, máy giặt giặt quần áo, quạt và điều hòa làm mát... Cuộc sống vì thế tiện nghi, tiết kiệm công sức và an toàn hơn.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Các sản phẩm công nghệ như điện thoại, máy giặt, bóng đèn điện có nguồn gốc từ đâu?","o":["Tự mọc lên trong tự nhiên","Do con người sáng tạo ra để phục vụ đời sống","Do cây cối và động vật tạo ra","Xuất hiện từ thời chưa có con người"],"a":"Do con người sáng tạo ra để phục vụ đời sống","h":"Sản phẩm công nghệ khác với vật có sẵn trong tự nhiên.","e":"Sản phẩm công nghệ là những sản phẩm do con người sáng tạo và chế tạo ra nhằm phục vụ đời sống, lao động và học tập. Chúng không tự có trong tự nhiên.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Nhà sáng chế là người như thế nào?","o":["Người tạo ra sản phẩm mới hoặc cách làm mới hữu ích cho đời sống","Người bán các sản phẩm công nghệ ở cửa hàng","Người sửa chữa đồ dùng bị hỏng","Người sử dụng thành thạo điện thoại"],"a":"Người tạo ra sản phẩm mới hoặc cách làm mới hữu ích cho đời sống","h":"Ví dụ nổi tiếng: Ê-đi-xơn (Edison) gắn liền với bóng đèn điện.","e":"Nhà sáng chế là người nghiên cứu, sáng tạo ra sản phẩm mới hoặc giải pháp mới có ích. Chẳng hạn, Ê-đi-xơn (Edison) đã phát minh và hoàn thiện bóng đèn điện thực dụng, giúp con người thắp sáng bằng điện.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Bước đầu tiên khi thiết kế một sản phẩm là gì?","o":["Mua vật liệu về làm ngay","Trang trí cho sản phẩm thật đẹp","Xác định nhu cầu: sản phẩm dùng để làm gì, cho ai sử dụng","Đem sản phẩm đi kiểm tra"],"a":"Xác định nhu cầu: sản phẩm dùng để làm gì, cho ai sử dụng","h":"Phải biết rõ mục đích của sản phẩm trước khi vẽ và chế tạo.","e":"Thiết kế sản phẩm bắt đầu bằng việc xác định nhu cầu: sản phẩm dùng để làm gì, phục vụ ai. Sau đó mới phác thảo ý tưởng, chế tạo thử, kiểm tra và cải tiến cho hoàn thiện.","t":"tin-lop5","g":5,"l":"nhe-nhang"},{"p":"Bản vẽ phác thảo trong thiết kế sản phẩm có tác dụng gì?","o":["Thay thế hoàn toàn cho sản phẩm thật","Giúp hình dung hình dáng, kích thước của sản phẩm trước khi chế tạo","Dùng để trang trí tường lớp học","Giúp bán sản phẩm được giá cao hơn"],"a":"Giúp hình dung hình dáng, kích thước của sản phẩm trước khi chế tạo","h":"Phác thảo là vẽ ra ý tưởng trên giấy trước khi bắt tay làm.","e":"Bản vẽ phác thảo thể hiện ý tưởng về hình dáng, kích thước và các bộ phận của sản phẩm, giúp người thiết kế hình dung rõ sản phẩm và dễ dàng sửa chữa ý tưởng trước khi chế tạo thật.","t":"tin-lop5","g":5,"l":"nhe-nhang"}];